(window.GIM_TP=window.GIM_TP||{})["Z.Tzav.0"]={"from":0,"a":[[["(ויקרא ו׳:י״ח) זֹאת תּוֹרַת הָעוֹלָה וְגוֹ'. רִבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (תהילים ל״ו:ז׳) צִדְקָתְךָ כְּהַרְרֵי אֵל מִשְׁפָּטֶיךָ תְּהוֹם רַבָּה וְגוֹ', (פקודי רל\"ח ע\"ב ושם מוגה) הַאי קְרָא אוֹקִימְנָא לֵיהּ וְאִתְּמַר, תָּא חֲזֵי, הַאי עוֹלָה, סְלִיקוּ וּקְשִׁירוּ דִכְּנֶסֶת יִשְׂרָאֵל לְעֵילָּא, וְדִבּוּקָא דִּילָהּ בְּגוֹ עָלְמָא דְּאָתֵי, לְמֶהֱוִי כֹּלָּא חַד, בְּקִשּׁוּרָא חֲדָא, בְּחִידוּ. וּבְגִין דְּסַלְּקָא לְעֵילָּא לְעֵילָּא, כְּתִיב זֹאת תּוֹרַת, רָזָא דְּכַר וְנוּקְבָּא כַּחֲדָא, תּוֹרָה שֶׁבִּכְתָּב, וְתוֹרָה שֶׁבְּעַל פֶּה, לְסַלְּקָא בַּחֲבִיבוּתָא.","כַּד אִתְּעַר סִטְרָא דְּצָפוֹן, כְּמָה דְּאוֹקִימְנָא דִּכְתִּיב, (שער השירים ב) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי, כְּדֵין אִיהִי סַלְּקָא בַּחֲבִיבוּתָא, וְאִתְעַטְּרָא בִּימִינָא, וְאִתְחַבְּרָא בְּאֶמְצָעִיתָא, וְאִתְנְהִיר כֹּלָּא מֵרָזָא דְּקֹדֶשׁ הַקֳדָשִׁים, וְדָא מִגּוֹ דְּרָזָא דְּאָדָם, בִּרְעוּ דְּכַהֲנָא, וּבִצְלוֹתָא, וּבְשִׁירָתָא.","וְהָא אוֹקִימְנָא דְּעוֹלָה קֹדֶשׁ קֳדָשִׁים, בְּרָזָא דְּרוּחַ עִלָּאָה, בְּגִין דִּתְלַת רוּחִין קְשִׁירָן כַּחֲדָא, רוּחַ תַּתָּאָה דְּאִקְרֵי רוּחַ הַקֹּדֶשׁ. רוּחַ דִּלְגוֹ בְּאֶמְצָעִיתָא, דְּאִקְרֵי רוּחַ חָכְמָה וּבִינָה. וְכֵן אִקְרֵי רוּחַ תַּתָּאָה. אֲבָל הַאי רוּחַ, דְּנָפִיק מִגּוֹ שׁוֹפָר, כְּלִילָן בְּאֶשָּׁא וּמַיָא. רוּחַ עִלָּאָה דְּאִיהוּ סָתִים בַּחֲשָׁאי, דְּבֵיהּ קַיְימִין כָּל רוּחִין קַדִּישִׁין, וְכָל אַנְפִּין נְהִירִין. וּבְגִין כָּךְ אַהֲדְרַת עוֹלָה רוּחַ מַמָּשׁ."],[[0,"זאת תורת העולה וגו׳:","ר׳ שמעון פתח ואמר. צדקתך כהררי אל משפטיך תהום רבה וגו׳. מקרא זה העמדנו אותו, ולמדנו. בוא וראה, עולה זו היא מעלה ומקשרת את כנסת ישראל למעלה, והדבקות שלה בעולם הבא, שהיא בינה, להיות הכל אחד, בקשר אחד, בשמחה. ומשום שעולה למעלה למעלה, לבינה, כתוב, \u0003זאת תורת\u0004 שה״ס דכר ונוקבא ביחד, דהיינו ז״א ומלכות, שהם תורה שבכתב ותורה שבעל פה, לעלות באהבה, לבינה. כי \u0003זאת,\u0004 ה״ס מלכות תורה שבעל פה. \u0003ותורת\u0004 ה״ס ז״א, תורה שבכתב."],[1,"כד אתער סטרא וכו׳:","כשנתעורר צד צפון, שהוא גבורה דז״א, קו השמאל, כמו שהעמדנו שכתוב, שמאלו תחת לראשי, דהיינו שהמלכות מקבלת מקו שמאל דז״א. אז היא, המלכות, עולה באהבה, ומתעטרת בימין דז״א, שהוא חסד. ונתחברה באמצע, דהיינו בקו האמצעי דז״א שהוא ת״ת דז״א, והאיר הכל מסוד קדש הקדשים, שהוא בינה. וזהו מתוך סוד אדם. ברצון הכהנים שהם קו ימין, ובתפלה של ישראל שהם קו האמצעי, ובשירה של הלוים שהם קו שמאל."],[2,"והא אוקימנא דעולה וכו׳:","והרי העמדנו, אשר עולה היא קודש הקדשים, בסוד רוח עליון, שהוא בינה. משום שג׳ רוחות קשורים יחד בעולה, א) רוח תחתון הנקרא רוח הקדש, שהוא המלכות. ב) רוח שבאמצע הנקרא רוח חכמה ובינה, שהוא ז״א שהוא בן לחכמה ובינה. וכן נקרא רוח תחתון, להיותו תחתון ביחס הבינה. אבל רוח הזה הוא יוצא מתוך השופר הכלול מאש וממים, (שפירושו תמצא לעיל בהקסה״ז דף קפ״ד אות רל\"ט ד״ה למשמע ע״ש). ג) רוח עליון הסתום בחשאי, שהוא בינה, שבו מתקיימים כל הרוחות הקדושים, וכל פנים מאירים ממנו, ומשום זה חוזרת העולה לרוח ממש."]],[[0,"","זֹאת תּוֹרַת הָעֹלָה וְגוֹ'. רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, צִדְקָתְךְ כְּהַרְרֵי אֵל מִשְׁפָּטֶיךְ תְּהוֹם רַבָּה וְגוֹ'. הַפָּסוּק הַזֶּה פֵּרַשְׁנוּהוּ וְנִתְבָּאֵר. בֹּא רְאֵה, הָעוֹלָה הַזּוֹ מַעֲלָה וְקוֹשֶׁרֶת אֶת כְּנֶסֶת יִשְׂרָאֵל לְמַעְלָה, וְהַדְּבֵקוּת שֶׁלָּהּ בְּתוֹךְ הָעוֹלָם הַבָּא לִהְיוֹת הַכֹּל אֶחָד בְּקֶשֶׁר אֶחָד, בְּשִׂמְחָה. וּמִשּׁוּם שֶׁעוֹלָה לְמַעְלָה לְמַעְלָה, כָּתוּב זֹּאת תּוֹרַת, סוֹד שֶׁל זָכָר וּנְקֵבָה יַחַד, תּוֹרָה שֶׁבִּכְתָב וְתוֹרָה שֶׁבְּעַל פֶּה לַעֲלוֹת בַּחֲבִיבוּת."],[1,"","כְּשֶׁמִּתְעוֹרֶרֶת רוּחַ צָפוֹן, כְּמוֹ שֶׁבֵּאַרְנוּהוּ שֶׁכָּתוּב שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי, אֲזַי הִיא עוֹלָה בַּחֲבִיבוּת, וּמִתְעַטֶּרֶת בְּיָמִין, וּמִתְחַבֶּרֶת עִם הָאֶמְצָעִי, וְהַכֹּל מֵאִיר מִסּוֹד שֶׁל קֹדֶשׁ הַקְּדָשִׁים, וְזֶה מִתּוֹךְ סוֹד שֶׁל אָדָם, בִּרְצוֹן הַכֹּהֵן וּבִתְפִלָּה וּבְשִׁירָה."],[2,"","וַהֲרֵי בֵּאַרְנוּ שֶׁעוֹלָה קֹדֶשׁ קָדָשִׁים בְּסוֹד הָרוּחַ הָעֶלְיוֹנָה, מִשּׁוּם שֶׁשָּׁלֹשׁ רוּחוֹת קְשׁוּרוֹת כְּאַחַת: הָרוּחַ הַתַּחְתּוֹנָה שֶׁנִּקְרֵאת רוּחַ הַקֹּדֶשׁ, הָרוּחַ שֶׁלְּפָנִים בָּאֶמְצַע, שֶׁנִּקְרֵאת רוּחַ חָכְמָה וּבִינָה, וְכֵן הָרוּחַ הַתַּחְתּוֹנָה. אֲבָל הָרוּחַ הַזּוֹ שֶׁיּוֹצֵאת מִתּוֹךְ שׁוֹפָר, כְּלוּלִים בְּאֵשׁ וּמַיִם. הָרוּחַ הָעֶלְיוֹנָה שֶׁהִיא סְתוּמָה בַּחֲשַׁאי, שֶׁבָּהּ מִתְקַיְּמִים כָּל הָרוּחוֹת הַקְּדוֹשׁוֹת וְכָל הַפָּנִים מְאִירוֹת, וּמִשּׁוּם כָּךְ חוֹזֶרֶת הָעוֹלָה רוּחַ מַמָּשׁ."]]],[["וּלְבָתַר מֵרָזָא דִּבְהֵמָה, מִסְתַּפְּקֵי וְאִתְּזָנוּ, לְאִתְקַשְּׁרָא רוּחָא אָחֳרָא, דְּאִיהִי גּוֹ מְסָאֲבוּ, מֵאִינּוּן תַּרְבִּין וְשַׁמְנוּנִין, כְּמָה דְּאִתְּמַר. וּבְגִין כַּךְ עוֹלָה קֹדֶשׁ קֳדָשִׁים, שְׁאָר קָרְבְּנִין לְמֶעְבַּד שְׁלָמָא בְּעָלְמָא כֻּלְּהוּ, מִכַּמָּה סִטְרִין וּמָארֵי דְּדִינִין. לְאִתְעַבְּרָא וּלְאִתְנַהֲרָא מִגּוֹ רְעוּתָא לְאִתְבַּסְּמָא, אִקְרוּן קֳדָשִׁים קַלִים, בְּגִין דְּלָא מִתְעַטְּרֵי לְעֵילָּא לְעֵילָּא בַּקֹּדֶשׁ הַקֳּדָשִׁים. וְעַל דָּא אִינּוּן קֳדָשִׁים קַלִים, וּנְכִיסוּ דִּלְהוֹן בְּכָל אֲתַר כְּמָה דְּאוּקְמוּהָ, אֲבָל עוֹלָה דְּאִיהִי רָזָא דְּקֹדֶשׁ הַקֳדָשִׁים, לָאו אִיהִי כִּשְׁאָר קָרְבְּנִין, דְּכָל עוֹבָדָהָא קֹדֶשׁ.","תָּא חֲזֵי, מַה כְּתִיב וְלָבַשׁ הַכֹּהֵן מִדוֹ בַד, אִלֵּין לְבוּשִׁין מְיַחֲדִין לִקְדוּשָּׁה. בַּד יְחִידָאי, מְיַחֲדָא לִקְדוּשָׁה. וּכְתִיב בִּגְדֵי קֹדֶשׁ הֵם וְרָחַץ בַּמַּיִם אֶת בְּשָׂרוֹ וּלְבֵשָׁם. מַאי טַעְמָא דָּא קֹדֶשׁ. אֶלָּא רָזָא דְּמִלָּה, כִּדְקָאָמַר דְּאִיהִי קֹדֶשׁ קֳדָשִׁים, דְּסַלְּקָא כֹּלָּא וְאִתְעַטְּרָא בְּקֹּדֶשׁ הַקֳּדָשִׁים, בְּקִשּׁוּרָא חֲדָא. וּלְבָתַר מַפְנֵי וְאַעְבַּר רוּחַ מִסְאֲבָא, דִּמְסָאֵב כֹּלָּא, דְּלָא שַׁלְטָא, וְלָא יִתְקְרִיב גּוֹ מַקְדְּשָׁא, וְאִתְעֲבָּר מִכָּל סִטְרֵי דְּקוּדְשָׁא, וְאִשְׁתְּאַר כֹּלָּא קֹדֶשׁ בִּקְדוּשָּׁה יְחִידָאי.","וְאָמַר רַבִּי שִׁמְעוֹן, הָא אִתְּמַר, (נח ס\"ד) דִּכְתִּיב, (תהילים ל״ו:ז׳) אָדָם וּבְהֵמָה תּוֹשִׁיעַ יְיָ'. וְהָכִי סַלְּקָא רָזָא דְּאָדָם, מִסִּטְרָא דְּאָדָם. בְּהֵמָה, מִסִּטְרָא דִּבְהֵמָה. וּבְגִין כַּךְ כְּתִיב אָדָם כִּי יַקְרִיב מִכֶּם. אָדָם ודַּאי, דְּהָא קָרְבָּנֵיהּ לְעֵילָּא, לְקַשְּׁרָא קִשְׁרָא. וּלְבָתַר מִן הַבְּהֵמָה. וְכֹלָּא אִיהוּ בַּקְּרָא, אָדָם וּבְהֵמָה. וְדָא אִיהוּ רָזָא, דְּאִצְטְרִיךְ לְקָרְבְּנָא אָדָם וּבְהֵמָה, כִּדְקָאָמַר. תָּא חֲזֵי, כַּד בָּרָא קוּדְשָׁא בְּרִיךְ הוּא עָלְמָא, הָכִי עָבֵד אָדָם וּבְהֵמָה.","וְאִי תֵּימָא וְהָא כְּתִיב (בראשית א׳:כ׳) וְעוֹף יְעוֹפֵף עַל הָאָרֶץ, דְּהָא מִנַּיְיהוּ מְקָרְבִין קָרְבְּנָא, וַאֲפִילּוּ עוֹלָה, כְּמָה דִּכְתִּיב וְאִם מִן הָעוֹף עוֹלָה קָרְבָּנוֹ. תָּא חֲזֵי, מִכָּל אִינּוּן עוֹפִין לָא מְקָרְבִין אֶלָּא מִן הַתּוֹרִים אוֹ בְּנֵי יוֹנָה. אֶלָּא רָזָא דָּא, מַה דְּאִתְכְּשַׁר בְּדָא, פָּסִיל בְּדָא. דָּא יְמִינָא, וְדָא שְׂמָאלָא, וְכֹלָּא חַד.","עוֹף יְעוֹפֵף עַל הָאָרֶץ, הָא אוֹקִימְנָא דְּאִינּוּן רָזָא דִּרְתִיכָא. וּבְהוּ תִּסְתָּלַּק רוּחַ הַקֹּדֶשׁ, לְסַלְּקָא לְעֵילָּא. דְּאִינּוּן תְּרֵי, חַד לִימִינָא, וְחַד לִשְׂמָאלָא. עוֹף לִימִינָא, וְדָא מִיכָאֵל. יְעוֹפֵף לִשְׂמָאלָא, וְדָא גַּבְרִיאֵל. דָּא לִימִינָא, וְדָא לִשְׂמָאלָא.","וּבְגִין כָּךְ מְקָרְבִין תְּרֵין אִלֵּין, לְסַלְּקָא רוּחַ קוּדְשָׁא, וּשְׂמָאלָא מְעַטֵּר וְזָיִין לְתַתָּא, לְהַהוּא סְטָר שְׂמָאלָא. וִימִינָא לִימִינָא. וְאִתְקַשְּׁרַת אִתְּתָא בְּבַעְלָהּ, לְמֶהֱוִי חַד. וְכֹלָּא מִסְתְּלַק וּמִתְקְשַׁר כַּחֲדָא, לְעֵילָּא וְתַתָּא וְקוּדְשָׁא בְּרִיךְ הוּא אִסְתַּלָּק בִּלְחוֹדוֹי וְאִתְתָּקַף.","וּבְסִפְרֵי קַדְמָאֵי, מִסְכְּנָא לָא יָהִיב חוּלָקָא לְאִתְּזְנָא, אֶלָּא לְעֵילָּא לְאִתְקַשְּׁרָא, אֲבָל כֹּלָּא לְעֵילָּא וְתַתָּא כָּל חַד מִתְקַשָּׁר לְסִטְרֵיהּ כְּדְקָא יֵאוֹת, וְהָא אוֹקִימְנָא.","(שמות רל\"ט ע\"ב) רִבִּי אֶלְעָזָר שָׁאִיל לְרַבִּי שִׁמְעוֹן אֲבוֹי וְאָמַר, הָא קִשּׁוּרָא דְּכֹלָּא אִתְקְשַׁר בַּקֹּדֶשׁ הַקֳדָשִׁים לְאִתְנַהֲרָא, אִתְדַּבְּקוּתָא דְּרַעֲוָא דְּכַהֲנֵי לֵיוָאֵי וְיִשְׂרָאֵל לְעֵילָּא, עַד הֵיכָן אִיהוּ סַלְּקָא.","אָמַר לֵיהּ הָא אוֹקִימְנָא, עַד אֵין סוֹף, דְּכָל קִשּׁוּרָא וְיִחוּדָא וּשְׁלִימוּ, לְאַצְנְעָא בְּהַהוּא צְנִיעוּ, דְּלָא אִתְדְּבַּק, וְלָא אִתְיְידַע, דְּרַעֲוָא דְּכָל רַעֲוִין בֵּיהּ. אֵין סוֹף לָא קַיְּימָא לְאוֹדָעָא, וְלָא לְמֶעְבַּד סוֹף, וְלָא לְמֶעְבַּד רֹאשׁ דְּאַיִן. (נ\"א ראש כמה דאין) קַדְמָאָה, אַפִּיק רֹאשׁ וְסוֹף, מַאן רֹאשׁ. דָּא נְקוּדָה עִלָּאָה, דְּאִיהִי רֵישָׁא דְּכֹלָּא סְתִימָאָה, דְּקַיְּימָא גּוֹ מַחֲשָׁבָה. וְעָבִיד סוֹף, דְּאִקְרֵי סוֹף דָּבָר, אֲבָל לְהָתָם אֵין סוֹף.","לָאו רְעוּתִין, לָאו נְהוֹרִין, לָאו בּוּצִינִין בְּהַהוּא אֵין סוֹף, כָּל אִלֵּין נְהוֹרִין וּבוּצִינִין תַּלְיָין לְאִתְקַיְּימָא בְּהוּ, וְלָא קַיְימֵי לְאִתְדַּבְּקָא, מַאן דְּיָדַע וְלָא יָדַע, לָאו אִיהוּ אֶלָּא רְעוּ עִלָּאָה סְתִימָאָה דְּכָל סְתִימִין, אַיִן.","וְכַד נְקוּדָה עִלָּאָה, וְעָלְמָא דְּאָתֵי, אִסְתְּלָקוּ, לָא יַדְעִין בַּר רֵיחָא, כְּמַאן דְּאָרַח בְּרֵיחָא וְאִתְבְּסָם, וְלָאו דָּא נַיְיחָא (ס\"א ניחח), דְּהָא כְּתִיב (ויקרא כ״ו:ל״א) וְלָא אָרִיחַ בְּרֵיחַ נִיחֹחֲכֶם, דְּהָא רֵיחַ נִיחֹחַ רֵיחָא דִּרְעוּתָא, דְּכָל הָנֵי רְעוּתָא דִּצְלוֹתָא, וּרְעוּתָא דְּשִׁירָתָא, וּרְעוּתָא דְּכַהֲנֵי, דְּכֻלְּהוּ רָזָא דְּאָדָם, כְּדֵין כֻּלְּהוּ אִתְעָבִידוּ רְעוּתָא חֲדָא, וְהַהוּא אִקְרֵי נִיחֹחַ, רְעוּתָא: כְּתַרְגוּמוֹ. כְּדֵין כֹּלָּא אִתְקְשַׁר וְאִתְנְהִיר כַּחֲדָא כְּדְקָא יֵאוֹת, כְּמָה דְּאִתְּמַר."],[[0,"ולבתר ברזא דבהמה וכו׳:","ואח״כ בסוד הבהמה, שמקריבים, מסתפקים ונזונים החיצונים, שיתקשר בקדושה רוח אחר שהוא בהם בתוך הטומאה, ע״י החלבים והשומן שמקריבים, כמו שלמדנו. ומשום זה, עולה היא קדש הקדשים, שאר הקרבנות הם לעשות שלום בעולם כולו, מכמה צדדים ובעלי הדין שבעולם, להעבירם, ולהאיר מתוך הרצון להתבשם. ונקראים קדשים קלים, משום שאינם מתעטרים למעלה למעלה בקדש הקדשים, שהוא בינה. וע\"כ הם קדשים קלים ושחיטתן בכל מקום. כמו שהעמידוהו. אבל עולה שהיא סוד קדש הקדשים, אינה כשאר הקרבנות כי כל מעשיה קדש."],[1,"ת״ח מה כתיכ וכו׳:","בוא וראה מה כתוב, ולבש הכהן מדו בד. אלו הם לבושים המיוחדים לקדושה. \u0003בד\u0004 הוא כמו בדד, דהיינו שמיוחד לקדושה. וכתוב, בגדי קדש הם ורחץ במים את בשרו ולבשם. מהו הטעם שהוא קדש. אלא סוד הדבר כמו שאמרנו, שהיא קדש קדשים, שעולה הכל ומתעטר בקדש הקדשים, שהוא בינה, בקשר אחד, ואח״כ נפנה ונעבר רוח הטומאה המטמא הכל ואינו שולט, ואינו קרב אל המקדש, ונעבר מכל הצדדים של הקדושה, ונשאר הכל קדש בקדושה לבד."],[2,"ואר״ש הא אתמר וכו׳:","ואמר ר׳ שמעון, הרי למדנו. שכתוב, אדם ובהמה תושיע ה'. וכך עולה סוד אדם מצד אדם, ע״י הרצון והתפלה, ובהמה, מצד הבהמה, שמוקרבת על המזבח, וע״כ כתוב, אדם כי יקריב מכם, אדם ודאי, שזה קרבנו, מרצון ומתפלה, למעלה לקשר קשר, בסוד אדם. ואח\"כ מן הבהמה, והכל הוא בכתוב, אדם ובהמה. וזה הוא סוד, שצריכים בקרבן אדם ובהמה. כמו שאמר. בוא וראה, כשברא הקב״ה את העולם עשה כך, אדם ובהמה."],[3,"ואי תימא והא וכו׳:","ואם תאמר הרי כתוב, ועוף יעופף על הארץ, שמהם מקריבים קרבנות ואפילו עולה, כמ״ש ואם מן העוף עולה קרבנו. הרי שבהמה אינה בדיוק. שתדרוש כנ״ל. ומשיב, בוא וראה, מכל העופות אין מקריבין אלא תורים ובני יונה, אלא סוד זה, מה שכשר בזה פסול בזה, שהאדום, כשר בתורים ופסול בבני יונה, (חולין כ״ב:) מטעם שזה. בני יונה, הוא ימין, וזה תורים הוא שמאל. וע״כ כשר בו אדום שהוא רומז על שמאל. והכל אחד."],[4,"עוף יעופף על הארץ:","הרי העמדנו, שהם סוד המרכבה, שהם המלאכים מיכאל גבריאל וכו', הנקראים עוף, ובהם עולה רוח הקודש, שהוא המלכות, לעלות למעלה לז״א, לזווג. שהם שנים, אחד לימין ואחד לשמאל, \u0003עוף\u0004 הוא לימין, וזה מיכאל. \u0003יעופף,\u0004 הוא לשמאל, וזה גבריאל. זה לימין וזה לשמאל."],[5,"ובג״כ מקרבין תרין וכו׳:","וע״כ מקריבים שנים אלו, תורים ובני יונה, שה״ס מיכאל וגבריאל, כדי להעלות, רוח הקודש שהוא המלכות, אל ז״א, והשמאל, דז״א מעטר ומזיין למטה לצד שמאל ההוא של המלכות, וימין לימין, ומתקשרת אשה בבעלה, דהיינו מלכות בז״א, להיות אחד. והכל מתעלה ומתקשר יחד למעלה ולמטה, והקב״ה מתעלה ונשגב בלבדו."],[6,"ובספרא קדמאי מסכנא וכו׳:","ובספרים הראשונים אמרו, העני, המקריב תורים ובני יונה, אינו נותן חלק, להזין העולמות, אלא ליחד למעלה. אבל הכל למעלה ולמטה כל אחד מתקשר אל הצד שלו כראוי. וכבר העמדנו."],[7,"רבי אלעזר שאיל וכו׳:","ר״א שאל את ר׳ שמעון אביו, ואמר, הרי קשר הכל נקשר בקדש הקדשים להאיר. שהיא בינה (כנ״ל אות ב׳). הדבקות של רצון הכהנים והלוים וישראל, עד אן היא עולה."],[8,"א״ל הא אוקימנא וכו׳:","א\"ל הרי העמדנו, שהדבקות שלהם עולה עד אין סוף, כי כל קשר ויחוד ושלמות הוא לגנוז בצניעות ההיא שאינה מושגת ולא נודע, אשר רצון כל הרצונות בו. אין סוף, אינו עומד להודע, ולא לעשות סוף, ולא לעשות ראש, ולא כמו \u0003אין,\u0004 שהוא כתר, הנקרא, אין, הראשון, שהוציא ראש וסוף. מי הוא ראש, זו היא נקודה העליונה, שהיא \u0003ראש\u0004 הכל הסתום, העומדת תוך המחשבה, שהיא חכמה הנקראת ראשית, והחכמה נאצלה מן הכתר שנקרא אין, בסו״ה והחכמה מאין תמצא (איוב כ״ח) ועשה \u0003סוף,\u0004 שהוא המלכות, הנקראת סוף דבר. אבל שמה, באין סוף, לא יש סוף."],[9,"לאו רעותין לאו וכו׳:","אין רצונות, ואין אורות, ואין נרות באין סוף, כל אלו האורות והנרות שבאצילות תלוים, באין סוף, שיתקיימו בהם, אבל אינם עומדים להשגה. מי שידוע ואינו ידוע, דהיינו שאפשר לדבר בו מבחינת ידיעה, אין הוא אלא רצון עליון הסתום מכל סתום הנקרא \u0003אין,\u0004 שהוא כתר, אבל בא״ס לא שייכת כלל ידיעה."],[10,"וכד נקודה עלאה וכו׳:","וכשנקודה העליונה, שהיא חכמה, ועולם הבא, שהוא בינה, מתעלים בהארתם, אינם יודעים רק \u0003ריח,\u0004 שה״ס ו״ק דחכמה המכונה ריח, ולא ג\"ר דחכמה, כמי שמריח בריח ומתבשם. ואין זה בחינת נחת, הנקרא ניחח. שהרי כתוב, ולא אריח בריח ניחחכם. הרי שריח וניחח הם שני דברים. כי ריח ניחח, פירושו ריח של הרצון, דהיינו כל אלו הרצונות של תפלה, ורצון השירה, ורצון הכהן, שכולם הם סוד אדם, (כנ״ל אות ו') אז נעשו כולם רצון אחד, וההוא, נקרא ניחח, דהיינו רצון כתרגומו. אז הכל נקשר ומאיר יחד כראוי, כמו שלמדנו."]],[[0,"","וְאַחַר כָּךְ מִסּוֹד שֶׁל הַבְּהֵמָה נֶהֱנִים וְנִזּוֹנִים לְהִתְקַשֵּׁר לְרוּחַ אַחֶרֶת, שֶׁהִיא בְּתוֹךְ הַטֻּמְאָה מֵאוֹתָם חֲלָבִים וְשֻׁמָּנִים, כְּמוֹ שֶׁנִּתְבָּאֵר. וּמִשּׁוּם כָּךְ עוֹלָה קֹדֶשׁ קָדָשִׁים, שְׁאָר הַקָּרְבָּנוֹת כֻּלָּם כְּדֵי לַעֲשׂוֹת שָׁלוֹם בָּעוֹלָם מִכַּמָּה צְדָדִים וּבַעֲלֵי דִינִים, לְהַעֲבִיר וְלִהְיוֹת נָאוֹר מִתּוֹךְ הָרָצוֹן לְהִתְבַּשֵּׂם, וְנִקְרָאִים קָדָשִׁים קַלִּים, מִשּׁוּם שֶׁלֹּא מִתְעַטְּרִים לְמַעְלָה לְמַעְלָה בְּקֹדֶשׁ הַקְּדָשִׁים. וְעַל זֶה הֵם קָדָשִׁים קַלִּים וּשְׁחִיטָתָם בְּכָל מָקוֹם, כְּמוֹ שֶׁבֵּאֲרוּהָ. אֲבָל הָעוֹלָה, שֶׁהִיא סוֹד שֶׁל קֹדֶשׁ הַקְּדָשִׁים, אֵינָהּ כִּשְׁאָר קָרְבָּנוֹת, שֶׁכָּל מַעֲשֶׂיהָ קֹדֶשׁ."],[1,"","בֹּא וּרְאֵה מַה כָּתוּב, וְלָבַשׁ הַכֹּהֵן מִדּוֹ בַד, הַלְּבוּשִׁים הַלָּלוּ מְיֻחָדִים לִקְדֻשָּׁה, בַד יְחִידִי, מְיֻחָד לִקְדֻשָּׁה. וְכָתוּב בִּגְדֵי קֹדֶשׁ הֵם וְרָחַץ בַּמַּיִם אֶת בְּשָׂרוֹ וּלְבֵשָׁם. מָה הַטַּעַם זֶה קֹדֶשׁ? אֶלָּא סוֹד הַדָּבָר, כְּמוֹ שֶׁאָמַר שֶׁהִיא קֹדֶשׁ קָדָשִׁים, שֶׁהַכֹּל עוֹלֶה וּמִתְעַטֵּר בְּקֹדֶשׁ הַקְּדָשִׁים בְּקֶשֶׁר אֶחָד, וְאַחַר כָּךְ מְפַנֶּה וּמַעֲבִיר רוּחַ טֻמְאָה, שֶׁמְּטַמֵּא הַכֹּל, שֶׁלֹּא יִשְׁלֹט וְלֹא יִקְרַב לְתוֹךְ הַמִּקְדָּשׁ, וּמָעֳבָר מִכָּל צִדְדֵי הַקְּדֻשָּׁה, וְהַכֹּל נִשְׁאָר קֹדֶשׁ בִּקְדֻשָּׁה יְחִידָה."],[2,"","וְאָמַר רַבִּי שִׁמְעוֹן, הֲרֵי נִתְבָּאֵר, שֶׁכָּתוּב (תהלים לד) אָדָם וּבְהֵמָה תוֹשִׁיעַ ה'. וְכָךְ עוֹלֶה סוֹד שֶׁל אָדָם מִצַּד שֶׁל אָדָם. בְּהֵמָה - מִצַּד שֶׁל בְּהֵמָה. וּמִשּׁוּם כָּךְ כָּתוּב אָדָם כִּי יַקְרִיב מִכֶּם, אָדָם וַדַּאי, שֶׁהֲרֵי קָרְבָּנוֹ לְמַעְלָה לִקְשֹׁר קֶשֶׁר, וְאַחַר מִן הַבְּהֵמָה. וְהַכֹּל הוּא בַּכָּתוּב - אָדָם וּבְהֵמָה. וְזֶהוּ סוֹד שֶׁצָּרִיךְ לְקָרְבָּן - אָדָם וּבְהֵמָה, כְּמוֹ שֶׁאָמַר. בּא רְאֵה, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, כָּךְ עָשָׂה - אָדָם וּבְהֵמָה."],[3,"","וְאִם תֹּאמַר, הֲרֵי כָּתוּב עוֹף יְעוֹפֵף עַל הָאָרֶץ, שֶׁהֲרֵי מֵהֶם מַקְרִיבִים קָרְבָּן, וַאֲפִלּוּ עוֹלָה, כְּמוֹ שֶׁכָּתוּב וְאִם מִן הָעוֹף עֹלָה קָרְבָּנוֹ - בֹּא רְאֵה, מִכָּל אוֹתָם עוֹפוֹת אֵין מַקְרִיבִים אֶלָּא מִן הַתּוֹרִים אוֹ בְּנֵי יוֹנָה, אֶלָּא סוֹד זֶה - מַה שֶּׁהֻכְשַׁר בָּזֶה, פָּסוּל בָּזֶה. זֶה יָמִין וְזֶה שְׂמֹאל, וְהַכֹּל אֶחָד."],[4,"","עוֹף יְעוֹפֵף עַל הָאָרֶץ, הֲרֵי בֵּאַרְנוּ שֶׁהֵם סוֹד הַמֶּרְכָּבָה, וּבָהֶם תִּתְעַלֶּה רוּחַ הַקֹּדֶשׁ לַעֲלוֹת לְמַעְלָה, שֶׁהֵם שְׁנַיִם, אֶחָד לְיָמִין וְאֶחָד לִשְׂמֹאל. הָעוֹף לְיָמִין, וְזֶה מִיכָאֵל. יְעוֹפֵף לִשְׂמֹאל, וְזֶה גַבְרִיאֵל. זֶה לְיָמִין, וְזֶה לִשְׂמֹאל."],[5,"","וּמִשּׁוּם כָּךְ מַקְרִיבִים שְׁנֵי אֵלֶּה, כְּדֵי לְהַעֲלוֹת אֶת רוּחַ הַקֹּדֶשׁ, וְהַשְּׂמֹאל מְעַטֵּר וּמֵזִין לְמַטָּה, לְאוֹתוֹ הַצַּד שֶׁל הַשְּׂמֹאל, וְיָמִין וְיָמִין, וְאִשָּׁה נִקְשֶׁרֶת לְבַעְלָהּ לִהְיוֹת אֶחָד, וְהַכֹּל מִתְעַלֶּה וּמִתְקַשֵּׁר כְּאֶחָד, לְמַעְלָה וּלְמַטָּה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מִתְעַלֶּה לְבַדּוֹ וּמִתְחַזֵּק."],[6,"","וּבַסְּפָרִים הַקַּדְמוֹנִים, הֶעָנִי לֹא נוֹתֵן חֵלֶק לְהָזִין אֶלָּא לְהִתְקַשֵּׁר לְמַעְלָה, אֲבָל הַכֹּל - לְמַעְלָה וּלְמַטָּה - כָּל אֶחָד נִקְשָׁר לְצִדּוֹ כָּרָאוּי, וַהֲרֵי בֵּאַרְנוּ."],[7,"","רַבִּי אֶלְעָזָר שָׁאַל אֶת רַבִּי שִׁמְעוֹן אָבִיו וְאָמַר, הֲרֵי הַקֶּשֶׁר שֶׁל הַכֹּל נִקְשָׁר בְּקֹדֶשׁ הַקְּדָשִׁים כְּדֵי לְהָאִיר, הִדָּבְקוּת שֶׁל הָרָצוֹן שֶׁל כֹּהֲנִים לְוִיִּם וְיִשְׂרְאֵלִים לְמַעְלָה, עַד הֵיכָן הִיא עוֹלָה?"],[8,"","אָמַר לוֹ, הֲרֵי בֵּאַרְנוּ, עַד אֵין סוֹף. שֶׁכָּל קֶשֶׁר וְיִחוּד וּשְׁלֵמוּת, לְהַצְנִיעַ בְּאוֹתָהּ צִנְעָה שֶׁאֵינָהּ מֻשֶּׂגֶת וְלֹא נוֹדַעַת שֶׁבָּהּ רְצוֹן כָּל הָרְצוֹנוֹת. אֵין סוֹף אֵינוֹ עוֹמֵד לְהִוָּדַע, וְלֹא לַעֲשׂוֹת סוֹף, וְלֹא לַעֲשׂוֹת רֹאשׁ שֶׁל אַיִן (ראשכמו שאין). הָרִאשׁוֹן הוֹצִיא רֹאשׁ וָסוֹף, מִי הָרֹאשׁ? זוֹ הַנְּקֻדָּה הָעֶלְיוֹנָה, שֶׁהִיא רֹאשׁ שֶׁל הַכֹּל הַנִּסְתָּר שֶׁעוֹמֶדֶת בְּתוֹךְ הַמַּחֲשָׁבָה. וְעוֹשָׂה סוֹף, שֶׁנִּקְרָא סוֹף דָּבָר, אֲבָל לְשָׁם אֵין סוֹף."],[9,"","אֵין רְצוֹנוֹת וְאֵין אוֹרוֹת וְאֵין נֵרוֹת בְּאוֹתוֹ אֵין סוֹף. כָּל הָאוֹרוֹת וְהַמְּאוֹרוֹת הַלָּלוּ תְּלוּיִים לְהִתְקַיֵּם בָּהֶם, וְלֹא עוֹמְדִים לְהַשָּׂגָה, מִי שֶׁיּוֹדֵעַ וְלֹא יוֹדֵעַ, אֵינוֹ אֶלָּא רָצוֹן עֶלְיוֹן נִסְתָּר שֶׁל כָּל הַנִּסְתָּריִם, אַיִן."],[10,"","וּכְשֶׁהַנְּקֻדָּה הָעֶלְיוֹנָה וְהָעוֹלָם הַבָּא הִתְעַלּוּ, אֵינָם יוֹדְעִים פְּרָט לְרֵיחַ, כְּמִי שֶׁהֵרִיחַ רֵיחַ וְהִתְבַּשֵּׂם, וְאֵין זֶה נַחַת (ניחח), שֶׁהֲרֵי כָּתוּב וְלֹא אָרִיחַ בְּרֵיחַ נִיחֹחֲכֶם, שֶׁהֲרֵי רֵיחַ נִיחֹחַ הוּא רֵיחַ שֶׁל רָצוֹן, שֶׁכָּל הָרְצוֹנוֹת הַלָּלוּ שֶׁל תְּפִלָּה, וְרָצוֹן שֶׁל שִׁירָה, וּרְצוֹן הַכֹּהֲנִים, שֶׁכֻּלָּם סוֹד שֶׁל אָדָם, אֲזַי כֻּלָּם נַעֲשִׂים רָצוֹן אֶחָד. וְהַהוּא נִקְרָא נִיחֹחַ, רָצוֹן כְּתַרְגּוּמוֹ. אָז הַכֹּל נִקְשָׁר וּמֵאִיר כְּאֶחָד כָּרָאוּי, כְּמוֹ שֶׁנִּתְבָּאֵר."]]],[["וְעַל דָּא אִתְיְהִיבַת הַאי סִטְרָא אָחֳרָא בִּידָא דְּכַהֲנָא, דִּכְתִּיב, צַו אֶת אַהֲרֹן וְאֶת בָּנָיו לֵאמֹר. רָזָא הָכָא, דְּהָא אוֹקִימְנָא, לֵית צַו אֶלָּא עֲבוֹדָה זָרָה. וְהָכָא אִתְיְיהִיבַת לֵיהּ לְאִתּוֹקְדָא הַהוּא מַחֲשָׁבָה רָעָה, וּלְאַעְבְּרָא לָהּ מִגּוֹ קוּדְשָׁא, בְּהַאי רְעוּתָא דְּסַלְּקָא לְעֵילָּא, וּבְהַאי תְּנָנָא וְתַרְבִּין דְּאִתּוֹקְדָן, בְּגִין לְאִתְעַבְּרָא מִן קוּדְשָׁא, וְהַאי צַו בִּרְשׁוּתַיְיהוּ קַיְּימָא, לְאַפְרְשָׁא לָהּ מִן קוּדְשָׁא מִגּוֹ הַאי קָרְבְּנָא וְאִי תֵּימָא צַו אֶת בְּנֵי יִשְׂרָאֵל, הָכִי נָמֵי דְּהָא בִּרְשׁוּתַיְיהוּ קַיְּימָא, (ס\"א לאפרשא לה מן קודשא) כָּל זִמְנָא דְּעַבְדֵי רְעוּתָא דְּמָארֵיהוֹן, דְּלָא יַכְלָא לְשַׁלְּטָאָה עָלַיְיהוּ.","וְהַאי קְרָא כֹּלָּא אַתְיָא לְאַחֲזָאָה רָזָא דְּמִלָּה, לְאַעְטְּרָא לְהַאי רוּחַ קוּדְשָׁא לְעֵילָּא לְעֵילָּא, וּלְאַפְרְשָׁא לָהּ לְדָא רוּחַ טוּמְאָה, לְנַחְתָּא לָהּ לְתַתָּא לְתַתָּא. דָּא בִּרְעוּתָא וּבִצְלוֹתָא כִּדְקָאָמַרָן, וְדָא בְּעוֹבָדָא כֹּלָּא כִּדְקָחֲזֵי לֵיהּ.","וְהַאי קְרָא מוֹכָחָא עָלַיְיהוּ, דִּכְתִּיב צַו אֶת אַהֲרֹן וְאֶת בָּנָיו לֵאמֹר. צַו: דָּא עֲבוֹדָה זָרָה, רוּחַ מִסְאֲבָא. (בראשית ל\"ח, נ\"ח, ס') לֵאמֹר: דָּא אִתְּתָא, דְּאִקְרֵי יִרְאַת יְיָ'. כְּתִיב הָכָא לֵאמֹר, וּכְתִיב הָתָם (ירמיהו ג׳:א׳) לֵאמֹר הֵן יְשַׁלַּח אִישׁ אֶת אִשְׁתּוֹ. וְהָא אוֹקְמוּהָ. בְּגִין כָּךְ כֹּלָּא אִתְּמַר, וְכַהֲנָא קַיְּימָא לְאִתְתַּקְנָא כֹּלָּא בְּרָזָא דְּאָדָם וּבְהֵמָה.","זַכָּאָה חוּלָקֵיהוֹן דְּצַדִּיקַיָּיא בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי, דְּאִינּוּן יַדְעֵי אוֹרְחֵי דְּאוֹרַיְיתָא, וְאַזְלֵי בָּהּ בְּאֹרַח קְשׁוֹט, עָלַיְיהוּ כְּתִיב (ישעיהו ל״ח:ט״ז) יְיָ' עֲלֵיהֶם יִחְיוּ. מַאן עֲלֵיהֶם. אִלֵּין אָרְחֵי דְּאוֹרַיְיתָא. יִחְיוּ: יִתְקַיְּימוּן, בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי.","תָּא חֲזֵי, כְּתִיב זֹאת תּוֹרַת הָעוֹלָה, אָמַר רִבִּי חִיָיא, הַאי קְרָא אוֹקִימְנָא לֵיהּ בְּהַאי גַּוְונָא, (זאת תורת, דא כנסת ישראל. העולה: דהיא סלקא, ומתעטרא לעילא לעילא, לאתקשרא כדקא יאות, עד אתר דאקרי קדש קדשים.)","(דבר אחר) זֹאת תּוֹרַת, דָּא כְּנֶסֶת יִשְׂרָאֵל. הָעוֹלָה: דָּא מַחֲשָׁבָה רָעָה, דְּאִיהִי סַלְּקָא עַל רְעוּתָא דְּבַּר נָשׁ לְאַסְטָאָה לֵיהּ מֵאֹרַח קְשׁוֹט, הִיא הָעוֹלָה, הִיא דְּסַלְּקָא וְאַסְטִיאַת לֵיהּ לְבַר נָשׁ, וּבָעֵי לְאוֹקְדָא לָהּ בְּנוּרָא. בְּגִין דְּלָא יִתְיְיהִיב לָהּ דּוּכְתָּא לְאַסְטָאָה.","וּבְגִין כָּךְ, עַל מוֹקְדָה עַל הַמִּזְבֵּחַ כָּל הַלַּיְלָה. מַאן לַיְלָה. דָּא כְּנֶסֶת יִשְׂרָאֵל. דְּאִיהִי זֹאת, בְּגִין דְּאָתֵי לְדַכְּאָה לְבַּר נָשׁ מֵהַהוּא רְעוּתָא. עַל מוֹקְדָה, בְּגִין דְּנָהַר דִּינוּר אִיהוּ אֲתַר לְאוֹקְדָא לְכָל אִינּוּן דְּלָא קַיְימֵי בְּקִיּוּמַיְיהוּ, דְּהָא עָאלִין לוֹן בְּהַהוּא נוּרָא דְּדָלִיק, וּמְעַבְּרֵי שׁוּלְטָנֵיהוֹן מֵעָלְמָא, וּבְגִין דְּלָא יִשְׁלוֹט, אִצְטְרִיךְ עַל מוֹקְדָה עַל הַמִּזְבֵּחַ כָּל הַלַּיְלָה, וְאִתְכַּפְיָא וְלָא שַׁלְטָא.","וְעַל דָּא, כַּד אִתְכַּפְיָא הַאי, סַלְּקָא כְּנֶסֶת יִשְׂרָאֵל, דְּאִיהִי רוּחַ קוּדְשָׁא, דְּסַלְּקָא וְאִתְעַטְּרָא לְעֵילָּא, דְּהָא סְלִיקוּ דִּילָהּ, כַּד אִתְכַּפְיָא הַאי חֵילָא אָחֳרָא, וְאִתְפְּרַשׁ מִנָּהּ. וּבְגִין כַּךְ בָּעֵינָן בְּרָזָא דְּקָרְבְּנָא, לְאַפְרְשָׁא לְהַאי סִטְרָא, מֵרוּחַ קוּדְשָׁא, וּלְמֵיהַב לָהּ חוּלָקָא, בְּגִין דְּרוּחַ קוּדְשָׁא תִּסְתָּלַּק לְעֵילָּא.","רִבִּי אֲחָא פָּתַח וְאָמַר, וְהָאֵשׁ עַל הַמִּזְבֵּחַ תּוּקַד בּוֹ וְגוֹ', וְהָאֵשׁ עַל הַמִּזְבֵּחַ תּוּקַד בּוֹ, אֲמַאי. וּבִעֵר עָלֶיהָ הַכֹּהֵן עֵצִים בַּבֹּקֶר בַּבֹּקֶר, אֲמַאי. וְכַהֲנָא אֲמַאי. וְהָא תָּנֵינָן אֶשָּׁא בְּכָל אֲתַר דִּינָא הוּא, וְכַהֲנָא מִסִּטְרָא דִּימִינָא קָא אָתֵי, וּרְחִיקָא הוּא מִן דִּינָא, דְּהָא כַּהֲנָא לָא אִזְדְּמַן בְּדִינָא לְעָלְמִין, וְהָכָא הוּא בָּעֵי לְאוֹקְדָא דִּינָא בְּעָלְמָא, דִּכְתִּיב וּבִעֵר עָלֶיהָ הַכֹּהֵן."],[[0,"ועל דא אתיהיבת וכו׳:","ועל כן ניתן צד האחר הזה ביד הכהן, שכתוב, צו את אהרן ואת בניו לאמר. ויש סוד כאן, כי העמדנו, שאין \u0003צו,\u0004 אלא ע״ז, דהיינו סטרא אחרא, וכאן ניתן לו לשרוף את המחשבה הרעה ההיא, ולהעבירה מן הקדושה ברצון הזה שעולה למעלה, ובעשן הזה, ובחלבים הנשרפין, כדי שיהיו נעברים מן הקדש, ו \u0003צו\u0004 ההוא, שהוא הסטרא אחרא, עומד ברשותם להפרידו מן הקדש על ידי הקרבן הזה. ואם תאמר, \u0003צו את בני ישראל,\u0004 איך אפשר לפרש שצו הוא הסטרא אחרא, ומשיב, אף כאן פירושו, שהסטרא אחרא עומד ברשותם, שכל זמן שישראל עושים רצונו של אדונם אין הסטרא אחרא יכול לשלוט עליהם."],[1,"והאי קרא כלא וכו׳:","ומקרא הזה, צו את אהרן, בא להראות סוד הדבר, לעטר רוה״ק הזה למעלה למעלה, ולהפריד את רוח הטומאה להורידה למטה למטה, זה, דהיינו ישראל, ברצון ותפלה, כמו שאמרנו. וזה, דהיינו הכהנים, במעשה הקרבת הקרבן, כל אחד כראוי לו."],[2,"והאי קרא מוכחא וכו׳:","ומקרא הזה מוכיח עליהם שכתוב, צו את אהרן ואת בניו לאמר. \u0003צו\u0004 זהו עבודה זרה, רוח הטומאה. \u0003לאמר,\u0004 זו אשה הנקראת יראת ה׳, דהיינו המלכות. כי כתוב כאן לאמר, וכתוב שם, לאמר הן ישלח איש את אשתו, מה שם, לאמר, סובב על אשה, אף לאמר שבכאן הוא אשה. וכבר העמדנו. ומשום זה הכל נאמר, במקרא הזה, דהיינו לעטר את המלכות, ולהוריד הסט״א והכהן עומד לתקן את הכל בסוד אדם ובהמה, (כנ״ל אות ו׳)."],[3,"זכאה חולקהון וכו׳:","אשרי חלקם של הצדיקים, בעולם הזה ובעולם הבא שהיו יודעים דרכי התורה והולכים בה בדרך אמת, עליהם כתוב, \u0003ה׳ עליהם יחיו,\u0004 מי הם, \u0003עליהם.\u0004 אלו הם דרכי התורה. \u0003יחיו,\u0004 היינו שיתקיימו בעולם הזה ובעולם הבא."],[4,"ת״ח כתיב זאת וכו׳:","בוא וראה, כתוב, זאת תורת העולה. א״ר חייא מקרא זה העמדתי אותו באפן זה. \u0003זאת תורת,\u0004 זו היא כנסת ישראל, דהיינו המלכות. \u0003העולה,\u0004 כי היא עולה ומתעטרת למעלה למעלה להתקשר כראוי עד המקום שנקרא קודש הקדשים. שהוא בינה."],[5,"ד״א זאת תורת וגו׳:","פירוש אחר, \u0003זאת תורת\u0004 זו היא כנסת ישראל, מלכות, \u0003העולה,\u0004 זו היא מחשבה רעה, שהיא עולה על מחשבתו של האדם להטותו מן דרך האמת, \u0003היא העולה,\u0004 זו היא העולה ומשטנת על האדם, וצריכים לשרפה באש, כדי שלא לתת לו מקום להשטין."],[6,"ובג״כ על מוקדה וכו׳:","ומשום זה על מוקדה על המזבח כל הלילה. מי הוא לילה. הוא כנסת ישראל, מלכות, שהיא זאת, הבאה לטהר את האדם מאותו הרצון. \u0003על מוקדה,\u0004 משום שנהר דינור הוא מקום לשרוף כל אלו שאינם נמצאים בקיומם, דהיינו הסטרא אחרא. כי מביאים אותם באש ההוא השורף, ומעבירים ממשלתם מן העולם. וכדי שלא ישלוט, צריך, על מוקדה על המזבח כל הלילה, ואז נכנע ואינו שולט."],[7,"ועל דא כד וכו׳:","וע\"כ כשזה, הס\"א, נכנע, עולה כנסת ישראל, מלכות, שהיא רוח הקודש, כי עולה ומתעטרת למעלה, כי העליה שלה, היא בעת שנכנע הכח האחר הזה ונפרד ממנה. ומשום זה צריכים בסוד הקרבן, להפריד את הצד ההוא, הס״א, מן רוח הקודש, שהוא המלכות, ולתת לה חלק (כנ״ל פקודי אות של״ג) כדי שרוח הקודש יתעלה למעלה."],[8,"רבי אבא פתח וכו׳:","רא\"פ ואמר, והאש על המזבח תוקד בו וגו'. שואל, והאש על המזבח תוקד בו, למה. ובער עליה הכהן עצים בבקר בבקר, למה. וכהן, למה יבעיר עצים על האש, והרי למדנו, שאש בכל מקום הוא דין, והכהן בא מצד ימין, והוא רחוק מן הדין, שהכהן אינו מזדמן בדין לעולם, וכאן הוא צריך להבעיר הדין בעולם, דהיינו שצריך להבעיר העצים, שכתוב, ובער עליה הכהן."]],[[0,"","וְעַל כֵּן נִתָּן הַצַּד הָאַחֵר בְּיַד הַכֹּהֵן, שֶׁכָּתוּב צַו אֶת אַהֲרֹן וְאֶת בָּנָיו לֵאמֹר. סוֹד כָּאן, שֶׁהֲרֵי בֵּאַרְנוּ, אֵין צַו אֶלָּא עֲבוֹדָה זָרָה. וְכָאן נִתָּן לוֹ לִשְׂרֹף אֶת אוֹתָהּ מַחֲשָׁבָה רָעָה וּלְהַעֲבִירָהּ מִתּוֹךְ הַקֹּדֶשׁ בָּרָצוֹן הַזֶּה שֶׁעוֹלֶה לְמַעְלָה, וּבֶעָשָׁן הַזֶּה וּבַחֲלָבִים שֶׁנִּשְׂרָפִים, כְּדֵי שֶׁיָּעָבְרוּ מִן הַקֹּדֶשׁ, וְהַצַּו הַזֶּה עוֹמֵד בִּרְשׁוּתָם לְהַפְרִידוֹ מִן הַקֹּדֶשׁ מִתּוֹךְ הַקָּרְבָּן הַזֶּה. וְאִם תֹּאמַר, צַו אֶת בְּנֵי יִשְׂרָאֵל - כָּךְ גַּם שֶׁהֲרֵי בִּרְשׁוּתָם עוֹמֵד (להפריש אותה מן הקדשה) כָּל זְמַן שֶׁעוֹשִׂים רְצוֹן רִבּוֹנָם, שֶׁלֹּא יוּכַל לִשְׁלֹט עֲלֵיהֶם."],[1,"","וְהַפָּסוּק הַזֶּה הַכֹּל בָּא לְהַרְאוֹת סוֹד הַדָּבָר, לְעַטֵּר אֶת רוּחַ הַקֹּדֶשׁ לְמַעְלָה לְמַעְלָה, וּלְהַפְרִיד אֶת רוּחַ הַטֻּמְאָה וּלְהוֹרִידָהּ לְמַטָּה לְמַטָּה, וְזֶה בְּרָצוֹן וּבִתְפִלָּה כְּפִי שֶׁאָמַרְנוּ, וְזֶה בְּמַעֲשֶׂה, הַכֹּל כְּמוֹ שֶׁרָאוּי לוֹ."],[2,"","וְהַכָּתוּב הַזֶּה מוֹכִיחַ עֲלֵיהֶם, שֶׁכָּתוּב צַו אֶת אַהֲרֹן וְאֶת בָּנָיו לֵאמֹר. צַו - זוֹ עֲבוֹדָה זָרָה, רוּחַ הַטֻּמְאָה. לֵאמֹר - זוֹ הָאִשָּׁה, שֶׁנִּקְרֵאת יִרְאַת ה'. כָּתוּב כָּאן לֵאמֹר, וְכָתוּב שָׁם (ירמיה ג) לֵאמֹר הֵן יְשַׁלַּח אִישׁ אֶת אִשְׁתּוֹ, וַהֲרֵי פֵּרְשׁוּהָ. מִשּׁוּם כָּךְ הַכֹּל נֶאֱמַר, וְהַכֹּהֵן עוֹמֵד לְתַקֵּן אֶת הַכֹּל בְּסוֹד שֶׁל אָדָם וּבְהֵמָה."],[3,"","אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, שֶׁהֵם יוֹדְעִים אֶת דַּרְכֵי הַתּוֹרָה וְהוֹלְכִים בָּהּ בְּדֶרֶךְ אֱמֶת, עֲלֵיהֶם כָּתוּב (ישעיה לא) ה' עֲלֵיהֶם יִחְיוּ. מִי עֲלֵיהֶם? אֵלּוּ דַּרְכֵי הַתּוֹרָה. יִחְיוּ - יִתְקַיְּמוּ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא."],[4,"","בֹּא רְאֵה, כָּתוּב זֹּאת תּוֹרַת הָעֹלָה. אָמַר רַבִּי חִיָּיא, הַפָּסוּק הַזֶּה בֵּאַרְנוּהוּ בַּצּוּרָה הַזּוֹ: (זאת תורת זו כנסת ישראל. העלה שהיא עולה ומתעטרת למעלה למעלה להתקשר כראוי, עד המקום שנקרא קדש קדשים)."],[5,"","(דבר אחר) זֹּאת תּוֹרַת - זוֹ כְּנֶסֶת יִשְׂרָאֵל. הָעֹלָה - זוֹ מַחֲשָׁבָה רָעָה שֶׁהִיא עוֹלָה עַל רְצוֹנוֹ שֶׁל הָאָדָם לְהָסִיט אוֹתוֹ מִדֶּרֶךְ אֱמֶת. הִיא הָעֹלָה - הִיא שֶׁעוֹלָה וּמַשְׂטִינָה עַל הָאָדָם, וְצָרִיךְ לִשְׂרֹף אוֹתָהּ בָּאֵשׁ כְּדֵי לֹא לָתֵת לָהּ מָקוֹם לְהַשְׂטִין."],[6,"","וּמִשּׁוּם כָּךְ, עַל מוֹקְדָה עַל הַמִּזְבֵּחַ כָּל הַלַּיְלָה. מִי הַלַּיְלָה? זוֹ כְּנֶסֶת יִשְׂרָאֵל, שֶׁהִיא זֹּאת, מִשּׁוּם שֶׁבָּאָה לְטַהֵר אֶת הָאָדָם מֵאוֹתוֹ רָצוֹן. עַל מוֹקְדָה, מִשּׁוּם שֶׁנְּהַר דִּינוּר הוּא מָקוֹם לִשְׂרֹף כָּל אֵלּוּ שֶׁלֹּא עוֹמְדִים בְּקִיּוּמָם, שֶׁהֲרֵי מַכְנִיסִים אוֹתָם בְּאוֹתָהּ אֵשׁ בּוֹעֶרֶת וּמַעֲבִירִים אֶת שִׁלְטוֹנָם מִן הָעוֹלָם, וּכְדֵי שֶׁלֹּא יִשְׁלֹט, צָרִיךְ עַל מוֹקְדָה עַל הַמִּזְבֵּחַ כָּל הַלַּיְלָה, וְנִכְנָע וְלֹא שׁוֹלֵט."],[7,"","וְלָכֵן, כְּשֶׁזֶּה נִכְנָע, עוֹלָה כְּנֶסֶת יִשְׂרָאֵל, שֶׁהִיא רוּחַ הַקֹּדֶשׁ שֶׁעוֹלָה וּמִתְעַטֶּרֶת לְמַעְלָה, שֶׁהֲרֵי עֲלִיָּתָהּ זֶה כְּשֶׁנִּכְנָע הַכֹּחַ הָאַחֵר הַזֶּה וְנִפְרָד מִמֶּנָּה, וְלָכֵן צְרִיכִים בְּסוֹד הַקָּרְבָּן, לְהַפְרִיד אֶת הַצַּד הַזֶּה מֵרוּחַ הַקֹּדֶשׁ, וְלָתֵת לוֹ חֵלֶק, כְּדֵי שֶׁרוּחַ הַקֹּדֶשׁ תִּתְעַלֶּה לְמַעְלָה."],[8,"","רַבִּי אָחָא פָּתַח וְאָמַר, וְהָאֵשׁ עַל הַמִּזְבֵּחַ תּוּקַד בּוֹ וְגוֹ'. וְהָאֵשׁ עַל הַמִּזְבֵּחַ תּוּקַד בּוֹ, לָמָּה? וּבִעֵר עָלֶיהָ הַכֹּהֵן עֵצִים בַּבֹּקֶר בַּבֹּקֶר, לָמָּה? וְכֹהֵן לָמָּה? וַהֲרֵי שָׁנִינוּ שֶׁאֵשׁ בְּכָל מָקוֹם הִיא דִּין, וְהַכֹּהֵן בָּא מִצַּד הַיָּמִין, וְרָחוֹק הוּא מִן הַדִּין, שֶׁהֲרֵי אֵין כֹּהֵן מִזְדַּמֵּן לְדִין לְעוֹלָמִים, וְכָאן הוּא צָרִיךְ לִשְׂרֹף דִּין בָּעוֹלָם, שֶׁכָתוּב וּבִעֵר עָלֶיהָ הַכֹּהֵן?"]]],[["אֶלָּא הָכִי אוֹלִיפְנָא, בַּר נָשׁ דְּאָתֵי לְמֶחטֵי קָמֵי מָארֵיהּ, הוּא אוֹקִיד גַּרְמֵיהּ בְּשַׁלְהוֹבִיתָא דְּיֵצֶר הָרָע. וְיֵצֶר הָרָע מִסִּטְרָא דְּרוּחַ מִסְאֲבָא קָא אַתְיָא, וְהָא שַׁרְיָא בֵּיהּ רוּחַ מִסְאֲבָא. וּלְזִמְנִין אִשְׁתְּמוֹדְעָן קָרְבָּנֵי דְּאַתְיָין מֵהַאי סִטְרָא, וּבָעָא לְקָרְבָא עַל מַדְבְּחָא כִּדְדָמֵי לֵיהּ. וְלָא אִשְׁתְּצֵי, וְלָא אִתְבְּטַל הַהוּא רוּחַ מִסְאֲבָא, בֵּין מִבַּר נָשׁ, וּבֵין מֵהַהוּא סִטְרָא דְּאָתֵי מִנֵּיהּ, אֶלָּא בְּאֶשָּׁא דְּמַדְבְּחָא, דְּהַהוּא אֶשָּׁא מְבָעֲרָא רוּחַ מִסְאֲבָא, וְּזִינִין בִּישִׁין מֵעָלְמָא, וְכַהֲנָא בְּדָא אִתְכְּוָון, לְתַקְּנָא אֶשָּׁא דִּיבָעֵר זִינִין בִּישִׁין מֵעָלְמָא.","וְעַל דָּא בָּעֵי, דְּלָא יִדְעַכוּן לֵיהּ לְעָלְמִין, וְלָא יִתְחֲלֵשׁ חֵילָא וְתּוּקְפָּא דִּילֵיהּ, לְתַּבְרָא חֵילָא דְּתּוּקְפָּא אָחֳרָא בִּישָׁא מֵעָלְמָא, וְעַל דָּא לֹא תִכְבֶּה. וְכַהֲנָא יְסַדֵר עָלֵיהּ אֶשָּׁא בַּבֹּקֶר בַּבֹּקֶר, בְּזִמְנָא דְּשַׁלְטָא סִטְרָא דִּילֵיהּ וְאִתְּעַר בְּעָלְמָא, בְּגִין לְבַסְּמָא עָלְמָא (ס\"א ולבסמא דינא), וְאִתְכַּפְיָין דִּינִין, וְלָא מִתְעָרֵי בְּעָלְמָא, וְעַל דָּא תָּנֵינָן, אִית אֶשָּׁא אַכְלָא אֶשָּׁא. אֶשָּׁא דִּלְעֵילָּא אַכְלָא אֶשָּׁא אָחֳרָא, אֶשָּׁא דְּמַדְבְּחָא אַכְלָא אֶשָּׁא אָחֳרָא, וְעַל דָּא, אֶשָּׁא דָּא לָא תִכְבֶּה לְעָלְמִין, וְכַהֲנָא מְסַדֵּר לֵיהּ בִּכָל יוֹמָא.","\u0003רעיא מהימנא\u0004 פִּקּוּדָא לַעֲשׂוֹת הָעוֹלָה כְּמִשְׁפָּטָהּ, וְעָלָהּ אִתְּמַר זֹאת תּוֹרַת הָעוֹלָה וְגוֹ'. חָמֵשׁ אִשִׁים הֲווֹ נַחְתִּין עַל קָרְבְּנָא. אֵשׁ אוֹכֵל וְאֵינוֹ שׁוֹתֶה. אֵשׁ שׁוֹתֶה וְאֵינוֹ אוֹכֵל. אֵשׁ אוֹכֵל וְשׁוֹתֶה. אֵשׁ אוֹכֵל לַחִים ויבֵשִׁים. אֵשׁ שֶׁאֵינוֹ אוֹכֵל וְאֵינוֹ שׁוֹתֶה. לָקֳּבְלַיְיהוּ אִינּוּן, זֹאת תּוֹרַת הָעוֹלָה, חַד. הִיא הָעוֹלָה עַל מוֹקְדָה, ב'. עַל הַמִּזְבֵּחַ, ג'. כָּל הַלַּיְלָה, ד'. וְאֵשׁ הַמִּזְבֵּחַ תּוּקַד בּוֹ ה'.","וְאוּקְמוּהָ מָארֵי מַתְנִיתִין, עוֹלָה כּוּלָהּ סַלְּקָא לַגָּבוֹהַּ. וְדָא בִּינָה, ה', ה' מַרְאוֹת דִּילָהּ. י', בַּת יְחִידָה, (שמות כ״ד:י״ז) וּמַרְאֶה כְּבוֹד יְיָ' כְּאֵשׁ אוֹכֶלֶת. ו' אוֹר דְּבַת עֵינָא, וְהִיא אֵשׁ שׁוֹתֶה כָּל מַיִין דְּאוֹרַיְיתָא, וְאוֹכֶלֶת כָּל קָרְבְּנִין דִּצְּלוֹתָא. וְאוֹכֶלֶת לַחִין וִיבֵשִׁין, אִינּוּן פְּשָׁטֵי דְּאוֹרַיְיתָא דְּאִינּוּן כְּעֵצִּים יְבֵשִׁים. וְרָזִי אוֹרַיְיתָא אִינּוּן כְּעֵצִּים לַחִים. וְהַאי אִיהוּ אֵשׁ אוֹכֶלֶת לַחִין וִיבֵשִׁין.","וְעוֹד אוֹכֶלֶת לַחִין, כָּל קָרְבְּנִין דַּהֲווֹ קְרֵבִין בִּצְּלוֹתָא, עַל מִצְּוֹת עֲשֵׂה. וִיבֵשִׁין, כָּל קָרְבְּנִין דַּהֲווֹ קְרֵבִין בִּצְּלוֹתָא, עַל מִצְּוֹת לֹא תַּעֲשֶׂה. וְהַאי אִיהוּ, סְקִילָה שְׂרֵיפָה הֶרֶג וְחֶנֶק, עַל מִצְּוֹת עֲשֵׂה, וְעַל מִצְּוֹת לֹא תַּעֲשֶׂה, אִלֵּין אִינּוּן קָרְבְּנַיָּא דִּשְׁכִינְתָּא, צְּלוֹתָא, דְּפִקּוּדִין דַּעֲשֵׂה וְלָא תַּעֲשֶׂה. וְלָקֳבֵל ה' מַרְאוֹת אִלֵּין, תַּקִּינוּ חֲמֵשׁ צְּלוֹתֵי בְּיוֹמָא דְּכִפּוּרֵי. וְלָקֳבֵל בַּת עֵינָא, אִינּוּן עֲשֶׂרֶת יְמֵי הַתְּשׁוּבָה ה' לָקֳבֵל אוֹר דְּבַת עֵינָא. ה' עִנּוּיִין, לָקֳבֵל ה' בַּתְרָאָה.","פִּקּוּדָא בָּתַר דָּא, לַעֲשׂוֹת הַחַטָאת כְּמִשְׁפָּטָהּ. תַּנָּאִים וַאֲמוֹרָאִים, אַתּוּן דְּמִסִטְרָא דְּמִדוֹת דְּקוּדְשָׁא בְּרִיךְ הוּא אַתִיתוּ, דְּטַרְחֲתוּן סַגֵּי לְנַקָּאָה בְּרַתָּא דִּילִי דְּאִיהִי הֲלָכָה, מֵאִלֵּין קְלִיפִין, דְּעֵרֶב רַב, קוּשְׁיָין בִּישִׁין, דְּלֵית לוֹן תִּירוּץ, וְלָא פִּרוֹקָא, דְּעָלַיְיהוּ אִתְּמַר, (קהלת א׳:ט״ו) מְעֻוָּת לֹא יוּכַל לִתְקוֹן, וְחֶסְרוֹן לֹא יוּכַל לְהִמָּנוֹת, אֶלָּא אִתְּמַר תִּיקוּ בְּהוֹן. וְכָל תִּיקוּ דְּאִסוּרָא לְחוּמְרָא, וְאִיהוּ תִּיקוּ חָסֵר ן' דְּלֵית לֵיהּ תִּקּוּן. חָסֵר נוּן, דְּאִיהִי עָלְמָא דְּאָתֵי, דְּתִיקוּ דְּעָלְמָא דְּאָתֵי, שְׁתִיקָה. כְּגוֹן שְׁתוֹק כַּךְ עָלָה בְּמַחֲשָׁבָה.","וְאִית קוּשְׁיָין דְּאִינּוּן לְבוּשִׁין דַּהֲלָכָה, דְּאִתְּמַר בְּהוֹן מִשְׁבְּצּוֹת זָהָב. הֲדָא הוּא דִכְתִיב, (תהילים מ״ה:י״ד) כָּל כְּבוּדָּה בַּת מֶלֶךְ פְּנִימָה מִמִּשְׁבְּצּוֹת זָהָב לְבוּשָׁהּ. וְאַתּוּן, פַּסְקִין לוֹן בְּכַמָּה פְּסָקוֹת, וּלְבָתַר מְתַקְּנִין וּמְפָרְקִין לוֹן בְּכַמָּה פִּרוּקִין.","וְאִי חָסֵר שׁוּם פְּסָק מִמַּתְנִיתִין, כְּמָּה דְּאוּקְמוּהָ זְה חָסֵר מִן הַמִּשְׁנָה, אַתּוּן מְתַקְּנִין לוֹן, וְהַאי הוּא חֶסְרוֹן שֶׁיוּכַל לְהִמָּנוֹת. וְאִי יִיתֵי טִפֵּשׁ וְיַפִּיק שׁוּם בִּישׁ עַל הַהוּא אוּמָנָא דְּחָתִיךְ לְבוּשִׁין, וְיִימָא וְכִי אוֹרַיְיתָא אִיהִי חָסֵר, וְהָא כְּתִיב (תהלים יט) תּוֹרַת יְיָ' תְּמִימָה, תְּמִימָה בְּכָל אֵבָרִין דְּגוּפָא, דְּאִינּוּן רמ\"ח פִּקוּדִין. הֲדָא הוּא דִכְתִיב, (שיר השירים ד׳:ז׳) כֻּלָּךְ יָפָה רַעְיָתִי וּמוּם אֵין בָּךְ. תְּמִימָה בִּלְבוּשָׁהָא, וְאֵיךְ חָסֵר מִן הַמִּשְׁנָה.","אַתּוּן תֵּימְרוּן לֵיהּ, דּוֹק וְתִשְׁכַּח חֲתִיכָה, וְתִשְׁכַּח לָהּ מְעוּרֶבֶת בִּשְׁאָר פְּסָקוֹת וּמִשְׁנָיוֹת. דְּאוֹרַח אוּמָנָא לְמֶחְתַּךְ לְבוּשִׁין בְּכַמָּה חֲתִיכוֹת, וְתַלְמִיד דְּלָאו אִיהוּ בָּקִי לְמִקְשַׁר הַהֲלָכָה בְּאִלֵּין חֲתִיכוֹת, מִתְחַלְּפֵי לֵיהּ פְּסָקוֹת וְקוּשְׁיָין, וְלָא אַשְׁכַּח לוֹן פִּרוּקָא. עַד דְּיִיתֵי אוּמָנָא, וּפָרִיק לוֹן כָּל אִלֵּין סְפֵקוֹת דִּלְהוֹן. בְּהַהוּא זִמְנָא, הֲלָכָה דְּאִיהִי בְּרַתָּא, סְלִיקַת קֳדָם מַלְכָּא, שְׁלֵימָא בְּכֹלָּא, בְּגוּפָא בִּלְבוּשָׁא וּבְתַכְשִׁיטָהָא, וְאִתְקָיָּים בָּהּ (בראשית ט׳:ט״ז) וּרְאִיתִיהָ לִזְכּוֹר בְּרִית עוֹלָם. וּלְזִמְנִין אִית לְאוּמָנָא תַּלְמִיד בָּקִי, דִּישָׁדֵּר לֵיהּ לְתַקְּנָא לוֹן.","קָמוּ כֻּלְּהוּ וְאָמְרוּ, וַדַּאי אַנְתְּ הוּא אוּמָנָא רַעְיָא מְהֵימְנָא. דְּאִתְּמַר בָּךְ מֹשֶׁה קִבֵּל תּוֹרָה מִסִּינַי, וּמִתַּמָּן וְאֵילָךְ כֻּלְּהוּ תַּלְמִידִים אִינּוּן דִּילָךְ, מִן יְהוֹשֻׁעַ עַד סוֹף כָּל דָּרִין. הֲדָא הוּא דְּאָמַר וּמְסָרָהּ לִיְהוֹשֻׁעַ, וִיהוֹשֻׁעַ לִזְקֵנִים, וּזְקֵנִים לִנְבִיאִים, עַד סוֹף כֻּלְּהוּ. תַּלְמִיד בָּקִי דִּילָךְ מַאן הוּא הָא חֲזֵינָא דְּאִתְּמַר, הַכֹּל יְהֵא מוּנַח עַד שֶׁיָּבֹא אֵלִיָּהוּ."],[[0,"אלא הכי אוליפנא וכו׳:","ומשיב, אלא כך למדנו. אדם הבא לחטוא לפני אדונו, הוא שורף את עצמו בשלהבת יצר הרע, ויצר הרע בא מצד רוח הטומאה, והרי שורה בו רוח הטומאה, ולפעמים נודע קרבנו שבא מצד הזה, דהיינו עז (כנ״ל ויקרא אות תמ״א ותמ״ב) שצריך להקריב על המזבח את הדומה לו, אל החוטא, ואינו כלה ואינו מתבטל אותו רוח הטומאה, בין מן האדם החוטא, ובין מאותו הצד שבא ממנו, אלא באש המזבח, שאש הזו מבערת רוח הטומאה, ומינים רעים מן העולם, והכהן נתכוון לזה, לתקן האש שתבער מינים רעים מן העולם. וע\"כ, צריכים לכהן שיעשה זאת, שהוא מן הימין, והימין מבער השמאל."],[1,"ועל דא בעי וכו׳:","ועל כן צריך, שלא יכבו אותה לעולם, אלא אש תמיד תוקד בו, כדי שלא יתחלש הכח והתוקף שבה ויוכל לשבור הכח של תוקף האחר הרע, מן העולם. ועל כן לא תכבה. והכהן יסדר עליו אש בבקר בבקר, בזמן ששולט הצד שלו, כי בבקר שולט צד הימין, ומתעורר בעולם, כדי לבשם העולם, ע״י עריכת האש על המזבח, ויכנעו הדינים ולא יתעוררו בעולם. על זה למדנו שיש אש אכלה אש, כי האש של מעלה, של המלכות, אוכלת אש אחרת, אש המזבח אוכלת אש אחר של הצד האחר. וע״כ אש זו, לא תכבה לעולם, והכהן מסדר אותה בכל יום."],[2,"פקודא לעשות העולה וכו׳:","מצוה, לעשות העולה כמשפטה. ועליה נאמר, זאת תורת העולה וגו'. חמשה מיני אש, היו יורדות על הקרבן, א) אש אוכלת ואינה שותה. ב) אש שותה ואינה אוכלת. ג) אש אוכלת ושותה. ד) אש אוכלת לחים ויבשים. ה) אש שאינה אוכלת ואינה שותה. כנגדן הם, א) זאת תורת העולה. ב) הוא העולה על מוקדה. ג) על המזבח. ד) כל הלילה. ה) ואש המזבח תוקד בו."],[2,"","פירוש. ה׳ דינים הם המכונים ה׳ אשות, ג׳ הם בחג״ת שלמעלה מחזה, הנמשכים מג׳ זריעות המכונות חלם שורק חירק, (כמ״ש לעיל בראשית א׳ דף ט״ו בד״ה ההיא, ע״ש) וב׳ הם מחזה ולמטה, א׳ בנו״ה ויסוד הנמשך מהמסך שבנקודת החזה. ב׳ הוא במלכות. והנה הדינים שבג׳ קוין חג״ת שלמעלה מחזה הם בחינות אש שאינה שורפת, אלא אוכל פירושו שממשיך חסדים. אבל ב׳ אשות שמחזה ולמטה, הן שורפות החצונים. ונודע שהמשכת החסדים מכונה אכילה, והמשכת החכמה שבקו שמאל מכונה שתיה. (כנ״ל ויקרא אות ל״ח, ע״ש)."],[2,"","וזה אמרו, \u0003אש אוכל ואינו שותה,\u0004 היינו הדינים שבקו ימין, הנמשכים מנקודת החולם, שהוא \u0003אוכלת,\u0004 שממשיך מוחין דחסדים, \u0003ואינו שותה,\u0004 שאינו ממשיך חכמה. \u0003אש שותה ואינו אוכל,\u0004 היינו הדינים שבקו שמאל הנמשכים מנקודת השורק, שהוא \u0003שותה,\u0004 דהיינו שממשיך מוחין דחכמה, \u0003ואיני אוכל,\u0004 שאינו ממשיך חסדים, כי השמאל הוא חכמה בלי חסדים. אש אוכל ושותה, היינו הדינים שבקו אמצעי הנמשכים מנקודת החירק, שהוא \u0003אוכל,\u0004 דהיינו שממשיך חסדים, וגם \u0003שותה,\u0004 שממשיך חכמה גם כן, להיותו כלול מב׳ הקוין ימין ושמאל, ויש לו מעלת שניהם. ועד כאן המדובר מלמעלה מחזה. אבל למטר מחזה, יש \u0003אש אוכל לחים ויבשים,\u0004 דהיינו הדינים שבנה״י, הנמשכים ממסך שבחזה, שהיא אוכלת ושורפת הקליפות שבימין, שהן \u0003לחות,\u0004 שיש בהן איזה לחלוחית אור, ואוכלת ושורפת הקליפות שבשמאל שהם \u0003יבשים\u0004 לגמרי ויש \u0003אש שאינו אוכל ואינו שותה.\u0004 היינו הדינים שבמלכות שאינם ממשיכים שום אור, לא של חכמה ולא של חסדים, כי המלכות אין לה מעצמה שום אור, רק מה שז״א משפיע אליה. וכנגדם הן ה׳ חלוקות שבהמקרא זאת תורת וגו׳. אשר, \u0003זאת תורת העולה,\u0004 הוא קו ימין, חסד, כנגד אש הא'. \u0003היא העולה על מוקדה,\u0004 הוא קו שמאל גבורה כנגד אש הב'. וע\"כ נזכר כאן מוקדה. \u0003על המזבח,\u0004 הוא קו האמצעי, ת״ת, שהוא על המזבח, המזבח הוא מלכות, על המזבח, דהיינו ממעל המזבח, הוא ת״ת. שהוא כנגד אש הג'. \u0003כל הלילה\u0004 הוא המסך השולט מחזה ולמטה, השייך לבחינת מלכות הנקראת לילה. והוא כנגד אש הד'. \u0003ואש המזבח תוקד בו,\u0004 הוא דין המלכות עצמה הנקראת מזבח. שהוא כנגד האש החמישית."],[3,"ואוקמוה מארי מתניתין וכו׳:","והעמידוהו בעלי המשנה. עולה, כולה עולה לגבוה, וזה היא בינה, שהיא \u0003ה׳\u0004 ראשונה דהויה. ונקראת כן על שם \u0003ה׳\u0004 מראות שלה, דהיינו ה׳ אשות הנ״ל שנמשכות לזו״ן מן הבינה. \u0003י׳\u0004 היא בת יחידה, דהיינו בת עין, מלכות, שעליה נאמר, ומראה כבוד ה׳ כאש אוכלת. אמנם המלכות מבחינתה עצמה, היא אש שאינה אוכלת ואינה שותה כנ״ל, אלא \u0003ו׳\u0004 שהוא ת״ת, קו האמצעי שהוא אוכל ושותה הוא האור של בת עין, וכשהמלכות מקבלת מן ה \u0003ו׳\u0004 גם היא אש שותה כל מים דאורייתא. ואוכלת את כל כל הקרבנות שבתפלה, דהיינו שמקבלת מן ה \u0003ו׳\u0004 כל ג׳ אשות דחג״ת הכלולות בו. וגם מקבלת מן האש הד׳ שבנה״י של ה \u0003ו׳\u0004 שמחזה ולמטה, וע״כ היא אוכלת לחים ויבשים, כמו אש הד׳. ומפרש, שממשכת פשטי התורה, שהם כעצים יבשים, וממשכת סודות התורה שהם כעצים לחים. כלומר, שעי״ז ששורפת הקליפות שבשמאל שהן יבשות, נמשכים פשטי התורה. ועי״ז ששורפת הקליפות שבימין שהן לחות נמשכים סודות התורה וזו היא אש אוכלת לחים ויבשים."],[4,"ועוד, אוכלת לחין וכו׳:","ועוד יש לפרש, אוכלת לחים, הם כל הקרבנות הנקרבים על ידי התפלה, בבחינת ונשלמה פרים שפתינו, על מצות עשה. ואוכלת יבשים, היינו כל הקרבנות שהיו נקרבים בתפלה על מצות לא תעשה, שזו היא שמענישים עליה ד׳ מיתות, סקילה שרפה הרג וחנק. והם הקרבנות שהם על מצות עשה ועל מצות לא תעשה. אלו הם הקרבנות של השכינה, הנקראת, תפלה, הבאים על מצות עשה ולא תעשה. וכנגד ה׳ מראות אלו, הנמשכים מבינה, כנ״ל, תקנו ה׳ תפלות ביום הכפורים. וכנגד בת עין, שהיא המלכות, כנ״ל, שהיא \u0003י׳,\u0004 הם עשרת ימי תשובה. ו \u0003ה׳\u0004 ראשונה דהוי״ה, הוא כנגד האור של בת עין הנמשך לה מן ה \u0003ו׳\u0004 כנ״ל. ה׳ עינוים שביוה״כ שאינם אוכלים ושותים, היא כנגד \u0003ה׳\u0004 אחרונה דהוי״ה, דהיינו המלכות מבחינתה עצמה, שאינה אוכלת ואינה שותה כנ״ל."],[5,"פקודא בתר דא וכו׳:","המצוה שלאחר זו, היא לעשות החטאת כמשפטה. תנאים ואמוראים, אתם, שמצד המדות של הקב״ה אתם באים, שעמלתם הרבה לנקות הבת שלי, שהיא הלכה, דהיינו מלכות, מן הקליפות של הערב רב, שהם קושיות רעות שאין להם ישוב, ולא תירוץ, שעליהם נאמר, מעוות לא יוכל לתקן וחסרון לא יוכל להמנות, אלא שנאמר בהם תיקו. וכל תיקו שבאיסור הוא לחומרא, והוא תיקו חסר \u0003ן׳,\u0004 שרומז שאין לו תקון. חסר \u0003ן׳\u0004 שהוא עולם הבא, דהיינו בינה, שיש לה \u0003נ׳\u0004 שערים, כי תיקו שבעולם הבא הוא שתיקה, כגון שתוק כך עלה במחשבה. פירוש, שהתיקון לזה היא שתיקה, כמו שאמר הקב״ה למשה, שתוק וכו'. (מנחות כט:) שזהו תיקו שבעולם הבא, דהיינו עם \u0003ן׳,\u0004 שהוא תקון."],[6,"ואית קושיין דאינון וכו׳:","ויש קושיות שהם לבושי הלכה, דהיינו לבושי מלכות, שנאמר בהם, משבצות זהב, ז\"ש כל כבודה בת מלך פנימה ממשבצות זהב לבושה. כי הקושיות ה״ס דינים, הנבחנים לחקיקות כמו משבצות, והם נעשו לבושים להמלכות. דהיינו אותם הדינים הגורמים לגילוי החכמה, (כנ״ל פקודי אות שע״ו), וע״כ ה״ס משבצות זהב, כי זהב יורה על גילוי חכמה שמשמאל. ואתם האמוראים, פוסקים לבוש המשבצות בכמה פסקי דינים, ואחר כך אתם מתקנים ומישבים אותם בכמה ישובים."],[7,"ואי חסר שום וכו':","ואם חסר איזה פרק מן המשנה, כמו שהעמידוהו, זה חסר מן המשנה, אתם מתקנים אותו, דהיינו במקומות שאמרינן בגמרא, חסורי מחסרא והכי קתני. (חגיגה ז:) וזה הוא חסרון שיוכל להמנות. ואם יבא פתי ויוציא שם רע על אותו אומן החותך הלבושים, ויאמר, וכי התורה הוא חסר, לומר על המשנה חסורי מחסרא, והרי כתוב, תורת ה׳ תמימה, תמימה בכל אברין דגופא, שהם רמ״ח מצות עשה, ז\"ש, כלך יפה רעיתי ומום אין בך. ותמימה בלבושים שלה, ואיך יהיה חסר מן המשנה."],[8,"אתון תימרון ליה וכו׳:","ומשיב. אתם תאמרו לו, תדייק ותמצא חתיכה החסרה, שתמצא אותה מעורבת בשאר פסקים ומשניות. כלומר, כך דרכה של תורה עניה במקום זה ועשירה במקום אחר. שדרך האומן לחתוך את הלבושים לכמה חתיכות והחסר במקום זה ממלא במקום אחר, ותלמיד שאינו בקי לקשר ההלכה באלו החתיכות הנמצאות במקום אחר, מתחלפים לו פסקים וקושיות ואינו מוצא תירוץ עליהם, עד שיבא האומן, ויתרץ להם כל אלו הספקות שלהם. בזמן ההוא, הלכה, שהיא הבת, דהיינו מלכות, עולה לפני המלך, שלמה בכל, בגוף, ובלבושים, ובתכשיטים, ומתקיים בה, וראיתיה לזכור ברית עולם. ולפעמים יש לאומן תלמיד בקי שישלח להם לתקן אותם. דהיינו אליהו כמ״ש לפנינו."],[9,"קמו כלהו ואמרו וכו׳:","קמו כולם ואמרו: רועה נאמן, ודאי אתה הוא האומן. שנאמר בך משה קבל תורה מסיני. ומשם והלאה, כולם הם תלמידים שלך, מן יהושע עד סוף כל הדורות. זהו שלמדנו, ומסרה ליהושע ויהושע לזקנים וזקנים לנביאים עד סוף כולם. תלמיד בקי שלך, הנזכר לעיל, מי הוא, הרי אנו רואים שאמרו, הכל יהא מונח עד שיבא אליהו. הרי שאליהו הוא התלמיד בקי שלך."]],[[0,"","אֶלָּא כָּךְ לָמַדְנוּ, אָדָם שֶׁבָּא לַחֲטֹא לִפְנֵי רִבּוֹנוֹ, הוּא שׂוֹרֵף אֶת עַצְמוֹ בְּשַׁלְהֶבֶת הַיֵּצֶר הָרָע, וְיֵצֶר הָרָע בָּא מִצַּד שֶׁל רוּחַ הַטֻּמְאָה, וַהֲרֵי שׁוֹרָה בּוֹ רוּחַ טֻמְאָה. וְלִפְעָמִים נוֹדָעִים הַקָּרְבָּנוֹת שֶׁבָּאִים מֵהַצַּד הַזֶּה, וְצָרִיךְ לְהַקְרִיב עַל הַמִּזְבֵּחַ אֶת מַה שֶּׁדּוֹמֶה לוֹ, וְלֹא מִתְכַּלָּה וְלֹא מִתְבַּטֶּלֶת אוֹתָהּ רוּחַ הַטֻּמְאָה בֵּין מֵהָאָדָם וּבֵין מֵאוֹתוֹ הַצַּד שֶׁבָּא מִמֶּנּוּ, אֶלָּא רַק בָּאֵשׁ שֶׁל הַמִּזְבֵּחַ, שֶׁאוֹתָהּ הָאֵשׁ מַבְעֶרֶת אֶת רוּחַ הַטֻּמְאָה וּמִינִים רָעִים מִן הָעוֹלָם. וְהַכֹּהֵן מִתְכַּוֵּן בָּזֶה לְתַקֵּן אֵשׁ שֶׁתְּבַעֵר מִינִים רָעִים מִן הָעוֹלָם."],[1,"","וְלָכֵן צָרִיךְ שֶׁלֹּא תִכְבֶּה לְעוֹלָמִים וְלֹא יֶחֱלַשׁ הַכֹּחַ וְהַתֹּקֶף שֶׁלָּהּ, כְּדֵי לשְׁבֹּר הַכֹּחַ הָרָע הָאַחֵר מִן הָעוֹלָם, וְלָכֵן לֹא תִכְבֶּה. וְהַכֹּהֵן יְסַדֵּר עָלֶיהָ אֵשׁ בַּבֹּקֶר בַּבֹּקֶר, בִּזְמַן שֶׁשּׁוֹלֵט הַצַּד שֶׁלּוֹ וּמִתְעוֹרֵר בָּעוֹלָם כְּדֵי לְבַשֵּׂם אֶת הָעוֹלָם (ולבסם הדין), וְהַדִּינִים נִכְנָעִים וְלֹא מִתְעוֹרְרִים בָּעוֹלָם. וְעַל זֶה שָׁנִינוּ, יֵשׁ אֵשׁ אוֹכֶלֶת אֵשׁ. אֵשׁ שֶׁלְּמַעְלָה אוֹכֶלֶת אֵשׁ אַחֶרֶת, אֵשׁ הַמִּזְבֵּחַ אוֹכֶלֶת אֵשׁ אַחֶרֶת. וְעַל זֶה הָאֵשׁ הַזּוֹ לֹא תִכְבֶּה לְעוֹלָמִים, וְהַכֹּהֵן מְסַדֵּר אוֹתָהּ בְּכָל יוֹם."],[2,"","מִצְוָה לַעֲשׂוֹת הָעוֹלָה כְּמִשְׁפָּטָהּ, וְעָלֶיהָ נֶאֱמַר זֹּאת תּוֹרַת הָעֹלָה וְגוֹ'. חֲמִשָּׁה אִשִּׁים הָיוּ יוֹרְדִים עַל הַקָּרְבָּן: אֵשׁ אוֹכֵל וְאֵינוֹ שׁוֹתֶה. אֵשׁ שׁוֹתֶה וְאֵינוֹ אוֹכֵל. אֵשׁ אוֹכֵל וְשׁוֹתֶה. אֵשׁ אוֹכֵל לַחִים וִיבֵשִׁים. אֵשׁ שֶׁאֵינוֹ אוֹכֵל וְאֵינוֹ שׁוֹתֶה. כְּנֶגְדָּם הֵם: זֹּאת תּוֹרַת הָעֹלָה - אַחַת. הִיא הָעֹלָה עַל מוֹקְדָה - שְׁתַּיִם. עַל הַמִּזְבֵּחַ - שָׁלֹשׁ. כָּל הַלַּיְלָה - אַרְבַּע. וְאֵשׁ הַמִּזְבֵּחַ תּוּקַד בּוֹ - חָמֵשׁ."],[3,"","וּפֵרְשׁוּהָ בַּעֲלֵי הַמִּשְׁנָה, הָעוֹלָה כֻּלָּהּ עוֹלָה לְגָבוֹהַּ, וְזוֹ בִּינָה, ה', ה' מַרְאוֹת שֶׁלָּהּ. י' בַּת יְחִידָה, (שמות כג) וּמַרְאֵה כְּבוֹד ה' כְּאֵשׁ אֹכֶלֶת. ו' אוֹר שֶׁל בַּת עַיִן, וְהִיא אֵשׁ שׁוֹתָה כָּל הַמַּיִם שֶׁל הַתּוֹרָה, וְאוֹכֶלֶת אֶת כָּל הַקָּרְבָּנוֹת שֶׁל הַתְּפִלָּה. וְאוֹכְלִים לַחִים וִיבֵשִׁים, אוֹתָם פְּשָׁטֵי הַתּוֹרָה שֶׁהֵם כְּמוֹ עֵצִים יְבֵשִׁים, וְסוֹדוֹת הַתּוֹרָה הֵם כְּמוֹ עֵצִים לַחִים. וְזוֹהִי אֵשׁ הָאוֹכֶלֶת לַחִים וִיבֵשִׁים."],[4,"","וְעוֹד אוֹכֶלֶת לַחִים, כָּל הַקָּרְבָּנוֹת שֶׁהָיוּ קְרֵבִים בִּתְפִלָּה עַל מִצְווֹת עֲשֵׂה. וִיבֵשִׁים - כָּל הַקָּרְבָּנוֹת שֶׁהָיוּ קְרֵבִים בִּתְפִלָּה עַל מִצְווֹת לֹא תַעֲשֶׂה. וְזֶהוּ סְקִילָה שְׂרֵפָה הֶרֶג וְחֶנֶק, עַל מִצְווֹת עֲשֵׂה, וְעַל מִצְווֹת לֹא תַעֲשֶׂה. אֵלּוּ הֵם הַקָּרְבָּנוֹת שֶׁל הַשְּׁכִינָה, תְּפִלָּה, שֶׁל מִצְווֹת עֲשֵׂה וְלֹא תַעֲשֶׂה. וּכְנֶגֶד חֲמֵשׁ הַמַּרְאוֹת הַלָּלוּ תִּקְּנוּ חָמֵשׁ תְּפִלּוֹת בְּיוֹם הַכִּפּוּרִים. וּכְנֶגֶד בַּת עַיִן אוֹתָם עֲשֶׂרֶת יְמֵי תְשׁוּבָה. חֲמִשָּׁה כְּנֶגֶד הָאוֹר שֶׁל בַּת עַיִן. חֲמִשָּׁה עִנּוּיִים כְּנֶגֶד ה' אַחֲרוֹנָה."],[5,"","הַמִּצְוָה אַחַר זוֹ, לַעֲשׂוֹת אֶת הַחַטָּאת כְּמִשְׁפָּטָהּ. תַּנָּאִים וְאָמוֹרָאִים, אַתֶּם שֶׁמִּצַּד מִדּוֹתָיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא בָּאתֶם, שֶׁטְּרַחְתֶּם הַרְבֵּה לְנַקּוֹת אֶת הַבַּת שֶׁלִּי, שֶׁהִיא הֲלָכָה, מֵאוֹתָן הַקְּלִפּוֹת שֶׁל עֵרֶב רַב, שֶׁהֵן קֻשְׁיוֹת רָעוֹת שֶׁאֵין לָהֶם תֵּרוּץ וְלֹא פֵרוּק, שֶׁעֲלֵיהֶם נֶאֱמַר (קהלת א) מְעֻוָּת לֹא יוּכַל לִתְקֹן וְחֶסְרוֹן לֹא יוּכַל לְהִמָּנוֹת, אֶלָּא נֶאֱמַר בָּהֶם תִּיקוּ. וְכָל תִּיקוּ שֶׁל אִסּוּר - לְחֻמְרָה. וְהוּא תִּיקוּ חָסֵר ן', שֶׁאֵין לוֹ תִּקּוּן. חָסֵר נוּן, שֶׁהוּא הָעוֹלָם הַבָּא, שֶׁתִּיקוּ שֶׁל הָעוֹלָם הַבָּא שְׁתִיקָה, כְּמוֹ: שְׁתֹק, כָּךְ עָלָה בְּמַחֲשָׁבָה."],[6,"","וְיִשִׁ קֻשְׁיוֹת שֶׁהֵן הַלְּבוּשִׁים שֶׁל הֲלָכָה, שֶׁנֶּאֱמַר בָּהֶם מִשְׁבְּצוֹת זָהָב. זֶהוּ שֶׁכָּתוּב (תהלים מה) כָּל כְּבוּדָּה בַּת מֶלֶךְ פְּנִימָה מִמִּשְׁבְּצוֹת זָהָב לְבוּשָׁהּ. וְאַתֶּם פּוֹסְקִים אוֹתָם בְּכַמָּה פְסָקִים, וְאַחַר כָּךְ מְתַקְּנִים וּמְיַשְּׁבִים אוֹתָם בְּכַמָּה פֵרוּקִים."],[7,"","וְאִם חָסֵר פְּסָק כָּלְשֶׁהוּ מִן הַמִּשְׁנָה, כְּמוֹ שֶׁבֵּאֲרוּהָ זֶה חָסֵר מִן הַמִּשְׁנָה, אַתֶּם מְתַקְּנִים אוֹתָם, וְזֶהוּ חֶסְרוֹן שֶׁיּוּכַל לְהִמָּנוֹת. וְאִם יָבֹא טִפֵּשׁ וְיוֹצִיא שֵׁם רַע עַל אוֹתוֹ אָמָּן שֶׁחוֹתֵךְ לְבוּשִׁים, וְיֹאמַר: וְכִי הַתּוֹרָה הִיא חֲסֵרָה?! וַהֲרֵי כָּתוּב תּוֹרַת ה' תְּמִימָה, תְּמִימָה בְּכָל אֵיבְרֵי הַגּוּף, שֶׁהֵם רמ\"ח מִצְווֹת, זֶהוּ שֶׁכָּתוּב (שיר ד) כֻּלָּךְ יָפָה רַעְיָתִי וּמוּם אֵין בָּךְ, תְּמִימָה בִלְבוּשֶׁיהָ, וְאֵיךְ חָסֵר מִן הַמִּשְׁנָה?"],[8,"","אַתֶּם תֹּאמְרוּ לוֹ: דַּיֵּק וְתִמְצָא חֲתִיכָה, וְתִמְצָא אוֹתָהּ מְעֹרֶבֶת עִם שְׁאָר פְּסָקִים וּמִשְׁנָיוֹת. שֶׁדֶּרֶךְ הָאָמָּן לַחְתֹּךְ לְבוּשִׁים לְכַמָּה חֲתִיכוֹת, וְהַתַּלְמִיד שֶׁאֵינוֹ בָּקִי לִקְשֹׁר אֶת הַהֲלָכָה בַּחֲתִיכוֹת הַלָּלוּ, מִתְחַלְּפוֹת לוֹ פְּסָקוֹת וְקֻשְׁיוֹת וְלֹא מוֹצֵא לָהֶם פֵּרוּק, עַד שֶׁיָּבֹא הָאָמָּן וּמְפָרֵק אוֹתָם אֶת כָּל הַסְּפֵקוֹת הַלָּלוּ שֶׁלָּהֶם. בְּאוֹתוֹ זְמַן, הֲלָכָה שֶׁהִיא בַּת, עוֹלָה לִפְנֵי הַמֶּלֶךְ שְׁלֵמָה בַּכֹּל, בְּגוּפָהּ בִּלְבוּשָׁהּ וּבְתַכְשִׁיטֶיהָ, וּמִתְקַיֵּם בָּהּ (בראשית ט) וּרְאִיתִיהָ לִזְכֹּר בְּרִית עוֹלָם. וְלִפְעָמִים יֵשׁ לָאָמָּן תַּלְמִיד בָּקִי שֶׁיִּשְׁלַח לוֹ לְתַקֵּן אוֹתָם."],[9,"","קָמוּ כֻלָּם וְאָמְרוּ, וַדַּאי שֶׁאַתָּה הוּא הָאָמָּן, רוֹעֶה הַנֶּאֱמָן, שֶׁבְּךְ נֶאֱמַר מֹשֶׁה קִבֵּל תּוֹרָה מִסִּינַי, וּמִשָּׁם וְאֵילָךְ כָּל הַתַּלְמִידִים הֵם שֶׁלְּךְ, מִיהוֹשֻׁעַ וְעַד סוֹף כָּל הַדּוֹרוֹת. זֶהוּ שֶׁאָמַר וּמְסָרָהּ לִיהוֹשֻׁעַ, וִיהוֹשֻׁעַ לִזְקֵנִים, וּזְקֵנִים לִנְבִיאִים, עַד הַסּוֹף שֶׁל כֻּלָּם. הַתַּלְמִיד הַבָּקִי שֶׁלְּךְ מִי הוּא? הֲרֵי רָאִינוּ שֶׁנֶּאֱמַר, הַכֹּל יְהֵא מֻנָּח עַד שֶׁיָּבא אֵלִיָּהוּ."]]],[["אָמַר לוֹן, וַדַּאי הָכִי הוּא, דְּאִיהוּ תַּלְמִיד חָבֵר, דְּעָלֵיהּ אִתְּמַר (במדבר כ״ה:ז׳) בֶּן אַהֲרֹן הַכֹּהֵן. כְּגַוְונָא דְּאִתְּמַר בְּאַהֲרֹן (שמות ד׳:ט״ז) הוּא יִהְיֶה לְּךָ לְפֶה, הָכִי נָמֵי בְּרֵיהּ, יִהְיֶה לִי לְפֶה, דְּאִיהִי אוֹרַיְיתָא דִּבְעַל פֶּה. בְּגִין דְּהֵיכִי דַּהֲוֵינָא בְּקַדְמִיתָא כְּבַד פֶּה וּכְבַד לָשׁוֹן, וְהָכִי יוֹקִים לִי קוּדְשָׁא בְּרִיךְ הוּא, כְּבַד פֶּה בְּאוֹרַיְיתָא דְבְּעַל פֶּה, וּכְבַד לָשׁוֹן בְּאוֹרַיְיתָא שֶׁבִּכְתָּב, דְּלָא יֵימְרוּן אִלֵּין דְּלָא אִשְׁתְּמוֹדְעִין לִי, אָחֳרָא אִיהוּ. וְאֵלִיָּהוּ הוּא יִהְיֶה לִי לְפֶה, יֵיתֵי לְתַקְּנָא כָּל אִלֵּין סְפֵקוֹת, וּלְפָרְקָא לוֹן.","בְּהַהוּא זִמְנָא, זֹאת תּוֹרַת הָעוֹלָה, בְּרַתָּא, דַּהֲוַת מְהַדְּקָא שְׁפָלָה בְּגָלוּתָא, סְלִיקַת עַל כָּל דַּרְגִּין דִּלְעֵילָּא, הֲדָא הוּא דִכְתִיב, (משלי ל״א:כ״ט) רַבּוֹת בָּנוֹת עָשׂוּ חָיִל וְאַתְּ עָלִית עַל כֻּלָּנָה, וּסְלִיקוּ דִּילָהּ תְּהֵא לְאַבָּא דְּאִיהוּ לִימִינָא חֶסֶד, דְּבֵיהּ הָרוֹצֶה לְהַחְכִּים יַדְרִים, מִתַּמָּן חָכְמָ\"ה, כ\"ח מ\"ה.","אָמַר חַד תָּנָא, בְּוַדַּאי בְּגִין דָּא אִתְּמַר בָּךְ, מוֹלִיךְ לִימִין מֹשֶׁה בְּגִין כַּלָּה דִּילָךְ, דְּלָא יְהֵא לָךְ שְׁלִימוּ אֶלָּא בָּהּ. דְּכַד אַנְתְּ תְּהֵא שְׁלֵימָא בָּהּ, אִתְּמַר בָּךְ (במדבר י״ב:ח׳) פֶּה אֶל פֶּה אֲדַבֶּר בּוֹ וּמַרְאֶה וְלָא בְחִידוֹת. בְּמַרְאֶה: כְּגַוְונָא דְּכַלָּה דְּאִתְפַּשְּׁטַת מַלְבּוּשָׁהָא, וּמִתְיַיחֶדֶת עִם בַּעְלָהּ בְּקֵירוּב בָּשָׂר, בְּרָמָ\"ח אֵבָרִים דִּילָהּ, וְלָא כַּסִּיאַת אֵבֶר חַד מִנָּהּ. וְהַאי אִיהוּ בְּמַרְאֶה רמ\"ח בְּחוּשְׁבָּן. (נ\"א אתחזי לה דאתמר ביה)","אָמַר בּוּצִינָא קַדִּישָׁא, בְּקַדְמִיתָא אִתְחֲזֵי לָךְ הַאי חֵיזוּ, דְּאִתְּמַר בָּהּ בְּמַרְאֶה, דְּאִיהוּ לָךְ הַמַרְאֶה הַגָּדוֹל בַּסְּנֶה, דְּאִדְכַּר בֵּיהּ חֲמִשָּׁה זִמְנִין הַסְּנֶה. וּכְעַן אִתְגַּלְיָא לָךְ חֵיזוּ דָּא, בְּרָמָ\"ח פִּקוּדִין, דְּאִינּוּן בְּחַמְשָׁה חוּמָשֵׁי תּוֹרָה. וְלֹא בְחִידוֹת, דְּאִינּוּן לְבוּשִׁין דִּילָהּ, דִּבְהוֹן חָזוּ כָּל נְבִיאֵי. דְּלֵית אֹרַח לְאִתְגַּלָּאָה כַּלָּה בְּקֵירוּב בָּשָׂר, אֶלָּא לְחָתָן דִּילָהּ.","בְּהַהוּא זִמְנָא יִתְקַיָּים בְּהוּ, (בראשית ב׳:כ״ה) וַיִּהְיוּ שְׁנֵיהֶם עֲרוּמִּים הָאָדָם וְאִשְׁתּוֹ וְלֹא יִתְבּוֹשָׁשׁוּ. כְּגוֹן אָדָם וְאִשְׁתּוֹ דִּכְבַר אִתְעַבָּר עִרְבּוּבְיָא בִּישָׁא, עֵרֶב רַב, קוּשְׁיָא בִּישָׁא מֵעָלְמָא, דְּאִינּוּן עֶרְיָין דְּקוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ, עֶרְיָין דְּיִשְׂרָאֵל. כָּל שֶׁכֵּן עֶרְיָין דִּילָךְ רַעְיָא מְהֵימָנָא. וּמֵהֲלָכָה דִּילָךְ. דִּבְגִּינַיְיהוּ צָּרִיךְ לְכַסָּאָה רָזִין דְּאוֹרַיְיתָא, כְּמָה דְּאוּקְמוּהָ (משלי כ״ה:ב׳) כְּבוֹד אֱלֹהִים הַסְתֵּר דָּבָר, עַד דְּמִתְעַבְּרִין מֵעָלְמָא. וְלֵית מְלָכִים אֶלָּא יִשְׂרָאֵל, כְּמָה דְּאוּקְמוּהָ, כָּל יִשְׂרָאֵל בְּנֵי מְלָכִים הֵם, בְּהַהוּא זִמְנָא, וּכְבוֹד מְלָכִים חֲקוֹר דָּבָר. אָמַר רַעְיָא מְהֵימָנָא, בְּרִיךְ אַנְתְּ לְעַתִּיק יוֹמִין, דְּמִתַּמָּן אַנְתְּ, כְּעַנְפָּא דְּאִתְפְּשַּׁט מֵאִילָנָא, הָכִי נִשְׁמָתִין עַנְפָּא מִנֵּיהּ.","תַּנָּאִים וְאָמוֹרָאִין, הָא וַדַּאי עוֹלָה וְחַטָאת וְאָשָׁם, תְּלַת פִּקוּדִין אִינּוּן, תְּלַת אֲבָהָן. שְׁלָמִים מַטְרוֹנִיתָא. אֵבֶר, דְּאִיהִי תַּשְׁלוּמִין דְּכָל אֵבֶר, כְּגַוְונָא דְּיוֹמָא קַדְמָאָה דְּחַג. (ס\"א אתר דאיהו תשלומים דכלא כגוונא).","מִי שֶׁלֹּא חַג בְּיוֹם טוֹב רִאשׁוֹן, אֵין תַשְׁלוּמִים לַרִאשׁוֹן, וּשְׁאָר יוֹמִין תַשְׁלוּמִין זֶה בָּזֶה, וּבְהוֹן וְחֶסְרוֹן לֹא יוּכַל לְהִמָּנוֹת אֲבָל מִי שֶׁלֹּא חַג יוֹם טוֹב הָרִאשׁוֹן שֶׁל חַג עָלֵיהּ אִתְּמַר (קהלת א׳:ט״ו) מְעֻוָּת לֹא יוּכַל לִתְקוֹן וְחֶסְרוֹן לֹא יוּכַל לְהִמָּנוֹת. וְהַאי אִיהוּ חַטָאת דִּמְעַכֵּב לָעוֹלָה. (מאי טעמא) חֵטְא אִיהוּ דְּכַר. חַטָאת, נוּקְבָּא. וּלְזִמְנִין דְּהָא אִתְבְּסָם חַטָאת, וְאִתְפְּרַשׁ מֵעוֹלָה. בְּהַהוּא שָׂעִיר, דְּאִתְּמַר (במדבר ט״ו:כ״ד) וּשְׂעִיר עִזִּים אֶחָד לְחַטָאת.","אֲשָׁם תָּלוּי אָחִיד בְּתַרְוַויְיהוּ, כְּמַאן דְּאָחִיד לְכָאן וּלְכָאן, וְאִיהוּ תָּלוּי בְּאֶמְצָּעִיתָא. כְּגוֹן, הַכֹּל תָּלוּי עַד שֶׁיָּבֹא אֵלִיָּהוּ, וְיַפְרִישׁ לֵהּ מִתַּמָּן. הָכִי אֲשָׁם תָּלוּי, אִיהוּ אָחִיד בְּתַרְוַויְיהוּ, עַד דְּיָהֲבִין לֵיהּ מְזוֹנָא דִּילֵיהּ, שׁוֹחַד דִּילֵיהּ, וְיִתְפְּרַשׁ מִתַּמָּן, וּמִתְקָרְבִין אֵבָרִין דְּכַלָּה דָּא לְדָא. דְּהָכִי אִיהוּ אָשָׁם וְחַטָאת, כְּסִרְכוֹת דַּאֲחִידָן בָּרֵיאָה, וְלָא מַנִּיחִין לָהּ לְפַרְחָא לְסַלְּקָא לְגַבֵּי עֵילָּא, לְנָשְׁבָּא בְּרוּחָא דְּקוּדְשָׁא.","שֶׂה אִיהוּ לְעוֹלָה, דִּכְתִּיב, (בראשית כ״ב:ז׳) וְאַיֵּה הַשֶּׂה לְעוֹלָה. וְאִתְּמַר בֵּיהּ (שמות י״ב:ה׳) שֶׂה תָמִים זָכָר, הֲדָא הוּא דִכְתִיב אִישׁ תָּמִים. וְהָא צָּרִיךְ לְמִשְׁאַל, דְּהָא שֶׂה אִיהוּ לִימִינָא, שָׂעִיר אִיהוּ לִשְׂמָאלָא, דְּהַיְינוּ שְׂעִיר עִזִּים אֶחָד לְחַטָאת, וְאִית שָׂעִיר, וְאִית שָׂעִיר. שָׂעִיר אֶחָד לַיְיָ', וּשְׂעִיר אֶחָד לַעֲזָאזִל. וְהַיְינוּ דִּכְתִּיב, (ויקרא ט״ז:ח׳) וְנָתַן אַהֲרֹן עַל שְׁנֵי הַשְּׂעִירִים גּוֹרָלוֹת גּוֹרָל אֶחָד לַיְיָ' וְגוֹרָל אֶחָד לַעֲזָאזֵל. וּבְהַהוּא שֵׂעִיר, אִתְּמַר בְּעֵשָׂו, (בראשית כ״ז:י״א) אִישׁ שָׂעִיר. וְדָא כָּבֵד. דְּנָטִיל כָּל אִינּוּן שְׁמָרִים דְּדָם. (דמתמן) שְׁחִין אֲבַעְבּוּעוֹת פּוֹרְחוֹת, סַפָּחֹת, וְכָל מִינֵי צָּרַעַת. וְהַיְינוּ דִּכְתִּיב, (ויקרא ט״ז:כ״ב) וְנָשָׁא הַשָּׂעִיר עָלָיו אֶת כָּל עֲוֹנוֹתָם אֶל אֶרֶץ גְּזִרָה. וְאִינּוּן עֲוֹנוֹת תָּם, דְּאִיהוּ לִבָּא, וּכְדֵין אִתְפְּרַשׁ מִלְּעָרְבָא בְּלִבָּא, וּכְדֵין אִתְבְּסָם, וְאִיהוּ כָּבֵד בְּאִלֵּין חוֹבִין, וְלָא קָל לְסַלְּקָא לְגַבֵּי יַעֲקֹב אִישׁ תָּם. חֲדוּ מָארֵי מַתְנִיתִין דִּמְתִיבְתָּאן, דְּקָא נַחְתֵּי עִם תָּנָאִין וְאָמוֹרָאִין.","קָם חַד מִנַּיְיהוּ וְאָמַר, רַעְיָא מְהֵימָנָא, הַב לִי רְשׁוּ לְמִשְׁאַל, בָּתַר דְּזָכֵינָא לְמִשְׁמַע מִלִּין יַקִּירִין אִלֵּין מִפּוּמָךְ, דְּאוֹרַיְיתָא דָּא דְּנָפְקָת מִפּוּמָךְ (משלי ג׳:ט״ו) יְקָרָה הִיא מִפְּנִינִים וְכָל חֲפָצֶּיךָ לֹא יִשְׁווּ בָהּ, וְעַל כָּל דָּא הֲלָכָה הִיא וְלִלְמוֹד אֲנִי צָּרִיךְ. הָא שָׂעִיר דַּעֲזָאזִל שַׁפִּיר, אָשָׁם תָּלוּי בְּאָן אֲתַר אִיהוּ.","אָמַר לֵיהּ, בְּרִיךְ אַנְתְּ בְּרִי, שַׁפִּיר קָא שָׁאַלְתְּ. אֶלָּא, מַה עַמּוּדָא דְּאֶמְצָּעִיתָא, אָחִיד בֵּיהּ יְמִינָא וּשְׂמָאלָא, דְּאִינּוּן חֶסֶד וּגְבוּרָה, כְּגוּפָא דְּאָחִיד בֵּין תְּרֵין דְּרוֹעִין דְּבַר נָשׁ. אוֹ כְּנֶשֶׁר, דַּאֲחִידָן בֵּיהּ תְּרֵין גַּדְפִּין לְפָרְחָא בְּהוֹן. וְכַיּוֹנָה, דַּאֲחִידַת בָּהּ תְּרֵין גַּדְפִּין, דְּאַמְתִּילַת לְאוֹרַיְיתָא, וְגַדְפִּין דִּילָהּ לְמִצְּוֹת עֲשֵׂה, וּבְהוֹן הִיא הָעוֹלָה, וּפַרְחַת לְעֵילָּא. הָכִי פִּקוּדִין דְּלָא תַּעֲשֶׂה, אִינּוּן תְּפִישׂוּ דִּילָהּ, כְּגוֹן צִּפֳּרִים הַנֶאֱחָזִים בַּפָּח. וְכָל תַּפְשִׂין דִּילָהּ, דִּמְעַכְּבִין לָהּ לְפַרְחָא, אִתְקְרִיאוּ סִרְכוֹת כְּאִלֵּין סִרְכוֹת, דִּמְעַכְּבֵי לְכַנְפֵי רֵיאָה, לְנָשְׁבָּא."],[[0,"אמר לון ודאי וכו׳:","אמר להם ודאי כך הוא. שאליהו, הוא תלמיד חבר, שעליו נאמר, בן אהרן הכהן דהיינו כמי שאומר, פנחס הוא אליהו. וכעין שנאמר באהרן, הוא יהיה לך ל \u0003פה.\u0004 אף כך בנו, אליהו, יהיה לי לפה, שהוא יתקן אורייתא דבעל \u0003פה.\u0004 משום, כי כמו שהייתי תחילה, כבד פה וכבד לשון, כך יקים אותי הקב״ה, לעת גמר התקון כבד פה בתורה שבעל פה. כבד לשון בתורה שבכתב שאלו, שלא הכירו אותי לא יאמרו שאחר הוא. דהיינו כמו שאמרו עתידים המתים לקום במומם שלא יאמרו אחר הוא. ואליהו, הוא יהיה לי ל \u0003פה,\u0004 יבא לתקן כל אלו הספיקות ולתרץ אותם."],[1,"בההוא זמנא זאת וכו׳:","בזמן ההוא, נאמר, \u0003זאת תורת העולה,\u0004 דהיינו הבת, שהיא מלכות הנקראת \u0003זאת\u0004 ונקראת \u0003תורה\u0004 כנ״ל, שהיתה נכתשת ושפלה בגלות, \u0003העולה,\u0004 עולה על כל המדרגות שלמעלה. ז״ש, רבות בנות עשו חיל ואת עלית על כולנה. והעליה שלה, תהיה, לאבא, שהוא לימין, והוא חסד. שבו אמרו, הרוצה להחכים ידרים, דהיינו חסד שהוא בדרום, משם הוא חכמה, כי בגדלות, נעשו חג״ת דז״א, חב״ד, ונמצא חסד דז״א שנעשה לחכמה שהוא אבא. וע״כ מדרום שהוא חסד, משם \u0003חכמה,\u0004 שהוא אותיות \u0003כ״ח מ״ה,\u0004 ז״א ה״ס הויה דאלפין שבגימטרייא \u0003מ״ה,\u0004 והחסד שנעשה לחכמה, הוא ה \u0003כח\u0004 שלו."],[2,"אמר חד תנא וכו׳:","אמר תנא אחד, ודאי משום זה, נאמר בך, מוליך לימין משה זרוע תפארתו, משום שהכלה שלך, הנקראת זרוע תפארת, לא יהיה לך שלמות אלא בה. כי כשאתה תהיה שלם בה, בהמלכות, נאמר בך, פה אל פה אדבר בו ומראה ולא בחידות. במראה, כמו כלה שמתפשטת לבושיה ומתיחדת עם בעלה בקירוב בשר ב \u0003רמ״ח\u0004 אברים שלה, ואינה מכסית אבר אחד שלה. וזה הוא \u0003במראה,\u0004 שעולה בחשבון \u0003רמ״ח.\u0004"],[2,"","פירוש. כי נתבאר לעיל (באות ל׳) שכל הקושיות, שהם הדינים, הן בלבושים של המלכות, הנקראים משבצות זהב, עש״ה, כי בשעה שהיא מגלה החכמה שבקו שמאל שהיא מבינה שחזרה לחכמה. היא מתלבשת בלבושים ההם, שלא יוכלו החיצונים לינק ממנה, (כנ״ל פקודי אות שע״ו) אמנם בשעה שמתיחדת בימין, דהיינו בחכמה שבקו ימין, שה״ס חסד שנעשה לחכמה, וה״ס אבא, כנ״ל, בסו\"ה מוליך לימין משה זרוע תפארתו, אז היא מתפשטת מכל הלבושים האלו, כי גילוי אור החסדים אינו צריך לשום לבוש, שאין שם אחיזה לחצונים, ואור החכמה שבקו ימין שה״ס או״א עלאין, ה״ס אור החסדים (כנ״ל ב״א דף רנ״א ד\"ה נחית) הנקראים אוירא דכיא, וז״ש, \u0003דאתפשטת מלבושהא ומתיחדת עם בעלה,\u0004 דהיינו בשעה שהיא לימין משה, אין פחד מחיצונים, ומתיחדת עם משה, שה״ס ז״א בעלה שנקרא משה, בלי שום לבושים \u0003בקירוב בשר ברמ״ח אברים דילה,\u0004 דהיינו בגילוי החסדים שלה המכונים רמ״ח אברים, שהם כנגד רמ״ח מצות עשה, שהם חסדים, ושס״ה גידין הם כנגד שס״ה מצות לא תעשה שהם גבורות מקו שמאל. וז״ש \u0003במראה, רמ\"ח בחושבן,\u0004 להורות שהיא גילוי \u0003מראה\u0004 החכמה שבקו ימין, שהוא בחינת רמ״ח אברים, דהיינו חסדים."],[3,"אמר בוצינא קדישא וכו׳:","אמר המאור הקדוש, דהיינו ר׳ שמעון, בתחילה נראה לך מראה הזה, שנאמר בו במראה, דהיינו המלכות, שהיא לך המראה הגדול בסנה, שנזכר שם ה׳ פעמים הסנה, כנגד ה׳ בחינות כח״ב תו״מ שבלבושים שלה הנמשכים משמאל, שה״ס בלבת אש מתוך הסנה, ועתה נגלה לך המראה הזה, ברמ״ח מצות עשה, דהיינו בחסדים (כנ״ל בדבור הסמוך), שהם בה׳ חומשי תורה, דהיינו בה׳ בחינות כח״ב תו״מ דז״א הנקרא תורה, \u0003ולא בחידות,\u0004 שהם הלבושים שלה, הנמשכים מקו שמאל, (כנ״ל אות ל׳) שבהם ראו כל הנביאים. כי אין דרך הכלה, שהיא מלכות, להתגלות בקירוב בשר, דהיינו בלי הלבושים שנמשכים משמאל, אלא לחתן שלה, שהוא משה. שהיה מסתכל במראה המאירה, מסוד החסדים דז״א, אבל שאר הנביאים היו מסתכלים במראה שאינה מאירה, דהיינו בלבושים שלה הנקראים חידות, וגם משבצות זהב (כנ״ל אות ל׳). ולא ראו אותה בלי לבושים אלו."],[4,"בההוא זמנא יתקיים וכו׳:","בזמן ההוא יתקיים בהם, בז״א שנקרא משה, ובמלכות, ויהיו שניהם ערומים האדם ואשתו ולא יתבוששו, כמו אדם ואשתו קודם החטא, כי כבר נעבר העירוב הרע שהם הערב רב, שהם קושיא רעה, כלומר דינים רעים, מן העולם. שהם העריות של קב\"ה ושכינתיה, שהם העריות של ישראל, ומכל שכן שהם העריות שלך, רועה נאמן, והם העריות מהלכה שלך, שהיא מלכות, שבשבילם צריכים לכסות סודות התורה, כמו שהעמידוהו, כבוד אלקים הסתר דבר, עד שיעברו מן העולם. ואין מלכים אלא ישראל, כמו שהעמידוהו, כל ישראל בני מלכים הם, שבעת ההוא, בגמר התקון, נאמר, וכבוד מלכים דהיינו ישראל, חקור דבר. אמר רועה הנאמן, שהוא משה, לר״ש, ברוך אתה לעתיק יומין, שהוא הכתר, שמשם אתה כענף המתפשט מן האילן, כך הנשמות הן ענפים ממנו."],[5,"תנאין ואמוראין וכו׳:","אמר להם רועה הנאמן, תנאים ואמוראים, הרי ודאי עולה חטאת ואשם, הם ג׳ מצות שהם ג׳ אבות, דהיינו חג״ת, שלמים, היא המלכה, דהיינו המלכות, שהיא אבר של ז״א דהיינו ספירה עשירית שלו, שהיא תשלומין של כל אבר דז״א. כי המלכות נלקחה מז״א ונבנית לפרצוף שלם, ונמצא שז״א חסר ספירת המלכות, וכמו שחסר בכללו מן המלכות כן הוא חסר ממנו בכל פרט שלו, שכל ספירה פרטית כלולה רק מט׳ ספירות ולא מעשר. וע״כ כשהמלכות עולה ומתחברת עם ז״א היא משלמת לכל פרט שלו לע״ס, דהיינו תשלומים לכל אבר שלו. כעין יום הראשון של חג, שמקריבים עולת ראיה, שעי״ז המלכות עולה ומשלמת לכל אבר ואבר של ז״א, לעשר ספירות."],[6,"מי שלא חג וכו׳:","מי שלא חג יו״ט הראשון של חג, שלא הביא עולת ראיה ושלמי חגיגה, לחבר המלכות עם ז״א. אחר שעבר הרגל ולא הביא, נאמר עליו, מעוות לא יוכל לתקן וחסרון לא יוכל להמנות (חגיגה ט.) וזו היא חטאת, דהיינו חטא, המעכב לעולה, כי ע״י שלא הביא עולת ראיה, עיכב עלית מלכות לז״א, שה״ס עולה. חטא, היא דכר, וחטאת, היא נוקבא, שלשניהם משמעות אחת. ולפעמים מתבשמת החטאת, דהיינו החטא, ונפרדת מעולה, שאינה מעכבת עוד את המלכות מעליה, על ידי שעיר ההוא, שנאמר, ושעיר עזים אחד לחטאת. דהיינו אם מביא קרבן חטאת. פירוש. ש \u0003עולה\u0004 ה\"ס קו ימין וחסדים, שעל ידיהם המלכות עולה לז״א ולבינה. ו \u0003חטאת,\u0004 דהיינו החטאים, מגבירים את קו השמאל על הימין, ומכבים זה את זה, והמלכות לא תוכל לעלות לז״א. וע״י \u0003קרבן חטאת,\u0004 מתתקן קו השמאל, להכלל בימין. והמלכות יכולה לעלות לז״א."],[7,"אשם תלוי אחיד וכו׳:","העון שמביאים עליו אשם תלוי נאחז בשניהם, כמי שאוחז לזה ולזה, והוא תלוי ביניהם באמצע, כלומר שפוגם בקו האמצעי הכולל ימין ושמאל. כמו, הכל תלוי עד שיבא אליהו, ויפריד אותה, את המלכות, משם, מן הקליפות. שזה יהיה בגמר התקון, כך אשם תלוי הוא נאחז בשניהם, שפוגם בימין ושמאל, עד שנותנים לו, לסטרא אחרא, המזון שלו והשוחד שלו, ע״י קרבן אשם תלוי שהוא מקריב, (כמ״ש לעיל נח דף ל״ז ד״ה וכדין, ע״ש כל ההמשך) ואז יפרד הס״א משם, ואברים של הכלה, דהיינו ב׳ קוין ימין ושמאל של המלכות, מתקרבים זה לזה. כי כך הם האשמות והחטאים, כמו סרכות האחוזים בריאה דהיינו קרומות המדביקים כנפי ריאה זו לזו, ואינם מניחים את המלכות לעוף ולעלות למעלה, לז״א, לנשב ברוח הקודש."],[8,"שה איהו לעולה וכו׳:","שה הוא לעולה, שכתוב, ואיה השה לעולה. ונאמר בו שה תמים זכר, כמו שאתה אומר איש תמים, שפירושו שלם אף שה תמים פירושו שלם, להיותו עולה שהוא בימין. והרי צריכים לשאול. הרי שה הוא לימין. שעיר הוא לשמאל, דהיינו שעיר עזים אחד לחטאת, אשר עזים יורה על דינים עזים שהם בשמאל, (כנ״ל אות תכ״ט) ויש שעיר ויש שעיר, דהיינו שעיר אחד לה׳, ושעיר אחד לעזאזל. והיינו שכתוב, ונתן אהרן על שני השעירים גורלות גורל אחד לה׳ וגורל אחד לעזאזל. ובשעיר הזה, נאמר בעשו, איש שעיר וזה הוא בחינת כבד, שלוקח ושואב כל השמרים שבדם. שהם שחין, אבעבועות פורחות, ספחת, וכל מיני צרעת. והיינו שכתוב, ונשא השעיר עליו את כל עונותם אל ארץ גזרה. עונותם הוא אותיות עונות תם, שהוא הלב שנקרא תם. ואז נפרד מלהתערב בלב, שה״ס המלכות, ואז נתבשם, והוא, העזאזל, כבד, באלו העונות שנושא עליו, ואינו קל שיוכל לעלות ליעקב איש תם. שה״ס ז״א. והרעיא מהימנא עוד לא אמר שאלתו מה היא, כי רצה שהם יאמרו השאלה. שמחו בעלי המשנה וראשי הישיבות שירדו עם התנאים והאמוראים."],[9,"קם חד מנייהו וכו׳:","קם אחד מהם, אמר: רועה נאמן תן לי רשות לשאול, אחר שזכיתי לשמוע דברים יקרים האלו מפיך, כי תורה זו היוצאת מפיך יקרה היא מפנינים וכל חפציך לא ישוו בה, ועם כל זה הלכה היא וללמוד אני צריך. הנה שעיר לעזאזל, יפה אמרת שהוא בשמאל, אשם תלוי באיזה מקום הוא."],[10,"אמר ליה בריך וכו׳:","א״ל, ברוך אתה בני. יפה שאלת. אלא, מה עמוד האמצעי אחוזים בו ימין ושמאל, שהם חסד וגבורה, כמו גוף הנאחז בין שתי זרועות האדם. או כנשר, שאחוזים בו ב׳ כנפים לעוף בהם. כי פני נשר הוא קו האמצעי שבד׳ חיות, הכולל ימין ושמאל. וכמו יונה, שה״ס המלכות המכונה יונה בשיר השירים, שנאחזים בה ב׳ כנפים, שנמשלה לתורה, והכנפים שלה למצות עשה. שה״ס ימין וחסדים, שבהם \u0003היא העולה\u0004 ומעופפת למעלה, לז״א. כך, מצות לא תעשה שהם שמאל ודינים, הם המלכודות שלה, כמו צפרים הנאחזות בפח, וכל המלכודות שלה, המעכבות אותה לעוף, למעלה, לז״א ולבינה, ונקראות סרכות, דהיינו קרומות הדבוקים בכנפי ריאה, כאלו הקרומות המעכבים את כנפי ריאה לנשב."]],[[0,"","אָמַר לָהֶם, וַדַּאי כָּךְ זֶה, שֶׁהוּא תַּלְמִיד חָבֵר, שֶׁעָלָיו נֶאֱמַר (במדבר כה) בֶּן אַהֲרֹן הַכֹּהֵן, כְּמוֹ שֶׁנֶּאֱמַר בְּאַהֲרֹן, (שמותד) הוּא יִהְיֶה לְּךְ לְפֶה, כָּךְ גַּם בְּנוֹ יִהְיֶה לִי לְפֶה, שֶׁהִיא הַתּוֹרָה שֶׁבְּעַל פֶּה. מִשּׁוּם שֶׁאֵיךְ שֶׁהָיִיתִי בָּרִאשׁוֹנָה כְּבַד פֶּה וּכְבַד לָשׁוֹן, וְכָךְ יָקִים אוֹתִי הַקָּדוֹשׁ בָּרוּךְ הוּא - כְּבַר פֶּה בַּתּוֹרָה שֶׁבְּעַל פֶּה, וּכְבַד לָשׁוֹן בַּתּוֹרָה שֶׁבִּכְתָב, שֶׁלֹּא יֹאמְרוּ אֵלּוּ שֶׁלֹּא מַכִּירִים אוֹתִי, זֶה מִישֶׁהוּ אַחֵר. וְאֵלִיָּהוּ הוּא יִהְיֶה לִי לְפֶה, יָבֹא לְתַקֵּן אֶת כָּל הַסְּפֵקוֹת הַלָּלוּ וּלְיַשֵּׁב אוֹתָם."],[1,"","בְּאוֹתוֹ זְמַן - זֹּאת תּוֹרַת הָעֹלָה, הַבַּת, שֶׁהָיְתָה לְחוּצָה שְׁפָלָה בַגָּלוּת, עוֹלָה עַל כָּל הַדְּרָגוֹת שֶׁלְּמַעְלָה. זֶהוּ שֶׁכָּתוּב (משלי לא) רַבּוֹת בָּנוֹת עָשׂוּ חָיִל וְאַתְּ עָלִית עַל כֻּלָּנָה, וַעֲלִיָּתָהּ תִּהְיֶה לְאַבָּא שֶׁהוּא לְיָמִין שֶׁל חֶסֶד, שֶׁבּוֹ הָרוֹצֶה לְהַחְכִּים יַדְרִים, מִשָּׁם חָכְמָ\"ה, כ\"ח מ\"ה."],[2,"","אָמַר תַּנָּא אֶחָד, וַדַּאי שֶׁבִּגְלַל כָּךְ נֶאֱמַר בְּךְ, מוֹלִיךְ לִימִין מֹשֶׁה, מִשּׁוּם הַכַּלָּה שֶׁלְּךְ שֶׁלֹּא תִהְיֶה לְךְ שְׁלֵמוּת אֶלָּא עִמָּהּ. שֶׁכְּשֶׁאַתָּה תִהְיֶה שָׁלֵם עִמָּהּ, נֶאֱמַר בְּךְ פֶּה אֶל פֶּה אֲדַבֶּר בּוֹ וּמַרְאֶה וְלֹא בְחִידת. בְּמַרְאֶה, כְּמוֹ כַּלָּה שֶׁפּוֹשֶׁטֶת מַלְבּוּשֶׁיהָ וּמִתְיַחֶדֶת עִם בַּעְלָהּ בְּקֵרוּב בָּשָׂר, בְּרָמָ\"ח אֵיבָרִים שֶׁלָּהּ, וְלֹא מְכַסָּה אֵיבָר אֶחָד מִמֶּנָּה. וְזֶה בְּמַרְאֶה, רמ\"ח בְּחֶשְׁבּוֹן (ראוי לה שנאמר בו)."],[3,"","אָמַר הַמְּנוֹרָה הַקְּדוֹשָׁה, בָּרִאשׁוֹנָה נִרְאָה לְךְ הַמַּרְאֶה הַזֶּה, שֶׁנֶּאֱמַר בּו בְּמַרְאֶה, שֶׁהוּא לְךְ הַמַּרְאֶה הַגָּדול בַּסְּנֶה שֶׁנִּזְכַּר בּו חָמֵשׁ פְּעָמִים הַסְּנֶה. וְכָעֵת הִתְגַּלָּה לְךְ הַמַּרְאֶה הַזֶּה בְּרמ\"ח מִצְווֹת שֶׁהֵם בַּחֲמִשָּׁה חֻמְשֵׁי תוֹרָה. וְלֹא בְחִידת, שֶׁאוֹתָם לְבוּשִׁים שֶׁלָּהּ, שֶׁבָּהֶם רָאוּ כָּל הַנְּבִיאִים. שֶׁאֵין דֶּרֶךְ שֶׁתִּתְגַּלֶּה כַלָּה בְּקֵרוּב בָּשָׂר אֶלָּא לֶחָתָן שֶׁלָּהּ."],[4,"","בְּאוֹתוֹ זְמַן יִתְקַיֵּם בָּהֶם, (בראשית ב) וַיִּהְיוּ שְׁנֵיהֶם עֲרוּמִּים הָאָדָם וְאִשְׁתּוֹ וְלֹא יִתְבֹּשָׁשׁוּ. כְּמוֹ אָדָם וְאִשְׁתּוֹ שֶׁכְּבָר הָעֳבַר הָעִרְבּוּב הָרָע שֶׁל עֵרֶב רַב, קֻשְׁיָה רָעָה מִן הָעוֹלָם, שֶׁהֵם הָעֲרָיוֹת שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ, הָעֲרָיוֹת שֶׁל יִשְׂרָאֵל. כָּל שֶׁכֵּן הָעֲרָיוֹת שֶׁלְּךְ, רוֹעֶה הַנֶּאֱמָן. וּמֵהַהֲלָכָה שֶׁלְּךְ, שֶׁבִּשְׁבִילָם צָרִיךְ לְכַסּוֹת אֶת סוֹדוֹת הַתּוֹרָה, כְּמוֹ שֶׁבֵּאֲרוּהָ (משלי כה) כְּבֹד אֱלֹהִים הַסְתֵּר דָּבָר, עַד שֶׁעוֹבְרִים מִן הָעוֹלָם. וְאֵין מְלָכִים אֶלָּא יִשְׂרָאֵל, כְּמוֹ שֶׁבֵּאֲרוּהָ, כָּל יִשְׂרָאֵל בְּנֵי מְלָכִים הֵם. בְּאוֹתוֹ זְמַן, וּכְבֹד מְלָכִים חֲקֹר דָּבָר. אָמַר הָרוֹעֶה הַנֶּאֱמָן, בָּרוּךְ אַתָּה לְעַתִּיק הַיָּמִים, שֶׁמִּשָּׁם אַתָּה, כְּעָנָף שֶׁמִּתְפַּשֵּׁט מִן הָאִילָן, כָּךְ הַנְּשָׁמוֹת עָנָף מִמֶּנּוּ."],[5,"","תַּנָּאִים וְאָמוֹרָאִים, הֲרֵי וַדַּאי עוֹלָה וְחַטָּאת וְאָשָׁם הֵן שָׁלֹשׁ מִצְווֹת, שְׁלֹשָׁה אָבוֹת. שְׁלָמִים הַגְּבִירָה. אֵיבָר שֶׁהִיא תַּשְׁלוּמִים שֶׁל כָּל אֵיבָר, כְּמוֹ הַיּוֹם הָרִאשׁוֹן שֶׁל חַג. (מקום שהוא תשלומים של הכל כדגמת)."],[6,"","מִי שֶׁלֹּא חָג בְּיוֹם טוֹב רִאשׁוֹן, אֵין לוֹ תַּשְׁלוּמִים לָרִאשׁוֹן, וּשְׁאָר הַיָּמִים תַּשְׁלוּמִין זֶה בָזֶה, וּבָהֶם וְחֶסְרוֹן לֹא יוּכַל לְהִמָּנוֹת. אֲבָל מִי שֶׁלֹּא חָג יוֹם טוֹב רִאשׁוֹן שֶׁל חַג, עָלָיו נֶאֱמַר מְעֻוָּת לֹא יוּכַל לִתְקֹן וְחֶסְרוֹן לֹא יוּכַל לְהִמָּנוֹת, וְזוֹהִי הַחַטָּאת שֶׁמְּעַכֶּבֶת אֶת הָעוֹלָה. (מה הטעם) הַחֵטְא הוּא זָכָר. הַחַטָּאת נְקֵבָה. וְלִפְעָמִים שֶׁהֲרֵי הַחַטָּאת מִתְבַּשֶּׂמֶת וְנִפְרֶדֶת מֵעוֹלָה בְּאוֹתוֹ שָׂעִיר, שֶׁנֶּאֱמַר (במדבר כח) וּשְׂעִיר עִזִּים אֶחָד לְחַטָּאת."],[7,"","אָשָׁם תָּלוּי אָחוּז בִּשְׁנֵיהֶם, כְּמִי שֶׁאוֹחֵז לְכָאן וּלְכָאן, וְהוּא תָּלוּי בָּאֶמְצַע. כְּמוֹ, הַכֹּל תָּלוּי עַד שֶׁיָּבֹא אֵלִיָּהוּ וְיַפְרִידוֹ מִשָּׁם. כָּךְ אָשָׁם תָּלוּי הוּא אָחוּז בִּשְׁנֵיהֶם עַד שֶׁנּוֹתְנִים לוֹ אֶת מְזוֹנוֹ, הַשֹּׁחַד שֶׁלּוֹ, וְיִפָּרֵד מִשָּׁם, וּמִתְקָרְבִים הָאֵיבָרִים שֶׁל הַכַּלָּה זֶה לָזֶה. שֶׁכָּךְ הוּא אָשָׁם וְחַטָּאת, כְּמוֹ סְרָכוֹת שֶׁאֲחוּזוֹת בָּרֵאָה, וְלֹא מְנִיחִים אוֹתָם לִפְרֹחַ לַעֲלוֹת כְּלַפֵּי מַעְלָה לְנַשֵּׁב בְּרוּחַ הַקֹּדֶשׁ."],[8,"","הַשֶּׂה הוּא לְעוֹלָה, שֶׁכָּתוּב (בראשית כב) וְאַיֵּה הַשֶּׂה לְעֹלָה. וְנֶאֱמַר בּוֹ שֶׂה תָמִים זָכָר. זֶהוּ שֶׁכָּתוּב אִישׁ תָּמִים. וַהֲרֵי צָרִיךְ לִשְׁאֹל, שֶׁהֲרֵי שֶׂה הוּא לְיָמִין, וְהַשָּׂעִיר הוּא לִשְׂמֹאל, שֶׁהַיְנוּ שְׂעִיר עִזִּים אֶחָד לְחַטָּאת. וְיֵשׁ שָׂעִיר וְיֵשׁ שָׂעִיר. שָׂעִיר אֶחָד לַה', וְשָׂעִיר אֶחָד לַעֲזָאזֵל. וְהַיְנוּ שֶׁכָּתוּב (ויקרא טז) וְנָתַן אַהֲרֹן עַל שְׁנֵי הַשְּׂעִירִים גּוֹרָלוֹת גּוֹרָל אֶחָד לַה' וְגוֹרָל אֶחָד לַעֲזָאזֵל. וּבְאוֹתוֹ שָׂעִיר נֶאֱמַר בְּעֵשָׂו (בראשית כז) אִישׁ שָׂעִיר. וְזֶה הַכָּבֵד שֶׁנּוֹטֵל אֶת כָּל אוֹתָם הַשְּׁמָרִים שֶׁל הַדָּם - (שמשם) שְׁחִין אֲבַעְבּוּעוֹת פּוֹרְחוֹת, סַפָּחוֹת, וְכָל מִינֵי צָרַעַת. וְהַיְנוּ שֶׁכָּתוּב (ויקרא טז) וְנָשָׂא הַשָּׂעִיר עָלָיו אֶת כָּל עֲונֹתָם אֶל אֶרֶץ גְּזֵרָה. וְהֵם עֲונוֹת תָּם, שֶׁהוּא הַלֵּב, וְאָז נִפְרָד מִלְּהִתְעָרֵב בַּלֵּב, וְאָז מִתְבַּשֵּׂם, וְהוּא כָּבֵד בַּחֲטָאִים הַלָּלוּ וְלֹא קַל לַעֲלוֹת אֶל יַעֲקֹב אִישׁ תָּם. שָׂמְחוּ בַּעֲלֵי הַמִּשְׁנָה שֶׁל הַיְשִׁיבוֹת, שֶׁיָּרְדוּ עִם הַתַּנָּאִים וְהָאָמוֹרָאִים."],[9,"","קָם אֶחָד מֵהֶם וְאָמַר, רוֹעֶה הַנֶּאֱמָן, תֵּן לִי רְשׁוּת לִשְׁאֹל, אַחַר שֶׁזָּכִיתִי לִשְׁמֹעַ דְּבָרִים נִכְבָּדִים אֵלּוּ מִפִּיךְ, שֶׁהַתּוֹרָה הַזּוֹ שֶׁיּוֹצֵאת מִפִּיךְ (משלי ג) יְקָרָה הִיא מִפְּנִינִים וְכָל חֲפָצֶיךְ לֹא יִשְׁווּ בָהּ, וְעִם כָּל זֶה הֲלָכָה הִיא, וְלִלְמֹד אֲנִי צָרִיךְ. בַּשָּׂעִיר הַזֶּה לַעֲזָאזֵל זֶה נָאֶה, אַךְ אָשָׁם תָּלוּי בְּאֵיזֶה מָקוֹם הוּא?"],[10,"","אָמַר לוֹ, בָּרוּךְ אַתָּה בְּנִי, יָפֶה שָׁאַלְתָּ. אֶלָּא מָה הָעַמּוּד הָאֶמְצָעִי אֲחוּזִים בּוֹ יָמִין וּשְׂמֹאל, שֶׁהֵם חֶסֶד וּגְבוּרָה, כְּמוֹ גוּף שֶׁאָחוּז בֵּין שְׁתֵּי הַזְּרוֹעוֹת שֶׁל הָאָדָם. אוֹ כְּמוֹ נֶשֶׁר, שֶׁאֲחוּזִים בּוֹ שְׁתֵּי כְנָפַיִם לִפְרֹחַ בָּהֶן. וּכְמוֹ יוֹנָה שֶׁאֲחוּזִים בָּהּ שְׁתֵּי כְנָפַיִם, שֶׁנִּמְשְׁלָה לַתּוֹרָה, וּכְנָפֶיהָ לְמִצְווֹת עֲשֵׂה, וּבָהֶן הִיא הָעוֹלָה, וּפוֹרַחַת לְמַעְלָה. כָּךְ מִצְווֹת לֹא תַעֲשֶׂה הֵן הַמַּלְכֹּדֶת שֶׁלָּהּ, כְּמוֹ צִפֳּרִים הַנֶּאֱחָזוֹת בְּפַח. וְכָל הַמַּלְכּוֹדוֹת שֶׁלָּהּ שֶׁמְּעַכְּבוֹת אוֹתָהּ מִלִּפְרֹחַ נִקְרָאוֹת סְרָכוֹת, כְּמוֹ הַסְּרָכוֹת הַלָּלוּ שֶׁמְּעַכְּבוֹת אֶת כַּנְפֵי הָרֵאָה מִלִּנְשֹׁב."]]],[["הָכִי אָשָׁם. דְּיִשְׂרָאֵל אָחִיד בְּגַדְפּוֹי דִּשְׁכִינְתָּא, דְּאִינּוּן חֵיוָון דְּכוּרְסְיָיא, דְּלָא תְּהֵא עוֹלָה בְּהוֹן בְּזִכְוָון דְּיִשְׂרָאֵל, לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא, וּמְעַכְּבִין לָהּ, וּמַכְבִּידִין גַּדְפָּאָה חי\"ת חי\"ת חֲטָאוֹת דִּלְהוֹן. וְאָשָׁם אִימָּא דְּעֵרֶב רַב, סִרְכָא אֲחִידָא בְּכוּרְסְיָּיא, דְּתַמָּן מַטְרוֹנִיתָא, וְלָא מַנְחַת לָהּ לְסַלְּקָא מִגָּלוּתָא. וְזַכְוָון אֲחִידָן בָּהּ לְסַלְּקָא, אִשְׁתְּאָרַת בַּאֲוִירָא, כְּגוֹן סִרְכָא תָּלוּי בַּאֲוִירָא. וְדָא עַמּוּדָא דְּאֶמְצָּעִיתָא. (דאיהו אוירא) הָכִי אֲשָׁם תָּלוּי בְּצַּדִּיק, דְּאִיהוּ אָחִיד בֵּין שְׁמַיָא וְאַרְעָא.","חַטָאת אִיהִי יוֹתֶרֶת הַכָּבֵד, אַכְבִּידַת עָלָה בְּחַטָאוֹת, דְּלִכְלוּכִין דְּחוֹבִין דְּיִשְׂרָאֵל, כְּגַוְונָא דְּכָבֵד מַכְבִּיד שְׁמָרִים, דְּאִינּוּן דָּמִים, עַל עַרְקִין דְּלִבָּא. הָכִי אִלֵּין חֲטָאוֹת, מַכְבִּידִין עַל גַּדְפּוֹי דִּשְׁכִינְתָּא, דְּאִינּוּן פִּקוּדִין דַּעֲשֵׂה, דְּדַמְיָין לְכַנְפֵי יוֹנָה. לֹא תַּעֲשֶׂה כַּד אִינּוּן מַכְבִּידִין עַל עֲשֵׂה, דְּאִינּוּן כַּד חוֹבִין דְּיִשְׂרָאֵל מְרוּבִּין מִזַּכְוָון, אִתְּמַר בְּאוֹרַיְיתָא דְּאִיהוּ גּוּפָא, (דניאל ח׳:י״ב) וְתַשְׁלֵךְ אֱמֶת אַרְצָּה, וְאִיהִי צּווָֹחַת (איכה א׳:י״ד) נְתָנַנִי יְיָ' בִּידֵי לֹא אוּכַל קוּם (עמוס ה׳:ב׳) נָפְלָה לֹא תוֹסִיף קוּם.","וּבְגִין דָּא, תַּקִּינוּ תַּנָּאִים וַאֲמוֹרָאִים צְּלוֹתִין בַּאֲתַר דְּקָרְבְּנִין, לְאַעְבְּרָא חֲטָאוֹת וַאֲשָׁמוֹת מִינָּהּ. וּבְגִין דָּא תַּקִּינוּ צְּלוֹתָא דְּשַׁחֲרִית, כְּקָרְבָּן הַשַּׁחַר. וּצְּלוֹתָא דְּמִנְחָה, כְּקָרְבָּן בֵּין הָעַרְבַּיִם. וּצְּלוֹתָא דְּעַרְבִית, כְּאֵמוּרִים וּפְדָרִים דַּהֲווֹ מִתְאַכְּלִים כָּל הַלַּיְלָה. וּתְלַת אֲבָהָן דְּתָקִינוּ תְּלַת צְּלוֹתִין, לָקֳבֵל מֶרְכַּבְתָּא דְּאִינּוּן קְטִירִין בָּהּ. כְּמָה דְּאוּקְמוּהָ, הָאָבוֹת הֵן הֵן הַמֶרְכָּבָה, דְּאִינּוּן פְּנֵי אַרְיֵה אֶל הַיָּמִין לְאַרְבַּעְתָּם וְגו'. (ע\"כ רעיא מהימנא)","(ויקרא ו׳:ו׳) אֵשׁ תָּמִיד תּוּקַד עַל הַמִּזְבֵּחַ לֹא תִכְבֶּה. רִבִּי חִיָּיא פָּתַח, (בראשית כ״ב:ז׳) וַיֹּאמֶר יִצְחָק אֶל אַבְרָהָם אָבִיו וַיֹּאמֶר אָבִי וַיֹאמֶר הִנֶּנִּי בְנִי וְגוֹ', וַיֹּאמֶר וַיֹּאמֶר תְּלַת זִמְנִין דְּיִצְחָק, וַיֹּאמֶר חַד דְּאַבְרָהָם, אֲמַאי הָכִי. אֶלָּא, ג' לְמַעֲשֶׂה בְּרֵאשִׁית, דְּאִינּוּן תְּלַת דְּיִצְחָק הֲווֹ. וְחַד דְּאַבְרָהָם בָּרְבִיעִי, דִּכְתִיב הִנֶּנִּי בְנִי דְּחִיקָא (ס\"א ודייקא) הִנֶּנִּי. וּכְתִיב, (בראשית א׳:י״ד) יְהִי מְאֹרֹת בִּרְקִיעַ הַשָּׁמַיִם מְאֹרֹת חָסֵר.","וְאִי תֵּימָא וַיֹּאמֶר וַיֹּאמֶר יַתִיר אִינּוּן. אֶלָּא, אִינּוּן סְתִימִין הֲווֹ בְּמַחֲשָׁבָה. וְאִלֵּין, אִתְגַלְּיָין מִגּוֹ חֲשׁוֹכָא. וַיֹּאמֶר יִצְחָק אֶל אַבְרָהָם, וּכְתִיב (בראשית א׳:ג׳) וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר וַיְהִי אוֹר. וַיֹּאמֶר אָבִי, וּכְתִיב וַיֹּאמֶר אֱלֹהִים יְהִי רָקִיעַ בְּתוֹךְ הַמָּיִם וִיהִי מַבְדִּיל בֵּין מַיִם לָמָיִם. וַיֹּאמֶר הִנֵּה הָאֵשׁ, וַיֹּאמֶר אֱלֹהִים יִקָּווּ הַמַּיִם. וַיֹּאמֶר הִנֶּנִּי, וַיֹאמֶר אֱלֹהִים יְהִי מְאוֹרוֹת.","\u0003רעיא מהימנא\u0004 וְעוֹד אֵשׁ תָּמִיד תּוּקַד עַל הַמִּזְבֵּחַ וְגוֹ'. דָּא אוֹרַיְיתָא, דְּאִתְּמַר בָּהּ (ירמיהו כ״ג:כ״ט) הֲלֹא כֹה דְבָרִי כָאֵשׁ נְאֻם יְיָ'. לֹא תִכְבֶּה וַדַּאי, דַּעֲבֵירָה אֵינָה מְכַבָּהּ תּוֹרָה. אֲבָל עֲבֵירָה מְכַבָּהּ מִצְּוָה, וּמַאן דְּעָבִיד עֲבֵירָה דִּמְכַבָּהּ מִצְּוָה דְּאִיהִי נֵר, הָכִי מְכַבָּהּ נֵר דִּילֵיהּ, דְּאִתְּמַר בָּהּ (משלי כ׳:כ״ז) נֵר יְיָ' נִשְׁמַת אָדָם מִגוּפֵיהּ, וְהַאי הוּא כִּבּוּי, דְּאִשְׁתְּאַר גּוּפָא בַּחֲשׁוֹכָא. וְהָכִי מַאן דְּסָלִיק שְׁכִינְתָּא מֵאַתְרָהָא, גָּרִים (לכל העולם) כִּבּוּי וַחֲשׁוֹכָא לְהַהוּא אֲתַר. וַחֲשׁוֹכָא אִיהִי עֲבֵירָה, (משלי ל׳:כ״ג) וְשִׁפְחָה כִּי תִירַשׁ גְּבִירְתָּהּ.","וּסְלִיקוּ דְּמִצְּוָה מִסִּטְרָא דְּעַמֵּי הָאָרֶץ, לְהוֹן מְכַבָּהּ מִצְּוָה, לְקַיֵּים בְּהוֹן, (שמואל א ב׳:ט׳) וּרְשָׁעִים בַּחֹשֶׁךְ יִדָּמוּ. אֲבָל לְגַבֵּי מָארֵי תּוֹרָה, לֵית לֵיהּ כְּבִיָּיה עוֹלָמִית, בְּהוֹן דְּנָהֲרִין לָהּ בְּכַמָּה רָזִין דְּאוֹרַיְיתָא, דְּאוֹר רָ\"ז אִתְקְרֵי. וּמִצְּוֹת דְּאוֹרַיְיתָא דִּמְקַיְּימִין לָהּ רַבָּנָן, תּוֹרָה אִיהוּ לְגַבַּיְיהוּ, לַיְלָה וְיוֹמָם לָא תִכְבֶּה עָלַיְיהוּ, בְּגִין דִּמְקַיְּימִין בָּהּ (יהושע א׳:ח׳) וְהָגִיתָ בּוֹ יוֹמָם וָלַיְלָה.","וְעָשָׁן דְּסָלִיק מִפּוּמַיְיהוּ בְּמִלֵּי דְּאוֹרַיְיתָא, אִיהוּ עָשָׁן הַמַּעֲרָכָה, דִּמְסַדְּרִין לָהּ, וּמַעֲרִיכִין לָהּ לְגַבֵּי בַּעְלָהּ, כְּגוֹן (במדבר ח׳:ב׳) בְּהַעֲלוֹתְךָ אֶת הַנֵּרוֹת, דְּאִתְּמַר בְּהוֹן לְהַעֲלוֹת נֵר תָּמִיד. וּבְעָשָׁן הַמַּעֲרָכָה וְעָנָן הַקְּטֹרֶת, דְּאוֹרַיְיתָא עָשָׁן דִּילָהּ, יִתְעַר מִלִּבָּא, לְגַבֵּי חָכְמְתָא, דְּאִיהוּ כְּמוֹחָא, כְּגַוְונָא דַּעֲנָנָא. דְּאִתְעָרוּתָא דַּעֲנָנָא מִלִּבָּא, הֲדָא הוּא דִּכְתִיב (בראשית ב׳:ו׳) וְאֵד יַעֲלֶה מִן הָאָרֶץ, וּלְבָתַר וְהִשְׁקָה אֶת כָּל פְּנֵי הָאֲדָמָה.","הָכִי יִתְעַר עָשָׁן, מִבִּינָה, דְּאִיהוּ בְּלִבָּא, דְּאוּקְמוּהָ לְגַבֵּיהּ, הַלֵּב מֵבִין. וְסָלִיק לְגַבֵי חָכְמָה, דְּאִיהִי (נ\"א במוחא) כְּמוֹחָא. (ומאן) וּמַאי עָשָׁן. (דעת) דָּא, עַמּוּדָא דְּאֶמְצָּעִיתָא, דַּעַת, לֵב מֵבִין דַּעַת."],[[0,"הכי אשם דישראל וכו׳:","כך הוא אשם. כי ישראל האחוזים בכנפי השכינה, שהם החיות הנושאות את הכסא, החטאת מעכבת שלא תעלה בהם המלכות ע״י זכיות ישראל אל הקב״ה, שהוא ז״א, שהחטאות שלהם מעכבים אותה ומכבידים הכנפים. וה \u0003אשם,\u0004 הוא האם של הערב רב, הוא סרכא הנאחזת בהכסא, ששם המלכה, ולא רק בכנפים כמו החטאת, ואינה עוזבת אותה לעלות מן הגלות. והזכיות, שעושים ישראל, נאחזות בה להעלותה מן הגלות, וע״כ היא נשארת באויר, כמו סרכא התלויה באויר, ואויר, זהו עמוד האמצעי. כלומר שתלויה כמו סרכא בקו האמצעי, שהוא ז״א, מחמת האשם, ואינה יכולה להתיחד עמו זולת ע״י קרבן אשם (כנ״ל אות מ״א). וע״כ נקרא אשם תלוי, ע\"ש תלייתו באויר. וכך אשם תלוי בצדיק, שהוא יסוד דז״א, ששם הוא פוגם, ושם מתקן הקרבן אשם, שהוא אחוז בין שמים שהוא ז״א, ובין הארץ שהיא המלכות, ונבחן שהוא תלוי בין ז״א למלכות, וע״כ נקראת אשם תלוי."],[0,"","והנה נתבאר, שהחטאת מקומו בשמאל, ופוגם בכנפי השכינה, שה״ס החיות, הנושאות את הכסא, שהוא המלכות, ולא בכסא עצמו. אבל האשם, מקומו הוא בקו האמצעי, בת״ת או ביסוד, והוא פוגם בכסא עצמו."],[1,"חטאת איהי יותרת וכו׳:","חטאת היא יותרת הכבד, משום שמכבידה על המלכות, בחטאות מטינופי עונות ישראל, כמו הכבד המכביד עם השמרים שהם דמים, על עורקי הלב, כך אלו חטאות מכבידות על כנפי השכינה, שהם מצות עשה, הדומים לכנפי יונה. (כנ\"ל אות מ״ד) לא תעשה המכבידים על עשה, שאמרנו, (שם) פירושו, כשעונות ישראל הם מרובים מזכיות, אז נאמר, בתורה, שהוא גוף, דהיינו ז״א המכונה גוף, ותשלך אמת ארצה. והמלכות צועקת, נתנני ה׳ בידי לא אוכל קום. נפלה לא תוסיף קום."],[2,"ובגין דא תקינו וכו׳:","ומשום זה התקינו התנאים והאמוראים תפלות במקום קרבנות, להעביר חטאות ואשמות מן המלכות. ומשום זה התקינו תפלת שחרית, כקרבן השחר. ותפלת מנחה, כקרבן בין הערבים. ותפלת ערבית, כאמורים ופדרים שהיו מתאכלים על המזבח כל הלילה, ושלשת האבות, שהתקינו ג׳ תפלות, כנגד המרכבה שהם קשורים בה, שהם חג״ת, כמו שהעמדנו, האבות הן הן המרכבה. שהם פני אריה אל הימין, שהוא חסר, ופני שור, שהוא גבורה, ופני נשר שהוא ת״ת. שכנגדם הן שלש תפלות. (ע״כ רעיא מהימנא)."],[3,"אש תמיד תוקד וגו׳:","ר׳ חייא פתח, \u0003ויאמר\u0004 יצחק אל אברהם אביו \u0003ויאמר\u0004 אבי \u0003ויאמר\u0004 הנני בני \u0003ויאמר\u0004 הנה האש וגו'. ויאמר ויאמר, ג׳ פעמים ויאמר של יצחק ופעם אחת ויאמר של אברהם, למה נאמר כך. ומשיב, אלא כנגד ג׳ ימים של מעשה בראשית היו ג׳ ויאמר, של יצחק, וויאמר האחד של אברהם הוא כנגד יום רביעי דמעשה בראשית, שכתוב, \u0003הנני בני,\u0004 ומשלא כתוב ויאמר אברהם הנני בני, יורה שמתוך הדחק אמר לו הנני, וזה כנגד הכתוב, יהי מארת ברקיע השמים. שגם שם כתוב מארת חסר \u0003ו׳,\u0004 שיורה על קטרוג הלבנה שהיה שם, (כמ״ש ב״א מאות ק״י עד אות קט״ו)."],[4,"ואי תימא ויאמר וכו׳:","ואם תאמר, ויאמר ויאמר הכתובים בפרשה זו, הם יותר, ולמה אני דורש רק ד׳ ויאמר. ומשיב, אלא אלו ויאמר האחרים שכתוב בפרשה, הם סתומים היו במחשבה, כלומר שהם מימין הנמשך מאו״א עלאין הנקראים מחשבה, שהם סתומים, דהיינו חסדים מכוסים מחכמה. ואלו ד׳ ויאמר, שאני דורש אותם, הם המתגלים בחכמה מתוך החשך. דהיינו גילוי חכמה דקו שמאל, שאינה מתגלה רק עם החשך והדינים הנמשכים משם, (כנ״ל פקודי אות שע״ו) \u0003ויאמר יצחק אל אברהם\u0004 הוא כנגד הכתוב, ויאמר אלקים יהי אור ויהי אור. \u0003ויאמר אבי,\u0004 הוא כנגד הכתוב, ויאמר אלקים יהי רקיע בתוך המים ויהי מבדיל בין מים למים. \u0003ויאמר הנה האש,\u0004 הוא כנגד הכתוב, ויאמר אלקים יקוו המים. \u0003ויאמר הנני,\u0004 הוא כנגד הכתוב, ויאמר אלקים יהי מארת."],[4,"","פירוש. ויאמר הוא לשון השפעה, ויאמר יצחק אל אברהם הוא התכללות יצחק, שה\"ס קו השמאל וגילוי חכמה, באברהם, שה״ס קו ימין וחסדים. וז״ס ויהי אור שביום א׳ דמעשה בראשית. (כמ״ש לעיל תרומה אות תכ״ז) אור דיומא קדמאה וכו' בסטרא דאשא הוה וכו' דאיהו יום שני. ע״ש. דהיינו מהתכללות השמאל, שה״ס יום ב׳, ביום א׳ שהוא קו ימין, נאמר ויהי אור ביום הא'. הרי שויאמר יצחק אל אברהם שה״ס התכללות שמאל בימין ה\"ס המאמר יהי אור ויהי אור שביום א׳ דמעשה בראשית. \u0003ויאמר אבי,\u0004 ה״ס הבדלה, כי הכיר את קו ימין, לבחינת שורש אליו ולמים עליונים והוא עצמו בן וענף לקו ימין, דהיינו מים תחתונים. וא״כ הוא כנגד המאמר, ויאמר אלקים יהי רקיע בתוך המים ויהי מבדיל וגו'. \u0003ויאמר הנה האש והעצים,\u0004 ה\"ס התגלות הדינים שבקו שמאל, הנקראים אש ועצים, והוא כנגד המאמר, ותראה היבשה, שביום ג'. כי מחמת גילוי הדינים דקו שמאל נעשית המלכות בחינת יבשה, דהיינו שלא יכלה להוציא פירות (כנ״ל בהקסה״ז אות ר״ו) ונמצא אשר ויאמר הנה האש והעצים, הוא כנגד, ותראה היבשה. \u0003ויאמר הנני,\u0004 שלא נזכר בו שם אברהם שהוא חסד, שהיה לו לומר ויאמר אברהם הנני בני, זה מורה, שהשמאל שלט אז בלי ימין, שהוא אברהם. והוא כנגד המאמר יהי מארת, חסר \u0003ו׳\u0004 שהוא חסדים, מפני שהשמאל שלט אז בלי ימין, וע״כ קטרגה הלבנה שהיתה מחוסרת חסדים הנמשכים רק מימין (כנ״ל ב״א דף ק״ח ד\"ה וכבר) הרי שויאמר הנני בני, הוא כנגד המאמר, יהי מארת שביום הרביעי."],[5,"ועוד, אש תמיד וכו׳:","ועוד יש לפרש, אש תמיד תוקד על המזבח. זו היא התורה שנקראת אש, אשר נאמר בה, הלא כה דברי כאש נאום ה', שצריכה להאיר תמיד על המזבח שהוא המלכות. \u0003לא תכבה,\u0004 ודאי שאש התורה לא תכבה, כי עבירה אינה מכבה את התורה. אבל עבירה מכבה מצוה, ומי שעושה עבירה המכבה מצוה, שהיא נקראת נר, כך הוא מכבה את הנר שלו מגופו, דהיינו הנשמה שנקראת נר. שנאמר בה. נר ה׳ נשמת אדם. שזה הוא כבוי, כי הגוף נשאר בחשך. וכך מי שגורם במעשיו שתסתלק השכינה ממקומה, הוא גורם כבוי וחשך לאותו מקום. ועבירה היא חשך, ושפחה כי תירש גברתה, כי העבירה, שהיא שפחה וחשך, תירש מקום הגבירה, שהיא השכינה שנסתלקה ממקומה."],[6,"וסליקו דמצוה מסטרא וכו׳:","והעליה של מצוה מצד עם הארץ, שאין לו תורה, לו העבירה מכבה מצוה. לקיים בו ורשעים בחשך ידמו. אבל אצל בעלי תורה אין לה, להמצוה, כביה עולמית בהם, כי מאירים אל המצוה בכמה סודות התורה. כי אור נקרא \u0003ר״ז,\u0004 דהיינו שאור הוא בגי׳ ר״ז. שרומז שרזי התורה הם אורות. ומצוות התורה שרבנן מקיימים אותם נחשבת אצלם כמו תורה. אשר, לילה ויומם לא תכבה עליהם. משום שמקיימים בה, והגית בו יומם ולילה."],[7,"ועשן דסליק מפומייהו וכו׳:","והעשן העולה מפיהם של בעלי התורה, בדברי תורה, הוא, כמו עשן המערכה, שה״ס המלכות, ונקרא מערכה, משום שמסדרים אותה ועורכים אותה אל בעלה, שהוא ז״א, כמו, בהעלותך את הנרות שנאמר על העלאת המלכות, שה״ס נרות אל ז״א, שנאמר בהם, להעלות נר תמיד. דהיינו המלכות שנקראת נר. וזה הוא בעשן המערכה של מזבח החיצון, שהעשן נבחן למלכות. ובעשן המערכה וענן הקטרת, שהיא במזבח הפנימי, שהתורה, שהיא ז״א, הוא עשן שלה, יתעורר ז״א מן הלב, שהוא בינה, ויעלה אל החכמה, שהוא כמוח, כי מוח ולב הם חו״ב, ועשן המערכה של מזבח הפנימי, שהוא ז״א, יעלה אליהם למ״ן ויחבר חכמה ובינה זו בזו. כעין הענן שהתעוררות הענן הוא מן הלב. ז״ש, \u0003ואד יעלה מן הארץ,\u0004 דהיינו ז״א שנקרא אד, שהוא עשן, יעלה מן הבינה, שה״ס ארץ עליונה, ואחר כך, \u0003והשקה את כל פני האדמה,\u0004 כי אחר שז״א עלה למ\"ן, וקבל שפע מחכמה ובינה, הוא משקה את כל פני האדמה, שהוא המלכות."],[8,"הכי יתער עשן וכו׳:","ומפרש דבריו. כך יתעורר עשן מבינה, שהוא בלב, שהעמידו בו הלב מבין, ועולה אל החכמה, שהיא כמו מוח. ומהו עשן. הוא קו האמצעי שהוא ז״א העולה ומיחד \u0003חכמה ובינה,\u0004 ונעשה אליהם \u0003דעת,\u0004 שז״ס לב מבין דעת, שמלב, שהוא בינה, עולה דעת, שהוא קו האמצעי המיחד חו״ב."]],[[0,"","כָּךָ אָשָׁם. שֶׁיִּשְׂרָאֵל אֲחוּזִים בְּכַנְפֵי הַשְּׁכִינָה, שֶׁהֵן חַיּוֹת הַכִּסֵּא, שֶׁלֹּא תִהְיֶה עוֹלָה בָהֶם בַּזְּכֻיּוֹת שֶׁל יִשְׂרָאֵל לַקָּדוֹשׁ- בָּרוּךְ-הוּא, וּמְעַכְּבִים אוֹתָהּ, וּמַכְבִּידִים אֶת כְּנָפֶיהָ חי\"ת חי\"ת הַחַטָּאוֹת שֶׁלָּהֶם. וְאָשָׁם, אִמָּם שֶׁל עֵרֶב רַב, הַסִּרְכָה הָאֲחוּזָה בְּכִסֵּא, שֶׁשָּׁם הַגְּבִירָה, וְלֹא מְנִיחָה אוֹתָהּ לַעֲלוֹת מִן הַגָּלוּת, וְהַזְּכֻיּוֹת אֲחוּזוֹת בָּהּ לְהַעֲלוֹתָהּ, וְנִשְׁאֶרֶת בָּאֲוִיר כְּמוֹ סִרְכָה שֶׁתְּלוּיָה בָּאֲוִיר. וְזֶהוּ הָעַמּוּד הָאֶמְצָעִי (שהוא אויר). כָּךְ אָשָׁם תָּלוּי בַּצַּדִּיק, שֶׁהוּא אָחוּז בֵּין שָׁמַיִם וָאָרֶץ."],[1,"","הַחַטָאת הִיא יוֹתֶרֶת הַכָּבֵד, מַכְבִּידָה עָלֶיה בַּחַטָּאוֹת שֶׁל לִכְלוּכִים שֶׁל חֲטָאֵי יִשְׂרָאֵל, כְּמוֹ שֶׁהַכָּבֵד מַכְבִּיד עַל הַשְּׁמָרִים, שֶׁהֵם דָּמִים, עַל הָעֳרָקִים שֶׁל הַלֵּב. כָּךְ הַחַטָּאוֹת הַלָּלוּ מַכְבִּידוֹת עַל כַּנְפֵי הַשְּׁכִינָה, שֶׁהֵן מִצְווֹת עֲשֵׂה, שֶׁדּוֹמוֹת לְכַנְפֵי יוֹנָה. וְלֹא תַעֲשֶׂה, כְּשֶׁהֵן מַכְבִּידוֹת עַל עֲשֵׂה, שֶׁהֵן כְּשֶׁחֲטָאֵי יִשְׂרָאֵל מְרֻבִּים מִן הַזְּכֻיּוֹת, נֶאֱמַר בַּתּוֹרָה שֶׁהִיא גּוּף, (דניאל ח) וְתַשְׁלֵךְ אֱמֶת אַרְצָה, וְהִיא צוֹוַחַת, (איכה א) נְתָנַנִי ה' בִּידֵי לֹא אוּכַל קוּם, (עמוס ה) נָפְלָה לֹא תוֹסִיף קוּם."],[2,"","וּמִשּׁוּם זֶה תִּקְּנוּ תַּנָּאִים וְאָמוֹרָאִים תְּפִלּוֹת בִּמְקוֹם קָרְבָּנוֹת, לְהַעֲבִיר מִמֶּנָּה חַטָּאוֹת וַאֲשָׁמוֹת, וּמִשּׁוּם כָּךְ תִּקְּנוּ תְּפִלַּת שַׁחֲרִית כְּמוֹ קָרְבַּן הַשַּׁחַר, וּתְפִלַּת מִנְחָה כְּמוֹ קָרְבַּן בֵּין הָעַרְבַּיִם, וּתְפִלַּת עַרְבִית כְּמוֹ אֵמוּרִים וּפְדָרִים שֶׁהָיוּ מִתְאַכְּלִים כָּל הַלַּיְלָה. וּשְׁלֹשֶׁת הָאָבוֹת שֶׁתִּקְּנוּ שָׁלֹשׁ תְּפִלּוֹת, כְּנֶגֶד הַמֶּרְכָּבָה שֶׁהֵם קְשׁוּרִים בָּהּ, כְּמוֹ שֶׁבֵּאֲרוּהָ, הָאָבוֹת הֵן הֵן הַמֶּרְכָּבָה, שֶׁהֵם פְּנֵי אַרְיֵה אֶל הַיָּמִין לְאַרְבַּעְתָּם. (ע\"כ רעיא מהימנא)."],[3,"","אֵשׁ תָּמִיד תּוּקַד עַל הַמִּזְבֵּחַ לֹא תִכְבֶּה. רַבִּי חִיָּיא פָּתַח, (בראשית כב) וַיֹּאמֶר יִצְחָק אֶל אַבְרָהָם אָבִיו וַיֹּאמֶר אָבִי וַיֹּאמֶר הִנֶּנִּי בְנִי וְגוֹ'. וַיֹּאמֶר וַיֹּאמֶר, שָׁלֹשׁ פְּעָמִים שֶׁל יִצְחָק, וַיֹּאמֶר אֶחָד שֶׁל אַבְרָהָם. לָמָּה זֶה כָּךְ? אֶלָּא שְׁלֹשָׁה לְמַעֲשֵׂה בְרֵאשִׁית, שֶׁהֵם הָיוּ הַשָּׁלֹשׁ שֶׁל יִצְחָק, וְאֶחָד שֶׁל אַבְרָהָם בָּרְבִיעִי, שֶׁכָּתוּב הִנֶּנִּי בְנִי, דָּחוּק (ודוקא) הִנֶּנִּי. וְכָתוּב (בראשית א) יְהִי מְאֹרֹת בִּרְקִיעַ הַשָּׁמַיִם, מְאֹרֹת חָסֵר."],[4,"","וְאִם תֹּאמַר, וַיֹּאמֶר וַיֹּאמֶר הֵם יוֹתֵר - אֶלָּא שֶׁהֵם הָיוּ נִסְתָּרִים בַּמַּחֲשָׁבָה, וְאֵלּוּ הִתְגַּלּוּ מִתּוֹךְ הַחֲשֵׁכָה. וַיֹּאמֶר יִצְחָק אֶל אַבְרָהָם - וְכָתוּב (בראשית א) וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר וַיְהִי אוֹר. וַיֹּאמֶר אָבִי - וְכָתוּב וַיֹּאמֶר אֱלֹהִים יְהִי רָקִיעַ בְּתוֹךְ הַמָּיִם וִיהִי מַבְדִּיל בֵּין מַיִם לָמָיִם. וַיֹּאמֶר הִנֵּה הָאֵשׁ - וַיֹּאמֶר אֱלֹהִים יִקָּווּ הַמַּיִם. וַיֹּאמֶר הִנֶּנִּי - וַיֹּאמֶר אֱלֹהִים יְהִי מְאֹרֹת."],[5,"","וְעוֹד אֵשׁ תָּמִיד תּוּקַד עַל הַמִּזְבֵּחַ וְגוֹ' - זוֹ הַתּוֹרָה, שֶׁנֶּאֱמַר בָּהּ (ירמיה כג) הֲלֹא כֹה דְבָרִי כָאֵשׁ נְאֻם ה'. לֹא תִכְבֶּה וַדַּאי, שֶׁעֲבֵרָה אֵינָהּ מְכַבָּה תּוֹרָה. אֲבָל עֲבֵרָה מְכַבָּה מִצְוָה, וּמִי שֶׁעוֹבֵר עֲבֵרָה שֶׁמְּכַבָּה מִצְוָה, שֶׁהִיא נֵר, כָּךְ מְכַבֶּה אֶת נֵרוֹ, שֶׁנֶּאֱמַר (משלי ב) נֵר ה' נִשְׁמַת אָדָם, מִגּוּפוֹ, וְזֶהוּ כִבּוּי, שֶׁנִּשְׁאָר הַגּוּף בַּחֲשֵׁכָה. וְכָךְ מִי שֶׁמְּסַלֵּק שְׁכִינָה מִמְּקוֹמָהּ, גּוֹרֵם (לכל העולם) כִּבּוּי וַחֲשֵׁכָה לְאוֹתוֹ מָקוֹם. וַחֲשֵׁכָה הִיא עֲבֵרָה, (משלי ל) וְשִׁפְחָה כִּי תִירַשׁ גְּבִרְתָּהּ."],[6,"","וַעָלִיַּת הַמִּצְוָה שֶׁל עַם הָאָרֶץ מְכַבָּה לָהֶם אֶת הַמִּצְוָה, לְקַיֵּם בָּהֶם וּרְשָׁעִים בַּחֹשֶׁךְ יִדָּמוּ. אֲבָל לְבַעֲלֵי תוֹרָה אֵין לָהּ כְּבִיָּה עוֹלָמִית בָּהֶם, שֶׁמְּאִירִים לָהּ בְּכַמָּה סוֹדוֹת שֶׁל הַתּוֹרָה, שֶׁאוֹר נִקְרָא רָ\"ז. וּמִצְווֹת הַתּוֹרָה שֶׁמְּקַיְּמִים אוֹתָן חֲכָמִים, זוֹ תוֹרָה לְגַבֵּיהֶם, לַיְלָה וְיוֹמָם לֹא תִכְבֶּה עֲלֵיהֶם, מִשּׁוּם שֶׁמְּקַיְּמִים בָּהּ וְהָגִיתָ בּוֹ יוֹמָם וָלַיְלָה."],[7,"","וְהֶעָשָׁן שֶׁעוֹלֶה מִפִּיהֶם בְּדִבְרֵי תוֹרָה, הוּא עֲשַׁן הַמַּעֲרָכָה שֶׁמְּסַדְּרִים אוֹתָהּ וְעוֹרְכִים אוֹתָהּ לְבַעְלָהּ, כְּמוֹ (במדבר ח) בְּהַעֲלֹתְךְ אֶת הַנֵּרֹת, שֶׁנֶּאֱמַר בָּהֶם לְהַעֲלוֹת נֵר תָּמִיד. וּבַעֲשַׁן הַמַּעֲרָכָה וּבַעֲנַן הַקְּטֹרֶת, שֶׁהַתּוֹרָה הוּא הֶעָשָׁן שֶׁלָּהּ, יִתְעוֹרֵר מֵהַלֵּב לַחָכְמָה, שֶׁהוּא כְּמוֹ מֹחַ, כְּמוֹ הֶעָנָן. שֶׁהִתְעוֹרְרוּת שֶׁל הֶעָנָן הִיא מֵהַלֵּב. זֶהוּ שֶׁכָּתוּב (בראשית ב) וְאֵד יַעֲלֶה מִן הָאָרֶץ, וְאַחַר כָּךְ - וִהִשְׁקָה אֶת כָּל פְּנֵי הָאֲדָמָה."],[8,"","כָּךָֹ יִתְעוֹרֵר עָשָׁן מִבִּינָה, שֶׁהִיא בַּלֵּב, שֶׁבֵּאֲרוּהָ אֶצְלוֹ, הַלֵּב מֵבִין, וְעוֹלֶה לַחָכְמָה שֶׁהִיא (במח) כְּמוֹ מֹחַ. (ומה) וּמִי הֶעָשָׁן? (דעת) זֶה הָעַמּוּד הָאֶמְצָעִי, דַּעַת, לֵב מֵבִין דַּעַת."]]],[["לְבָתַר דְּנָחִית עָשָׁן, חָכְמָה לְגַבֵי בִּינָה, דְּאִינּוּן דָּא לִשְׂמָאלָא, וְדָא לִימִינָא. אִיהוּ נָחִית מָלֵּא מֵאַבָּא וְאִימָּא, מָלֵּא י\"ה, לְאוֹקְדָא עֵצִּים דְּאִינּוּן תַּלְמִידֵי חֲכָמִים, מִסִּטְרָא דְּעֵץ חַיִּים, דְּאִינּוּן אֵבָרִים דְּגוּפָא, דְּתַמָּן ה' הָעֵצִּים ודַּאי, לְאוֹקְדָא לוֹן בְּשַׁלְהוֹבִין דְּאוֹרַיְיתָא, דְּאִתְּמַר בֵּיהּ (ירמיהו כ״ג:כ״ט) הֲלֹא כֹה דְבָרִי כָּאֵשׁ נְאֻם יְיָ'. בְּשַׁלְהוֹבִין דְּנֵר מִצְּוָה בִּרְחִימוּ. ע\"כ (קנ\"ז ע\"ב תנאים ואמוראים וכו')","פִּקוּדָא (שייך לדף ק\"י ע\"ב) לְהַקְרִיב בְּכָל יוֹמָא תְּמִידִין. וַאֲבַתְרֵיהּ לְהַדְלִיק אֵשׁ, הֲדָא הוּא דִכְתִיב אֵשׁ תָּמִיד תּוּקַד עַל הַמִּזְבֵּחַ לֹא תִכְבֶּה. וַאֲבַּתְרֵיהּ, תְּרוּמַת הַדֶּשֶׁן. וַאֲבַתְרֵיהּ, קָרְבָן נֶדֶר אוֹ נְדָבָה. תַּנָּאִים וְאָמוֹרָאִים, כָּל אִלֵּין תְּמִידִין, אִינּוּן מִדוֹת דְּקוּדְשָׁא בְּרִיךְ הוּא, דִּצְּרִיכֵי לְמֶהֱוִי לוֹן נַיְיחָא. וְאַף עַל גַּב דְּכָל סְפִירָן כֻּלְּהוּ חַד, מִכָּל מָקוֹם, כָּל סְפִירָה וּסְפִירָה מְמָנָא עַל שַׁבָּתוֹת וּזְמָנִין וְיוֹמִין טָבִין, וְהַהִיא מִדָּה דְּשׁוּלְטָנוּתָא דְּהַהוּא זִמְנָא, כָּל סְפִירָן אִתְכְּלִילוּ בָּה, וְאִתְקְרִיאוּ כֻּלְּהוּ עַל שֵׁם הַהִיא מִדָּה, בְּחֶסֶד חֲסָדִים, בִּגְבוּרָה גְּבוּרוֹת וְהָכִי בְּכָל מִדָה.","וְאִית הַשְׁבָּתַת מְלָאכָה, כְּגוֹן שׁוֹר, דְּאִית לֵיהּ עוֹל. וַחֲמוֹר, דְּאִית לֵיהּ מַשְׂאוֹי. בֵּין עוֹל מַלְכוּת שָׁמַיִם, כְּגוֹן תְּפִילִין. בֵּין עוֹל מַלְכוּת עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, כְּפוּם עוֹבָדַיְיהוּ, בְּאִלֵּין יוֹמִין אִית לוֹן הַשְׁבָּתַת מְלָאכָה וְנַיְיחָא. מַאן דְּלָא אִתְעֲסַּק בְּאוֹרַיְיתָא וּבְפִקּוּדִין, אִית לֵיהּ עוֹל מַלְכוּת עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת. וּמַאן דְּאִתְעֲסָּק בְּאוֹרַיְיתָא וּבְפִקּוּדִין, אִית לוֹן עוֹל מַלְכוּת שָׁמַיִם, דְּאִיהִי ה' בַּתְרָאָה, מַלְכוּת שָׁמַיִם אִתְקְרִיאַת.","עוֹל מִצְּוֹת אִיהִי וַדַּאי, בְּגִין דְּבָהּ אִתְבְּרִיאוּ כָּל בִּרְיָין דִּשְׁמַיָּא וְאַרְעָא, הֲדָא הוּא דִכְתִיב, (בראשית ב׳:ד׳) אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם. בְּה' בְּרָאָם. וְכַד יֵיתֵי שַׁבָּת וְיוֹם טוֹב, נַחְתַּת בִּינָה דְּאִיהוּ יד\"ו, עַל ה', דְּאִיהִי מַלְכוּת שָׁמַיִם נְשָׁמָה יְתֵירָה, וְאִיהוּ (שמות ל״ב:ט״ז) חָרוּת עַל הַלּוּחוֹת. אָנֹכִי בִּיצִּיאַת מִצְּרַיִם, וּפְרִישַׁת גַּדְפָהָא עַל בְּרַתָּא, וְעַל מַשִּׁרְיָין דִּילָהּ, וְאִית לוֹן נַיְיחָא. וְאִתְּמַר בְּמַשִּׁרְיָין דְּסָמָאֵ\"ל וְנָחָשׁ, (דברים כ״ח:י׳) וְרָאוּ כָּל עַמֵּי הָאָרֶץ כִּי שֵׁם יְיָ' נִקְרָא עָלֶיךָ וְיָרְאוּ מִמֶּךָ, אוֹת תְּפִלִין וְאוֹת שַׁבָּת, וְאוֹת דְּיוֹמִין טָבִין, וְאוֹת בְּרִית כֻּלְּהוּ שְׁקִילִין.","וְאִית אוֹת דְּשַׁדַּ\"י, דְּאִיהוּ מְטַטְרוֹ\"ן עֶבֶד, וְכַמָּה עַבָדִין תַּלְיָין מִנֵּיהּ, דִּמְמָנָא עַל אִלֵּין דְּעַבְדִין פִּקּוּדֵי עַל מְנָת לְקַבֵּל פְּרָס. מְטַטְרוֹ\"ן וּמַשִּׁרְיָין דִּילֵיהּ מְמָנָן עָלַיְיהוּ. בְּגִינַיְיהוּ אִתְּמַר, (שמות כ״ג:י״ב) לְמַעַן יָנוּחַ שׁוֹרְךָ וַחֲמוֹרֶךָ וְעַבְדְךָ וַאֲמָתְךָ. אֲבָל אִינּוּן דְּעַבְדִין פִּקוּדִין שֶׁלֹּא עַל מְנָת לְקַבֵּל פְּרָס, אִינּוּן בְּנוֹי דְּמַלְכָּא וּמַטְרוֹנִיתָא. וְאִינּוּן כִּתְרִין וְתָגִין עַל רֵישָׁא, דְּעַבָדִין בְּיוֹמִין דְּחוֹל. וּבְגִינַיְיהוּ אִתְּמַר וּדְאִשְׁתַּמַּשׁ בְּתָגָא חֲלָף, וְהַזָּר הַקָּרֵב לְגַבַּיְיהוּ יוּמַת. דְּשַׁבָּתּוֹת אִתְקְרִיאוּ לְגַבֵּי עַבָדִין.","וּבְגִין דָּא, אִם כְּבָנִים אִם כַּעֲבָדִים. אִם כְּבָנִים, דְּאִתְּמַר בְּהוֹן (דברים י״ד:א׳) בָּנִים אַתֶּם לַיְיָ' אֱלֹהֵיכֶם. אִם כַּעֲבָדִים, (ויקרא כה) כִּי לִי בְנֵי יִשְׂרָאֵל עֲבָדִים וְלָא שְׁאָר אוּמִין. אַבָל אִינּוּן חַיָיבַיָא דְּלָא מִשְׁתַּדְּלִין בְּאוֹרַיְיתָא וּמִצְּוֹת, וְלֵית עָלַיְיהוּ עוֹל תּוֹרָה וְעוֹל תְּפִלִין, וּשְׁאָר פִּקוּדִין, אִינּוּן עֲבָדִין לְאוּמִין דְּעָלְמָא, וּמִשְׁתַּעֲבְּדִין בְּהוּ. כְּגוֹן (דברים ו׳:כ״א) עֲבָדִים הָיִינוּ לְפַרְעֹה בְּמִצְּרָיִם.","וְאִי נַטְרֵי שַׁבָּתוֹת וְיָמִים טוֹבִים, אִתְּמַר בְּהוּ וַיוֹצִּיאֵנוּ יְיָ' אֱלֹהֵינוּ. וְיִתְקַיָּים בְּהוּ, (שמות כ״ג:י״ב) לְמַעַן יָנוּחַ שׁוֹרְךָ וַחֲמוֹרֶךָ, חֲמוֹר בַּתוֹרָה וּבְמִצְּוֹת, וְיִנָּפֵשׁ בֶּן אֲמָתְךָ וּבְהֶמְתֶּךָ, עַם הָאָרֶץ בְּהֵמָה אִקְרֵי. וּלְבָתַר דְּיִיעוּל גַּרְמֵיהּ תְּחוֹת אָדָם בַּתּוֹרָה, יִתְקַיָּים בֵּיהּ (תהילים ל״ו:ז׳) אָדָם וּבְהֵמָה תּוֹשִׁיעַ יְיָ'. אִם הוּא כַּסּוּס דְּרָכִיב עָלֵיהּ מָארֵיהּ, וְסָבִיל לֵיהּ, וְלָא מְבָעֵט בְּמָארֵיהּ.","וּמַאי סְבִילוּ דְּעַם הָאָרֶץ לְתַּלְמִיד חָכָם. בְּגִין, דְתַּלְמִיד חָכָם כְּיּוֹם שַׁבָּת צָּרִיךְ אִיהוּ, דְּלֵית לֵיהּ מִדִּילֵיהּ, וְאִי עַם הָאָרֶץ סָבִיל לֵיהּ בְּמָמוֹנֵיהּ, וְאִתְנְהִיג בֵּיהּ כְּפוּם רְעוּתֵיהּ לְשַׁמְּשָׁא לֵיהּ, וּלְאִתְנָהֲגָא בְּפִקּוּדִין כְּפוּם רְעוּתֵיהּ, יִתְקַיֵּים בֵּיהּ אָדָם וּבְהֵמָה תּוֹשִׁיעַ יְיָ'. יוֹשִׁיעַ לֵיהּ מִשּׁוֹד וּגְזֵלָה, יוֹשִׁיעַ לֵיהּ מִמַּלְאַךְ הַמָּוְת, דְּלָא שַׁלִּיט עָלֵיהּ, וְיִשְׁחָט לֵיהּ בְּסַכִּין פָּגוּם דִּילֵיהּ. וְכָל מַאן דְּשָׁחִיט בְּסַכִּין פָּגוּם, נְבֵלָה אִיהוּ, דְּאִתְּמַר בֵּיהּ לַכֶּלֶב תַּשְׁלִיכוּן אוֹתוֹ, דְּאִיהוּ סָמָאֵ\"ל.","וְנֶפֶשׁ דְתַּלְמִיד חָכָם אִתְקְרִיאַת שַׁבָּת מַלְכְּתָא, נֶפֶשׁ יְתֵירָה דְּשַׁבָּת. וְעֹנֶג דִּילֵיהּ נִשְׁמַת חַיִּים, וְרוּחַ שִׂכְלִי. וְאִינּוּן נְשָׁמָה יְתֵירָה, רוּחַ יְתֵירָה, עַל נְשָׁמָה וְרוּחָא וְנַפְשָׁא, דְּאִינּוּן עַבָדִין, דְּשַׁלְטִין בְּגוּפָא, דְּיוֹמִין דְּחוֹל. נְשָׁמָה יְתֵירָה, נִשְׁמַת כָּל חַי, (רמ\"ב ע\"ב) כֶּתֶר בְּרֹאשׁ צַּדִיק, דְּאִיהוּ יוֹם שַׁבָּת. וּבְהַאי נְשָׁמָה יְתֵירָה תְּהַלֵּל יָהּ, דְּאִינּוּן אַבָּא וְאִימָּא, דְּעָלָהּ אִתְּמַר, (ישעיהו ס״ד:ג׳) עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךָ, בְּגִין דְּאִיהוּ מֶרְכָּבָה לְעִלַּת הָעִלּוֹת, דְּאִיהוּ מְכוּסֶּה וְלָא שַׁלִּיט עָלֵיהּ עֵינָא, וּבְגִין דָּא עַיִן לֹא רָאָתָה.","רוּחָא יְתֵירָה, נָהָר דְּנָפִיק מְעֵדֶן, מִבֵין אַבָּא וְאִימָּא. וּמַהֲלָכוֹ חֲמֵשׁ מְאָה שְׁנִין, וּמָטֵי לִשְׁתִיתָאָה דְּאִיהוּ צַּדִיק. לְהַשְׁקוֹת אֶת הַגָּן, דְּאִיהִי נֶפֶשׁ יְתֵירָה, מַלְכוּת."],[[0,"לבתר דנחית עשן וכו׳:","אחר שיורד העשן, שהוא ז״א, ודעת, מחכמה לבינה, שהם זה לשמאל וזה לימין, שבינה היא משמאל לז\"א, והחכמה היא מימינו, הוא יורד מלא משפע אבא ואמא, שהם חכמה ובינה, מלא, משפע \u0003י״ה,\u0004 לשרוף העצים, שהם תלמידי חכמים, שהם מצד \u0003עץ\u0004 החיים שהוא ז״א, וע\"כ מכונים עצים, שהם אברים של הגוף, ששם \u0003ה'\u0004 של \u0003ה\u0004 עצים, דהיינו אברי מלכות הנקראת גוף ונקראת \u0003ה׳\u0004 שנשמות ת״ח הם תולדות מז\"א ומלכות. ודאי שהכוונה היא, לשרוף אותם בשלהבת התורה, שנאמר בה כה דברי כאש נאם ה'. ובשלהבת של נר מצוה באהבה, דהיינו ברשפי אש האהבה של המצוה."],[1,"פקודא להקריב בכל וכו׳:","מצוה להקריב בכל יום תמידים ואח״כ להדליק אש, ז״ש אש תמיד תוקד על המזבח לא תכבה. ואח\"כ, תרומת הדשן, ואח״כ קרבן נדר או נדבה. תנאים ואמוראים, כל אלו התמידים הם מדותיו של הקב״ה, דהיינו הספירות, שצריך שיהיה להם מנוחה. ואע״פ שכל הספירות כולם אחד, מכל מקום כל ספירה וספירה ממונה על שבתות וזמנים וימים טובים דהיינו שבכל שבת ובכל יו״ט שולטת ספירה אחרת, ומדה ההיא השולטת באותו זמן, כל הספירות נכללות בה, כי בכל ספירה כלולות כל עשר ספירות, ונקראות כולן על שם אותה ספירה השולטת, בחסד חסדים, ובגבורה גבורות. אם ספירה השולטת היא חסד, נקראות כל עשר ספירות הנכללות בה, חסדים. ואם הספירה השולטת היא גבורה, נקראות כל ע״ס שבה, גבורות, וכך בכל מדה השולטת."],[2,"ואית השבתת מלאכה וכו׳:","ויש השבתת מלאכה בשבת ויו״ט, לכל אחד לפי בחינתו, כמו שור שנוהג בו עול, וחמור שנוהג בו משא, בין אותם שיש להם עול מלכות שמים, כמו תפלין, שבשבת ויו״ט הם פטורים. ובין עול מלכות עכו״ם, כולם לפי מעשיהם יש להם באלו ימים, השבתת מלאכה ומנוחה. כי מי שאינו עוסק בתורה ומצוות יש לו עול מלכות עכו\"ם. ומי שעוסק בתורה ומצות יש לו עול מלכות שמים, שהיא ה׳ אחרונה דהוי״ה, הנקראת מלכות שמים."],[3,"עול מצות איהי וכו׳:","היא ודאי עול מצות, משום שבה נבראו כל הבריות שבשמים וארץ, כי כל המציאות שבג׳ עולמות בי״ע יצאו מן המלכות, ז״ש, אלה תולדות השמים והארץ בהבראם, שהוא אותיות בה׳ בראם, וכשבאים שבת ויו״ט, יורדת בינה, שהוא \u0003יה״ו,\u0004 שהם חב״ד שבבינה, על \u0003ה׳\u0004 שהיא מלכות שמים, ואז היא נשמה יתרה, והיא הבינה, חרות על הלוחות, הלוחות הם המלכות, והשראת הבינה עליה, עושה אותה חרות מן כל הקליפות, והיא סוד \u0003אנכי\u0004 שביציאת מצרים, דהיינו מ״ש, אנכי ה' אלקיך אשר הוצאתיך מארץ מצרים, שהבינה פרשה כנפיה על הבת, שהיא מלכות, ועל המחנות שלה, ויש להם מנוחה. ואז נאמר במחנות סמאל והנחש, וראו כל עמי הארץ כי שם ה׳ נקרא עליך ויראו ממך. שם ה׳, היינו אות תפלין, אבל אות תפלין, ואות שבת, ואות של יום טוב, ואות ברית, כולם שוים. ועל כולם נאמר, וראו כל עמי הארץ כי שם ה׳ נקרא עליך."],[4,"ואית אות דשדי וכו׳:","ויש אות של השם \u0003שד״י,\u0004 שהוא המלאך מטטרון, שנקרא עבד. וכמה עבדים נמשכים ממנו, שהם ממונים על אותם שעושים מצות על מנת לקבל שכר, אשר מטטרון והמחנות שלו ממונים עליהם. עליהם נאמר, למען ינוח שורך וחמורך \u0003ועבדך ואמתך.\u0004 אבל אותם שעושים מצות שלא על מנת לקבל שכר, הם בניהם של המלך והמלכה, שהם ז״א ומלכות, ובימות החול, הם כתרים ועטרות על ראשיהם של העבדים הנ״ל, ובשבילם אמרו, והמשתמש בתגא חלף, שהמשמש עם הבנים הנ״ל, שהם עטרה לעבדים, חולף ועובר מן העולם. והזר הקרב אליהם, אל הבנים, יומת. כי הם, בימות החול, נקראים שבתות כלפי העבדים."],[5,"ובגין דא כעבדים וכו׳:","ומשום זה. אומרים במוסף ראש השנה, אם כבנים אם כעבדים, \u0003אם כבנים,\u0004 היינו שנאמר בהם, בנים אתם לה׳ אלקיכם. \u0003אם כעבדים,\u0004 שכתוב, כי לי בני ישראל עבדים, ולא שאר האומות. אבל אלו הרשעים שאינם עוסקים בתורה ומצות, ואין עליהם עול תורה ועול תפלין ושאר המצות, הם עבדים לאומות העולם המשעבדים בהם. כמו, עבדים היינו לפרעה במצרים."],[6,"ואי נטרי שבתות וכו׳:","ואם שומרים שבתות וימים טובים, נאמר בהם, ויוציאנו ה׳ אלקינו. ויתקיים בהם, למען ינוח שורך וחמורך, שהם חמור בתורה ומצות, וינפש בן אמתך ובהמתך, עם הארץ, נקרא בהמה. ואחר שיכניס את עצמו תחת בחינת אדם, בתורה, יתקיים בו, אדם ובהמה תושיע ה׳. והיינו אם הוא כסוס, שאדונו רוכב עליו, והסוס סובל אותו, ואינו בועט באדונו. כך הוא צריך להיות כסוס תחת התלמיד חכם."],[7,"ומאי סבילו דעם הארץ וכו׳:","ומהו הסבל, שהעם הארץ צריך לסבול את התלמיד חכם. הוא, כי התלמיד חכם הוא, כיום השבת, שהוא צריך להיות כמי שאין לו משלו, כי ימות החול מכינים לשבת, ובשבת אין כלום ואם עם הארץ סובל אותו בכספו ונוהג עמו לעשות רצונו, לשמש אותו, ולהתנהג במצות כפי רצונו, יתקיים בו, אדם ובהמה תושיע ה'. יושיע לו משוד ומגזלה, יושיע לו ממלאך המות שלא ישלוט עליו וישחט אותו בסכין פגום שלו, וכל מה שנשחט בסכין פגום הוא נבלה, שנאמר בו, לכלב תשליכון אותו. שהוא סמאל. שנקרא כלב."],[8,"ונפש דת״ח אתקריאת וכו׳:","ונפש של ת״ח, נקראת שבת המלכה, שהיא נפש היתירה של שבת והעונג שלה, הוא, נשמת חיים ורוח שכלי, שהם נשמה יתירה נשמת כל חי ורוח יתירה, על נשמה רוח ונפש שהם עבדים, השולטים בגוף בימות החול. נשמה יתירה, הוא סוד כתר על ראש צדיק שהוא יום השבת, שהוא ז״א הנקרא יום השבת, והכתר שלו הוא מאבא ואמא, ובנשמה יתירה הזו תהלל \u0003יה,\u0004 שהם אבא ואמא, שעליהם נאמר, עין לא ראתה אלקים זולתך, משום שהם מרכבה לעלת העלות, שהוא א״א, שהוא מכוסה ואין העין שולטת בו. ומשום זה, עין לא ראתה, גם באו״א שהם המרכבה שלו. שמהם נמשכת נשמה יתירה דשבת, שהם כתר דז״א."],[9,"רוחא יתירה נהר וכו׳:","רוח יתירה, הוא נהר היוצא מעדן, דהיינו מבין אבא ואמא, שהוא ז״א, שה״ס בן י״ה, כי נאצל מי״ה, שהם אבא ואמא, ומהלכו חמש מאות שנים, דהיינו ה׳ ספירות חג״ת נ״ה הנמשכים לו מבינה, שספירותיה בסוד מאות, וע״כ הם ה׳ מאות שנה ומגיע לספירה הששית שהיא צדיק, דהיינו יסוד, להשקות את הגן, שהוא נפש יתירה, דהיינו המלכות."]],[[0,"","אַחַר שֶׁיּוֹרֵד עָשָׁן, חָכְמָה לְבִינָה, שֶׁהֵם זֶה לִשְׂמֹאל וְזֶה לְיָמִין. הוּא יוֹרֵד מָלֵא מֵאַבָּא וְאִמָּא, מָלֵא י\"ה, לִשְׂרֹף עֵצִים שֶׁהֵם תַּלְמִידֵי חֲכָמִים, מִצַּד שֶׁל עֵץ הַחַיִּים, שֶׁהֵם אֵיבָרִים שֶׁל הַגּוּף, שֶׁשָּׁם ה' הָעֵצִים וַדַּאי, לִשְׂרֹף אוֹתָם בְּשַׁלְהֲבוֹת הַתּוֹרָה, שֶׁנֶּאֱמַר בָּהּ הֲלֹא כֹה דְבָרִי כָּאֵשׁ נְאֻם ה'. בְּשַׁלְהֲבוֹת נֵר שֶׁל מִצְוָה בְּאַהֲבָה."],[1,"","מִצְוָה לְהַקְרִיב בְּכָל יוֹם תְּמִידִים וְאַחֲרָיו לְהַדְלִיק אֵשׁ. זֶהוּ שֶׁכָּתוּב אֵשׁ תָּמִיד תּוּקַד עַל הַמִּזְבֵּחַ לֹא תִכְבֶּה. וְאַחֲרָיו תְּרוּמַת הַדֶּשֶׁן, וְאַחֲרָיו קָרְבַּן נֶדֶר אוֹ נְדָבָה. תַּנָּאִים וְאָמוֹרָאִים, כָּל אֵלּוּ תְּמִידִים, הֵם מִדּוֹתָיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁצְּרִיכִים לִהְיוֹת לָהֶם נַחַת. וְאַף עַל גַּב שֶׁכָּל הַסְּפִירוֹת כֻּלָּן אַחַת, מִכָּל מָקוֹם כָּל סְפִירָה וּסְפִירָה מְמֻנָּה עַל שַׁבָּתוֹת וּזְמַנִּים וְיָמִים טוֹבִים, וְאוֹתָהּ מִדָּה שֶׁשּׁוֹלֶטֶת בְּאוֹתוֹ זְמַן, כָּל הַסְּפִירוֹת נִכְלָלוֹת בָּהּ, וְכֻלָּן נִקְרָאוֹת עַל שֵׁם אוֹתָהּ מִדָּה., בְּחֶסֶד חֲסָדִים, בִּגְבוּרָה גְּבוּרוֹת, וְכָךְ בְּכָל מִדָּה."],[2,"","וְיִשִׁ הַשְׁבָּתַת מְלָאכָה, כְּמוֹ שׁוֹר שֶׁיֵּשׁ לוֹ עֹל, וַחֲמוֹר שֶׁיֵּשׁ לוֹ מַשָּׂא. בֵּין עֹל מַלְכוּת שָׁמַיִם, כְּמוֹ תְּפִלִּין, בֵּין עֹל מַלְכוּת עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת, כְּפִי מַעֲשֵׂיהֶם בַּיָּמִים הַלָּלוּ יֵשׁ לָהֶם הַשְׁבָּתַת מְלָאכָה וּמְנוּחָה. מִי שֶׁלֹּא מִתְעַסֵּק בְּתוֹרָה וּבַמִּצְווֹת, יֵשׁ לוֹ עֹל מַלְכוּת עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת. וּמִי שֶׁמִּתְעַסֵּק בְּתוֹרָה וּמִצְווֹת, יֵשׁ לוֹ עֹל מַלְכוּת שָׁמַיִם, שֶׁהִיא ה' אַחֲרוֹנָה, שֶׁנִּקְרֵאת מַלְכוּת שָׁמַיִם."],[3,"","עֹל מִצְווֹת הִיא וַדַּאי, מִשּׁוּם שֶׁבָּהּ נִבְרְאוּ כָּל הַבְּרִיּוֹת שֶׁל שָׁמַיִם וָאָרֶץ, זֶהוּ שֶׁכָּתוּב (בראשית ב) אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם. בְּה' בְּרָאָם. וּכְשֶׁיָּבֹא שַׁבָּת וְיוֹם טוֹב, יוֹרֶדֶת בִּינָה, שֶׁהִיא יה\"ו, עַל ה', שֶׁהִיא מַלְכוּת שָׁמַיִם נְשָׁמָה יְתֵרָה, וְהוּא (שמות לב) חָרוּת עַל הַלֻּחֹת. אָנֹכִי בִּיצִיאַת מִצְרַיִם, וּפוֹרֶשֶׂת כְּנָפֶיהָ עַל הַבַּת וְעַל הַמַּחֲנוֹת שֶׁלָּהּ, וְיֵשׁ לָהֶם מְנוּחָה. וְנֶאֱמַר בְּמַרְכְּבוֹתָיו שֶׁל סָמָאֵ\"ל וְנָחָשׁ, (דברים כח) וְרָאוּ כָּל עַמֵּי הָאָרֶץ כִּי שֵׁם ה' נִקְרָא עָלֶיךְ וְיָרְאוּ מִמֶּךָּ. אוֹת תְּפִלִּין וְאוֹת שַׁבָּת וְאוֹת יָמִים טוֹבִים וְאוֹת בְּרִית - כֻּלָּם שְׁקוּלִים."],[4,"","וְיִשִׁ אוֹת שֶׁל שַׁדַּ\"י, שֶׁהוּא מטטרו\"ן עֶבֶד, וְכַמָּה עֲבָדִים תְּלוּיִים מִמֶּנּוּ, שֶׁמְּמֻנֶּה עַל אֵלּוּ שֶׁעוֹשִׂים מִצְווֹת עַל מְנָת לְקַבֵּל פְּרָס. מטטרו\"ן וְהַמַּחֲנוֹת שֶׁלּוֹ מְמֻנִּים עֲלֵיהֶם. בִּשְׁבִילָם נֶאֱמַר, לְמַעַן יָנוּחַ שׁוֹרְךְ וַחֲמוֹרְךְ וְעַבְדְּךְ וַאֲמָתְךְ. אֲבָל אוֹתָם שֶׁעוֹשִׂים מִצְווֹת שֶׁלֹּא עַל מְנָת לְקַבֵּל פְּרָס, הֵם בְּנֵי הַמֶּלֶךְ וְהַגְּבִירָה, וְהֵם הַכְּתָרִים וְהַתָּגִים עַל הָרֹאשׁ הָעֲבָדִים בִּימוֹת הַחֹל, וּבִשְׁבִילָם נֶאֱמַר וּדְאִשְׁתַּמַּשׁ בְּתָגָא חֲלָף, וְהַזָּהר הַקָּרֵב אֲלֵיהֶם יוּמַת. שֶׁנִּקְרָאִים שַׁבָּתוֹת אֶל הָעֲבָדִים."],[5,"","וּמִשּׁוּם כָּךְ, אִם כְּבָנִים אִם כַּעֲבָדִים. אִם כְּבָנִים, שֶׁנֶּאֱמַר בָּהֶם בָּנִים אַתֶּם לַה' אֱלֹהֵיכֶם. אִם כַּעֲבָדִים, כִּי לִי בְנֵי יִשְׂרָאֵל עֲבָדִים, וְלֹא שְׁאָר הָאֻמּוֹת. אֲבָל אוֹתָם הָרְשָׁעִים שֶׁאֵין מִשְׁתַּדְּלִים בַּתּוֹרָה וּבַמִּצְווֹת וְאֵין עֲלֵיהֶם עֹל תּוֹרָה וְעֹל תְּפִלִּין וּשְׁאָר מִצְווֹת, הֵם עֲבָדִים לְאֻמּוֹת הָעוֹלָם וּמִשְׁתַּעְבְּדִים בָּהֶם, כְּמוֹ עֲבָדִים הָיִינוּ לְפַרְעֹה בְּמִצְרָיִם."],[6,"","וְאִם שׁוֹמְרִים שַׁבָּתוֹת וְיָמִים טוֹבִים, נֶאֱמַר בָּהֶם וַיּוֹצִיאֵנוּ ה' אֱלֹהֵינוּ. וְיִתְקַיֵּם בָּהֶם, לְמַעַן יָנוּחַ שׁוֹרְךְ וַחֲמוֹרֶךְ, חֲמוֹר בַּתּוֹרָה וּבַמִּצְווֹת, וְיִנָּפֵשׁ בֶּן אֲמָתְךְ וּבְהֶמְתֶּךְ, עַם הָאָרֶץ נִקְרָא בְּהֵמָה. וְאַחַר שֶׁיַּכְנִיס אֶת עַצְמוֹ תַּחַת אָדָם בַּתּוֹרָה, יִתְקַיֵּם בּוֹ אָדָם וּבְהֵמָה תּוֹשִׁיעַ ה'. אִם הוּא כְּמוֹ סוּס שֶׁרוֹכֵב עָלָיו אֲדוֹנוֹ, וְסוֹבֵל אוֹתוֹ, וְלֹא בוֹעֵט בַּאֲדוֹנוֹ."],[7,"","וּמַהוּ הַסֵּבֶל שֶׁעַם הָאָרֶץ לְתַלְמִיד חָכָם? מִשּׁוּם שֶׁתַּלְמִיד חָכָם כְּמוֹ יוֹם הַשַּׁבָּת הוּא צָרִיךְ, שֶׁאֵין לוֹ מִשֶּׁלּוֹ. וְאִם עַם הָאָרֶץ סוֹבֵל אוֹתוֹ בְּמָמוֹנוֹ וְנוֹהֵג בּוֹ כְּפִי רְצוֹנוֹ לְשַׁמֵּשׁ אוֹתוֹ וּלְהִתְנַהֵג בַּמִּצְווֹת כְּפִי רְצוֹנוֹ, יִתְקַיֵּם בּוֹ - אָדָם וּבְהֵמָה תּוֹשִׁיעַ ה'. יוֹשִׁיעַ אוֹתוֹ מִשּׁוֹד וּמִגְּזֵלָה, יוֹשִׁיעַ אוֹתוֹ מִמַּלְאַךְ הַמָּוֶת שֶׁלֹּא יִשְׁלֹט עָלָיו וְיִשְׁחַט אוֹתוֹ בְּסַכִּינוֹ הַפְּגוּמָה. וְכָל מִי שֶׁנִּשְׁחַט בְּסַכִּין פְּגוּמָה, הוּא נְבֵלָה, שֶׁנֶּאֱמַר בּו לַכֶּלֶב תַּשְׁלִכוּן אֹתוֹ, שֶׁהוּא סָמָאֵ\"ל."],[8,"","וְהַנֶּפֶשׁ שֶׁל תַּלְמִיד חָכָם נִקְרֵאת שַׁבָּת הַמַּלְכָּה, נֶפֶשׁ יְתֵרָה שֶׁל שַׁבָּת, וְהָעֹנֶג שֶׁלָּהּ נִשְׁמַת חַיִּים וְרוּחַ שִׂכְלִי. וְהֵם נְשָׁמָה יְתֵרָה, רוּחַ יְתֵרָה, עַל נְשָׁמָה וְרוּחַ וְנֶפֶשׁ, שֶׁהֵם עֲבָדִים שֶׁשּׁוֹלְטִים בַּגּוּף שֶׁל יְמוֹת הַחֹל. נְשָׁמָה יְתֵרָה, נִשְׁמַת כָּל חַי, כֶּתֶר הָרֹאשׁ צַדִּיק, שֶׁהוּא יוֹם הַשַּׁבָּת. וּבַנְּשָׁמָה הַיְתֵרָה הַזּוֹ תְּהַלֵּל יָהּ, שֶׁהֵם אַבָּא וְאִמָּא, שֶׁעֲלֵיהֶם נֶאֱמַר (ישעיה סד) עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךְ, מִשּׁוּם שֶׁהִיא מֶרְכָּבָה לְעִלַּת הָעִלּוֹת, שֶׁהוּא מְכֻסֶּה וְלֹא שׁוֹלֶטֶת עָלָיו הָעַיִן, וּמִשּׁוּם כָּךְ עַיִן לֹא רָאָתָה."],[9,"","רוּחַ יְתֵרָה, הַנָּהָר שֶׁיּוֹצֵא מֵעֵדֶן מִבֵּין אַבָּא וְאִמָּא, וּמַהֲלָכוֹ חֲמֵשׁ מֵאוֹת שָׁנָה, וּמַגִּיעַ לַשִּׁשִּׁי שֶׁהוּא צַדִּיק לְהַשְׁקוֹת אֶת הַגָּן, שֶׁהִיא נֶפֶשׁ יְתֵרָה, מַלְכוּת."]]],[["נְשָׁמָה דְּשַׁלְטָא בְּיוֹמִין דְּחוֹלָא, עַל עֶבֶד יְיָ', אִיהִי מִכִּסֵא הַכָּבוֹד. כְּמָה דְּאוּקְמוּהָ מָארֵי מַתְנִיתִין, כָּל הַנְּשָׁמוֹת גְּזוּרוֹת מִתַּחַת כִּסֵּא הַכָבוֹד. וְרוּחַ דְּשַׁלְטָא בְּיוֹמֵי דְּחוֹל, עַל עֶבֶד יְיָ', אִיהִי מֵעַבְדָא דְּמַלְכָּא מְטַטְרוֹ\"ן, כָּלִיל שִׁית סִדְרֵי מִשְׁנָה, וְאִיהִי שֵׁשׁ מַעֲלוֹת לַכִּסֵּא. וְנֶפֶשׁ דְּשַׁלִּיט בְּחוֹל, אִיהִי מִכִּסֵא דִּין, סַנְדַלְפוֹ\"ן, תְּכֵלֶת שֶׁבַּצִּיצִּית, כְּמַעֲשֵׂה לִבְנַת הַסַּפִיר. אֲבָל בְּרַתָּא דְּמַלְכָּא. בַּפֶסַח, אִיהִי נֶפֶשׁ הַשִּׂכְלִית, לֵיל שִׁמּוּרִים, מַצָּה שְׁמוּרָה, וְרוּחַ שִׁמּוּר לָקֳבְלֵיהּ אִיהִי יוֹם טוֹב, וְאִיהִי יוֹם שַׁבָּת, זָכוֹר וְשָׁמוֹר. בְּגִין דְּאִיהִי אֲצִּילוּת מִמַּלְכוּת.","וְהָכִי תַּלְמִידֵי חֲכָמִים, בְּנוֹי דְּמַלְכָּא וּמַטְרוֹנִיתָא, אִתְקְרִיאוּ שַׁבָּתוֹת וְיָמִים טוֹבִים, וְלֵית לוֹן מִדִּלְהוֹן, דְּלָאו אִינּוּן בַּעֲלֵי מְלָאכָה, כִּשְׁאָר עֲבָדִין בְּנוֹי דְּחוּלִין. אַגְרָא דִּלְהוֹן בְּעָלְמָא דֵּין, וּבְעָלְמָא דְּאָתֵי, לְעַנְּגָא לוֹן בְּכָל מִינֵי מַאֲכָל וּמִשְׁתֶּה, וּלְאוֹקְרָא לוֹן בִּלְבוּשִׁין שַׁפִּירִין, כְּגַוְונָא דְּשַׁבָּת, דְּאִתְּמַר בֵּיהּ, כַּבְּדֵהוּ בִּכְסוּת נְקִיָּה. כָּל מַה דְּעָבַד בַּר נָשׁ לְשַׁבָּתוֹת וְיָמִים טוֹבִים, אִית לְמֶעְבַּד לוֹן.","וּמַאן דִּמְחַלֵּל שַׁבָת חַיָּיב סְקִילָה. וְהָכִי מַאן דְּאִשְׁתַּמַּשׁ בְּתָגָא, חֲלָף. וְהָכִי הוּא הַמִּשְׁתַּמֵּשׁ בְּמִי שֶׁשּׁוֹנֶה הֲלָכוֹת, דִּמְחַלֵּל תּוֹרָתֵיהּ. וְכָּל שֶׁכֵּן הַמְבַזֶּה לֵיהּ, כְּאִילּוּ מְבַזֶּה שַׁבָּתוֹת וּמוֹעֲדוֹת. וְאוּקְמוּהָ מָארֵי מַתְנִיתִין, כָּל הַמְבַזֶּה אֶת הַמּוֹעֲדוֹת, כְּאִלּוּ כּוֹפֵר בָּעִיקָר.","וּכְגַוְונָא דְּכָל מָאנֵי בֵּית הַמִּקְדָּשׁ וְאִתְקְרִיאוּ קֹדֶשׁ, הָכִי כָּל אִינּוּן דִּמְשַׁמְשֵׁי תַּלְמִידֵי חֲכָמִים, אִתְקְרִיאוּ קֹדֶשׁ. וְתַלְמִידֵי דְּרַב דְּאִינּוּן לָקֳבֵל אֵבָרִים דְּגוּפָא, אִתְקְרִיאוּ קֹדֶשׁ קֳדָשִׁים. וְרָזָא דְּמִלָּה קָא רָמִיז בְּהוֹן, (שמות כ״ו:ל״ג-ל״ד) וְהִבְדִּילָה הַפָּרֹכֶת לָכֶם בֵּין הַקֹדֶשׁ וּבֵין קֹדֶשׁ הַקֳּדָשִׁים. וּמְטַטְרוֹ\"ן, אַתְ וּמַשִּׁרְיָין דִּילָךְ, צְּרִיכִין לְקָרְבָא לוֹן קָרְבְּנָא קֳדָם יְיָ' בְּכָל לֵילְיָא.","עֲשִׂיָּה לְקַבֵּל עָלֵיהּ עוֹל מַלְכוּת שָׁמַיִם, דָּא קַבָּלַת יִסוּרִין דַּעֲנִיוּת לְתַּלְמִיד חָכָם אִיהוּ מָוְת לְגוּפָא דִּבְעִירָן. דִּמְזוֹנָא דְּאוֹרַיְיתָא, אִיהוּ מְזוֹנָא דְּנִשְׁמְתָא וְרוּחָא וְנַפְשָׁא שִׂכְלִיִּים, דְּאִינּוּן כֹּהֵן לֵוִי וְיִשְׂרָאֵל. כֹּהֵן בֵּיהּ י', חָכְמָה וַדַאי. לֵוִי, בֵּיהּ ה', תְּבוּנָה. יִשְׂרָאֵל, בֵּיהּ דַּעַת, וְדָא ו'. נֶפֶשׁ יְתֵירָה, ה' בַּתְרָאָה, רמ\"ח מִצְּוַות עְשֵׂה ושס\"ה לֹא תַּעֲשֶׂה. וְתוֹרָה דָּא אָדָם, הֲדָא הוּא דִּכְתִיב, (במדבר יט) זֹאת הַתּוֹרָה אָדָם. וְדָא כָּלִיל שְׁמָא מְפֹרָשׁ, יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. הַאי אִיהוּ אוֹרַיְיתָא מְזוֹנָא לְאָדָם, בְּד' אַנְפִּין דִּילֵיהּ. מְזוֹנָא דִּבְעִירָן, נָהֲמָא וְחַמְרָא וּבִשְׂרָא, וְכָל מִינֵי פֵּירוֹת, (קהלת ז׳:י״ד) זֶה לְעֻמַּת זֶה עָשָׂה הָאֱלֹהִים.","וְצָּרִיךְ בַּר נָשׁ, לְקָרְבָּא בְּכָל לֵילְיָא, קָרְבָּן נַפְשָׁא וְרוּחָא וְנִשְׁמְתָא דִּבְעִירָן, קֳדָם יְיָ'. וְיִתְוַדֶּה בְּכַמָּה מִינֵי וִדוּיִין, וְיִסְלַק לוֹן בְּמַחֲשַׁבְתֵיהּ, קָרְבְּנָא קֳדָם יְיָ'. לְאַפָּקָא לוֹן בְּקְרִיאַת שְׁמַע, (בלב אחד) לְקָמֵי קוּדְשָׁא בְּרִיךְ הוּא, וְיַפִּיק רוּחֵיהּ דְּדָפִיק בְּעַרְקִין דְּלִבָּא. נֶפֶשׁ, יְכַוִּון בִּשְׂרֵפָתָהּ, וּבִשְׁחִיטָתָהּ, וּבִנְחִירָתָה, דַּהֲווֹ נְחִירִין כַּהֲנַיָיא, הֲדָא הוּא דִכְתִיב וּמָלַק אֶת רֹאשׁוֹ מִמוּל עָרְפּוֹ וְלֹא יַבְדִּיל. וְהַיְינוּ חֶנֶק. וּתְלָתָא מִיתוֹת אִלֵּין, הֲווֹ כְּמָרָה סוּמָקָא, יְרוֹקָא, אוּכָמָא. דְּאִינּוּן בַּכָּבֵד בַּמָרָה בַּטְחוֹל, וְאִינּוּן כִּתְלַת קְלִיפִּין דֶּאֱגוֹזָא.","וְקוֹדֶם דָּא, יְתַקֵּן מִזְבַּח אֲבָנִים, וִיכַוִּין לְמֶעְבְּדָהּ סְקִילָה, מִמָּרָה חִוָּורָא, דְּשַׁלְטַת בְּכַנְפֵי רֵיאָה, בְּאִינּוּן סִרְכוֹת דְּאִלֵּין בְּעִירָן תְּפוּסִין תַּמָּן. וּנְחִיתַת אֶשָּׁא תְּכֵלָא, וִישֵׁצֵּי לוֹן, וִיהוֹן חֵיוָון וּבְעִירָן וְעוֹפִין דַּכְיָין, לְקָרְבָא לַיְיָ', וּלְשַׁרְיָיא שְׁמֵיהּ עָלַיְיהוּ. בְּהַהוּא זִמְנָא יִתְקַיֵּים בְּהוּ, (דברים ד׳:ד׳) וְאַתֶּם הַדְּבֵקִים בַּיְיָ' אֱלֹהֵיכֶם חַיִּים. ויהוֹן כְּסוּסְיָא דְּרָכִיב מָארֵיהּ עָלַיְיהוּ, הֲדָא הוּא דִכְתִיב, (חבקוק ג׳:ח׳) כִּי תִרְכַב עַל סוּסֶיךָ מַרְכְּבוֹתֶיךָ יְשׁוּעָה, וּבְהַהוּא זִמְנָא (תהילים ל״ו:ז׳) אָדָם וּבְהֵמָה תּוֹשִׁיעַ יְיָ'.","וְתָּא חֲזֵי אִיהוּ שָׁקִיל לְכָל מָארֵי תּוֹרָה, וְהָכִי צָּרִיךְ לְמֶהֱוִי שָׁקִיל גַּרְמֵיהּ מִסִּטְרָא דְּאוֹרַיְיתָא, וּמִסִּטְרָא דְּאֵבָרִים דְּגוּפָא, צָּרִיךְ לְמִשְׁקַל גַּרְמֵיהּ לְכָל עַמֵּי הָאָרֶץ. כְּמָה דְּאוּקְמוּהָ מָארֵי מַתְנִיתִין, לְעוֹלָם יִרְאֶה אָדָם עַצְּמוֹ, כְּאִלּוּ כָּל הָעוֹלָם כֻּלּוֹ תָּלוּי בּוֹ. וִיכַוִּין בְּנַפְשֵׁיהּ וּבְרוּחֵיהּ וּבְנִשְׁמָתֵיהּ, לְמֶעְבַּד לוֹן קָרְבְּנִין, עִם כָּל בְּנֵי עָלְמָא. וְקוּדְשָׁא בְּרִיךְ הוּא מְצָּרֵף מַחֲשָׁבָה טוֹבָה לְמַעֲשֶׂה. וּבְדָא אָדָם וּבְהֵמָה תּוֹשִׁיעַ יְיָ'. קָמוּ כֻּלְּהוּ תָּנָאִין וְאָמוֹרָאִין לְגַבֵּיהּ, וְאָמְרוּ כֻּלְּהוּ בְּקָלָא חֲדָא, אַנְתְּ הוּא רַעְיָא מְהֵימָנָא, דְּאִית לָךְ רְשׁוּ לְמֶעְבַּד כָּל דָּא, דְּאַנְתְּ שָׁקִיל לְכָל יִשְׂרָאֵל, וּבְגִין דָּא שָׁלַּח לָךְ קוּדְשָׁא בְּרִיךְ הוּא בֵּינַיְיהוּ. (ע\"כ רעיא מהימנא)","\u0003תוספתא\u0004 (ויקרא ו׳:י״ח) זֹאת תּוֹרַת הָעוֹלָה. אָמַר רִבִּי חִיָּיא, הַאי קְרָא אוֹקִימְנָא לֵיהּ בְּהַאי גַּוְונָא, זֹאת תּוֹרַת: דָּא כְּנֶסֶת יִשְׂרָאֵל. הָעוֹלָה דָּא מַחֲשָׁבָה רָעָה, דְּאִיהִי סַלְּקָא עַל רְעוּתָא דְּבַּר נָשׁ, לְאַסְטָאָה לֵיהּ מֵאָרְחָא דִּקְשׁוֹט. הִיא הָעוֹלָה: הִיא הִיא דְּסַלְּקָא וְאַסְטְיָיה לֵיהּ לְבַּר נָשׁ, בָּעֵי לְאוֹקְדָא לֵיהּ בְּנוּרָא. בְּגִין דְּלָא יִתְיְיהִיב לֵיהּ דּוּכְתָא לְאַסְטָאָה, וּבְגִין כָּךְ עַל הַמִּזְבֵּחַ כָּל הַלַּיְלָה. מַאן לַיְלָה. דָּא כְּנֶסֶת יִשְׂרָאֵל, דְּאִיהִי זֹאת לְאִתְדַכְּאָה בַּר נָשׁ מֵהַהוּא רְעוּתָא."],[[0,"נשמה דשלטא ביומין וכו׳:","נשמה השולטת בימות החול על עבד ה׳, היא מכסא הכבוד, שהוא עולם ה \u0003בריאה,\u0004 הנקרא כסא הכבוד. כמו שהעמידוהו בעלי המשנה, כל הנשמות גזורות מתחת כסא הכבוד. והרוח השולט בימות החול על עבד ה', הוא מעבד המלך מטטרון שבעולם \u0003היצירה,\u0004 שהוא כולל ששה סדרי משנה, שה״ס שש ספירות שלו חג״ת נה״י שבהן הוא משנה לז״א, והוא שש מעלות לכסא. כי חג״ת נה״י דיצירה, הן שש מעלות לעולם הבריאה הנקרא כסא. והנפש השולטת בימות החול היא מכסא דין, דהיינו מעולם \u0003העשיה,\u0004 מסנדלפון, שה״ס תכלת שבציצית, וה״ס כ \u0003מעשה\u0004 לבנת הספיר. שהוא לשון עשיה. אבל בת המלך, היא הנפש השכלית של ת״ח שבפסח, ה״ס ליל שמורים מצה שמורה, שנמשכת ממלכות, הנקראת בפסח ליל שמורים ומצה שמורה, לרוב מעלתה, והרוח, שמור כנגדה, שהוא בחינת יום, שהוא יום טוב, והוא יום שבת. והם זכור ושמור. שהרוח הוא בחינת זכור שהוא ז״א, יום השבת. והנפש היא בחינת שמור, שהיא המלכות, שה״ס ליל שמורים וליל שבת. משום שהיא נפש דאצילות ממלכות."],[1,"והכי ת״ח בנוי וכו':","וכך הם תלמידי חכמים שהם בניהם של המלך והמלכה, שהנפש שלהם היא של המלכות ואצילות, והרוח שלהם הוא מז״א דאצילות כנ״ל, הם נקראים שבתות וימים טובים, ואין להם כלום משלהם, כמו שבתות ויו״ט, כי אינם בעלי מלאכה כשאר עבדים שהם בניהם של ג׳ עולמות בי״ע שהם חולין. השכר שלהם בעולם הזה ובעולם הבא, הוא לענג אותם בכל מיני מאכל ומשתה, ולכבדם בלבושים יפים כמו השבת, שנאמר בו כבדהו, בכסות נקיה. כל מה שעושה האדם לכבוד שבתות וימים טובים, יש לעשות להם."],[2,"ומאן דמחלל שבת וכו׳:","ומי שמחלל שבת חייב סקילה, וכך מי שמשתמש בעטרה, חלף. וכך הוא המשתמש במי ששונה הלכות שמחלל תורתו. וכ״ש המבזה אותו, שהוא כאלו מבזה שבתות ומועדים. והעמידו בעלי המשנה, כל המבזה את המועדות כאלו כופר בעיקר."],[3,"וכגוונא דכל מאני וכו׳:","וכמו כל הכלים של בית המקדש שנקראים קדש, כך כל אלו המשמשים את תלמידי חכמים נקראים קדש. ותלמידי הרב, שהם כנגד אברי הגוף, של הרב, נקראים קדש קדשים. וסוד הדבר, כי נרמז בהם, והבדילה הפרכת לכם בין הקדש לבין קדש הקדשים. ומטטרון: אתה והמחנות שלך, צריכים לקרב אותם, קרבן לפני ה׳ בכל לילה."],[4,"עשיה לקבל עליה וכו':","העשיה שצריך לעשות, כדי לקבל עליו עול מלכות שמים, הוא, קבלת יסורין של עניות, אשר לתלמיד חכם הוא מות לגוף הבהמי שלו. כי מזון התורה, הוא מזון של נשמה רוח ונפש השכליים, שהם כהן לוי וישראל. \u0003כהן\u0004 בו \u0003י'\u0004 שהוא חכמה ודאי. \u0003לוי,\u0004 בו \u0003ה׳,\u0004 שהיא תבונה. \u0003ישראל\u0004 בו דעת, וזהו \u0003ו'.\u0004 נפש יתירה, היא \u0003ה׳\u0004 אחרונה של שם הויה, שהיא מלכות, הכוללת רמ״ח מצוות עשה ושס״ה לא תעשה. (כנ״ל אות מ״ו). ותורה, זו היא אדם (כנ״ל אות נ״ט) שהיא ז״א, ז״ש זאת התורה אדם. והוא כולל שם המפורש, \u0003יוד הא ואו הא,\u0004 דהיינו ד׳ אותיות הויה, במילוי אלפין. זו היא תורה שהיא מזון לאדם בד׳ פנים שלו, שהם פני אריה פני שור פני נשר פני אדם, שהם חו״ג תו״מ, כי פני אדם כוללים כל ד׳ פנים. שהוא לעומת מזון של גוף הבהמי, שהוא ד׳ מינים שהם, לחם ויין, ובשר, וכל מיני פירות, זה לעומת זה עשה אלקים. כי לחם, כנגד פני אריה, דהיינו חסד. ויין, כנגד פני שור, דהיינו גבורה, ובשר, כנגד פני נשר, דהיינו, ת״ת, ומיני פירות, כנגד פני אדם, שהוא מלכות."],[5,"וצריך בר נש וכו׳:","וצריך האדם להקריב בכל לילה, קרבן של נפש רוח ונשמה הבהמיים לפני ה׳. ויתודה בכמה מיני וידוים, ויעלה אותם במחשבתו בעת קריאת שמע, להוציא אותם לקרבן לפני ה', דהיינו שיכוון, שיוציא את רוחו הדופק בעורקי הלב. והנפש, יכוון בשריפתה, ובשחיטתה, ובנחירתה, כמו הכהנים שהיו נוחרים, ז״ש, ומלק את ראשו ממול ערפו ולא יבדיל. והוא חנק. ויש כאן קבלת ג׳ מיתות, שריפה. ושחיטה שהם הרג. ונחירה שהיא חנק. וג' מיתות אלו הם כמרה אדומה וכמרה ירוקה וכמרה שחורה, שהם בכבד במרה ובטחול, והם כג׳ קליפות של אגוז. פירוש. כי ד׳ מרות הן כנגד חו״ב תו״מ, וכן ריאה כבד מרה וטחול. וכן ד׳ קליפות של אגוז, ואומר, שג׳ מיתות שריפה הרג וחנק, הם כנגד ג׳ מרות וכו׳ שהם בינה ת״ת ומלכות. שהאדומה היא כנגד בינה. והירוקה כנגד ז״א. והשחורה כנגד מלכות. וכן מיתת שריפה כנגד מה שפגם בחכמה, ומיתת הרג כנגד מה שפגם בז״א, ומיתת חנק כנגד מה שפגם במלכות, ומיתת סקילה תתבאר בסמוך."],[6,"וקודם דא יתקן וכו':","וקודם זה יתקן בחינת מזבח אבנים, דהיינו שיכוון לעשותה סקילה, כלומר, שיקבל עליו מיתת סקילה. שהיא ממרה הלבנה, שהיא כנגד חכמה, השולטת בכנפי ריאה, שהיא ג״כ כנגד חכמה, כנ״ל בדבור הסמוך, דהיינו באלו הסרכות, דהיינו הקליפות, המדביקות כנפי ריאה זו לזו ואינן יכולות לנשב, (כנ״ל אות מ״ד) שאלו הבהמות דהיינו נפשות ורוחות ונשמות הבהמיות, נלכדות שם. ואז יורדת אש תכלת מן המלכות ומכלה אותם, ויהיו נפש רוח נשמה הבהמיות שלו, בבחינת חיות ובהמות ועופות הטהורים, להקריבם לה׳ ולהשרות שמו עליהם. בזמן ההוא יתקיים בהם, ואתם הדבקים בה׳ אלקיכם חיים. ויהיו כסוס שאדוניו רוכב עליו, דהיינו שיהיו מרכבה לה׳, ז״ש, כי תרכב על סוסיך מרכבותיך ישועה. ובזמן ההוא, אדם ובהמה תושיע ה'. שהם נר״ן השכליים הנקראים אדם, ונר״ן הבהמיים הנקראים בהמה."],[7,"ות״ח איהו שקיל וכו׳:","ובוא וראה, הוא צריך לראות את עצמו שקול כנגד כל בעלי תורה, וכך הוא צריך לשקול את עצמו מצד התורה, דהיינו מצד נר״נ השכליים. ומצד האברים של הגוף, דהיינו מצד נר״נ הבהמיים, צריך לראות את עצמו שקול כנגד כל עמי הארץ. כמו שהעמידו בעלי המשנה, לעולם יראה אדם עצמו כאלו כל העולם כלו תלוי בו. וע״כ יכוון בנפשו וברוחו ונשמתו לעשות אותם קרבנות עם כל בני העולם. והקב״ה מצרף מחשבה טובה למעשה. ובזה אדם ובהמה תושיע ה׳. כנ״ל. קמו כל התנאים והאמוראים אליו, ואמרו כולם בקול אחד, אתה הוא רועה נאמן, שיש לך רשות לעשות כל זה. כי אתה שקול כנגד כל ישראל. וע״כ שלח אותך הקב\"ה ביניהם. (ע״כ רעיא מהימנא)."],[8,"זאת תורת העולה:","אמר ר׳ חייא, מקרא זה העמדנו אותו באפן זה. \u0003זאת תורת,\u0004 זו היא כנסת ישראל. \u0003העולה\u0004 זו היא מחשבה רעה, העולה ברצון בן האדם, להטותו מדרך האמת. \u0003היא העולה,\u0004 היא היא העולה ומשטינה על האדם. וצריכים לשרוף אותה באש, שלא לתת לה רשות להשטין, ומשום זה, \u0003על המזבח כל הלילה.\u0004 מי הוא לילה. זו היא כנסת ישראל, שנקראת בתחילת הכתוב, \u0003זאת,\u0004 כדי לטהר האדם מן הרצון הזה."]],[[0,"","הַנְּשָׁמָה שֶׁשּׁוֹלֶטֶת בִּימוֹת הַחֹל עַל עֶבֶד ה' הִיא מִכִּסֵּא הַכָּבוֹד, כְּמוֹ שֶׁבֵּאֲרוּהָ בַּעֲלֵי הַמִּשְׁנָה, כָּל הַנְּשָׁמוֹת גְּזוּרוֹת מִתַּחַת כִּסֵּא הַכָּבוֹד. וְרוּחַ שֶׁשּׁוֹלֶטֶת בִּימוֹת הַחֹל עַל עֶבֶד ה', הִיא מֵעֶבֶד הַמֶּלֶךְ מטטרו\"ן, כּוֹלֵל שִׁשָּׁה סִדְרֵי מִשְׁנָה, וְהִיא שֵׁשׁ מַעֲלוֹת לַכִּסֵּא. וְהַנֶּפֶשׁ שֶׁשּׁוֹלֶטֶת בִּימוֹת הַחֹל הִיא מִכִּסֵּא דִין, סַנְדַּלְפוֹ\"ן, תְּכֵלֶת שֶׁבַּצִּיצִית, כְּמַעֲשֵׂה לִבְנת הַסַּפִּיר. אֲבָל בַּת הַמֶּלֶךְ, בְּפֶסַח, הִיא נֶפֶשׁ הַשִּׂכְלִית, לֵיל שִׁמּוּרִים, מַצָּה שְׁמוּרָה, וְרוּחַ שִׁמּוּר כְּנֶגְדָּהּ הִיא יוֹם טוֹב, וְהִיא יוֹם שַׁבָּת, זָכוֹר וְשָׁמוֹר, מִשּׁוּם שֶׁהִיא אֲצִילוּת מִמַּלְכוּת."],[1,"","וְכָךָ תַּלְמִידֵי חֲכָמִים, בְּנֵי הַמֶּלֶךְ וְהַמַּלְכָּה, נִקְרְאוּ שַׁבָּתוֹת וְיָמִים טוֹבִים, וְאֵין לָהֶם מִשֶּׁלָּהֶם, שֶׁאֵינָם בַּעֲלֵי מְלָאכָה כְּמוֹ שְׁאָר הָעֲבָדִים בְּנֵי הַחֻלִּין. שְׂכָרָם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא לְעַנֵּג אוֹתָם בְּכָל מִינֵי מַאֲכָל וּמִשְׁתֶּה, ז וּלְכַבְּדָם בלבוּשִׁים יָפִים כמו שֶׁשַּׁבָּת, שֶׁנֶּאֱמַר בָּהּ, כַּבְּדֵהוּ בִּכְסוּת נְקִיָּה. כָּל מַה שֶּׁעוֹשֶׂה אָדָם לְשַׁבָּתוֹת וְיָמִים טוֹבִים, יֵשׁ לַעֲשׂוֹת לָהֶם."],[2,"","וּמִי שֶׁמְּחַלֵּל שַׁבָּת חַיָּב סְקִילָה. וְכֵן מִי שֶׁמִּשְׁתַּמֵּשׁ בְּכֶתֶר חוֹלֵף. וְכָךְ מִי שֶׁמִּשְׁתַּמֵּשׁ בְּמִי שֶׁשּׁוֹנֶה הֲלָכוֹת, שֶׁמְּחַלֵּל אֶת תּוֹרָתוֹ. וְכָל שֶׁכֵּן הַמְבַזֶּה אוֹתוֹ, כְּאִלּוּ מְבַזֶּה שַׁבָּתוֹת וּמוֹעֲדוֹת. וּפֵרְשׁוּהָ בַּעֲלֵי הַמִּשְׁנָה, כָּל הַמְבַזּה אֶת הַמּוֹעֲדוֹת, כְּאִלּוּ כּוֹפֵר בָּעִקָּר."],[3,"","וּכְמוֹ שֶׁכָּל כְּלֵי בֵּית הַמִּקְדָּשׁ שֶׁנִּקְרְאוּ קֹדֶשׁ, כָּךְ כָּל אוֹתָם שֶׁמְּשַׁמְּשִׁים תַּלְמִידֵי חֲכָמִים נִקְרָאִים קֹדֶשׁ. וְתַלְמִידֵי רַב, שֶׁהֵם כְּנֶגֶד אֵיבְרֵי הַגּוּף, נִקְרְאוּ קֹדֶשׁ קָדָשִׁים. וְסוֹד הַדָּבָר רָמוּז בָּהֶם, (שמותכו) וְהִבְדִּילָה הַפָּרֹכֶת לָכֶם בֵּין הַקֹּדֶשׁ וּבֵין קֹדֶשׁ הַקְּדָשִׁים. וּמטטרו\"ן, אַתָּה וּמַחֲנוֹתֶיךְ, צְרִיכִים לְהַקְרִיבָם קָרְבָּן לִפְנֵי ה' בְּכָל לַיְלָה."],[4,"","עָשִׂיָּה, לְקַבֵּל עָלָיו עֹל מַלְכוּת שָׁמַיִם, זוֹ קַבָּלַת יִסּוּרִים שֶׁל עֲנִיּוּת לְתַלְמִיד חֲכָמִים, שֶׁהוּא מָוֶת לְגוּף הַבְּהֵמוֹת. שֶׁמְּזוֹן הַתּוֹרָה הוּא מָזוֹן שֶׁל הַנְּשָׁמָה וְרוּחַ וְנֶפֶשׁ הַשִּׂכְלִיִּים, שֶׁהֵם כֹּהֵן לֵוִי וְיִשְׂרָאֵל. הַכֹּהֵן בּוֹ י', חָכְמָה וַדַּאי. הַלֵּוִי בּוֹ ה', תְּבוּנָה. יִשְׂרָאֵל בּוֹ דַּעַת, וְזוֹ ו'. נֶפֶשׁ יְתֵרָה, ה' אַחֲרוֹנָה, רמ\"ח מִצְווֹת עֲשֵׂה וּשס\"ה לֹא תַעֲשֶׂה. וְתוֹרָה זוֹ אָדָם. זֶהוּ שֶׁכָּתוּב זֹּאת הַתּוֹרָה אָדָם. וְזֶה כּוֹלֵל אֶת הַשֵּׁם הַמְפֹרָשׁ יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. זוֹהִי הַתּוֹרָה מָזוֹן לָאָדָם בְּאַרְבַּע הַפָּנִים שֶׁלּוֹ. מְזוֹן הַבְּהֵמוֹת לֶחֶם וְיַיִן וּבָשָׂר וְכָל מִינֵי פֵרוֹת, (קהלת ו) זֶה לְעֻמַּת זֶה עָשָׂה הָאֱלֹהִים."],[5,"","וְצָרִיךָ אָדָם לְהַקְרִיב בְּכָל לַיְלָה קָרְבַּן נֶפֶשׁ וְרוּחַ וּנְשָׁמָה שֶׁל בְּהֵמוֹת לִפְנֵי ה', וְיִתְוַדֶּה בְּכַמָּה מִינֵי וִדּוּיִים, וְיַעֲלֶה אוֹתָם בְּמַחֲשַׁבְתּוֹ קָרְבָּן לִפְנֵי ה'. לְהוֹצִיא אוֹתָם בִּקְרִיאַת שְׁמַע (בלבאחד) לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְיוֹצִיא אֶת רוּחוֹ שֶׁדּוֹפֵק בְּעוֹרְקֵי הַלֵּב. הַנֶּפֶשׁ, יְכַוֵּן בִּשְׂרֵפָתָהּ וּבִשְׁחִיטָתָהּ וּבִנְחִירָתָהּ, שֶׁהָיוּ הַכֹּהֲנִים נוֹחֲרִים, זֶהוּ שֶׁכָּתוּב וּמָלַק אֶת רֹאשׁוֹ מִמּוּל עָרְפּוֹ וְלֹא יַבְדִּיל. וְהַיְנוּ חֶנֶק. וּשְׁלֹשׁ הַמִּיתוֹת הַלָּלוּ הָיוּ כְּמוֹ מָרָה אֲדֻמָּה, יְרֻקָּה וּשְׁחֹרָה, שֶׁהֵם בַּכָּבֵד, בַּמָּרָה וּבַטְּחוֹל, וְהֵם כִּשְׁלֹשׁ קְלִפּוֹת הָאֱגוֹז."],[6,"","וְקֹדֶם לָכֵן יְתַקֵּן מִזְבַּח אֲבָנִים, וִיכַוֵּן לַעֲשׂוֹת סְקִילָה מִמָּרָה הַלְּבָנָה שֶׁשּׁוֹלֶטֶת בְּכַנְפֵי רֵאָה בְּאוֹתָן סְרָכוֹת שֶׁאוֹתָן הַבְּהֵמוֹת תְּפוּסוֹת שָׁם. וְיוֹרֶדֶת אֵשׁ תְּכֵלֶת וּמְכַלָּה אוֹתָם, וְיִהְיוּ הַחַיּוֹת וְהַבְּהֵמוֹת וְהָעוֹפוֹת טְהוֹרִים לִקְרַב לַה' וּלְהַשְׁרוֹת שְׁמוֹ עֲלֵיהֶם. בְּאוֹתוֹ זְמַן יִתְקַיֵּם בָּהֶם, (דברים ד) וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם חַיִּים. וְיִהְיוּ כְּמוֹ סוּס שֶׁאֲדוֹנוֹ רוֹכֵב עָלָיו. זֶהוּ שֶׁכָּתוּב (חבקוק ג) כִּי תִרְכַּב עַל סוּסֶיךְ מַרְכְּבֹתֶיךְ יְשׁוּעָה. וּבְאוֹתוֹ זְמַן - אָדָם וּבְהֵמָה תּוֹשִׁיעַ ה'."],[7,"","וְהַתַּלְמִיד חָכָם שָׁקוּל לְכָל בַּעֲלֵי הַתּוֹרָה, וְכָךְ צָרִיךְ לִשְׁקֹל עַצְמוֹ מִצִּדָּהּ שֶׁל הַתּוֹרָה, וּמִצַּד הָאֵיבָרִים שֶׁל הַגּוּף צָרִיךְ לִשְׁקֹל לְעַצְמוֹ לְכָל עַמֵּי הָאָרֶץ, כְּמוֹ שֶׁבֵּאֲרוּהָ בַּעֲלֵי הַמִּשְׁנָה, לְעוֹלָם יִרְאֶה אָדָם עַצְמוֹ כְּאִלּוּ כָּל הָעוֹלָם כֻּלּוֹ תָּלוּי בּוֹ. וִיכַוֵּן בְּנַפְשׁוֹ וּבְרוּחוֹ וּבְנִשְׁמָתוֹ לַעֲשׂוֹת אוֹתָם קָרְבָּנוֹת עִם כָּל בְּנֵי הָעוֹלָם. וְהַקָּדוֹשׁ בָּרוּךְ הוּא מְצָרֵף מַחֲשָׁבָה טוֹבָה לְמַעֲשֶׂה. וּבָזֶה, אָדָם וּבְהֵמָה תּוֹשִׁיעַ ה'. קָמוּ כָּל הַתַּנָּאִים וְהָאָמוֹרָאִים אֵלָיו, וְאָמְרוּ כֻלָּם בְּקוֹל אֶחָד: אַתָּה הוּא הָרוֹעֶה הַנֶּאֱמָן שֶׁיֵּשׁ לְךְ רְשׁוּת לַעֲשׂוֹת אֶת כָּל זֶה, שֶׁאַתָּה שָׁקוּל לְכָל יִשְׂרָאֵל, וּמִשּׁוּם כָּךְ שָׁלַח אוֹתְךְ הַקָּדוֹשׁ בָּרוּךְ הוּא בֵּינֵיהֶם. (ע\"כ הרעיא מהימנא)."],[8,"","זֹאת תּוֹרָה הָעֹלָה. אָמַר רַבִּי חִיָּיא, אֶת הַפָּסוּק הַזֶּה בֵּאַרְנוּ בַּגָּוֶן הַזֶּה: זֹּאת תּוֹרַת - זוֹ כְּנֶסֶת יִשְׂרָאֵל. הָעֹלָה - זוֹ מַחֲשָׁבָה רָעָה, שֶׁעוֹלָה עַל רְצוֹנוֹ שֶׁל אָדָם לַהֲסִיטוֹ מִדֶּרֶךְ הָאֱמֶת. הִיא הָעֹלָה - הִיא הִיא שֶׁעוֹלָה לְהַסְטִין עַל הָאָדָם, וְרוֹצֶה לִשְׂרֹף אוֹתוֹ בָּאֵשׁ, כְּדֵי שֶׁלֹּא יִנָּתֵן לוֹ מָקוֹם לְהַשְׂטִין. וְלָכֵן, עַל הַמִּזְבֵּחַ כָּל הַלַּיְלָה. מִי הַלַּיְלָה? זוֹ כְּנֶסֶת יִשְׂרָאֵל, שֶׁהִיא זֹּאת, לְטַהֵר אֶת הָאָדָם מֵאוֹתוֹ רָצוֹן."]]],[["עַל מוֹקְדָה, בְּגִין דְּנָהַר דִּי נוּר אִיהוּ אֲתַר לְאוֹקְדָא, לְכָל אִינּוּן דְּלָא קַיְימֵי בְּקִיּוּמַיְיהוּ, דְּהָא עָאלִין לוֹן בְּהַהוּא נוּרָא דְּדָלִיק וּמְעַבְּרֵי שׁוּלְטָנֵיהוֹן מֵעָלְמָא. וּבְגִין דְּלָא תִּשְׁלוֹט (ס\"א אצטריך) עַל מוֹקְדָה כָּל הַלַּיְלָה, וְאִתְכַּפְיָיא וְלָא שַׁלְטָא. (ע\"כ תוספתא)","כְּתִיב (מלכים א י״ט:י״א) וְהִנֵּה יְיָ' עֹבֵר וְגו' וְרוּחַ גְּדוֹלָה וְחָזָק וְגוֹ'. רוּחַ גְּדוֹלָה דְּאַמָרָן, וּכְתִיב לֹא בָרוּחַ יְיָ'. וְאַחַר הָרוּחַ רַעַשׁ דִּכְתִּיב, (יחזקאל ג׳:י״ב) וַתִּשָּׂאֵנִי רוּחַ וָאֶשְׁמַע אַחֲרַי קוֹל רַעַשׁ גָּדוֹל. הֲרֵי רַעַשׁ אֲבַתְרֵיהּ דְּרוּחַ. וְאַחַר הָרַעַשׁ אֵשׁ, דָּא הוּא דִּכְתִיב (דניאל ז׳:י׳) נְהַר דִּי נוּר נָגִיד וְנָפֵק מִן קֳדָמוֹהִי וְגוֹ'.","רִבִּי יִצְחָק אָמַר הַיְינוּ דִּכְתִּיב, (יחזקאל א׳:י״ג) וּדְמוּת הַחַיּוֹת מַרְאֵיהֶן כְּגַחֲלֵי אֵשׁ בּוֹעֲרוֹת כְּמַרְאֵה הַלַּפִּידִים הִיא מִתְהַלֶּכֶת בֵּין הַחַיּוֹת וְנֹגַהּ לָאֵשׁ וּמִן הָאֵשׁ יוֹצֵא בָרָק וְאַחַר הָאֵשׁ קוֹל דְּמָמָה דַּקָּה. קוֹל דָּא, קוֹל בַּתְרָאָה, דְּהִיא דְּמָמָה, דְּלֵית לָהּ מִלָּה פְּרָטָא, אֶלָּא הִיא דְּמָמָה מִגַּרְמָהּ. וְכַד מִתְכַּנְּשֵׁי עָלָהּ, הִיא אִשְׁתְּמַע בְּכֻלְּהוּ עָלְמִין, וְכֻלְּהוּ מִזְדַּעֲזְעֵי מִנָּהּ. דְּמָמָה דַּקָּה, אֲמַאי הִיא דַּקָּה. בְּגִין (ס\"א דאיהי) (דאתיא) זְעֵירָא מִכֹּלָּא.","רִבִּי חִיָּיא אָמַר, אֵשׁ תָּמִיד תּוּקַד עַל הַמִּזְבֵּחַ לֹא תִכְבֶּה, דָּא אֶשּׁוֹ דְּיִצְחָק. דִּכְתִּיב, (בראשית כ״ב:ז׳) הִנֵּה הָאֵשׁ וְהָעֵצִים, וְהַיְינוּ אֵשׁ תָּמִיד, דְּקַיְּימָא תָּדִיר. וְהָעֵצִים, אִלֵּין עֵצִים דְּאַבְרָהָם, דִּכְתִּיב וּבִעֵר עָלֶיהָ הַכֹּהֵן עֵצִים בַּבֹּקֶר בַּבֹּקֶר.","תְּנָן, מֵאֶשָּׁא דְּיִצְחָק נָגִיד וּמָטֵי לְהַאי מִזְבֵּחַ, וְנָפִיק גּוּמְרָא חַד לִסְטַר מִזְרָח, וְגוּמְרָא חַד לִסְטַר מַעֲרָב, וְגוּמְרָא חַד לִסְטַר צָפוֹן, וְגוּמְרָא חַד לִסְטַר דָּרוֹם, לְד' זָוְויָּין דְּמַדְבְּחָא, וְכַהֲנָא אַסְחַר לָהּ לְד' זָוְויָּין.","בְּמַדְבְּחָא (ס\"א במזרח) אִית כֶּבֶשׁ חַד, בְּדַרְגִּין יְדִיעָן. וְדַרְגָּא תַּתָּאָה, מָטֵי וְנָחִית לִתְהוֹמָא עִלָּאָה, מִגּוֹ שִׁית חַד. וּבְשַׁעֲתָא דְּאִינּוּן גּוּמְרִין מָטוּ לְד' זָוְויָּין, חַד זִיקָא אִתְּעַר וְנָחִית לְהַהוּא תְּהוֹמָא עִלָּאָה.","וּבְהַהוּא אֲתַר, אִית חַיָּילִין חַיָּילִין דְּאָמְרֵי קָדוֹשׁ, בְּקָל רַב עִלָּאָה. וּמִסִּטְרָא אָחֳרָא אַמְרֵי קָדוֹשׁ, בְּקָל נְעִימוּתָא עִלָּאָה. וּמִסִּטְרָא אָחֳרָא, חַיָּילִין אָחֳרָנִין דְּאָמְרֵי קָדוֹשׁ. וְכֵן לְד' זַוְויָין. שִׁית מְאָה אֶלֶף רִבְּוָון חַיָּילִין בְּכָל זָוְויָּיא אִשְׁתְּכַח, וְעָלַיְיהוּ חַד מְמָנָא, וְכֻלְּהוּ מִתְלַבְּשֵׁי אֵפוֹדָא, וְקַיְימֵי לְסַדְּרָא פּוּלְחָנָא דְּמַדְבְּחָא לָקֳבֵל תַּתָּאֵי.","בַּאֲתַר אָחֳרָא מִשְׁתַּכְּחֵי גַּלְגַּלֵּי יַמָּא דְּנַהֲמִין, וְנַחְתִּין בְּדַרְגִּין יְדִיעָן, וְתַמָּן חַיָּילִין אַמְרִין בְּקָל נְעִימוּתָא, (יחזקאל ג׳:י״ב) בָּרוּךְ כְּבוֹד יְיָ' מִמְּקוֹמוֹ. וְכֻלְּהוּ מְשַׁבְּחֵי בְּשִׁירָתָא, וְלָא מִשְׁתַּכְכֵי בִּימָמָא וּבְלֵילְיָא, וְכֻלְּהוּ מְסַדְּרֵי שְׁבָחָא בְּקָל נְעִימוּתָא.","בַּאֲתַר אָחֳרָא, מִשְׁתַּכְּחֵי חַיָּילִין חַיָּילִין, קַיְימִין בִּדְחִילוּ בְּזִיעַ בְּרֶתֶת, כְּמָה דְאַתְּ אָמֵר (יחזקאל א) וְנֹגַהּ לָהֶם וְיִרְאָה לָהֶם. (וגבה להם ויראה להם). וְכֻלְּהוּ מִסְתַּכְּלֵי לְגַבֵּי הַהוּא מַדְבְּחָא דִּלְעֵילָּא.","וּבְשַׁעֲתָא דְּמָטֵי אֶשָּׁא דְּיִצְחָק עַל גַּבֵּי מַדְבְּחָא, כַּמָה זִיקִין סַלְּקִין וְנַחְתִּין לְכָל עִיבָר, וּמִתְלַהֲטִין מִנַּיְיהוּ, כַּמָה תַּקִּיפִין מָארֵי דְּחֵילָא, גִּיבָּרִין דְּעָלְמָא. וְאִלְמָלֵא דְּכַהֲנָא קָאִים עַל מַדְבְּחָא, וּמְסַדֵּר אָעִין, לָא יָכִיל עָלְמָא לְמֵיקָם קָמַיְיהוּ. מֵאִלֵּין גּוּמְרִין וְזִיקִין דְּנָפְקִין, מִתְלַהֲטָן גַּבֵּיהוֹן דְּאִינּוּן חֵיוָון, כְּמָה דְאַתְּ אָמֵר וּדְמוּת הַחַיּוֹת מַרְאֵיהֶם כְּגַחֲלֵי אֵשׁ בּוֹעֲרוֹת כְּמַרְאֵה הַלַּפִּידִים.","מִסִּטְרָא דִּימִינָא דְּאִינּוּן חֵיוָון, אִתְּעַר רוּחָא חֲדָא מִלְּעֵילָּא, נָשִׁיב וְיָתִיב בְּהַהוּא אֶשָּׁא, וּמִתְלַהֲטָא וּמִתְבַּסְּמָא, וְלָהִיט, וְשָׁכִיךְ בְּזִיוָוא יַקִּירָא, וְנָהִיר לְכַמָּה חַיָּילִין דְּקַיְימִין בְּסִטְרָא דִּימִינָא. מִסִּטְרָא דִּשְׂמָאלָא, אִתְּעַר רוּחָא אָחֳרָא תַּקִּיפָא, מַתְבָּר טִנָרִין, וְנָשִׁיב (ס\"א ויתיב) בְּהַהוּא אֶשָּׁא, וְאִתְתְּקַף וְאִתְגַּבָּר. כְּדֵין אִתְלְבַּשׁ מִנֵּיהּ הַהוּא רוּחָא דְּמִסִּטְרָא דִּשְׂמָאלָא, וְנָהִיר (ס\"א ולהיט) לְכַמָּה חַיָּילִין דְּקַיְימִין לְהַהוּא סְטַר. וְכֵן לְאַרְבַּע סִטְרִין, לְד' מַשִׁרְיָין. וְכֻלְּהוּ מִתְבַּסְּמָן בְּשַׁעֲתָא דְּכַהֲנָא סָלִיק עַל מַדְבְּחָא."],[[0,"על מוקדה:","היינו בנהר דינור, כי נהר דינור, הוא מקום לשרוף לכל אלו שאינם נמצאים כמו שצריכים להיות. ומביאים אותם באש שורף ההוא, ומעבירים ממשלתם מן העולם. וכדי שלא תשלוט, צריך \u0003על מוקדה כל הלילה,\u0004 ונכנעת ואינה שולטת. (ע״כ תוספתא)."],[1,"כתיב והנה ה׳ וגו':","כתוב והנה ה׳ עבר ורוח גדולה וחזק מפרק הרים וגו' \u0003רוח גדולה\u0004 היינו כמו שאמרנו (לעיל ויקהל אות קס״ב) שהוא רוח סערה, העומד קודם הכל ושומר הקדושה כקליפה השומרת את המוח. ע״ש. וכתוב, \u0003לא ברוח ה׳ ואחר הרוח רעש,\u0004 מהו רעש. הוא כמו שכתוב, ותשאני \u0003רוח\u0004 ואשמע אחרי קול \u0003רעש\u0004 גדול ברוך כבוד ה׳ ממקומו, הרי רעש זה הוא אחרי הרוח כמו רעש דאליהו, וכאן מבואר הרעש שהוא מפני שאומרים, ברוך כבוד ה׳ ממקומו. \u0003ואחר הרעש אש,\u0004 מהו אש. זה הוא שכתוב, נהר דינור נגיד ונפק מן קדמוהי וגו'. והוא האש שראה אליהו."],[2,"ר׳ יצחק אמר וכו׳:","רי״א, שהאש שראה אליהו, היינו שכתוב, ודמות החיות מראיהן כגחלי אש בוערות כמראה הלפידים היא מתהלכת בין החיות ונגה לאש ומן האש יוצא ברק. והיינו האש שראה אליהו. אשר החיות האלה הם מרכבה אל המלכות. והיינו שכתוב, \u0003ואחר האש קול דממה דקה,\u0004 קול, זהו קול האחרון, דהיינו המלכות, שהיא דממה, כי אין לה דבר פרטי משלה, אלא היא דממה מעצמה, כי המלכות לית לה מגרמה ולא מידי אלא הכל נותן לה ז״א. וכשמתקבצים עליה הספירות דז״א להשפיע לה, היא נשמעת בכל העולמות, דהיינו שכל העולמות בי״ע מקבלים ממנה, וכולם מזדעזעים ממנה. דממה \u0003דקה\u0004 למה נקראת, היה מספיק לקרוא לה קול דממה. הוא משום שהיא דקה וקטנה מכל הספירות דאצילות."],[3,"ר׳ חייא אמר וכו׳:","רח״א, אש תמיד תוקד על המזבח לא תכבה, זו היא אשו של יצחק, שכתוב, הנה האש והעצים, שהם הדינים הנמשכים מקו שמאל מטרם התכללותו בקו ימין, והיינו \u0003אש תמיד,\u0004 שעומד תמיד במלכות, כדי שתקבל החסדים מז״א. \u0003והעצים,\u0004 אלו הם העצים של אברהם, דהיינו החסדים הנמשכים מקו ימין שנקרא אברהם. שכתוב, ובער עליה הכהן עצים בבקר בבקר. והכהן הוא איש החסד."],[4,"תנן מאשא דיצחק וכו׳:","למדנו מאשו של יצחק, שה״ס הדין של קו שמאל דז״א, יורד ומגיע למזבח הזה, שהוא מלכות, ויוצאת גחלת אחת לצד מזרח, וגחלת אחת לצד מערב וגחלת אחת לצד צפון וגחלת אחת לצד דרום, שהם חו\"ג תו״מ, לד׳ קרנות המזבח, והכהן מחזיר אותה לד׳ קרנות."],[4,"","פירוש. כי הגחלת באה מן הצפון שהוא קו שמאל דהיינו אשו של יצחק, וא״כ היתה צריכה להגיע לצד צפון של המזבח בלבד, אלא הכהן, שהוא חסד, דהיינו קו ימין, מקבל הגחלת הזאת שהיא משמאל, ונכלל בה והיא בו, ע״י קו האמצעי, שה״ס ישראל, וגם המזבח עצמו שהוא מלכות המקבלת אותה נכלל ממנה, וע״כ נכללה הגחלת בכל ג׳ קוין, שה״ס דרום צפון ומזרח, ובמלכות, וע״כ הגיעה על ידי הכהן לד׳ קרנות המזבח. וז״ש \u0003וכהנא אסחר לה לד׳ זויין.\u0004"],[5,"במדבחא אית כבש וכו׳:","במזבח יש כבש אחד, דהיינו מדרגה, שהכהנים עומדים עליה לשמש במזבח, ויש בה מדרגות ידועות, דהיינו שיש בה ז״ס חג״ת נהי״מ, והמדרגה התחתונה, שהיא מלכות שבה, מגיעה ויורדת לתהום העליון, שהיא בינה דקליפה, מתוך שית אחד, דהיינו נקב חלל אחד המגיע ממנה עד התהום, ובשעה שאלה הגחלים מגיעים לד׳ קרנות המזבח, מתעורר ניצוץ אש אחד מהם ויורד דרך השית לתהום העליון ההוא. שמניצוץ הזה, מקבלת הקליפה כח לענוש הרשעים. \u0003שית\u0004 פירושו נקב חלל היורד עד התהום. מלשון \u0003שתין\u0004 מחוללין ויורדים עד התהום (סוכה מט.)"],[6,"ובההוא אתר אית וכו׳:","ובמקום ההוא, דהיינו על הכבש, יש צבאות צבאות שאומרים \u0003קדוש\u0004 בקול גדול עליון, שהם מקו ימין, חסד, ומצד אחר, אומרים \u0003קדוש\u0004 בקול נעימות עליונה, שהם מקו שמאל, גבורה. ומצד אחר, צבאות אחרים שאומרים \u0003קדוש,\u0004 שהם מקו אמצעי ת״ת. וכן לד׳ קרנות של הכבש. שבכל קרן עומדים ג׳ כתות הנ״ל ואומרים ג״פ קדוש. שהם כנגד י״ב צרופי אלכסון, שהם ד׳ בחינות חו״ג תו״מ שבכל אחת ג׳ קוין, והם י״ב. שש מאות אלף רבבות צבאות, שש ה״ס חג״ת נה״י, והארת הבינה ה״ס מאות ומחכמה ה״ס אלף, ומכתר ה״ס רבבות. ומבחינת יסוד, ה״ס צבאות. כלומר שעליהם הארת הג״ר. נמצאים בכל קרן של הכבש, ועליהם ממונה אחד, וכולם מתלבשים אפוד, מסוד בגדי כהונה, ועומדים על הכבש לסדר עבודת המזבח, שהיא המלכות, כנגד התחתונים, שבבית המקדש."],[7,"באתר אחרא וכו׳:","במקום אחר, לעומת הכבש, נמצאים גלי הים הרועשים, דהיינו בסו״ה ויעמד רוח סערה ותרומם גליו, שה״ס ואחר הרוח רעש (כנ״ל אות ע״ג, ע״ש) שיורדים במדרגות ידועות, ושם אומרים הצבאות בקול נעימות, ברוך כבוד ה׳ ממקומו. שהסו״ה, ואשמע אחרי קול רעש גדול ברוך כבוד ה׳ ממקומו. כי הם עומדים לעומת הצבאות הנ״ל העומדים על כבש המזבח ואומרים ג״פ קדוש קדוש קדוש (כנ״ל בדבור הסמוך) וז״ס לעומתם משבחים ואומרים ברוך כבוד ה׳ ממקומו. וכולם משבחים בשירה ואינם שותקים ביום ובלילה, וכולם מסדרים שבחים בקול נעימות."],[8,"באתר אחרא וכו׳:","במקום אחר, נמצאים צבאות צבאות העומדים ביראה ברעדה וברתת, כמש״א וגבה להם ויראה להם. ואומרי קדוש הם כנגד חסד, קו ימין, ואומרי ברוך הם כנגד גבורה, קו שמאל. ואלו שבכאן הם כנגד ת״ת, קו האמצעי. וע״כ אין בהם חידוש, כי כל החידושים הם בימין ובשמאל, וקו אמצעי אינו מוסיף עליהם אלא שכולל את שניהם בתוכו. וכולם מסתכלים, דהייני שמקבלים שפעם, אל מזבח ההוא שלמעלה, שהוא מלכות."],[9,"ובשעתא דמטי אשא וכו׳:","ובשעה שמגיע אש של יצחק, שהיא הדינים של קו שמאל, על המזבח, כמה שביבים עולים ויורדים לכל צד, ומתלהטים מהם כמה תקיפים בעלי כח גבורי העולם. ואם לא היה הכהן עומד על המזבח ומסדר העצים (כנ״ל אות ע״ה) לא היה יכול העולם לעמוד מפניהם. מאלו הגחלים והשביבים היוצאים מהם, מתלהטים גביהם של החיות. כש״א, ודמות החיות מראיהם כגחלי אש בוערות כמראה הלפידים."],[10,"מסטרא דימינא דאינון וכו׳:","מצד ימין של אלו החיות, מתעורר רוח אחד מלמעלה, מחסד דז״א, נושב ומתישב באש ההוא, של החיות, ומתלהט ומתבשם, ולוהט, ושוקט בזיו היקר, ומאיר לכמה צבאות הנמצאים בצד ימין. מצד שמאל, של החיות, מתעורר רוח אחר חזק, מגבורה דז״א, משבר סלעים, ונושב באש ההוא של החיות, ומתחזק ומתגבר, אז מתלבש בה באש ההוא, הרוח שמצד שמאל דז״א, ומאיר לכמה צבאות העומדים בצד ההוא בצד שמאל של החיות. וכן לד׳ רוחות חו״ג תו״מ, לד׳ מחנות. שנמשכים מד׳ רוחות חו״ג תו״מ דז״א, ד׳ רוחות, לד׳ מחנות שבחו״ג תו״מ של החיות, וכולם מתבשמים בעת שהכהן עולה על המזבח."]],[[0,"","עַל מוֹקְדָה, מִשּׁוּם שֶׁנְּהַר דִּינוּר הוּא מָקוֹם לִשְׂרֹף אֶת כָּל אֵלּוּ שֶׁלֹּא עוֹמְדִים בְּקִיּוּמָם, שֶׁהֲרֵי מַכְנִיסִים אוֹתָם לְאוֹתָהּ אֵשׁ בּוֹעֶרֶת וּמַעֲבִירִים אֶת שְׁלִיטָתָם מִן הָעוֹלָם. וּכְדֵי שֶׁלֹּא תִשְׁלֹט, (צריך) עַל מוֹקְדָה כָּל הַלַּיְלָה, וְתִכָּנַע וְלֹא תִשְׁלֹט."],[1,"","כָּתוּב (מלכים א יט) וְהִנֵּה ה' עֹבֵר וְרוּחַ גְּדוֹלָה וְחָזָק וְגוֹ'. רוּחַ גְּדוֹלָה שֶׁאָמַרְנוּ, וְכָתוּב לֹא בָרוּחַ ה'. וְאַחַר הָרוּחַ רַעַשׁ, שֶׁכָּתוּב (יחזקאל א) וַתִּשָּׂאֵנִי רוּחַ וָאֶשְׁמַע אַחֲרַי קוֹל רַעַשׁ גָּדוֹל. הֲרֵי רַעַשׁ אַחַר הָרוּחַ. וְאַחַר הָרַעַשׁ אֵשׁ, זֶהוּ שֶׁכָּתוּב (דניאל ז) נְהַר דִּינוּר יוֹצֵא וְשׁוֹפֵעַ מִלְפָנָיו וְגוֹ'. רַבִּי יִצְחָק אָמַר, הַיְנוּ שֶׁכָּתוּב (יחזקאל א) וּדְמוּת הַחַיּוֹת מַרְאֵיהֶם"],[2,"","כְּגַחֲלֵי אֵשׁ בּעֲרוֹת כְּמַרְאֵה הַלַּפִּדִים הִיא מִתְהַלֶּכֶת בֵּין הַחַיּוֹת וְנֹגַהּ לָאֵשׁ וּמִן הָאֵשׁ יוֹצֵא בָרָק. וְאַחַר הָאֵשׁ קוֹל דְּמָמָה דַקָּה, הַקּוֹל הַזֶּה קוֹל אַחֲרוֹן, שֶׁהוּא דְּמָמָה דַקָּה, שֶׁאֵין לָהּ דָּבָר פְּרָט מִשֶּׁלָּהּ, אֶלָּא הִיא דּוֹמֶמֶת מֵעַצְמָהּ. וּכְשֶׁמִּתְכַּנְּסִים עָלֶיהָ, הִיא נִשְׁמַעַת בְּכָל הָעוֹלָמוֹת, וְכֻלָּם מִזְדַּעְזְעִים מִמֶּנָּה. דְּמָמָה דַקָּה, לָמָּה הִיא דַּקָּה? מִשּׁוּם (שהיא) (שבאה) הַקְּטַנָּה מִכֻּלָּן."],[3,"","רַבִּי חִיָּיא אָמַר, אֵשׁ תָּמִיד תּוּקַד עַל הַמִּזְבֵּחַ לֹא תִכְבֶּה - זֶה אִשּׁוֹ שֶׁל יִצְחָק, שֶׁכָּתוּב (בראשית כב) הִנֵּה הָאֵשׁ וְהָעֵצִים, וְהַיְנוּ אֵשׁ תָּמִיד, שֶׁעוֹמֶדֶת תָּמִיד. וְהָעֵצִים - אֵלּוּ הָעֵצִים שֶׁל אַבְרָהָם, שֶׁכָּתוּב וּבִעֵר עָלֶיהָ הַכֹּהֵן עֵצִים בַּבֹּקֶר בַּבֹּקֶר."],[4,"","שָׁנִינוּ, מֵהָאֵשׁ שֶׁל יִצְחָק שׁוֹפֵעַ וּמַגִּיעַ לַמִּזְבֵּחַ הַזֶּה, וְיוֹצֵאת גַּחֶלֶת אַחַת לְצַד מִזְרָח, וְגַחֶלֶת אַחֶרֶת לְצַד מַעֲרָב, וְגַחֶלֶת אַחַת לְצַד צָפוֹן, וְגַחֶלֶת אַחַת לְצַד דָּרוֹם, לְאַרְבַּע קַרְנוֹת הַמִּזְבֵּחַ, וְהַכֹּהֵן מְסוֹבֵב אוֹתָהּ לְאַרְבַּע קְרָנוֹת."],[5,"","בַּמִּזְבֵּחַ (במזרח) יֵשׁ כֶּבֶשׁ אֶחָד בִּדְרָגוֹת יְדוּעוֹת, וְהַדַּרְגָּה הַתַּחְתּוֹנָה מַגִּיעָה וְיוֹרֶדֶת לַתְּהוֹם הָעֶלְיוֹן, מִתּוֹךְ שֵׁשׁ אַחַת. וּבְשָׁעָה שֶׁאוֹתָן הַגֶּחָלִים מַגִּיעוֹת לְאַרְבַּע הַקְּרָנוֹת, רוּחַ אַחַת מִתְעוֹרֶרֶת וְיוֹרֶדֶת לְאוֹתוֹ הַתְּהוֹם הָעֶלְיוֹן."],[6,"","וּבְאוֹתוֹ מָקוֹם יֵשׁ צְבָאוֹת צְבָאוֹת שֶׁאוֹמְרִים קָדוֹשׁ בְּקוֹל גָּדוֹל עֶלְיוֹן. וּמִצַּד אַחֵר אוֹמְרִים קָדוֹשׁ בְּקוֹל נְעִימוּת עֶלְיוֹנָה. וּמִצַּד אַחֵר צְבָאוֹת אֲחֵרִים שֶׁאוֹמְרִים קָדוֹשׁ. וְכֵן לְאַרְבַּע הַקְּרָנוֹת. שֵׁשׁ מֵאוֹת אֶלֶף רְבָבוֹת צְבָאוֹת בְּכָל קֶרֶן נִמְצָאִים, וַעֲלֵיהֶם מְמֻנֶּה אֶחָד, וְכֻלָּם לְבוּשִׁים אֵפוֹד, וְעוֹמְדִים לְסַדֵּר עֲבוֹדַת הַמִּזְבֵּחַ כְּנֶגֶד הַתַּחְתּוֹנִים."],[7,"","בְּמָקוֹם אַחֵר נִמְצָאִים גַּלֵּי הַיָּם שֶׁנּוֹהֲמִים וְיוֹרְדִים בִּדְרָגוֹת יְדוּעוֹת, וְשָׁם צְבָאוֹת שֶׁאוֹמְרִים בְּקוֹל נְעִימוּת, בָּרוּךְ כְּבוֹד ה' מִמְּקוֹמוֹ. וְכֻלָּם מְשַׁבְּחִים בְּשִׁירָה וְלֹא שׁוֹקְטִים בַּיּוֹם וּבַלַּיְלָה, וְכֻלָּם מְסַדִּרִים שֶׁבַח בְּקוֹל נְעִימוּת."],[8,"","בְּמָקֹוֹם אַחֵר נִמְצָאִים צְבָאוֹת צְבָאוֹת, עוֹמְדִים בְּפַחַד, בְּזִיעַ, בְּרֶתֶת, כְּמוֹ שֶׁנֶּאֱמַר (יחזקאל א) וְנֹגַהּ לָהֶם וְיִרְאָה לָהֶם. (וגבה להם ויראה להם). וְכֻלָּם מִסְתַּכְּלִים אֶל אוֹתוֹ מִזְבֵּחַ שֶׁלְּמַעְלָה."],[9,"","וּבְשָׁעָה שֶׁמַּגִּיעָה הָאֵשׁ שֶׁל יִצְחָק עַל גַּבֵּי הַמִּזְבֵּחַ, כַּמָּה זִיקִים עוֹלִים וְיוֹרְדִים לְכָל עֵבֶר, וְלוֹהֲטִים מֵהֶם כַּמָּה תַקִּיפִים בַּעֲלֵי כֹחַ, גִּבּוֹרִים שֶׁל הָעוֹלָם. וְאִלְמָלֵא שֶׁהַכֹּהֵן עוֹמֵד עַל הַמִּזְבֵּחַ וּמְסַדֵּר עֵצִים, לֹא יָכוֹל הָעוֹלָם לַעֲמֹד לִפְנֵיהֶם. מֵאֵלֶּה הַגֶּחָלִים וְהַזִּיקִים שֶׁיּוֹצְאִים, לוֹהֲטִים גַּבֵּיהֶם שֶׁל אוֹתָן חַיּוֹת, כְּמוֹ שֶׁנֶּאֱמַר וּדְמוּת הַחַיּוֹת מַרְאֵיהֶם כְּגַחֲלֵי אֵשׁ בּעֲרוֹת כְּמַרְאֵה הַלַּפִּדִים."],[10,"","מִצַד יָמִין שֶׁל אוֹתָן הַחַיּוֹת מִתְעוֹרֶרֶת רוּחַ אַחַת מִלְמַעְלָה, נוֹשֶׁבֶת וְיוֹשֶׁבֶת בְּאוֹתָהּ הָאֵשׁ, וּמִתְלַהֶטֶת וּמִתְבַּשֶּׂמֶת, וְלוֹהֶטֶת, וְשׁוֹכֶכֶת בְּזִיו יָקָר, וּמְאִירָה לְכַמָּה צְבָאוֹת שֶׁעוֹמְדִים בְּצַד יָמִין. וּמִצַּד הַשְּׂמֹאל מִתְעוֹרֶרֶת רוּחַ אַחֶרֶת חֲזָקָה מְשַׁבֶּרֶת סְלָעִים וְנוֹשֶׁבֶת (ויושבת) בְּאוֹתָהּ הָאֵשׁ וּמִתְחַזֶּקֶת וּמִתְגַּבֶּרֶת. וְאָז מִתְלַבֶּשֶׁת מִמֶּנָּה אוֹתָהּ רוּחַ שֶׁמִּצַּד שְׂמֹאל, וּמְאִירָה (ולוהטת) לְכַמָּה צְבָאוֹת שֶׁעוֹמְדִים בְּאוֹתוֹ צַד, וְכֵן לְאַרְבַּעַת הַצְּדָדִים, לְאַרְבַּע מַחֲנוֹת. וְכֻלָּם מִתְבַּשְּׂמִים בְּשָׁעָה שֶׁהַכֹּהֵן עוֹלֶה עַל הַמִּזְבֵּחַ."]]],[["אָמַר רִבִּי אַבָּא תְּרֵין מַדְבְּחָאן אִינּוּן לְתַתָּא, וּתְרֵין לְעֵילָּא. חַד פְּנִימָאָה דְּכֹלָּא, דְּמִתְקָרֵב בֵּיהּ קְטֹרֶת פְּנִימָאָה, וְדַקָּה. קִשּׁוּרָא דִּמְהֵימְנוּתָא, וְכַהֲנָא עִלָּאָה מִכֹּלָּא, אִתְקְשַׁר (נ\"א אקטר) קְטוֹרְתָּא דָּא, בְּקִשּׁוּרָא דִּמְהֵימְנוּתָא, וְדָא אִתְקְרֵי מִזְבַּח הַזָּהָב, וּמֵהָכָא אִתְקְטַר וְאִתְקְשַׁר קִשְׁרָא דִּמְהֵימְנוּתָא, בְּחַד קִשְׁרָא. וְחַד מַדְבְּחָא אָחֳרָא, וְאִקְרֵי מִזְבַּח הַנְּחֹשֶׁת, וְדָא הוּא לְבַר, (רברבא עלאה) וּמִיכָאֵל הַשַּׂר הַגָּדוֹל, מַקְרִיב עָלֵיהּ קָרְבְּנָא נַיְיחָא דְּקוּדְשָׁא בְּרִיךְ הוּא. וּלְתַתָּא, מִזְבַּח הַזָּהָב, וּמִזְבַּח הַנְּחֹשֶׁת, בְּדָא קְטֹרֶת. וּבְדָא חֲלָבִין וְאֵמוּרִין.","וְעַל דָּא כְּתִיב, (משלי כ״ז:ט׳) שֶׁמֶן וּקְטֹרֶת יְשַׂמַּח לֵב. וְלָא כְּתִיב שֶׁמֶן וַחֲלָבִין וְאֵמוּרִין יְשַׂמַּח, אַף עַל גַּב דְּאִתְבַּסְמוּתָא דְּרוּגְזָא וְדִינָא אִינּוּן. אֲבָל שֶׁמֶן וּקְטֹרֶת, חֶדְוָותָא דְּכֹלָּא אִיהוּ, וְלָא מִסִּטְרָא דְּרוּגְזָא וְדִינָא. וְדָא מַדְבְּחָא דְּאִיהוּ פְּנִימָאָה דִּקְטֹרֶת (ס\"א דאינון פנימאה דקטרת) דַּקָּה, בְּדַקּוּתָא דְּכֹלָּא, בְּקִשּׁוּרָא דִּמְהֵימְנוּתָא, אִקְרֵי קוֹל דְּמָמָה דַּקָּה, וּבְגִין דְּאִיהוּ מַדְבְּחָא פְּנִימָאָה, דְּאִתְקְשַׁר בְּקִשּׁוּרָא דִּמְהֵימְנוּתָא.","מַדְבְּחָא אָחֳרָא, אִקְרֵי מִזְבֵּחַ הַחִצוֹן. וּפְנִימָאָה אִקְרֵי מִזְבַּח יְיָ'. אָחֳרָא, אִקְרֵי מִזְבַּח הַנְּחֹשֶׁת, כְּמָה דְאַתְּ אָמֵר (מלכים א ח׳:ס״ד) מִזְבַּח הַנְּחֹשֶׁת אֲשֶׁר לִפְנֵי יְיָ' קָטֹן מֵהָכִיל וְגוֹ'. רִבִּי יוֹסֵי אָמַר מֵהָכָא, (דברים ל״ג:י׳) וְכָלִיל עַל מִזְבְּחֶךָ, תְּרֵי. וּכְתִיב עַל מִזְבְּחוֹתַי לְרָצוֹן.","רִבִּי אַבָּא (אחא) אָמַר, כְּתִיב (שמות י״ז:ט״ו) וַיִבֶן מֹשֶׁה מִזְבֵּחַ וְגוֹ', לָקֳבֵל הַהוּא פְּנִימָאָה בָּנָהּ הַאי, וְעַל דָּא אִתְקְרֵי יְיָ' נִסִּי. מַהוּ נִסִּי. דְּרָשִׁים רְשִׁימָא דְּאָת קַיָּימָא קַדִּישָׁא. דִּבְשַׁעֲתָא דַּעֲמָלֵק אָתָא לְאַעְבְּרָא הַאי רְשִׁימָא קַדִּישָׁא מִנַיְיהוּ דְּיִשְׂרָאֵל, הַאי מִזְבַּח קַיְּימָא לָקֳבְלֵיהּ לְנַקְמָא הַהוּא נוּקְמָא דְּאָת קַיָּימָא, וְעַל דָּא אִתְקְרֵי (ויקרא כ״ו:כ״ה) חֶרֶב נוֹקֶמֶת נְקַם בְּרִית. וְדָא אַתְקְנַת לְהוּ לְיִשְׂרָאֵל רְשִׁימָא קַדִּישָׁא. וּמֹשֶׁה בָּנָה לָקֳבֵל הַאי מִזְבֵּחַ, וְקָרֵי לֵיהּ יְיָ' נִסִּי. וְדָא הוּא מִזְבֵּחַ פְּנִימִי, (מלכים א י״ט:י״ב) קוֹל דְּמָמָה דַּקָּה.","וְעַל דָּא אֵשׁ תָּמִיד תּוּקַד עַל הַמִּזְבֵּחַ וְגוֹ', אֵשׁ דְּאִשְׁתְּכַח תְּדִירָא. וּמַאי אִיהוּ. אֶשָּׁא דְּיִצְחָק. וּכְדֵין, שְׁמָא דָּא, אֲדֹנָ\"י. וְכַד יְסַדָּר עָלָה כַּהֲנָא אִינּוּן אָעִין, אִתְבַּסְמָא בִּשְׁמָא, וְקָרֵינָן לָהּ בִּשְׁמָא דְּרַחֲמֵי, יְיָ', וְקָרֵינָן לָהּ בִּשְׁמָא דָּא. וּלְזִמְנִין קַיְּימָא כְּגַוְונָא דָּא, וּלְזִמְנִין קַיְּימָא כְּגַוְונָא דָּא. רִבִּי שִׁמְעוֹן אָמַר, תְּרֵי הֲווֹ, וּפְנִימָאָה קַיְּימָא עַל הַהוּא דִּלְבַר, וּמִנָהּ אִתְּזָן, וְאִתְקַשְּׁרָא דָּא בְּדָא.","(ויקרא ו׳:י״ג) זֶה קָרְבָּן אַהֲרֹן. רִבִּי חִזְקִיָּה פָּתַח, (תהילים קמ״ה:י״ז) צַדִּיק יְיָ' בְּכָל דְּרָכָיו וְחָסִיד בְּכָל מַעֲשָׂיו. צַדִּיק יְיָ' בְּכָל דְּרָכָיו, הָא תָּנֵינָן, כַּמָה אִית לוֹן לִבְנֵי נָשָׁא לְאִסְתַּכְּלָא בִּיקָרָא דְּמָארֵיהוֹן, וְלָא יִסְטוּ מֵאָרְחַיְיהוּ לְבַר. דְּהָא בְּכָל יוֹמָא וְיוֹמָא דִּינָא תָּלֵי בְּעָלְמָא, בְּגִין דְּעָלְמָא עַל דִּינָא אִתְבְּרֵי וְקַיְּימָא.","וְעַל דָּא, בָּעֵי בַּר נָשׁ לְאִסְתַּמְּרָא מֵחוֹבוֹי, דְּלָא יָדַע זִמְנָא דְּדִינָא שַׁרְיָא עֲלוֹי. יָתִיב בְּבֵיתֵיהּ, דִּינָא שַׁרְיָא עֲלוֹי. נָפַק מִבֵּיתֵיהּ לְבַר, דִּינָא שַׁרְיָא עֲלוֹי. וְלָא יָדַע אִי יְתוּב לְבֵיתֵיהּ אִי לָאו. נָפִיק לְאָרְחָא, עַל אַחַת כַּמָה וְכַמָּה, דְּהָא כְּדֵין דִּינָא נָפְקָא קַמֵּיהּ, הֲדָא הוּא דִכְתִיב, (תהילים פ״ה:י״ד) צֶדֶק לְפָנָיו יְהַלֵּךְ. בְּגִין כָּךְ, בָּעֵי לְאַקְדְּמָא וּלְמִבָּעֵי רַחֲמֵי קָמֵי מַלְכָּא, בְּגִין דְּיִשְׁתְּזִיב מִן דִּינָא, בְּשַׁעֲתָא דְּשַׁרְיָא בְּעָלְמָא. דְּהָא כָּל יוֹמָא וְיוֹמָא שַׁרְיָא דִּינָא בְּעָלְמָא, הֲדָא הוּא דִכְתִיב, (תהלים ז) וְאֵל זוֹעֵם בְּכָל יוֹם.","הַשְׁתָּא אִית לְמֵימַר, הָא תָּנֵינָן, וְאִתְּעֲרוּ חַבְרַיָּיא, אֵל בְּכָל אֲתַר חֶסֶד הוּא, כְּמָה דְאַתְּ אָמֵר (דברים י) הָאֵל הַגָּדוֹל, וְדָא נְהִירוּ דְּחָכְמָה עִלָּאָה, וְאַתְּ (קי\"ט ע\"ב) אַמְרַת וְאֵל זוֹעֵם בְּכָל יוֹם, שָׁבִיק קְרָא כָּל אִלֵּין שְׁמָהָן, וְאָחִיד בְּהַאי, אִי הָכִי לָא קַיְימִין מִילֵּי. וְעוֹד, דִּכְתִּיב, (ישעיה ט) אֵל גִּבּוֹר, אוֹ נוֹקִים לֵיהּ דִּינָא, אוֹ נוֹקִים לֵיהּ רַחֲמֵי.","אֶלָּא הָכִי שְׁמַעְנָא, חַיָּיבַיָּא מְהַפְּכֵי רַחֲמֵי לְדִינָא. דְּלֵית לָךְ בְּכָל אִינּוּן כִּתְרִין עִלָּאִין דְּמַלְכָּא קַדִּישָׁא, דְּלָא כְּלִילָן רַחֲמֵי בְּדִינָא, וְדִינָא בְּרַחֲמֵי. וְחַיָּיבַיָּא, מְהַפְּכֵי רַחֲמֵי לְדִינָא.","אָמַר לֵיהּ רִבִּי יְהוּדָה, שַׁפִּיר בְּהַהוּא דִּכְתִּיב אֵל גִּבּוֹר, אֶלָּא אֵל זוֹעֵם בְּכָל יוֹם מַהוּ, דְּהָא בְּכָל יוֹמָא וְיוֹמָא קַיְּימָא בְּדִינָא, בֵּין דִּבְנֵי עָלְמָא זַכָּאִין, בֵּין דְּלָא זַכָּאִין. לָא הֲוָה בִּידֵיהּ, אָתוּ שָׁאִילוּ לֵיהּ לְרַבִּי שִׁמְעוֹן. אָמַר לוֹן, וַדַּאי אֵל זוֹעֵם בְּכָל יוֹם, וְהָא אוּקְמוּהָ חַבְרַיָּיא, לְזִמְנִין הוּא דִּינָא, לְזִמְנִין הוּא רַחֲמֵי. אִי זַכָּאִין בְּנֵי עָלְמָא, הָא אֵל קַיְּימָא, וְהוּא חֶסֶד. וְאִי לָא זַכָּאן, הָא אֵל קַיְּימָא, וְאִקְרֵי גִּבּוֹר, וְעַל דָּא קַיְּימָא בְּכָל יוֹמָא."],[[0,"א״ר אבא תרין וכו׳:","אר״א, ב׳ מזבחות הם למטה, וב׳ מזבחות הם למעלה. ב׳ המזבחות שלמעלה, אחד הוא פנימי מכל, שנקרבת בו קטרת פנימית ודקה שהיא קשר האמונה, וכהן העליון מכל, קושר קטורת זו בקשר האמונה. וזה נקרא מזבח הזהב, ומכאן נקטר ונקשר קשר האמונה לקשר הכל בקשר אחד. ואחד הוא, מזבח אחר, שנקרא מזבח הנחשת, וזה הוא מבחוץ, ומיכאל השר הגדול מקריב עליו קרבן ניחוח להקב״ה. וב׳ מזבחות למטה, בבית המקדש, מזבח הזהב, ומזבח הנחשת, בזה קטרת, ובזה חלבים ואמורים."],[0,"","פירוש. ג׳ פרצופין הם במלכות שהם מלובשים זה בתוך זה, פרצוף חב״ד הוא פנימי מכולם, ועליו מלביש פרצוף חג״ת, ועליו מלביש פרצוף נה״י. והם נחלקים לפנימי וחיצון, שפרצוף חב״ד הוא פנימי, וב׳ הפרצופין חג״ת נה״י הם חצוניים. וקטורת, ה״ס בינה."],[0,"","וז״ש, \u0003חד פנימאה דכלא,\u0004 שמזבח אחד הוא בסוד פרצוף הפנימי של המלכות דהיינו חב״ד, שהוא הפנימי מכל ג׳ הפרצופין שלה. \u0003דמתקרב ביה קטרת פנימאה ודקה,\u0004 שבו מוקרבת קטרת שהיא פנימית ודקה, דהיינו שרומזת על בינה, שהיא דקה מלהשיג בה, שזה עושה קשר האמונה, שהיא המלכות, בקטרת שהיא בינה, וז״ש, \u0003קשורא דמהימנותא.\u0004 ומפרש, \u0003כהנא עלאה מכלא,\u0004 שהוא חכמה, הנקראת כהן גדול, \u0003אקטר קטורתא דא בקשורא דמהימנותא,\u0004 שהחכמה מקשרת קטורת זו שהיא בינה, בהמזבח שהוא מלכות הפנימית. \u0003ודא אתקרי מזבח הזהב,\u0004 כי הבינה נקראת זהב, ועל שם הקטרת שבמלכות שהיא בינה, היא נקראת מזבח הזהב. וז״ש, \u0003ומהכא אתקטר ואתקשר קשרא דמהימנותא בחד קשרא.\u0004 כי ע״י קשר זה של בינה במלכות, נקשרים כל הספירות בקשר אחד, דהיינו שכולן מתיחדות זו בזו. \u0003וחד מדבחא אחרא ואקרי מזבח הנחשת, ודא הוא לבר,\u0004 דהיינו המזבח שבבחינת ו״ק שלה, שהם בב׳ פרצופין החצונים חג״ת נה״י כנ״ל. \u0003ומיכאל השר הגדול מקריב עליה קרבנא נייחא דקב״ה,\u0004 דהיינו קרבן של נשמות הצדיקים, (כנ\"ל פרשת לך אות פ״ד)."],[1,"ועל דא כתיב וכו׳:","ועל כן כתוב, שמן וקטרת ישמח לב, ולא כתוב שמן וחלבים ואמורים ישמח. אע״פ שגם הם המתקת הרוגז והדין כמו שמן וקטרת, אבל יש הפרש, כי שמן וקטרת, הרומזים על יחוד חו״ב, כי שמן הוא חכמה, וקטרת היא בינה, הם שמחת הכל, ולא מצד הרוגז והדין, כי בהם עצמם אין שום דין כלל. משא״כ החלבים והאמורים שעל ידיהם נעשה היחוד של ז״א ומלכות, לא נאמר בהם, ישמח לב, מחמת שיש בהם אחיזה לדינים. וזה המזבח שהוא פנימי, אשר קטרת דקה, הדקה מכל, דהיינו בינה, שאין השגה בה מחמת דקותה, היא בקשר האמונה, שנקשרת במלכות הנקראת אמונה, הוא נקרא קול דממה דקה, משום שהוא מזבח פנימי הנקשר בקשר האמונה. (דפו״י דף ל׳ ע״ב)"],[2,"מדבחא אחרא אקרי וכו׳:","מזבח האחר נקרא מזבח החיצון. והפנימי נקרא מזבח ה׳. מזבח האחר נקרא מזבח הנחשת, כש״א מזבח הנחשת אשר לפני ה׳ קטן מהכיל וגו'. ר׳ יוסי אומר, שזה נלמד מכאן, שכתוב, וכליל על מזבחך, אשר הח׳ היא סגולה, שמורה על רבים, שמשמע שנים. וכתוב, את מזבחותיך ה׳ צבאות (תהלים פ״ד) (כצ״ל, כמ״ש להלן בלק קצ״ו ע״ב, ד״י) שמשמע שנים."],[3,"רבי אחא אמר וכו׳:","רא״א, ר״א חולק על ר׳ אבא ור׳ יוסי, ואומר, שאין כאן אלא מזבח אחד, שלפעמים נקרא פנימי ולפעמים חיצוני, כמ״ש לפנינו, ואומר, כתוב, ויבן משה מזבח וגו', כנגד הפנימי בנה זה, וע״כ נקרא הויה נסי, כי הפנימי נקרא מזבח הויה. מהו נסי. היינו שרשם ותקן רשימת אות ברית קודש. כי בשעה שבא עמלק להעביר רשימה הקדושה הזו, דהיינו ברית מילה, מן ישראל, מזבח הזה, שהוא המלכות, עמד כנגדו לנקום נקמה ההיא של אות ברית, וע״כ נקראת המלכות, חרב נוקמת נקם ברית. וזו, המלכות, תקנה לישראל את הרשימה הקדושה, ומשה בנה כנגד מזבח הזה, וקרא אותו הויה נסי. וזה הוא מזבח הפנימי. שנקרא קול דממה דקה."],[4,"ועל דא, אש וגו':","ועל זה, המזבח הפנימי, נאמר, אש תמיד תוקד על המזבח וגו', שהוא אש הנמצאת תמיד, ומה היא. היא אשו של יצחק, דהיינו הדינים דקו שמאל, שהם נמצאים תמיד, ואז שם המזבח \u0003אדני,\u0004 דהיינו בבחינת דין, ואז נקרא \u0003מזבח חיצון.\u0004 וכשיסדר עליו הכהן אלו העצים, שהם חסדים שקו שמאל מתלבש בהם, שמו של המזבח מתבשם, וקוראים אותו בשם של רחמים הויה, וקוראים אותו בשם זה דהיינו מזבח הויה, שהוא אז מזבח פנימי. ולפעמים עומד המזבח כאפן הזה, בבחינת דין שהוא מזבח חיצוני, ולפעמים הוא עומד באופן הזה, בבחינת רחמים, שהוא מזבח פנימי. ואינם ב׳ מזבחות נפרדים זה מזה. ר׳ שמעון אמר שנים היו, דהיינו ב׳ מזבחות מיוחדים, שמכריע כמו ר׳ אבא ור׳ יוסי, והפנימי עומד על מזבח ההוא שמבחוץ. כלומר שמתלבשים זה בזה, כי פרצוף הפנימי של המלכות מלובש בפרצוף החיצוני (כנ\"ל אות פ״ב) והחיצוני ניזון מהפנימי ונקשרים זה בזה."],[5,"זה קרבן אהרן:","ר׳ חזקיה פתח, צדיק ה׳ בכל דרכיו וחסיד בכל מעשיו. צדיק ה׳ בכל דרכיו, הרי למדנו, כמה יש לבני אדם להסתכל בכבוד אדונם, ולא יטו מדרכיהם לחוץ, כי בכל יום ויום דין תולה בעולם, משום שהעולם נברא בדין ועומד על דין."],[6,"ועל דא בעי וכו׳:","וע״כ צריך האדם להשמר מעונותיו, כי אינו יודע הזמן שהדין שורה עליו. יושב בביתו שורה עליו הדין, יוצא מביתו לחוץ שורה עליו הדין, ואינו יודע אם ישוב לביתו או לא, שיכול למות ולא ישוב לביתו. יוצא לדרך על אחת כמה וכמה, שיש לחוש שלא ישוב לביתו. כי אז הדין יוצא לפניו, ז״ש, צדק לפניו יהלך וגו'. משום זה צריך האדם להקדים ולבקש רחמים לפני המלך, כדי שינצל מן הדין, בשעה ששורה בעולם. כי בכל יום ויום שורה דין בעולם. ז״ש ואל זועם בכל יום."],[7,"השתא אית למימר וכו׳:","עתה יש לשאול. הרי למדנו והעירו החברים שהשם \u0003אל,\u0004 בכל מקום הוא חסד, כש״א האל הגדול, וזה הוא הארה של חכמה העליונה, כי חסד, לעת גדלות ז״א, עולה ונעשה לחכמה עליונה. ואתה אומר, ואל זועם בכל יום, שעוזב הכתוב כל אלו השמות שיורים על חסד, ואוחז בזה, בדין, אם כן אין הדברים אמיתים. ועוד, שכתוב, אל גבור. שקשה או נעמיד השם \u0003אל\u0004 בדין, או נעמיד השם \u0003אל\u0004 ברחמים."],[8,"אלא הכי שמענא וכו׳:","ומשיב, אלא כך שמעתי, הרשעים מהפכים הרחמים לדין, שאין לך בכל ספירות העליונות של מלך הקדוש שהרחמים לא יהיו כלולים בדין, והדין ברחמים, והרשעים מהפכים הרחמים לדין. וע״כ, אע״פ שהשם \u0003אל,\u0004 הוא חסד הרשעים מהפכים אותו לדין."],[9,"אמר ליה ר׳ יהודה וכו׳:","א\"ל ר״י, התירוץ שלך יפה בזה שכתוב, \u0003אל גבור,\u0004 שלרשעים נהפך לדין, אלא הכתוב, \u0003אל זועם בכל יום,\u0004 מה תאמר, שמשמע שבכל יום ויום עומד בדין, בין שבני העולם צדיקים בין שאינם צדיקים. לא היה בידו לתרץ את זה. באו שאלו לר׳ שמעון, אמר להם, ודאי, אל זועם בכל יום, וכבר העמידו החברים, שלפעמים השם אל הוא דין, ולפעמים הוא רחמים, אם בני העולם זכאים, הרי עומד השם אל, והוא חסד. ואם אינם זכאים, הרי עומד ונקרא גבור. ועל זה עומד בכל יום, כלומר, שבכל יום יש זכאים ואינם זכאים, וע״כ לאינם זכאים, ואל זועם בכל יום."]],[[0,"","אָמַר רַבִּי אַבָּא, שְׁנֵי מִזְבְּחוֹת הֵם לְמַטָּה, וּשְׁנַיִם לְמַעְלָה, אֶחָד פְּנִימִי שֶׁל הַכֹּל, שֶׁנִּקְרֶבֶת בּוֹ הַקְּטֹרֶת הַפְּנִימִית וְדַקָּה, קֶשֶׁר הָאֱמוּנָה, וְהַכֹּהֵן הָעֶלְיוֹן מֵהַכֹּל קוֹשֵׁר (מקטיר) אֶת הַקְּטֹרֶת הַזּוֹ בְּקֶשֶׁר הָאֱמוּנָה, וְזֶה נִקְרָא מִזְבַּח הַזָּהָב. וּמִכָּאן נִקְטָר וְנִקְשָׁר קֶשֶׁר הָאֱמוּנָה בְּקֶשֶׁר אֶחָד. וּמִזְבֵּחַ אֶחָד אַחֵר שֶׁנִּקְרָא מִזְבַּח הַנְּחֹשֶׁת, וְזֶהוּ בַּחוּץ, (גדול עליון) וּמִיכָאֵל הַשַּׂר הַגָּדוֹל מַקְרִיב עָלָיו קָרְבָּן נִיחֹחַ לַקָּדוֹשׁ בָּרוּךְ הוּא. וּלְמַטָּה - מִזְבַּח הַזָּהָב וּמִזְבַּח הַנְּחֹשֶׁת, בָּזֶה קְטֹרֶת, וּבָזֶה חֲלָבִים וְאֵמוּרִים."],[1,"","וְעַל זֶה כָּתוּב, (משליכו) שֶׁמֶן וּקְטֹרֶת יְשַׂמַּח לֵב. וְלֹא כָתוּב שֶׁמֶן וַחֲלָבִים וְאֵמוּרִים יְשַׂמַּח, אַף עַל גַּב שֶׁהֵם הִתְבַּשְּׂמוּת שֶׁל הָרֹגֶז וְהַדִּין. אֲבָל שֶׁמֶן וּקְטֹרֶת הֵם שִׂמְחַת הַכֹּל, וְלֹא מִצַּד הָרֹגֶז וְהַדִּין. וְהַמִּזְבֵּחַ הַזֶּה שֶׁהוּא פְּנִימִי שֶׁל קְטֹרֶת (שהם פנימיות הקטרת) דַּקָּה, בְּדַקּוּת שֶׁל הַכֹּל, בְּקֶשֶׁר הָאֱמוּנָה, נִקְרָא קוֹל דְּמָמָה דַקָּה, וּמִשּׁוּם שֶׁהוּא הַמִּזְבֵּחַ הַפְּנִימִי שֶׁנִּקְשָׁר בְּקֶשֶׁר הָאֱמוּנָה."],[2,"","מִזְבֵּחַ אַחֵר נִקְרָא מִזְבֵּחַ הַחִיצוֹן, וְהַפְּנִימִי נִקְרָא מִזְבַּח ה'. הָאַחֵר נִקְרָא מִזְבַּח הַנְּחֹשֶׁת, כְּמוֹ שֶׁנֶּאֱמַר (מלכים א ח) מִזְבַּח הַנְּחֹשֶׁת אֲשֶׁר לִפְנֵי ה' קָטֹן מֵהָכִיל וְגוֹ'. רַבִּי יוֹסֵי אָמַר מִכָּאן, (דברים לג) וְכָלִיל עַל מִזְבְּחֶךְ, שְׁנַיִם. וְכָתוּב עַל מִזְבְּחוֹתַי לְרָצוֹן."],[3,"","רַבִּי אַבָּא (אחא) אָמַר, כָּתוּב (שמות יז) וַיִּבֶן מֹשֶׁה מִזְבֵּחַ וְגוֹ', כְּנֶגֶד אוֹתוֹ פְּנִימִי בָּנָה אֶת זֶה, וְעַל זֶה נִקְרָא ה' נִסִּי. מַה זֶּה נִסִּי? שֶׁרָשַׁם אֶת הָרֹשֶׁם שֶׁל אוֹת הַבְּרִית הַקָּדוֹשׁ. שֶׁבְּשָׁעָה שֶׁעֲמָלֵק בָּא לְהַעֲבִיר אֶת הָרֹשֶׁם הַקָּדוֹשׁ הַזֶּה מִיִּשְׂרָאֵל, הַמִּזְבֵּחַ הַזֶּה עָמַד כְּנֶגְדּוֹ לִנְקֹם אוֹתָהּ נִקְמַת אוֹת הַבְּרִית, וְלָכֵן נִקְרָא (ויקרא כו) חֶרֶב נֹקֶמֶת נְקַם בְּרִית. וְזוֹ הִתְקִינָה לְיִשְׂרָאֵל רֹשֶׁם קָדוֹשׁ. וּמֹשֶׁה בָּנָה כְּנֶגְדָּהּ מִזְבֵּחַ, וְקָרָא לוֹ ה' נִסִּי, וְזֶהוּ מִזְבֵּחַ הַפְּנִימִי, (מלכים א יט) קוֹל דְּמָמָה דַקָּה."],[4,"","וְעַל כֵּן, אֵשׁ תָּמִיד תּוּקַד עַל הַמִּזְבֵּחַ וְגוֹ', אֵשׁ שֶׁנִּמְצֵאת תָּמִיד. וּמִי הִיא? הָאֵשׁ שֶׁל יִצְחָק. וְאָז הַשֵּׁם הַזֶּה - אֲדֹנָ\"י. וּכְשֶׁיְּסַדֵּר עָלָיו הַכֹּהֵן אוֹתָם עֵצִים, הוּא מִתְבַּשֵּׂם בַּשֵּׁם, וְקוֹרְאִים לוֹ בְּשֵׁם הָרַחֲמִים - יְיָ, וְקוֹרְאִים לָהּ בַּשֵּׁם הַזֶּה. וְלִפְעָמִים עוֹמֶדֶת כְּמוֹ זֶה, וְלִפְעָמִים עוֹמֶדֶת כְּמוֹ זֶה. רַבִּי שִׁמְעוֹן אָמַר, שְׁנַיִם הָיוּ, וְהַפְּנִימִי עוֹמֵד עַל אוֹתוֹ אֶחָד שֶׁבַּחוּץ, וּמִמֶּנּוּ נִזּוֹן, וְנִקְשָׁרִים זֶה עִם זֶה."],[5,"","זְהִ קָרְבַּן אַהֲרֹן. רַבִּי חִזְקִיָּה פָּתַח, (תהלים קמה) צַדִּיק ה' בְּכָל דְּרָכָיו וְחָסִיד בְּכָל מַעֲשָׂיו. צַדִּיק ה' בְּכָל דְּרָכָיו, הֲרֵי שָׁנִינוּ, כַּמָּה יֵשׁ לִבְנֵי אָדָם לְהִתְבּוֹנֵן בִּכְבוֹד רִבּוֹנָם שֶׁלֹּא יִסְטוּ מִדַּרְכָּם הַחוּצָה, שֶׁהֲרֵי בְּכָל יוֹם וָיוֹם הַדִּין תָּלוּי בָּעוֹלָם, מִשּׁוּם שֶׁהָעוֹלָם נִבְרָא וְעוֹמֵד עַל הַדִּין."],[6,"","וְלָכֵן צָרִיךְ אָדָם לְהִשָּׁמֵר מֵחֲטָאָיו, שֶׁלֹּא יֵדַע אֶת הַזְּמַן שֶׁהַדִּין שׁוֹרֶה עָלָיו. יוֹשֵׁב בְּבֵיתוֹ - הַדִּין שׁוֹרֶה עָלָיו. יוֹצֵא מִבֵּיתוֹ הַחוּצָה - הַדִּין שׁוֹרֶה עָלָיו, וְלֹא יֵדַע אִם יָשׁוּב לְבֵיתוֹ וְאִם לֹא. יוֹצֵא לַדֶּרֶךְ - עַל אַחַת כַּמָּה וְכַמָּה, שֶׁהֲרֵי הַדִּין יוֹצֵא כְנֶגְדּוֹ. זֶהוּ שֶׁכָּתוּב (שם פה) צֶדֶק לְפָנָיו יְהַלֵּךְ. מִשּׁוּם כָּךְ צָרִיךְ לְהַקְדִּים וּלְבַקֵּשׁ רַחֲמִים מִלִּפְנֵי הַמֶּלֶךְ כְּדֵי שֶׁיִּנָּצֵל מִן הַדִּין בְּשָׁעָה שֶׁהוּא שׁוֹרֶה בָּעוֹלָם, שֶׁהֲרֵי בְּכָל יוֹם וָיוֹם שׁוֹרֶה הַדִּין בָּעוֹלָם. זֶהוּ שֶׁכָּתוּב וְאֵל זֹּעֵם בְּכָל יוֹם."],[7,"","עֵתָּה יֵשׁ לוֹמַר, הֲרֵי שָׁנִינוּ, וְהִתְעוֹרְרוּ הַחֲבֵרִים, אֵל בְּכָל מָקוֹם חֶסֶד הוּא, כְּמוֹ שֶׁנֶּאֱמַר (דברים י) הָאֵל הַגָּדֹל, וְזֶה אוֹר שֶׁל חָכְמָה עֶלְיוֹנָה, וְאַתָּה אָמַרְתָּ וְאֵל זֹּעֵם בְּכָל יוֹם. עָזַב הַפָּסוּק כָּל אֵלּוּ הַשֵּׁמוֹת וְאָחַז בָּזֶה. אִם כֵּן, לֹא עוֹמְדִים הַדְּבָרִים. וְעוֹד, שֶׁכָּתוּב (ישעיה ט) אֵל גִּבּוֹר, אוֹ שֶׁנַּעֲמִיד אוֹתוֹ בְדִין, אוֹ שֶׁנַּעֲמִיד אוֹתוֹ בְרַחֲמִים."],[8,"","אֶלָּא כָּךְ שָׁמַעְנוּ, הָרְשָׁעִים מְהַפְּכִים רַחֲמִים לְדִין. שֶׁאֵין לְךְ בְּכָל אֵלּוּ כְּתָרִים עֶלְיוֹנִים שֶׁל הַמֶּלֶךְ הַקָּדוֹשׁ שֶׁלֹּא כְלוּלִים רַחֲמִים בְּדִין, וְדִין בְּרַחֲמִים. וְרְשָׁעִים מְהַפְּכִים רַחֲמִים לְדִין."],[9,"","אָמַר לוֹ רַבִּי יְהוּדָה, טוֹב בָּזֶה שֶׁכָּתוּב אֵל גִּבּוֹר, אֶלָּא אֵל זֹּעֵם בְּכָל יוֹם מַהוּ? שֶׁהֲרֵי בְּכָל יוֹם וָיוֹם עוֹמֵד בְּדִין, בֵּין שֶׁבְּנֵי הָעוֹלָם זַכָּאִים, בֵּין שֶׁלֹּא זַכָּאִים. לֹא הָיָה בְיָדוֹ. בָּאוּ וְשָׁאֲלוּ לוֹ לְרַבִּי שִׁמְעוֹן. אָמַר לָהֶם, וַדַּאי אֵל זֹּעֵם בְּכָל יוֹם, וַהֲרֵי בֵּאֲרוּהָ הַחֲבֵרִים, לְעִתִּים הוּא דִּין וּלְעִתִּים הוּא רַחֲמִים. אִם זוֹכִים בְּנֵי הָעוֹלָם, הֲרֵי אֵל עוֹמֵד, וְהוּא חֶסֶד. וְאִם לֹא זוֹכִים, הֲרֵי אֵל עוֹמֵד, וְנִקְרָא גִּבּוֹר, וְעַל זֶה עוֹמֵד בְּכָל יוֹם."]]],[["אֲבָל מִלָּה שַׁפִּיר הוּא, אֵל בְּכָל אֲתַר, נְהִירוּ (רב) דְּחָכְמְתָא עִלָּאָה הוּא, וְקַיְּימָא בְּקִיּוּמֵיהּ בְּכָל יוֹמָא, דִּכְתִּיב, (תהילים נ״ב:ג׳) חֶסֶד אֵל כָּל הַיּוֹם. וְאִלְמָלֵא דְּהַאי אֵל אִתְּעַר בְּעָלְמָא, לָא יָכִיל עָלְמָא לְמֵיקָם אֲפִילּוּ שַׁעֲתָא חֲדָא, מִקַּמֵּי דִּינִין תַּקִּיפִין דְּמִתְעֲרִין בְּעָלְמָא בְּכָל יוֹמָא, הֲדָא הוּא דִכְתִיב, (בראשית ב׳:ד׳) אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם, אַל תִּקְרֵי בְּהִבָּרְאָם, אֶלָּא בְּאַבְרָהָם, בְּאִתְעָרוּתָא דְּאַבְרָהָם קַיְימֵי, וְכַד אִתְּעַר אַבְרָהָם בְּעָלְמָא, כָּל אִינּוּן דִּינִין דְּמִשְׁתַּכְּחֵי בְּכָל יוֹמָא וְיוֹמָא דָּחֵי לְהוּ לְבַר, וְלָא קַיְימִין קַמֵּיהּ.","הֲדָא הוּא דִכְתִיב, וְאֵל זוֹעֵם בְּכָל יוֹם, נִזְעָם, אוֹ זְעוּם בְּכָל יוֹם, לָא כְּתִיב, אֶלָּא זוֹעֵם. בְּכָל יוֹמָא וְיוֹמָא דְּדִינָא אִשְׁתְּכַח, דָּחֵי לוֹן לְבַר, וְקַיְּימָא הוּא וּמְבָסֵּם עָלְמָא, הֲדָא הוּא דִכְתִיב, (תהילים מ״ב:ט׳) יוֹמָם יְצַוְּה יְיָ' חַסְדּוֹ. וְאִלְמָלֵא הַאי, לָא יָכִיל עָלְמָא לְמֵיקָם אֲפִילוּ רִגְעָא חֲדָא. וְעַל דָּא כֹּלָּא קַיְימוּ בְּגִינֵיהּ דְּאַבְרָהָם.","וְהַאי דִּכְתִּיב אֵל גִּבּוֹר, לָאו דְּאִיהוּ גִּבּוֹר, אֶלָּא הַאי קְרָא רֶמֶז הוּא דְּקָא רָמִיז לַאֲבָהָן, וּרְמִיזָא הוּא דְּקָא רָמִיז לִמְהֵימְנוּתָא עִלָּאָה קַדִּישָׁא, דִּכְתִּיב (ישעיהו ט׳:ה׳) פֶּלֶא יוֹעֵץ אֵל גִּבּוֹר אֲבִי עַד שַׂר שָׁלוֹם. פֶּלֶא, דָּא חָכְמְתָא עִלָּאָה, דְּהִיא פְּלִיאָה וְאִתְכַּסְיָא מִכֹּלָּא, כְּמָה דְאַתְּ אָמֵר (דברים י״ז:ח׳) כִּי יִפָּלֵא מִמְּךָ דָּבָר. יוֹעֵץ, דָּא הוּא נָהָר עִלָּאָה דְּנָגִיד וְנָפִיק, וְלָא פָּסְקָא, וְדָא יוֹעֵץ לְכֹלָּא, וְאַשְׁקֵי לְכֹלָּא. אֵל דָּא אַבְרָהָם, כְּמָה דְּאוֹקִימְנָא הָאֵל הַגָּדוֹל. גִּבּוֹר, דָּא יִצְחָק, דִּכְתִּיב הַגִּבּוֹר. אֲבִי עַד, דָּא יַעֲקֹב, דְּאָחִיד לְהַאי סִטְרָא וּלְהַאי סִטְרָא, וְקַיְּימָא בְּקִיּוּמָא שְׁלִים. שַׂר שָׁלוֹם, דָּא צַדִּיק, דְּאִיהוּ שְׁלָמָא דְּעָלְמָא, שְׁלָמָא דְּבֵיתָא, שְׁלָמָא דְּמַטְרוֹנִיתָא.","אָתוּ רִבִּי חִזְקִיָּה וְרִבִּי יְהוּדָה, וְנַשְּׁקוּ יְדוֹי. בָּכוּ, וְאָמְרוּ זַכָּאָה חוּלָקָנָא, דְּשָׁאִילְנָא הַאי. זַכָּאָה הוּא דָּרָא, דְּאַתְּ שָׁארֵי בְּגַוַויְיהוּ.","אָמַר רִבִּי שִׁמְעוֹן, כְּתִיב. זֶה קָרְבַּן אַהֲרֹן וּבָנָיו אֲשֶׁר יַקְרִיבוּ לַיְיָ'. תָּא חֲזֵי, חַיָּיבֵי עָלְמָא, גַּרְמִין לֵיהּ לְּקוּדְשָׁא בְּרִיךְ הוּא, לְאִסְתַּלְּקָא מִכְּנֶסֶת יִשְׂרָאֵל. הֲדָא הוּא דִכְתִיב, (משלי ט״ז:כ״ח) אִישׁ תַּהְפּוּכוֹת יְשַׁלַּח מָדוֹן וְנִרְגָּן מַפְרִיד אַלּוּף. מַאן הוּא אַלּוּף. דָּא קוּדְשָׁא בְּרִיךְ הוּא (דאיהו אלופו של עולם), כְּמָה דְאַתְּ אָמֵר, (ירמיהו ג׳:ד׳) אַלּוּף נְעוּרַי אָתָּה. וְאִינּוּן (חייבי) מַפְרִישִׁין לְזֹאת מִזֶּה, דְּאִיהוּ שְׁלָמָא דְּבֵיתָא, וְאִינּוּן זִוּוּגָא חֲדָא.","אָתָא אַהֲרֹן קַדִּישָׁא וּבְנוֹי, וְעַל יְדַיְיהוּ מִתְקָרְבִין תַּרְוַויְיהוּ, וְאִזְדְּוַוג זֶה בְּזֹאת. הֲדָא הוּא דִכְתִיב, (ויקרא ט״ז:ג׳) בְּזֹאת יָבֹא אַהֲרֹן אֶל הַקֹּדֶשׁ. זֶה קָרְבָּן אַהֲרֹן וּבָנָיו. וְאִינּוּן מְזַוְּוגֵי לְמַלְכָּא קַדִּישָׁא עִלָּאָה בְּמַטְרוֹנִיתָא, וְעַל יְדַיְיהוּ מִתְבָּרְכָאן עִלָּאִין וְתַתָּאִין, וּמִשְׁתַּכְחִין בִּרְכָאן בְּכֻלְּהוּ עָלְמִין, וְאִשְׁתְּכַח כֹּלָּא חַד בְּלָא פִּרוּדָא.","וְאִי תֵּימָא, אֲמַאי לָא כְּתִיב זֹאת קָרְבָּן, לְקָרְבָא זֹאת לְאַתְרֵיהּ. לָאו הָכֵי, דְּהָא כַּהֲנָא מֵעֵילָּא קָא שָׁרֵי לְאַיְיתָאָה זִוּוּגָא לָהּ לִכְנֶסֶת יִשְׂרָאֵל, עַד דְּמָטֵי לְהַאי זֶה, לְאִזְדַּוְּוגָא בְּזֹאת וּלְקָרְבָא לוֹן כַּחֲדָא. וּבְגִין כָּךְ כַּהֲנָא אַשְׁלִים קָרְבְּנָא וְקָרִיב זִוּוּגָא, זַכָּאָה חוּלָקֵיהוֹן בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי.","רִבִּי חִיָּיא וְרִבִּי יוֹסֵי הֲווֹ אָזְלֵי מֵאוּשָׁא לִטְבֶרְיָה, אָמַר רִבִּי חִיָּיא, כְּתִיב (תהילים קל״ב:י״ד) כִּי בָחַר יְיָ' בְּצִיּוֹן וְגוֹ'. זֹאת מְנוּחָתִי וְגוֹ', לְזִמְנִין קָרָאן לְהַאי חַבְרַיָּיא כֻּלְּהוּ דְּכוּרָא, בְּגִין דְּאִיהוּ (ס\"א דציון איהו) רַחֲמֵי. וְהָכָא קְרָא נוּקְבָּא קָרָא לֵיהּ.","אָמַר רִבִּי יוֹסֵי, הָכִי שְׁמִיעַ לִי מִבּוּצִינָא קַדִּישָׁא, (אבל) בְּשַׁעֲתָא דְּזִוּוּגָא אִזְדְּוַוג כַּחֲדָא, לְאַחֲזָאָה דְּהָא נוּקְבָּא אִתְכְּלִילַת בֵּיהּ בִּכְלָלָא חֲדָא, אִתְקְרֵי נוּקְבָּא בִּשְׁמָא (דדכורא), דְּהָא כְּדֵין בִּרְכָאן דְּמַטְרוֹנִיתָא אִשְׁתְּכָחוּ, וְלָא הֲוִי בָּהּ פְּרִישׁוּתָא כְּלַל. וְעַל דָּא לְמוֹשָׁב לוֹ כְּתִיב. וּכְתִיב כִּי בָחַר יְיָ' בְּצִיּוֹן, בְּצִיּוֹן דַּיְיקָא, בְּהַהוּא דְּאִית בְּגַוִּיהּ דְּשַׁרְיָא בֵּיהּ, וְלָא כְּתִיב לְצִיּוֹן. וְכֹלָּא חַד, בֵּין דְּקָרָא לְהַאי בִּשְׁמָא דִּדְכוּרָא, וּבֵין דְּקָרָא לְהַאי בִּשְׁמָא דְּנוּקְבָּא כֹּלָּא חַד וּבְדַרְגָּא חַד קַיְימִין.","(פתח רבי יוסי ואמר), וְעַל דָּא כְּתִיב, (תהילים פ״ז:ה׳) וּלְצִיּוֹן יֵאָמֵר אִישׁ וְאִישׁ יוּלַּד בָּהּ. חַד לְדִינָא, וְחַד לְרַחֲמֵי. כַּד מִזְדַּוְּוגֵי כַּחֲדָא בְּזִוּוּגָא חַד, כְּדֵין צִיּוֹן אִקְרֵי, וְצִיּוֹן וִירוּשָׁלַים אִשְׁתְּמוֹדַע, וְאִשְׁתְּכַח דְּדָא בְּדָא תַּלְיָיא."],[[0,"אבל מלה שפיר הוא וכו׳:","אבל התירוץ הטוב הוא, \u0003אל,\u0004 בכל מקום, הוא הארת חכמה עליונה, דהיינו חסד (כנ״ל אות פ״ט), ועמד בקיומו בכל יום, שכתוב, חסד אל כל היום. ולולא השם אל הזה היה מתעורר בעולם, לא היה יכול העולם לעמוד אפילו שעה אחת מפני דינים קשים המתעוררים בעולם בכל יום. ז\"ש, אלה תולדות השמים והארץ בהבראם, אל תקרי בהבראם אלא באברהם, שהוא חסד, כי בהתעוררות אברהם, עומדים שמים וארץ, וכשנתעורר אברהם בעולם, שהוא מדת החסד, כל הדינים הנמצאים בכל יום ויום, דוחה אותם לחוץ ואינם עומדים לפניו."],[1,"הה״ד ואל זועם בכל יום:","נזעם או זעום בכל יום אינו כתוב, אלא זועם, כי בכל יום ויום שהדין נמצא דוחה אותו לחוץ והוא עומד ומבשם העולם, ז״ש יומם יצוה ה׳ חסדו. ולולא זה, לא היה יכול העולם לעמוד אפילו רגע אחד. וע״כ הכל עומד ומתקיים בשביל אברהם, שהוא חסד."],[2,"והאי דכתיב אל גבור וכו׳:","וזה שכתוב, \u0003אל גבור\u0004 אין הפירוש, שהשם אל הוא גבור, אלא מקרא זה, רמז הוא מרמז על האבות שהם חג״ת, ורמז הוא מרמז לאמונה העליונה הקדושה, שהיא בינה, שכתוב, פלא יועץ \u0003אל גבור\u0004 אבי עד שר שלום. \u0003פלא,\u0004 זו היא חכמה העליונה, שהיא פליאה ומכוסה מכל, כמש״א, כי יפלא ממך דבר. אשר פלא, היא לשון העלם. \u0003יועץ,\u0004 זה הוא נהר העליון הנמשך ויוצא ואינו נפסק, שהוא בינה, וזה יועץ לכל ומשקה לכל. כי כל המוחין של זו״ן ובי״ע מבינה יוצאים. \u0003אל,\u0004 זהו אברהם, כמו שהעמדנו, האל הגדול, שהוא חסד. \u0003גבור,\u0004 זה יצחק, שלא כתוב הגבור דהיינו שלא כתוב אל הגבור כמו שכתוב האל הגדול, אלא כתוב אל גבור, שמשמע שגבור אינו סובב על, אל, אלא הוא שם מיוחד, שזה יצחק, דהיינו מדת הגבורה. \u0003אבי עד,\u0004 זה יעקב, שאוחז לצד זה, ימין, ואוחז לצד זה, שמאל ונמצא בקיום השלם. כי אבי עד, הוא לשון שלמות. \u0003שר שלום,\u0004 זה צדיק, דהיינו יסוד, שהוא שלום העולם שלום בית, שלום המלכה."],[3,"אתו ר׳ חזקיה וכו׳:","באו ר׳ חזקיה ור׳ יהודה ונשקו ידיו. בכו ואמרו, אשרי חלקנו ששאלנו זאת. אשרי הוא הדור שאתה שוכן בתוכם."],[4,"אמר ר׳ שמעון וכו׳:","אמר ר״ש, כתוב זה קרבן אהרן ובניו אשר יקריבו לה׳. בוא וראה, רשעי העולם גורמים להקב״ה להסתלק מכנסת ישראל. ז״ש איש תהפוכות ישלח מדון ונרגן מפריד אלוף. מי הוא אלוף. הוא הקב״ה, כש״א, אלוף נעורי, אתה. והם מפרידים \u0003זאת,\u0004 שהיא המלכות מ \u0003זה\u0004 שהוא ז״א, שהוא שלום בית, דהיינו יסוד, והם חבור אחד."],[5,"אתא אהרן קדישא וכו׳:","בא אהרן הקדוש ובניו, ועל ידיהם נתקרבו שניהם, ונזדווג \u0003זה\u0004 שהוא ז״א, ב \u0003זאת\u0004 שהיא מלכות, ז״ש ב \u0003זאת\u0004 יבא אהרן אל הקדש. \u0003זה\u0004 קרבן אהרן ובניו. והם מזווגים מלך הקדוש העליון, שהוא ז״א במטרוניתא, שהיא המלכות, ועל ידיהם מתברכים העליונים והתחתונים, ונמצאות ברכות בכל העולמות. ונמצא הכל אחד בלא פרוד."],[6,"ואי תימא אמאי וכו׳:","ואם תאמר, למה לא כתוב זאת קרבן, שיהיה פירושו, לקרב \u0003זאת\u0004 שהיא המלכות, למקומה שהוא ז״א. ולמה כתוב זה קרבן, שסובב על ז״א, והרי את המלכות אנו צריכים לקרב לז״א, ולא להיפך. ומשיב, אינו כן, כי בשעה שהכהן מקריב הקרבן מלמטה, הרי הכהן מלמעלה, שהוא ספירת החסד, מתחיל להביא החבור לכנסת ישראל, שהיא המלכות, עד שמגיע אל \u0003זה\u0004 ההוא שהוא ז״א, לחבר אותו ב \u0003זאת,\u0004 שהיא המלכות, ולקרב אותם יחד. כלומר, כמו שהכהן למטה מקרב המלכות לז״א, כן כהן שלמעלה מקרב ז״א למלכות. ומשום זה הכהן משלים הקרבן ומקרב הזווג. אשרי חלקם בעולם הזה ובעולם הבא."],[7,"ר׳ חייא ור׳ יוסי וכו׳:","ר״ח ור״י היו הולכים מאושא לטבריא, אמר ר׳ חייא, כתוב, כי בחר ה׳ בציון אוה למושב לו זאת מנוחתי וגו׳ כי אויתיה, שואל, לפעמים קוראים החברים כולם לזה, להשם ציון, בלשון זכר, משום שציון, שהוא יסוד המלכות, הוא רחמים. וכאן המקרא קורא אותו בלשון נקבה, שנאמר אוה למושב לו, וכן כי אויתיה. פירוש. שיש פנימיות וחיצוניות ביסוד המלכות, הפנימיות שהיא רחמים, נקראת \u0003ציון,\u0004 והחיצוניות, שהיא דין נקראת ירושלים."],[8,"אמר ר׳ יוסי וכו׳:","אר״י, כך שמעתי מן המאור הקדוש. בשעה שזווג ז״א ומלכות, נזדווג יחד, הנה כדי להראות שהנוקבא נכללת בז״א, בכלל אחד, נקראת הנוקבא בשם הזכר, כי אז נמצאות הברכות של המלכות ואין בה פירוד כלל. פירוש כי המלכות שהיא נוקבא, היא מטעם שהיא חסרת השלמות, וחסרת השלמות מכונה נקבה. אבל בעת הזווג עם ז״א, היא מלאה ברכות וכל השלמות, וע״כ נבחנת בבחינת זכר. ועל כן כתוב, ל \u0003מושב\u0004 לו, ולא כתוב למושבה, לשון נקבה, כי למושב לו, סובב על זמן הזווג, ואז היא זכר. וכתוב, כי בחר ה׳ בציון, בציון הוא בדיוק, שפירושו בתוך ציון, דהיינו בההוא שיש בתוכה ששורה בה, דהיינו יסוד הפנימי של המלכות, וע״כ לא כתוב לציון, שהיה משמע לחיצוניות שלה. וע״כ הכל אחד בין שקורא לזה בשם זכר, ובין שקורא לזה בשם נקבה, כי הכל אחד ובמדרגה אחת עומדים. שע״כ קורא אותו הכתוב, פעם לשון זכר, דהיינו, למושב לו, ופעם לשון נקבה, דהיינו, כי אויתיה."],[9,"ועל דא כתיב וכו׳:","ועל כן כתוב, ולציון יאמר איש ואיש יולד בה, ב״פ איש, שאיש אחד הוא דין, ואחד הוא רחמים, דהיינו שיש ביסוד המלכות שנקרא ציון, ב׳ בחינות, שהם דין ורחמים, אמנם הדין שבה מכונה ירושלים, אבל כשמזדווגים ז\"א ומלכות יחד בזווג אחד, אז נקרא יסוד המלכות בשם ציון לבד וציון וירושלים נודעות, שציון היא פנימיות היסוד דמלכות, וירושלים היא חיצוניות היסוד דמלכות ונמצא שזה בזה תלוים."]],[[0,"","אֲבָל דָּבָר נָאֶה הוּא, אֵל בְּכָל מָקוֹם זֶהוּ אוֹר (רב) הַחָכְמָה הָעֶלְיוֹנָה, וְעוֹמֵד בְּקִיּוּמוֹ בְּכָל יוֹם, שֶׁכָּתוּב (תהלים נו) חֶסֶד אֵל כָּל הַיּוֹם. וְאִלְמָלֵא שֶׁאֵל הַזֶּה מִתְעוֹרֵר בָּעוֹלָם, לֹא יָכוֹל הָעוֹלָם לַעֲמֹד אֲפִלּוּ שָׁעָה אַחַת מִלִּפְנֵי הַדִּינִים הַקָּשִׁים שֶׁמִּתְעוֹרְרִים בָּעוֹלָם בְּכָל יוֹם. זֶהוּ שֶׁכָּתוּב (בראשית ב) אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם, אַל תִּקְרֵי בְּהִבָּרְאָם אֶלָּא בְּאַבְרָהָם, בַּהִתְעוֹרְרוּת שֶׁל אַבְרָהָם עוֹמְדִים, וּכְשֶׁמִּתְעוֹרֵר אַבְרָהָם בָּעוֹלָם, כָּל אוֹתָם הַדִּינִים שֶׁנִּמְצָאִים בְּכָל יוֹם וָיוֹם, הוּא דּוֹחֶה אוֹתָם הַחוּצָה וְלֹא עוֹמְדִים לְפָנָיו."],[1,"","זֶהוּ שֶׁכָּתוּב וְאֵל זֹּעֵם בְּכָל יוֹם. נִזְעָם אוֹ זָעוּם בְּכָל יוֹם לֹא כָתוּב, אֶלָּא זוֹעֵם. בְּכָל יוֹם וָיוֹם שֶׁנִּמְצָא דִין, דּוֹחֶה אוֹתָם הַחוּצָה, וְהוּא עוֹמֵד וּמְבַשֵּׂם אֶת הָעוֹלָם. זֶהוּ שֶׁכָּתוּב (תהלים מב) יוֹמָם יְצַוֶּה ה' חַסְדּוֹ. וְאִלְמָלֵא זֶה, לֹא יָכוֹל הָעוֹלָם לַעֲמֹד אֲפִלּוּ רֶגַע אֶחָד. וְלָכֵן הַכֹּל עוֹמֵד מִשּׁוּם אַבְרָהָם."],[2,"","וְזְהִ שֶׁכָּתוּב אֵל גִּבּוֹר. לֹא שֶׁהוּא גִּבּוֹר, אֶלָּא הַפָּסוּק הַזֶּה רֶמֶז הוּא שֶׁרוֹמֵז לָאָבוֹת, וְרֶמֶז הוּא שֶׁרוֹמֵז לָאֱמוּנָה הָעֶלְיוֹנָה הַקְּדוֹשָׁה, שֶׁכָּתוּב פֶּלֶא יוֹעֵץ אֵל גִּבּוֹר אֲבִי עַד שַׂר שָׁלוֹם. פֶּלֶא - זוֹ הַחָכְמָה הָעֶלְיוֹנָה שֶׁמֻּפְלָאָה וּמְכֻסֵּית מֵהַכֹּל, כְּמוֹ שֶׁנֶּאֱמַר (דברים יז) כִּי יִפָּלֵא מִמְּךְ דָבָר. יוֹעֵץ - זֶהוּ נָהָר עֶלְיוֹן שֶׁשּׁוֹפֵעַ וְיוֹצֵא וְלֹא פוֹסֵק. וְזֶה יוֹעֵץ לַכֹּל וּמַשְׁקֶה אֶת הַכֹּל. אֵל - זֶה אַבְרָהָם, כְּמוֹ שֶׁבֵּאַרְנוּ הָאֵל הַגָּדוֹל. גִּבּוֹר - זֶה יִצְחָק, שֶׁכָּתוּב הַגִּבּוֹר. אֲבִי עַד - זֶה יַעֲקֹב, שֶׁאוֹחֵז בַּצַּד הַזֶּה וּבַצַּד הַזֶּה וְעוֹמֵד בְּקִיּוּם שָׁלֵם. שַׂר שָׁלוֹם - זֶה צַדִּיק, שֶׁהוּא הַשָּׁלוֹם שֶׁל הָעוֹלָם, שְׁלוֹם הַבַּיִת, שְׁלוֹם הַגְּבִירָה."],[3,"","בָּאוּ רַבִּי חִזְקִיָּה וְרַבִּי יְהוּדָה וְנָשְׁקוּ אֶת יָדוֹ. בָּכוּ וְאָמְרוּ: אַשְׁרֵי חֶלְקֵנוּ שֶׁשָּׁאַלְנוּ אֶת זֶה. אַשְׁרֵי הַדּוֹר שֶׁאַתָּה שָׁרוּי בְּתוֹכוֹ."],[4,"","אָמַר רַבִּי שִׁמְעוֹן, כָּתוּב זֶה קָרְבַּן אַהֲרֹן וּבָנָיו אֲשֶׁר יַקְרִיבוּ לַה'. בֹּא רְאֵה, הָרְשָׁעִים שֶׁל הָעוֹלָם גּוֹרְמִים לַקָּדוֹשׁ בָּרוּךְ הוּא לְהִסְתַּלֵּק מִכְּנֶסֶת יִשְׂרָאֵל. זֶהוּ שֶׁכָּתוּב (משלי טז) אִישׁ תַּהְפֻּכוֹת יְשַׁלַּח מָדוֹן וְנִרְגָּן מַפְרִיד אַלּוּף. מִי הָאַלּוּף? זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא (שהוא אלופו של עולם), כְּמוֹ שֶׁנֶּאֱמַר אַלּוּף נְעוּרַי אָתָּה. וְהֵם (הרשעים) מַפְרִידִים אֶת זֹּאת מִזֶּה, שֶׁהִיא שְׁלוֹם הַבַּיִת, וְהֵם זִוּוּג אֶחָד."],[5,"","בָּא אַהֲרֹן הַקָּדוֹשׁ וּבָנָיו, וְעַל יְדֵיהֶם נִקְרָבִים שְׁנֵיהֶם וּמִזְדַּוְּגִים זֶה עִם זֹּאת. זֶהוּ שֶׁכָּתוּב, בְּזֹּאת יָבֹא אַהֲרֹן אֶל הַקֹּדֶשׁ. זֶה קָרְבַּן אַהֲרֹן וּבָנָיו. וְהֵם מְזַוְּגִים אֶת הַמֶּלֶךְ הַקָּדוֹשׁ הָעֶלְיוֹן בַּגְּבִירָה, וְעַל יְדֵיהֶם מִתְבָּרְכִים עֶלְיוֹנִים וְתַחְתּוֹנִים וְנִמְצָאוֹת בְּרָכוֹת בְּכָל הָעוֹלָמוֹת, וְנִמְצָא הַכֹּל אֶחָד בְּלִי פֵרוּד."],[6,"","וְאִם תֹּאמַר, לָמָּה לֹא כָתוּב זֹּאת קָרְבָּן, לְקָרֵב זֹּאת לִמְקוֹמָהּ? לֹא כָּךְ, שֶׁהֲרֵי הַכֹּהֵן מִמַּעְלָה שׁוֹרֶה לְהָבִיא אֶת הַזִּוּוּג לִכְנֶסֶת יִשְׂרָאֵל, עַד שֶׁמַּגִּיעַ לְזֶה הַזֶּה לְזַוְּגוֹ עִם זֹּאת וּלְקָרְבָם כְּאֶחָד, וְלָכֵן הַכֹּהֵן מַשְׁלִים אֶת הַקָּרְבָּן וּמְקָרֵב אֶת הַזִּוּוּג. אַשְׁרֵי חֶלְקָם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא."],[7,"","רַבִּי חִיָּיא וְרַבִּי יוֹסֵי הָיוּ הוֹלְכִים מֵאוּשָׁא לִטְבֶרְיָה. אָמַר רַבִּי חִיָּיא, כָּתוּב (תהלים קלב) כִּי בָחַר ה' בְּצִיּוֹן וְגוֹ'. זֹּאת מְנוּחָתִי וְגוֹ'. לִפְעָמִים קוֹרְאִים אֶת זֶה כָּל הַחֲבֵרִים זָכָר, מִשּׁוּם שֶׁהוּא (שציון הוא) רַחֲמִים, וְכָאן הַכָּתוּב קוֹרֵא אוֹתוֹ נְקֵבָה."],[8,"","אָמַר רַבִּי יוֹסֵי, כָּךְ נִשְׁמָע לִי מֵהַמְּנוֹרָה הַקְּדוֹשָׁה, (אבל) בְּשָׁעָה שֶׁהַזִּוּוּג מִזְדַּוֵּג כְּאֶחָד לְהַרְאוֹת שֶׁהַנְּקֵבָה נִכְלֶלֶת בּוֹ בִּכְלָל אֶחָד, הַנְּקֵבָה נִקְרֵאת בְּשֵׁם (הזכר), שֶׁהֲרֵי אָז נִמְצָאוֹת הַבְּרָכוֹת שֶׁל הַגְּבִירָה וְאֵין בָּהּ פְּרִישׁוּת כְּלָל, וְעַל כֵּן כָּתוּב לְמוֹשָׁב לוֹ. וְכָתוּב כִּי בָחַר ה' בְּצִיּוֹן, בְּצִיּוֹן בְּדִיּוּק, בְּאוֹתוֹ שֶׁיֵּשׁ בְּתוֹכוֹ שֶׁשּׁוֹרֶה בּוֹ, וְלֹא כָתוּב לְצִיּוֹן, וְהַכֹּל אֶחָד. בֵּין שֶׁקּוֹרֵא לָזֶה בְּשֵׁם שֶׁל זָכָר, וּבֵין שֶׁקּוֹרֵא לָזֶה בְּשֵׁם שֶׁל נְקֵבָה, הַכֹּל אֶחָד וְעוֹמְדִים בְּדַרְגָּה אַחַת."],[9,"","(פתח רבי יוסי ואמר,) וְעַל זֶה כָּתוּב, (שם פז) וּלְצִיּוֹן יֵאָמֵר אִישׁ וְאִישׁ יוּלַד בָּהּ. אֶחָד לְדִין, וְאֶחָד לְרַחֲמִים. כְּשֶׁמִּזְדַּוְּגִים כְּאֶחָד בְּזִוּוּג אֶחָד, אָז נִקְרָא צִיּוֹן, וְצִיּוֹן וִירוּשָׁלַיִם יְדוּעִים, וְנִמְצָא שֶׁזֶּה תָלוּי בָּזֶה."]]],[["פָּתַח רִבִּי יוֹסֵי וְאָמַר, כְּתִיב (ויקרא כ׳:ז׳) וְהִתְקַדִּשְׁתֶּם וִהְיִיתֶם קְדוֹשִׁים. מַאן דִּמְקַדֵּשׁ גַּרְמֵיהּ מִלְּרַע, מְקַדְּשִׁין לֵיהּ מִלְעֵילָּא. מַאן דְּמַסְאִיב גַּרְמֵיהּ מִלְּרַע, מְסָאֲבִין לֵיהּ מִלְעֵילָּא. מְקַדְּשִׁין לֵיהּ מִלְעֵילָּא יָאוּת, דְּהָא קְדוּשָּׁה דְּמָארֵיהּ שַׁרְיָא עָלֵיהּ, אֲבָל מְסָאֲבִין לֵיהּ מֵאָן אֲתַר. וְאִי תֵּימָא מִלְּעֵילָּא, וְכִי מְסָאֲבוּתָא שַׁרְיָא לְעֵילָּא.","אָמַר רִבִּי חִיָיא, הַיְינוּ דְּתָנֵינָן, בְּעוֹבָדָא דִּלְתַּתָּא אִתְּעַר עוֹבָדָא לְעֵילָּא. אִי עוֹבָדָא דִּלְתַּתָּא הִיא בִּקְדוּשָּׁה, אִתְּעַר קְדוּשָּׁה לְעֵילָּא, וְאָתֵי וְשַׁרְיָא עָלֵיהּ, וְאִתְקַדָּשׁ בֵּיהּ. וְאִי אִיהוּ אִסְתְּאַב לְתַתָּא, אִתְּעַר רוּחַ מִסְאֲבוּתָא לְעֵילָּא, וְאָתֵי וְשַׁרְיָא עָלֵיהּ, וְאִסְתְּאַב בֵּיהּ. דְּהָא בְּעוֹבָדָא תַּלְיָא מִלְּתָא.","דְּהָא לֵית לָךָ טַב וּבִישׁ, קְדוּשָּׁא וּמְסָאֲבוּתָא, דְּלֵית לֵיהּ עִקָרָא וְשָׁרְשָׁא לְעֵילָּא. וּבְעוֹבָדָא דִּלְתַּתָּא אִתְּעַר עוֹבָדָא דִּלְעֵילָּא, מַה דְּתָלֵי בְּעוֹבָדָא, בְּעוֹבָדָא אִתְּעַר לְעֵילָּא, וְאִתְעָבִיד עוֹבָדָא. וּמַה דְּתָלֵי בְּמִלִּין, בְּמִלִּין. כַּד אִתְגְּזַר בְּמִלָּה, אִתְּעַר הָכִי לְעֵילָּא.","וְאִי תֵּימָא, מִלָּה מַה אִתְּעַר. אֶלָּא הָכִי כְּתִיב, (ישעיה נח) וְדַבֵּר דָּבָר. הַהוּא דָּבַר, אִתְּעַר מִלָּה אָחֳרָא לְעֵילָּא, דְּאִקְרֵי דָּבָר. (הושע א) דְּבַר יְיָ' אֲשֶׁר הָיָה. (שמואל א, ג) וּדְבַר יְיָ' הָיָה יָקָר. (תהילים ל״ג:ו׳) בִּדְבַר יְיָ' שָׁמַיִם נַעֲשׂוּ. דְּהָא תָּנֵינָן, הַהִיא מִלָּה סַלְּקָא, וּבָקַע רְקִיעִין, עַד דְּסַלְּקָא (ס\"א דאתיישבא) בְּדוּכְתֵּיהּ, וְאִתְּעַר מַה דְּאִתְּעַר, אִי טַב, טַב. אִי בִּישׁ, בִּישׁ. וְעַל דָּא כְּתִיב, (דברים כ״ג:י׳) וְנִשְׁמַרְתָּ מִכֹּל דָּבָר רָע.","ד' מִינִין בַּלוּלָב, וְאִינּוּן שִׁבְעָה. וְאִי תֵּימָא דְּז' מִינִין אִינּוּן. לָאו הָכֵי, אֶלָּא אַרְבְּעָה נִינְהוּ וְאִינּוּן מִתְפָּרְשִׁין לִתְלָתָא אוֹחֲרָנִין. וּבְעוֹבָדָא דִּלְהוֹן אִתְּעֲרוּ שִׁבְעָה אָחֳרָנִין לְעֵילָּא, לְאוֹטָבָא עָלְמָא בְּכַמָּה סִטְרִין.","כְּנֶסֶת יִשְׂרָאֵל, אַף עַל גַּב דְּאִיהִי בִּכְלָלָא, מִתְבָּרְכָא מְכֻּלְּהוּ שִׁית, (ס\"א ולאתברכא מאינון שית) וּמִנַּחֲלָא דַּעֲמִיקָא דְּמַבּוּעָא, דְּנָגִיד וְלָא פָּסִיק לְעָלְמִין מֵימוֹי דְּנַגְדָא (ס\"א מלנגדא) עָלַיְיהוּ, וְיַנְקָא לְבַת. דְּהָא בְּגִין דְּאִיהִי בַּת לָהּ לְעָלְמָא עִלָּאָה וְתַתָּאָה, אִתְבָּרְכָא מִנַּיְיהוּ בְּאִתְעָרוּתָא דָּא. דְּהָא בְּשַׁעֲתָא דִּכְנֶסֶת יִשְׂרָאֵל אִתְבָּרְכָא מִנַּיְיהוּ, כֻּלְּהוּ עָלְמִין אִתְבָּרְכָן. עַל דָּא סוֹבְבִים אֶת הַמִּזְבֵּחַ כְּמָה (כ\"ד ע\"ב) דְּאִתְּמַר.","וְעוֹד בְּאִתְּעָרוּתָא דָּא, שִׁיתָא כֻּלְּהוּ מִתְבָּרְכָא בְּמַיָּא, לְאִסְתַּפְּקָא בֵּיהּ, וְאִשְׁתַּאֲבִין כֻּלְּהוּ מִמַּבּוּעָא דְּיֵינָא (ס\"א דימא) (דמיא) (ס\"א דנחלא) עֲמִיקָא דְּכֹלָּא, לְנַחְתָּא לְעָלְמָא. וּבְגִין כָּךְ, בַּעְיָין כֻּלְּהוּ לַחִין וְלָא יְבֵשִׁין, לְאַמְשָׁכָא בִּרְכָאן לְעָלְמָא, בְּגִין דְּאִילָנֵי אִלֵּין, כֻּלְּהוּ לַחִין תְּדִירָא, וְטַרְפִּין דִּלְהוֹן מִשְׁתַּכְּחִין תְּדִירָא, וּזְמַן חֶדְוָותָא דִּלְהוֹן בְּהַאי זִמְנָא.","וְתָנֵינָן בְּסִפְרָא דְּרַב הַמְנוּנָא סָבָא, דְּהָא הַהוּא חֵילָא דְּאִתְפָּקְּדָא עַל אִילָנִין אִלֵּין, כָּל חַד וְחַד מֵאִלֵּין, לָא נָטִיל בִּרְכָאן דְּחֶדְוְותָא לְעֵילָּא, אֶלָּא בְּזִמְנָא דָּא. וְחֶדְוָותָא דִּלְהוֹן כֻּלְּהוּ לְעֵילָּא, וְחֶדְוָותָא דְּאִילָנִין אִלֵּין לְתַתָּא, כֻּלְּהוּ בְּזִמְנָא דָּא הוּא. וְאִתְּעֲרוּתָא דִּלְהוֹן בְּאִינּוּן קַדִּישֵׁי מַלְכָּא תַּלְיָין. וְכַד יִשְׂרָאֵל נַטְלֵי לוֹן, כֹּלָּא אִתְּעַר בְּזִמְנָא דָּא, וְעָלְמָא מִתְבָּרְכָא, (ס\"א לכנסת ישראל מתברכא) לְאַרְקָא בִּרְכָאן לְעָלְמָא.","כְּתִיב (תהילים כ״ט:ג׳) קוֹל יְיָ' עַל הַמָּיִם אֵל הַכָּבוֹד, אָמַר רִבִּי יוֹסֵי, דָּא אַבְרָהָם. קוֹל יְיָ' בַּכֹּחַ: דָּא יִצְחָק. קוֹל יְיָ' בֶּהָדָר: דָּא יַעֲקֹב. קוֹל יְיָ' שׁוֹבֵר אֲרָזִים: דָּא נֶצַח. קוֹל יְיָ' חוֹצֵב לַהֲבוֹת אֵשׁ: דָּא הוֹד. קוֹל יְיָ' יָחִיל מִדְבָּר: דָּא צַדִּיק. קוֹל יְיָ' יְחוֹלֵל אַיָּלוֹת: דָּא צֶדֶק. וְכֻלְּהוּ מִתְגַּדְּלֵי עַל יַמָּא (מיא) וְאִתְשַּׁקְיָין בְּמַיָּא, לְגַדְּלָא. הֲדָא הוּא דִכְתִיב, (בראשית ב׳:י׳) וְנָהָר יוֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן. וְכֻלְּהוּ הָנֵי מִתְעָרֵי בִּרְכָאן לְעָלְמָא, מֵהַהוּא שַׁקְיוּ, דְּאִתְּשַׁקְיָין כֻּלְּהוּ.","תָּא חֲזֵי, הָנֵי שֶׁבַע קָלִין, תַּלְיָין בְּמִלָּה דְּפוּמָא בִּשְׁאָר יוֹמֵי שַׁתָּא, וְהַשְׁתָּא, לָא תַּלְיָין אֶלָּא בְּעוֹבָדָא, וַאֲנָן עוֹבָדָא קָא בָּעֵינָן, וְלָא מִלָּה. בְּגִין דִּבְזִמְנָא דָּא, מְבָרֵךְ לְכָל שַׁתָּא.","בְּיוֹמָא שְׁבִיעָאָה דְּחָג, הוּא סִיּוּמָא דְּדִינָא דְּעָלְמָא, וּפִתְקִין נָפְקִין מִבֵּי מַלְכָּא, וּגְבוּרָן מִתְעָרֵי וּמִסְתַּיְּימָן בְּהַאי יוֹמָא, וְעַרְבֵי נַחַל (תליין) בְּהוּ. וּבָעֵינָן לְאִתְּעָרָא גְּבוּרָן לְמַיָּא. וּלְסַחֲרָא ז' זִמְנִין, לְרַוָואָה לְהַאי מִזְבֵּחַ, מִמַּיָּא דְּיִצְחָק, בְּגִין דְּאִתְמַלְיָא מַיָּא הַאי בֵּירָא דְּיִצְחָק, וְכַד הוּא אִתְמַלְּיָא, כָּל עָלְמָא אִתְבָּרְכָא בְּמַיָּא."],[[0,"פתח ר׳ יוסי וכו׳:","פר״י ואמר, כתוב, והתקדשתם והייתם קדושים. מי שמקדש עצמו מלמטה, מקדשים אותו מלמעלה. מי שמטמא עצמו מלמטה מטמאים אותו מלמעלה. שואל, מקדשים אותו מלמעלה, יפה הוא. שפירושו, שקדושת אדונו שורה עליו, אבל מטמאים אותו, מאיזה מקום מטמאים אותו, ואם תאמר, \u0003מלמעלה,\u0004 וכי יש טומאה למעלה."],[1,"אמר ר' חייא וכו':","אר\"ח, היינו שלמדנו, במעשה שלמטה מתעורר מעשה למעלה, אם המעשה שלמטה הוא בקדושה, מתעוררת קדושה מלמעלה ובאה ושורית על האדם ומתקדש בו. ואם הוא מטמא עצמו מלמטה, מתעורר רוח הטומאה מלמעלה, ובא ושורה עליו ונטמא בו. כי במעשה של האדם תלוי הדבר."],[2,"דהא לית לך וכו':","כי אין לך טוב ורע, קדושה וטומאה, שלא יהיה לו עיקר ושורש למעלה, ובמעשה של מטה מתעורר מעשה שלמעלה, מה שתלוי במעשה, מתעורר למעלה ונעשה מעשה. ומה שתלוי בדיבור, הוא בדבור, כי כשנגזר דבור למטה, מתעורר כך למעלה."],[3,"ואי תימא מלה וכו':","ואם תאמר, דבור, מהו שמתעורר למעלה. ומשיב, אלא כך כתוב, \u0003ודבר דבר,\u0004 דבור ההוא מעורר דבור אחר למעלה שנקרא דבר, דהיינו המלכות, כמ\"ש, \u0003דבר\u0004 ה' אשר היה. ו \u0003דבר\u0004 ה' היה יקר. ב \u0003דבר\u0004 ה' שמים נעשו, שכל אלו רומזים על המלכות הנקראת דבר. כי למדנו דבור ההוא של האדם עולה ובוקע רקיעים עד שעולה במקומו, ומעורר מה שמעורר, אם טוב, טוב. ואם רע, רע. דהיינו או שמעורר המלכות דקדושה להשפיע עליו, או שמעורר מלכות דטומאה להשפיע עליו. ועל כן כתוב, ונשמרת מכל דבר רע."],[3,"","ונתבאר, שהן מעשה והן דבור שהאדם עושה ומדבר למטה, אם הם מצוות, הוא מושך קדושה מלמעלה, דהיינו ממלכות, ואם הם חטאים, הוא מושך טומאה מלמעלה. וההפרש בין מעשה לדבור, הוא כי ע\"י מצוות התלויות במעשה, מעורר ומושך מחיצוניות המלכות, ששם בחינת מעשה. וע\"י מצוות התלויות בדבור, מעורר ומושך מפנימיות המלכות, ששם בחינת דבור."],[4,"ארבעה מינין בלולב וכו':","ד' מינים יש בלולב, והם שבעה, דהיינו ג' הדסים, וב' ערבות, ולולב, ואתרוג. ואם תאמר שהם ז' מינים. אינו כן, אלא הם ד' מינים, והם נחלקים לג' אחרים, כי ההדס נחלק לשלשה, והערבות לשנים, ונתוספו שנים על ההדס, ואחד על הערבות, וע\"כ הם ז'. ובהמעשה שלהם, דהיינו בנטילתם לשם מצוה, מתעוררים שבעה אחרים למעלה, שהם ז\"ס חג\"ת נהי\"ם, ג' הדסים נגד חג\"ת, וב' ערבות נגד נו\"ה, ולולב יסוד, ואתרוג מלכות, להטיב העולם בכמה בחינות. המושפעות מז' ספירות הנ\"ל."],[5,"כ\"י אע\"ג דאיהי וכו':","כנסת ישראל, שהיא המלכות, אע\"פ שהיא בכלל ז' הספירות, היא מתברכת מן כל שש הספירות שלמעלה ממנה, שהם חג\"ת נה\"י, ומהנחל העמוק שהמבוע נמשך, ומימיו אינם נפסקים לעולם מלהמשך עליהם, על ו' ספירות חג\"ת נה\"י, והיא יונקת את הבת, שהיא מלכות, כי משום שהיא בת לה, לעולם העליון, שהוא בינה, ולעולם התחתון, שהוא ז\"א, היא מתברכת מהם בהתעוררות הזו. כי בשעה שכנסת ישראל מתברכת מהם, כל העולמות מתברכים, שמקבלים ממנה, וע\"כ סובבים את המזבח, כמו שלמדנו. בז' ימי סוכות, כי המזבח, הוא כנגד המלכות, המקבלת מבינה ומז\"א כנ\"ל. ובז' הקפות ממלאים אותה בז' ספירות."],[6,"ועוד באתערותא דא וכו':","ועוד כי בהתעוררות הזו, של נטילת ד' מינים, מתברכות כל שש הספירות חג\"ת נה\"י, במים, דהיינו בשפע, להסתפק בו, ושואבים כולם, ממבוע הנחל העמוק מכל, שהוא בינה, להוריד לעולם. וע\"כ צריכים כל ד' מינים, להיות לחים ולא יבשים, כי לחים רומזים שהם מלאי שפע להמשיך ברכות לעולם. כי אילנות אלו, הדס וערבה ולולב, כולם לחים תמיד, והעלים שלהם נמצאים תמיד, באילן בין בקיץ ובין בחורף, וזמן שמחתם הוא בזמן ההוא, של ז' ימי סוכות."],[7,"ותנינן בספרא דרב וכו':","ולמדנו בספרו של רב המנונא סבא, כי הכח ההוא שנתמנה על האילנות האלו, של ד' מינים, כל אחד ואחד מאלו, אינו לוקח ברכות של שמחה למעלה, אלא בזמן ההוא. והשמחה של כולם למעלה, והשמחה של אילנות אלו למטה, היא כולה בזמן הזה, של ימי הסוכות. והתעוררות שלהם תלויה באלו קדושי המלך, דהיינו בנטילת לולב של ישראל, וכשישראל נוטלים אותם, הכל מתעורר בזמן הזה, והעולם שהוא המלכות, מתברך להוריק ברכות אל עולם הזה."],[8,"כתיב קול ה' וגו':","כתוב קול ה' על המים אל הכבוד, א\"ר יוסי זהו אברהם, דהיינו מדת החסד. קול ה' בכח, זהו יצחק דהיינו גבורה. קול ה' בהדר, זהו יעקב שהוא תפארת. קול ה' שובר ארזים, זהו נצח. קול ה' חוצב להבות אש, זהו הוד. קול ה' יחיל מדבר, זה צדיק, שהוא יסוד. קול ה' יחולל אילות, זהו צדק, דהיינו מלכות. וכולם גדלים על הים, שהוא בינה, ומושקים במים, דהיינו, בשפע בינה, להתגדל. ז\"ש, ונהר יוצא מעדן להשקות את הגן. ואלו כולם מעוררים ברכות לעולם, משקוי ההוא שהשקו כולם."],[9,"ת\"ח הני שבע וכו':","בוא וראה אלו שבעה קולות, שהם חג\"ת נהי\"מ, תלוים בדבורי הפה בכל ימות השנה, ועתה, בז' ימי סוכות, אינם תלוים אלא במעשה, ואנו צריכים למעשה, ולא לדבור, משום שבזמן הזה, דז' ימי הסוכות, מברך לכל השנה."],[9,"","פירוש. כי מצוות התלויות בדבור ממשיכות פנימיות, שהוא סוד חסדים, אבל אינן ממשיכות הארת חכמה מקו שמאל, להיותה חיצוניות. ומצוות התלויות במעשה ממשיכות חיצוניות, דהיינו הארת חכמה מקו שמאל. שהוא מוחין דו\"ק וחיצוניות. ובז' ימי סוכות אנו צריכים לתקן את החיצוניות, שה\"ס המשכת החכמה משמאל, וע\"כ אנו צריכים למצוות מעשיות המסוגלות לעורר זאת. וז\"ש, \u0003והשתא לא תליין אלא בעובדא, ואנן עובדא קא בעינן,\u0004 כדי להמשיך תקון החיצוניות שה\"ס הארת החכמה שמשמאל, \u0003ולא מלה,\u0004 כי הדבור ממשיך רק פנימיות, שה\"ס חסדים, שאת זה אנו ממשיכין בכל ימות השנה, וז\"ש, \u0003הני שבע קלין תליין במלה דפומא בשאר יומי שתא\u0004 ואינם צריכים למעשה. והוא מטעם, \u0003בגין דבזמנא דא,\u0004 דז' ימי סוכות, \u0003מברך לכל שתא,\u0004 כי אחר שהמשכנו הארת החכמה שבשמאל בז' ימי הסוכות, לחג\"ת נהי\"מ, מספיק זה לכל ימות השנה, באפן, שהחסדים שאנו ממשיכים ע\"י מצות התלויות בדבור בכל ימות השנה, מתברכים בהארת החכמה מז' ימי הסוכות, והם נעשים בזה לחסדים מגולים, ואין צריכים יותר למצוות התלויות במעשה, לענין הזה, אלא לשאר דברים, כמ\"ש במקומו."],[10,"ביומא שביעאה דחג וכו':","ביום השביעי של החג, דהיינו בהושענא רבא, הוא סיום הדין של העולם, ופסקי הדינים יוצאים מבית המלך, והגבורות מתעוררות ומסתיימות ביום ההוא. וערבי נחל תלוים בהם, בגבורות אלה. וצריכים לעורר הגבורות למים, ולהקיף ז' פעמים, כנגד חג\"ת נהי\"מ, את המזבח, שהוא כנגד המלכות, כדי להרוות את המזבח במים של יצחק, דהיינו בהארת החכמה שמקו שמאל הנקרא יצחק. כדי שהמים ימלאו את בארו של יצחק, דהיינו המלכות, שבשעה שמקבלת משמאל, נקראת כך. וכשהיא מתמלאת מתברך כל העולם במים."],[10,"","פירוש. כי ג' ספרים נפתחים בראש השנה, (כמ\"ש בזהר אמור דף ק' ע\"ב ד\"י) שהם של צדיקים גמורים ושל רשעים גמורים ושל בינונים צדיקים גמורים נכתבים לאלתר לחיים. רשעים גמורים נכתבים לאלתר למיתה ובינונים תלוים ועומדים עד יום הכפורים (רה\"ש ט\"ז:) והנה מצדיקים גמורים ורשעים גמורים אין מדובר בהם, כי כבר נגמר דינם ביום א' של ראש השנה. וכל המדובר הוא בבינונים. שהם תלוים ועומדים עד יום הכפורים, אם עושים תשובה נחתמים לחיים, והרשעים שאינם עושים תשובה נחתמים למיתה. וסוד כפרת עונות שביוה\"כ, ה\"ס המשכת הארת חכמה ע\"י עלית המלכות לבינה, שאין כפרת העונות אלא ע\"י גילוי אור החכמה, וה\"ס אור החיים. וע\"כ הבינונים שעשו תשובה זוכים אז לכפרת עונות, ולחתימה לחיים. אמנם עוד לא נגמר הדבר בשלמות, כי אור החכמה אינו מאיר בלי חסדים, וזמן המשכת החסדים להלבשת החכמה, הוא בז' ימי סוכות, ונמצא שביום השביעי, הושענא רבה, נגמרה התלבשות החכמה בחסדים, ואז נשלמת החתימה לחיים שנעשתה ביום הכפורים. ועד\"ז לאותם שלא עשו תשובה ונחתמו למיתה ביום הכפורים, עוד לא נגמרה לגמרי החתימה, כי יש להם זמן לשוב, עד יום הז' של סוכות, כי עד אותו זמן נמשכת עוד החכמה, (כנ\"ל באות קי\"ג) ואם ישובו, יתכפרו עונותיהם על ידה, ויזכו לאור החיים. וע\"כ נבחן יום הושענא רבה ליום של מסירת פסקי דינים למלאכים, אם לחיים ואם למות, כי לאחר שנמסרו פסקי הדינים למוציאים לפועל, כבר אין מחזירים אותם. והוא משום כי אחר יום הושענא רבא, אין עוד המשכת חכמה. כנ\"ל (אות קי\"ג)."],[10,"","וז\"ש \u0003ביומא שביעאה דחג הוא סיומא דדינא,\u0004 מחמת שאחר כך אין עוד המשכת חכמה, וע\"כ, \u0003ופתקין נפקין מבי מלכא,\u0004 שנמסרים למוציאים לפועל, ואין מחזירים אותם יותר. \u0003וגבורן מתערי ומסתיימן בהאי יומא,\u0004 כי הגבורות, שה\"ס המשכת החכמה, מסתיימת ביום הזה, ואין ממשיכים חכמה לאחר כך, (כנ\"ל אות קי\"ג) והשאר מבואר."]],[[0,"","פָּתַח רַבִּי יוֹסֵי וְאָמַר, כָּתוּב (ויקרא ב) והתקדשתם והייתם קדשים. מי שמקדש את עצמו מלמטה, מקדשים אותו מלמעלה. ומי שמטמא את עצמו מלמטה, מטמאים אותו מלמעלה. מקדשים אותו מלמעלה - נאה, שהרי קדשת רבונו שורה עליו, אבל מטמאים אותו מאיזה מקום? ואם תאמר מלמעלה, וכי טמאה שורה מלמעלה?"],[1,"","אָמַר רַבִּי חִיָּיא, זֶה שֶׁשָּׁנִינוּ, בַּמַּעֲשֶׂה שֶׁלְּמַטָּה מִתְעוֹרֵר מַעֲשֶׂה שֶׁלְּמַעְלָה. אִם הַמַּעֲשֶׂה שֶׁלְּמַטָּה בִּקְדֻשָּׁה, מִתְעוֹרֶרֶת קְדֻשָּׁה לְמַעְלָה, וּבָאָה וְשׁוֹרָה עָלָיו וּמִתְקַדֵּשׁ בָּהּ. וְאִם הוּא מִטַּמֵּא לְמַטָּה, מִתְעוֹרֶרֶת רוּחַ טֻמְאָה מִלְמַעְלָה, וּבָאָה וְשׁוֹרָה עָלָיו וְנִטְמָא בָּהּ, שֶׁהֲרֵי הַדָּבָר תָּלוּי בְּמַעֲשֶׂה."],[2,"","שֶׁהֲרֵי אֵין לְךְ טוֹב וָרָע, קְדֻשָּׁה וְטֻמְאָה, שֶׁאֵין לָהֶם עִקָּר וְשֹׁרֶשׁ לְמַעְלָה, וּבַמַּעֲשֶׂה שֶׁלְּמַטָּה מִתְעוֹרֵר מַעֲשֶׂה שֶׁלְּמַעְלָה. מַה שֶׁתָּלוּי בְּמַעֲשֶׂה, בְּמַעֲשֶׂה מִתְעוֹרֵר לְמַעְלָה וְנַעֲשֶׂה מַעֲשֶׂה. וּמַה שֶּׁתָּלוּי בִּדְבָרִים, בִּדְבָרִים. כְּשֶׁנִּגְזַר בַּדָּבָר, מִתְעוֹרֵר כָּךְ לְמַעְלָה."],[3,"","וְאִם תֹּאמַר, מָה הַדָּבָר מְעוֹרֵר? אֶלָּא כָּךְ כָּתוּב, (ישעיהנח) וְדַבֵּר דָּבָר. אוֹתוֹ הַדָּבָר מְעוֹרֵר דָּבָר אַחֵר לְמַעְלָה שֶׁנִּקְרָא דָבָר. (הושע א) דְּבַר ה' אֲשֶׁר הָיָה. (שמואל א ג) וּדְבַר ה' הָיָה יָקָר. (תהלים לג) בִּדְבַר ה' שָׁמַיִם נַעֲשׂוּ. שֶׁהֲרֵי שָׁנִינוּ, אוֹתוֹ הַדָּבָר עוֹלֶה וּבוֹקֵעַ רְקִיעִים עַד שֶׁעוֹלֶה (שמתישב) בִּמְקוֹמוֹ וּמְעוֹרֵר אֶת מַה שֶּׁמְּעוֹרֵר, אִם טוֹב - טוֹב, וְאִם רַע - רַע. וְעַל זֶה כָּתוּב, (דברים כג) וְנִשְׁמַרְתָּ מִכֹּל דָּבָר רָע."],[4,"","וְאַרְבָּעָה מִינִים בַּלּוּלָב, וְהֵם שִׁבְעָה. וְאִם תֹּאמַר שֶׁשִּׁבְעָה מִינִים הֵם - לֹא כָּךְ, אֶלָּא אַרְבָּעָה הֵם, וְהֵם נִפְרָדִים לִשְׁלֹשָׁה אֲחֵרִים, וּבַמַּעֲשֶׂה שֶׁלָּהֶם מִתְעוֹרְרִים שִׁבְעָה אֲחֵרִים לְמַעְלָה לְהֵיטִיב אֶת הָעוֹלָם בְּכַמָּה צְדָדִים."],[5,"","כְּנֶסֶת יִשְׂרָאֵל, אַף עַל גַּב שֶׁהִיא בִּכְלָל, מִתְבָּרֶכֶת מִכָּל הַשִּׁשָּׁה, (ולהתברך מאותם ששה) וּמֵהַנַּחַל הֶעָמֹק שֶׁל הַמַּעְיָן שֶׁשּׁוֹפֵעַ וְאֵינוֹ פוֹסֵק אֶת מֵימָיו לְעוֹלָמִים שֶׁמַּשְׁפִּיעַ (מלהשפיע) עֲלֵיהֶם, וּמֵינִיק לַבַּת. שֶׁמִשּׁוּם שֶׁהִיא בַּת לָעוֹלָם הָעֶלְיוֹן וְלַתַּחְתּוֹן, הִיא מִתְבָּרֶכֶת מֵהֶם בַּהִתְעוֹרְרוּת הַזּוֹ. שֶׁהֲרֵי בְּשָׁעָה שֶׁכְּנֶסֶת יִשְׂרָאֵל מִתְבָּרֶכֶת מֵהֶם, כָּל הָעוֹלָמוֹת מִתְבָּרְכִים, וְעַל כֵּן סוֹבְבִים אֶת הַמִּזְבֵּחַ, כְּמוֹ שֶׁנִּתְבָּאֵר."],[6,"","וְעוד, בַּהִתְעורְרוּת הַזֹּאת מִתְבָּרְכִים כָּל הַשִּׁשָּׁה בְּמַיִם לֵהָנות בּוֹ, וְכֻלָּם שׁוֹאֲבִים מֵהַמַּעְיָן שֶׁל הַיַּיִן (של הים) (של המים) (של הנחל) הֶעָמֹק שֶׁל הַכֹּל לָרֶדֶת לָעוֹלָם. וּמִשּׁוּם כָּךְ צְרִיכִים כֻּלָּם לַחִים וְלֹא יְבֵשִׁים, לִמְשֹׁךְ בְּרָכוֹת לָעוֹלָם, מִשּׁוּם שֶׁהָאִילָנוֹת הַלָּלוּ כֻּלָּם לַחִים תָּמִיד, וְהֶעָלִים שֶׁלָּהֶם נִמְצָאִים תָּמִיד, וּזְמַן הַשִּׂמְחָה שֶׁלָּהֶם בַּזְּמַן הַזֶּה."],[7,"","וְשָׁנִינוּ בְּסִפְרוֹ שֶׁל רַב הַמְנוּנָא סָבָא, שֶׁהֲרֵי אוֹתוֹ כֹּחַ שֶׁהֻפְקַד עַל הָאִילָנוֹת הַלָּלוּ, כָּל אֶחָד וְאֶחָד מֵאֵלּוּ לֹא נוֹטֵל בְּרָכוֹת שֶׁל שִׂמְחָה לְמַעְלָה, אֶלָּא בַּזְּמַן הַזֶּה. וְהַשִּׂמְחָה שֶׁלָּהֶם כֻּלָּם לְמַעְלָה, וְשִׂמְחַת הָאִילָנוֹת הַלָּלוּ לְמַטָּה, כֻּלָּם בַּזְּמַן הַזֶּה הוּא. וְהַהִתְעוֹרְרוּת שֶׁלָּהֶם בְּאוֹתָם קְדוֹשֵׁי הַמֶּלֶךְ תְּלוּיִים. וּכְשֶׁיִּשְׂרָאֵל נוֹטְלִים אוֹתָם, הַכֹּל מִתְעוֹרֵר בַּזְּמַן הַזֶּה, וְהָעוֹלָם מִתְבָּרֵךְ (לכנסת ישראל מתברכת) לְהוֹרִיק בְּרָכוֹת לָעוֹלָם."],[8,"","כָּתוּב, (תהלים כט) קוֹל ה' עַל הַמָּיִם אֵל הַכָּבוֹד. אָמַר רַבִּי יוֹסֵי, זֶה אַבְרָהָם. קוֹל ה' בַּכֹּחַ - זֶה יִצְחָק. קוֹל ה' בֶּהָדָר - זֶה יַעֲקֹב. קוֹל ה' שֹׁבֵר אֲרָזִים - זֶה נֵצַח. קוֹל ה' חֹצֵב לַהֲבוֹת אֵשׁ - זֶה הוֹד. קוֹל ה' יָחִיל מִדְבָּר - זֶה צַדִּיק. קוֹל ה' יְחוֹלֵל אַיָּלוֹת - זֶה צֶדֶק. וְכֻלָּם גְּדֵלִים עַל הַיָּם (המים) וְנִשְׁקִים בַּמַּיִם כְּדֵי לִגְדֹּל. זֶהוּ שֶׁכָּתוּב (בראשיתב) וְנָהָר יֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן. וְכָל אֵלֶּה מְעוֹרְרִים בְּרָכוֹת לָעוֹלָם מֵאוֹתָהּ הַהַשְׁקָאָה שֶׁכֻּלָּם מֻשְׁקִים."],[9,"","בֹּא רְאֵה, שִׁבְעַת הַקּוֹלוֹת הַלָּלוּ תְּלוּיִים בְּדִבּוּר הַפֶּה בִּשְׁאָר יְמוֹת הַשָּׁנָה, וְעַכְשָׁו אֵין תְּלוּיִים אֶלָּא בְּמַעֲשֶׂה, וְאָנוּ צְרִיכִים מַעֲשֶׂה, וְלֹא דִבּוּר, מִשּׁוּם שֶׁבַּזְּמַן הַזֶּה מְבָרֵךְ אֶת כָּל הַשָּׁנָה."],[10,"","בַּיּוֹם הַשְּׁבִיעִי שֶׁל הֶחָג, הוּא סִיּוּם הַדִּין שֶׁל הָעוֹלָם, וְהַפְּתָקִים יוֹצְאִים מִבֵּית הַמֶּלֶךְ, וְהַגְּבוּרוֹת מִתְעוֹרְרוֹת וּמִסְתַּיְּמוֹת בַּיּוֹם הַזֶּה, וְעַרְבֵי נַחַל (תלויים) בָּהֶם. וּצְרִיכִים לְעוֹרֵר גְּבוּרוֹת לַמַּיִם, וּלְהַקִּיף שֶׁבַע פְּעָמִים כְּדֵי לְרַוּוֹת אֶת הַמִּזְבֵּחַ הַזֶּה מֵהַמַּיִם שֶׁל יִצְחָק, מִשּׁוּם שֶׁהַבְּאֵר הַזּוֹ שֶׁל יִצְחָק מִתְמַלֵּאת מַיִם, וּכְשֶׁמִּתְמַלֵּאת, כָּל הָעוֹלָם מִתְבָּרֵךְ בְּמַיִם."]]],[["וּבְהַאי יוֹמָא גְּבוּרוֹת בָּעֵינָן לְמַיָּא, וּלְסַיְימָא לוֹן לְבָתַר, דְּהָא בְּהַאי יוֹמָא מִסְתַּיְּימֵי דִּינָא. וּבְגִין כָּךְ בָּעֵינָן לְבַטְּשָׁא לוֹן בְּאַרְעָא, וּלְסַיְימָא לוֹן דְּלָא מִשְׁתַּכְחוּ, דְּהַאי יוֹמָא אִתְּעָרוּתָא וְסִיּוּמָא הוּא. וְעַל דָּא אִתְּעָרוּתָא וְסִיּוּמָא הוּא דְּעַבְדִינָן בְּעַרְבֵי נַחַל.","אָמַר רִבִּי חִיָיא וַדַּאי הָכִי הוּא, וְשַׁפִּיר. וְעַרְבֵי נַחַל, מִסִּטְרָא דְּנַחַל, נַפְקֵי גְּבוּרָאן. וּבְהַאי יוֹמָא מִתְעָרֵי וּמְסַיְּימֵי. בְּהַאי יוֹמָא כְּתִיב, (בראשית כ״ו:י״ח) וַיָּשָׁב יִצְחָק וַיַחְפּוֹר אֶת בְּאֵרֹת הַמַּיִם. בְּאֵרֹת כְּתִיב חָסֵר. וַיָּשָׁב, מַהוּ וַיָּשָׁב. אֶלָּא יוֹמָא קַדְמָאָה דְּיַרְחָא, שֵׁירוּתָא דְּדִינָא הַוָה בְּכָל עָלְמָא, וְיִצְחָק קַיְּימָא לְכוּרְסְיָיא לְמֵידָן עָלְמָא. בְּהַאי יוֹמָא, וַיָּשָׁב יִצְחָק לְאִתְּעָרָא דִּינִין וּלְסַיְימָא דִּינִין. וַיַחְפּוֹר אֶת בְּאֵרֹת הַמַיִם, לְאַרְקָא גְּבוּרָן לִכְּנֶסֶת יִשְׂרָאֵל, לְאִתְּעָרָא לְמַיָּא, דְּהָא מַיָּא בִּגְבוּרָן נַחְתָּן לְעָלְמָא.","וּבְגִין דְּאִלֵּין גְּבוּרָן, לָא נַחְתִּין אֶלָּא בְּעִיבָא, וְיוֹמָא דְּעִיבָא לָא נַיְיחָא רוּחֵיהוֹן דְּקַיְימֵי עָלְמָא, אֶלָּא בְּגִין דְּעָלְמָא אִצְטְרִיךְ לְהוּ. מַאי טַעֲמָא. בְּגִין דְּעָלְמָא בְּדִינָא אִתְבְּרֵי, וְכֹלָּא בַּעְיָא הָכִי. בְּגִין כָּךְ כֹּלָּא בְּעוֹבָדָא תַּלְיָא מִלְּתָא. וְעַל דָּא, כַּהֲנָא בְּעוֹבָדָא וְתִקּוּנָא דְּאִיהוּ עָבִיד לְתַתָּא, אִתְּעֲרוּ עִלָּאִין וְתַתָּאִין לְתַקְּנָא לוֹן, וּמִתְתַּקְנֵי עַל יְדוֹי.","אָמַר רִבִּי יוֹסֵי הָא תָּנֵינָן, הַעֲרָבָה דְּדַמְיָא לְשִׂפְוָון בְּהַאי יוֹמָא, וּמַאי הִיא. אָמַר רִבִּי חִיָּיא, אַף עַל גַּב דְּלִדְרָשָׁא הוּא דְּאָתֵי, הָכִי הוּא וַדַּאי. דְּהָא בְּהַאי יוֹמָא בְּשִׂפְוָון תַּלְיָא, בְּהַאי יוֹמָא פָּקִיד מַלְכָּא לְמֵיהַב פִּתְקִין לְסַנְטִירָא, וּמִסְתַּיְּימֵי דִּינִין, וְאַסְתִּים לִישָׁנָא בִּישָׁא מֵעָלְמָא. בְּיוֹמָא קַדְמָאָה דְּיַרְחָא שֵׁירוּתָא דְּדִינָא הוּא, וְסִיּוּמָא הוּא בְּהַאי יוֹמָא. וְהָא אִתְּמַר.","תָּא חֲזֵי, בְּיוֹמָא דָּא שְׁלֵמִין וּמְסַיְּימֵי עַמִּין עוֹבְדֵי עֲבוֹדָה זָרָה בִּרְכָאן דִּלְהוֹן, וְשָׁרָאן בְּדִינָא. וְיִשְׂרָאֵל בְּיוֹמָא דָּא מְסַיְּימֵי דִּינִין דִּלְהוֹן וְשָׁרָאן בְּבִרְכָתָא. דְּהָא לְיוֹמָא אָחֳרָא זְמִינִין לְאִשְׁתַּעְשְׁעָא בְּמַלְכָּא, לְנַטְלָא מִינֵיהּ בִּרְכָאן לְכָל שַׁתָּא, וּבְהַהוּא חֶדְוָותָא לָא מִשְׁתַּכְּחֵי בְּמַלְכָּא אֶלָּא יִשְׂרָאֵל בִּלְחוֹדַיְיהוּ. וּמַאן דְּיָתִיב עִם מַלְכָּא, וְנָטַל לֵיהּ בִּלְחוֹדֵיהּ, כָּל מַה דְּבָעֵי שָׁאִיל, וְיָהִיב לֵיהּ. וְעַל דָּא יִשְׂרָאֵל שָׁרָאן, וְעַמִּין עוֹבְדֵי עֲבוֹדָה זָרָה מְסַיְּימֵי. וְעַל דָּא כְּתִיב, (מלאכי א׳:ב׳) אָהַבְתִּי אֶתְכֶם אָמַר יְיָ' וְגוֹ'.","אָמַר לֵיהּ, הָא חֲמֵינָא לֵיהּ לְעֵשָׂו בְּשַׁלְוָה, בְּמַלְכוּ, בִּכְרִיכָן עִלָּאִין, וְשָׁלִיט עַל עָלְמָא, וְאַתְּ אָמַר וָאָשִׂים אֶת הָרָיו שְׁמָמָה. אָמַר לֵיהּ, בְּכָל אֲתַר הָכִי הוּא. כֵּיוָן דְּמַלְכָּא קַדִּישָׁא גָּזַר גְּזֵרָה, וְשַׁוִּי הַהִיא גְּזֵרָה בְּפִתְקֵיהּ, קְרָא אַסְהִיד כְּמָה דְּאִתְעָבִיד. וְעַל דָּא וָאָשִׂים אֶת הָרָיו שְׁמָמָה, הָא שִׁוִיתִי בְּפִתְקָא דִּילִי. וְכֵן כָּל אִינּוּן טָבָן דְּגָזַר עָלַיְיהוּ דְּיִשְׂרָאֵל, דִּכְתִּיב, (יחזקאל י״ז:כ״ד) אֲנִי יְיָ' דִּבַּרְתִּי וְעָשִׂיתִי.","(ויקרא ז׳:י״א) וְזֹאת תּוֹרַת הָאָשָׁם וְזֹאת תּוֹרַת הַמִּנְחָה וְזֹאת תּוֹרַת זֶבַח הַשְּׁלָמִים זֹאת תּוֹרַת הַחַטָּאת. רִבִּי יִצְחָק אָמַר, הָא אוּקְמוּהָ אִי לְתַתָּא דָּא בְּכֹלָּא. אִי לְעֵילָּא דָּא בְּכֹלָּא. וּמַאן דְּאִשְׁתְּדַל בְּאוֹרַיְיתָא, נָטְלָא לְחוּלָקֵיהּ בְּכֹלָּא, וְאִתְאֲחִיד בְּכָל סִטְרִין, וְלָא בָּעֵי לְקָרְבָא קָרְבְּנָא עַל נַפְשֵׁיהּ, וְהָא אִתְּמַר.","רִבִּי יִצְחָק פָּתַח, (ירמיהו ב׳:ח׳) הַכֹּהֲנִים לֹא אָמְרוּ אַיֵה יְיָ' וְתוֹפְשֵׂי הַתּוֹרָה לֹא יְדָעוּנִי וְהָרוֹעִים פָּשְׁעוּ בִי. הַכֹּהֲנִים, אִלֵּין כֹּהֲנִים דִּמְשַׁמְּשִׁין בִּכְהוּנָה גְּדוֹלָה, וּמְקָרְבִין מִלִּין קַדִּישִׁין לְאַתְרַיְיהוּ, וּמְיַיחֲדִין יִחוּדָא כָּל חַד וְחַד כַּדְקָא חֲזֵי. וְתוֹפְשֵׂי הַתּוֹרָה מַאן אִינּוּן תּוֹפְשֵׂי הַתּוֹרָה, וְכִי כַּהֲנֵי לָאו תּוֹפְשֵׂי הַתּוֹרָה נִינְהוּ. אֶלָּא, אִלֵּין אִינּוּן לֵיוָאֵי, דְּתַפְשֵׂי בְּכִנּוֹרוֹת, דְּאַתְיָין מִסִּטְרָא דְּאוֹרַיְיתָא. וְאִתְיְיהִיבַת מִסִּטְרָא דִּלְהוֹן אוֹרַיְיתָא. וְאִינּוּן מְמָנָן עַל שְׁבָחָא דְּתוּשְׁבַּחְתָּא דְּמַלְכָּא קַדִּישָׁא, לְיַחֲדָא לֵיהּ יִחוּדָא שְׁלִים כְּדְקָא יֵאוֹת. וְהָרוֹעִים פָּשְׁעוּ בִי. אִלֵּין אִינּוּן רַבְרְבֵי עַמָּא, דְּאִינּוּן רַעְיָין לְעַמָּא, כְּרַעְיָא דְּמַדְבַּר עָאנֵיהּ.","וְאִלֵּין אִינּוּן ג' דַּרְגִּין, דְּבַעְיָא לְאִשְׁתַּכְּחָא תָּדִיר עַל קָרְבְּנָא, לְאַשְׁכְּחָא רַעֲוָא לְעֵילָּא וְתַתָּא, וּלְאִשְׁתַּכְּחָא בִּרְכָאן בְּכֻלְּהוּ עָלְמִין. כַּהֲנָא מְקָרֵב קָרְבְּנָא, וְאִתְכְּוָּון לְיַחֲדָא שְׁמָא קַדִּישָׁא כַּדְקָא חֲזֵי, וּלְאַתְעֲרָא סִטְרָא דִּילֵיהּ. וְלֵיוָאֵי אִתְכַּוְּונָן בְּשִׁיר, לְאִתְּעָרָא סִטְרָא דִּלְהוֹן, וּלְאִתְכַּלְּלָא בְּסִטְרָא דְּכַהֲנָא. וְיִשְׂרָאֵל אִתְכְּוָּון לִבָּא וּרְעוּתָא לְתִיוּבְתָּא שְׁלֵימָתָא, וְאִתְכְּנָּע קָמֵי מַלְכָּא קַדִּישָׁא, וְהַאי נָטִיל כֹּלָּא, וְאִתְכְּפַּר חוֹבֵיהּ, וְאִשְׁתְּכַח חֶדְוָותָא בְּעִלָּאֵי וְתַתָּאֵי."],[[0,"ובהאי יומא גבורות וכו':","וביום ההוא, בהושענא רבא, צריכים גבורות כדי להמשיך מים, שה\"ס הארת חכמה כנ\"ל, שאינה נמשכת אלא עם גבורות ודינים, (כנ\"ל פקודי אות שע\"ו, ע\"ש) ולסיים אותם אח\"כ, כי ביום ההוא מסתיים הדין, שאין צריכים להמשיך עוד הארת החכמה הנמשכת בדין, (כנ\"ל באות קי\"א) וע\"כ צריכים להכות הערבות על הארץ, ולסיים אותם דהיינו הארתם שלא ימצאו. כי ביום הזה ישנם התעוררות החכמה וסיום החכמה, וע\"כ, בערבי נחל, הרומזים על נו\"ה, שבהם מתגלה החכמה, ע\"י דינים, אנו עושים התעוררות וסיום. פי' הקרקע היא בחינה אחרונה שבמלכות, וכשמכים הערבות על הקרקע, נמשכת הארת החכמה עם הדינים לבחינה האחרונה של המלכות ששם סיום ההארה. והטעם שהחכמה אינה מתגלית אלא בסוד הערבות, שהם נצח והוד, הוא, משום שמחזה ולמעלה ה\"ס ג\"ר דגוף, ונו\"ה שמחזה ולמטה ההא ו\"ק דגוף, וכיון שג\"ר דחכמה נגנזו, ואינם מתגלים אלא ו\"ק דחכמה, ע\"כ מקומם בו\"ק דגוף שהוא נו\"ה. שה\"ס ערבי נחל."],[1,"אמר ר' חייא וכו':","אר\"ח ודאי כך הוא, ויפה הוא, וערבי נחל נקראים, משום שמצד הנחל, שהוא בינה, יוצאות הגבורות, דהיינו הארת חכמה עם הדינים שבהם. וביום ההוא מתעוררים ומסתיימים. ביום ההוא כתוב, וישב יצחק ויחפור את בארות המים, בארת כתוב חסר \u0003ו',\u0004 משום שרומז על המלכות שנקראת באר. \u0003וישב,\u0004 מהו וישב. אלא ביום הראשון של החדש, דהיינו בראש השנה, היתה התחלת הדין בכל העולם, ויצחק, שה\"ס קו שמאל, קם לכסא הדין לדון העולם. ביום ההוא, בהושענא רבא, \u0003וישב יצחק,\u0004 לעורר דינים ולסיים הדינים. \u0003ויחפור את בארת המים,\u0004 היינו להוריק גבורות לכנסת ישראל, שהיא המלכות המכונה באר, לעורר את המים, שה\"ס הארת החכמה, כי המים בגבורות יורדים לעולם, כלומר, שאין הארת חכמה נמשכת אלא עם דינים ביחד (כמ\"ש פקודי אות שע\"ו ע\"ש)."],[1,"","פירוש. כי בראש השנה התחילו הדינים דקו שמאל להתגלות, שהיתה אז המלכות בסוד ב' מאורות הגדולים, והלבישה קו שמאל דבינה. ובתקיעת השופר, נתמעט קו השמאל ע\"י קו האמצעי, ע\"י ב' פעולות, תחילה בסוד המנעולא הממעט אותו לגמרי, ואח\"כ ע\"י המפתחא, המכשירו לקבל ו\"ק דחכמה, וביוה\"כ ע\"י עלית המלכות לבינה נגלה בה ו\"ק דחכמה, בסוד ה' עינוים שקבלה מקו שמאל דבינה. ואחר יוה\"כ התחילו להתגלות החסדים להלביש את החכמה, שאין החכמה מאירה זולתם, ונמשך תקון חכמה בחסדים ע\"י הקפת המזבח, עד יום הושענא רבא, שהוא בחינת מלכות, דז' ימי סוכות ה\"ס חג\"ת נהי\"מ, וע\"כ צריכים לעורר מחדש את החכמה בתקון החסדים, בסוד הקפת המזבח, כדי לתקן עמה את יום הז' ולסיים בכלל את המשכת החכמה, כי כיון שהגיעה למלכות, שוב אין צריך עוד להמשיכה. וז\"ש, \u0003בהאי יומא, ויושב יצחק, לאתערא דינין ולסיימא דינין.\u0004 כי אין צריך יותר להמשיך."],[2,"ובגין דאלין גבורן וכו':","ומשום שאלו הגבורות אינם יורדים אלא על ידי עננים, שהם דינים, וביום המעונן, אין הרוח של עמודי העולם מתישב בהם, אלא כך מוכרח להיות משום שהעולם צריך להם, מהו הטעם, הוא משום שהעולם נברא בדין, דהיינו בראש השנה, כנ\"ל בדבור הסמוך, ומשום זה, צריכים הדינים להתגלות תמיד עם המים שה\"ס הארת החכמה, כדי שהרשעים לא יתאחזו בקו שמאל, ויחזירו הדינים דראש השנה, (כנ\"ל פקודי אות שע\"ו) והכל צריך להיות כך. משום זה הכל תלוי במעשה. וע\"כ הכהן בהמעשה והתקון שהוא עושה למטה דהיינו מעשה הקרבן, מתעוררים עליונים ותחתונים לתקנם ומתתקנים על ידו, אף כך, ע\"י המעשה דד' מינים, וערבה שבהושענא רבא, מתתקנת החכמה ע\"י הדינים שמתגלים עמה. שלא תהיה בה אחיזה לרשעים."],[3,"א\"ר יוסי הא וכו':","אר\"י, הנה למדנו, שהערבה דומה לשפתים, ביום הזה, ומה זה. א\"ר חייא, אע\"פ שזה רק דרש, כך הוא ודאי. שביום הזה הדבר תלוי בשפתים. כי ביום הזה מצוה המלך לתת פסקי הדינים אל הממונה, והדינים מסתיימים ונסתם לשון הרע מן העולם. ביום הראשון של החודש, התחלת הדין הוא, והסיום הוא ביום הזה. וכבר נתבאר. \u0003סנטירא,\u0004 פירושו ממונה ומשגיח. כמו, המוכר את העיר מכר את \u0003הסנטר,\u0004 שפירושו ממונה ומשגיח (ב\"ב ס\"ח)."],[3,"","פירוש. ביום א' של החדש נאחזה המלכות בקו שמאל דבינה, שה\"ס יצחק, ויצחק קיימא לכרסייא למידן עלמא (כנ\"ל אות קט\"ז). וע\"י תקיעת שופר התעורר קו האמצעי להזדווג על מסך דחירק, למעט הקו שמאל, תחילה במנעולא, ואח\"כ במפתחא, (כנ\"ל לך י\"ג ד\"ה ונתבאר) שפירושו שהמלכות עלתה לבינה והבינה חזרה לבחינת ו\"ק בלא ראש (כמ\"ש שם). והנה מצד אחד נעשה תקון בזה להכניע הדינין דקו שמאל ולהכינו שיתיחד בימין. אבל מצד הב' נאחזו הדינים דקטנות בבינה, מחמת עלית המלכות בתוכה, שמחמת זה יצאו החיצונים בלשון הרע על הבינה, לומר שיש בה חסרון, כדי שיתאחזו בה במקום החסרון כדרכם. ע\"כ היה צורך לסתום פי החיצונים שלא ידברו לשון הרע על הבינה, שזה נעשה ביום הכפורים ובז' ימי סוכות, שהמלכות חזרה וירדה מן הבינה, והבינה קבלה בחזרה את הג\"ר שלה מבחינת ו\"ק דחכמה. וז\"ש \u0003ואסתים לישנא בישא מעלמא.\u0004 שביום הושענא רבה נגמרה חזרת ו\"ק דחכמה אל הבינה כמקודם לכן, ונסתמו פיות החיצונים מלדבר לשון הרע על הבינה. ואחר שפסק הלשון הרע, אין צורך עוד להמשיך חכמה, המביאה עמה דינים. וז\"ש, \u0003בהאי יומא פקיד מלכא למיהב פתקין לסנטירא\u0004 (כמ\"ש לעיל באות קי\"ד) \u0003ומסתיימי דינין,\u0004 כי אחר שנסתמה הלשון הרע, אין צורך עוד לגילוי החכמה. ונתבאר לעיל שע\"י המצוות התלויות במעשה, שהם נטילת לולב וערבות. נמשכה החכמה וע\"י מצוות התלויות בדבור דהיינו ב \u0003שפתיים,\u0004 ממשיכים החסדים (כנ\"ל אות קי\"א ע\"ש) וז\"ש, \u0003ערבה דדמיא לשפוון וכו' דהא בהאי יומא בשפוון תליא.\u0004 כי בערבה אנחנו מעוררים החכמה עם הגבורות ומסיימים אותה, שמכאן והלאה לא נמשיך עוד אלא חסדים ממצוות התלויות ב \u0003שפתיים,\u0004 כנ\"ל וע\"כ יש רמז על זה שהעלים של הערבה דומים לשפתיים."],[4,"ת\"ח ביומא דא","וכו': בוא וראה, ביום הזה, העמים עכו\"ם משלימים ומסיימים הברכות שלהם, ושורים בדין. וישראל, ביום הזה, מסיימים הדינים שלהם ושורים בברכות, כי ביום האחר, דהיינו בשמיני עצרת, עתידים להשתעשע עם המלך, לקחת ממנו ברכות על כל ימות השנה, ובשמחה ההיא לא נמצא עם המלך רק ישראל לבדם. ומי שיושב עם המלך ולוקח אותו לבדו, כל מה שרוצה הוא מבקש, והמלך נותן לו. וע\"כ ישראל מתחילים לקבל הברכות, ועמים העכו\"ם מסיימים ברכותיהם. וע\"כ כתוב, אהבתי אתכם אמר ה'."],[4,"","פירוש. כי אומות העולם אחוזים בקו שמאל, שמשם הארת החכמה, ואינם יכולים לקבל מקו ימין שהוא חסדים, כי שורשם רק בשמאל בלבד הוא. ולפיכך בז' ימי סוכות שהחכמה נמשכת בהם מקו שמאל, ע\"י מעשה המצוות כנ\"ל, מקבלים אז אומות העולם את ברכותיהם. וז\"ס ע' פרים שאנו מקריבים בז' ימי החג כנגד ע' אומות, שמשם יניקתם. ונמצא שביום הז' אחר חבטת הערבה, שכבר נפסקה המשכת החכמה, נפסקו הברכות מן האומות, כי אין להם עוד ממה לינק. וז\"ש, \u0003ביומא דא שלמין ומסיימי עמין עכו\"ם ברכאן דלהון,\u0004 שכבר נפסקה ביום הזה המשכת החכמה שהיא כל הברכות שלהם, \u0003ושראן בדינא,\u0004 כי אינם יכולים לינק חסדים מימין כנ\"ל. והם בריקנות. אבל ישראל, שהם דבוקים בקו אמצעי, שמשם החסדים, וכל שורשם הוא שם, נמצא, שהחכמה הנמשכת בז' ימי החג מקו שמאל, כיון שאינה נמשכת אלא עם דינים, הרי אחר שנסתיימה הארת החכמה נסתיימו הדינים שעמה, וז\"ש, \u0003וישראל ביומא דא מסיימי דינין דלהון,\u0004 משום שאין ממשיכים יותר הארת חכמה, \u0003ושראן בברכתא,\u0004 דהיינו בחסדים הנמשכים מקו אמצעי שהוא שורשם. \u0003דהא ליומא אחרא וכו' ברכאן לכל שתא,\u0004 כי מזווג ז\"א ומלכות שביום שמיני עצרת נמשכות ברכות לישראל דהיינו חסדים לכל השנה. וז\"ש \u0003ובההוא חדוותא לא משתכחי במלכא אלא ישראל בלחודייהו\u0004 שבהיות השמחה מהשפעת החסדים, שאין שום אומה יכולה לקבל אותם רק ישראל בלבד, נמצא שאין אז עם המלך, אלא ישראל בלבד. וע\"ד \u0003ישראל שראן ועמין עכו\"ם מסיימי,\u0004 כי הארת השמאל שהוא משורשם של האומות הסתיימה, ואין להם עוד מה לינק. והארת קו האמצעי שהוא משורשם של ישראל מתחילה בשמיני עצרת ונמשכת בכל השנה, שהיא הארת החסדים (כנ\"ל באות קי\"ג)."],[5,"א\"ל הא חמינא וכו':","אמר לו, הרי אנו רואים את עשו שהוא בשלוה, במלכות, בערים גדולות עליונות, ושולט על העולם, ואתה אומר, ואשים את הריו שממה. אמר לו, בכל מקום כך הוא, כיון שהמלך הקדוש גוזר גזרה, ושם גזרה ההיא בפסקי דינים שלו, הכתוב מעיד כמו שנעשה, ואע\"פ שעוד לא יצא פסק הדין לפועל. וע\"כ כתוב, ואשים את הריו שממה. כי כבר שויתי את זה בפסק דין שלי. והדבר יתקיים בזמנו. וכן כל הטוב שגזר על ישראל, הוא באפן זה, דהיינו שיתקיים בזמנו. שכתוב, אני ה׳ דברתי ועשיתי."],[6,"וזאת תורת האשם וכו׳: וזאת","תורת האשם. \u0003וזאת\u0004 תורת המנחה. וזאת תורת זבח השלמים. \u0003זאת\u0004 תורת החטאת. ר׳ יצחק אמר, הרי העמידוהו, אם למטה, זאת היא בכל, ואם למעלה זאת היא בכל. כי \u0003זאת,\u0004 שהיא המלכות, כוללת כל האורות שממנה ולמעלה, שהיא מקבלת לתוכה את כולם. וכן למטה, שהיא משפעת לכל העולמות שממנה ולמטה, וכוללת כולם. וע״ז נאמר השם \u0003זאת\u0004 בכל הקרבנות, להיותה כוללת אותם כולם. ומי שעוסק בתורה לוקח אותה, את המלכות, לחלקו לגמרי, ומתאחד בכל הבחינות שלה, הנ״ל, שהם, אשם, מנחה, שלמים, חטאת, וע״כ אינו צריך עוד להקריב קרבן על עצמו. וכבר למדנו זה."],[7,"ר׳ יצחק פתח וכו׳:","רי״פ, הכהנים לא אמרו איה ה׳ ותופשי התורה לא ידעוני והרועים פשעו בי. \u0003הכהנים,\u0004 אלו הכהנים המשמשים בכהונה גדולה, ומקרבים דברים קדושים למקומם, ומיחדים יחוד כל דבר ודבר כראוי. \u0003ותופשי התורה,\u0004 מי הם תופשי התורה, וכי הכהנים אינם תופשי התורה. ומשיב, אלא אלו הם הלוים התופשים בכנורות הבאים מצד התורה. והתורה ניתנה מצד שלהם, שהוא צד השמאל, גבורה (כנ״ל ב״ב אות ר״ג), והם ממונים על השיר של שבחי המלך הקדוש, ליחד אותו ביחוד השלם כראוי. \u0003והרועים פשעו בי,\u0004 אלו הם שרי העם, שהם רועים את העם, כרועה המנהיג את צאנו."],[8,"ואלין אינון ג' וכו׳:","ואלה הם שלש מדרגות דהיינו ג׳ קוין, ימין, שמאל, אמצע, שצריכים להמצא תמיד על הקרבן, למצוא רצון למעלה ולמטה, ושתמצאנה ברכות בכל העולמות. \u0003הכהן,\u0004 מקריב קרבן ומכוון ליחד השם הקדוש כראוי ולעורר את הצד שלו, שהוא צד ימין, חסד. \u0003והלוים,\u0004 מכוונים בשיר לעורר הצד שלהם, שהוא צד שמאל, גבורה. ולהכלל בצד של הכהן. \u0003וישראל,\u0004 שהם הרועים, הם קו האמצעי, תפארת, שמכוונים הלב ורצון לתשובה שלמה, ונכנעים לפני המלך הקדוש שהוא לוקח הכל, ומתכפרים עונותיהם, ונמצאת שמחה בעליונים ותחתונים."]],[[0,"","וּבַיּוֹם הַזֶּה צְרִיכִים גְּבוּרוֹת לַמַּיִם, וּלְסַיֵּם אוֹתָהּ אַחַר כָּךְ, שֶׁהֲרֵי בַּיּוֹם הַזֶּה מִסְתַּיֵּם הַדִּין, וּמִשּׁוּם כָּךְ צְרִיכִים לַחְבֹּט אוֹתָם בַּקַּרְקַע שֶׁלֹּא יִמָּצְאוּ, שֶׁהֲרֵי זֶהוּ יוֹם שֶׁל הִתְעוֹרְרוּת וְסִיּוּם. וְלָכֵן הִתְעוֹרְרוּת וְסִיּוּם הוּא שֶׁעוֹשִׂים בְּעַרְבֵי נַחַל."],[1,"","אָמַר רַבִּי חִיָּיא, וַדַּאי כָּךְ הוּא, וְיָפֶה. וְעַרְבֵי נָחַל, מֵהַצַּד שֶׁל נַחַל יוֹצְאוֹת גְּבוּרוֹת. וּבַיּוֹם הַזֶּה מִתְעוֹרְרִים וּמְסַיְּמִים. בַּיּוֹם הַזֶּה כָּתוּב, (בראשית כו) וַיָּשָׁב יִצְחָק וַיַּחְפֹּר אֶת בְּאֵרֹת הַמַּיִם. בְּאֵרֹת כָּתוּב חָסֵר. וַיָּשָׁב, מַה זֶּה וַיָּשָׁב? אֶלָּא הַיּוֹם הָרִאשׁוֹן שֶׁל הַחֹדֶשׁ, רֵאשִׁית הַדִּין הָיָה בְּכָל הָעוֹלָם, וְיִצְחָק עוֹמֵד לַכִּסֵּא לָדוּן אֶת הָעוֹלָם. בַּיּוֹם הַזֶּה, וַיָּשָׁב יִצְחָק, לְעוֹרֵר דִּינִים וּלְסַיֵּם דִּינִים. וַיַּחְפֹּר אֶת בְּאֵרֹת הַמַּיִם, לְהָרִיק גְּבוּרוֹת לִכְנֶסֶת יִשְׂרָאֵל לְעוֹרֵר אֶת הַמַּיִם, שֶׁהֲרֵי מַיִם יוֹרְדִים לָעוֹלָם בִּגְבוּרוֹת."],[2,"","וּמִשּׁוּם שֶׁהַגְּבוּרוֹת הַלָּלוּ אֵין יוֹרְדוֹת אֶלָּא בַּעֲנָנִים, וְיוֹם הַמְעֻנָּן לֹא נָחָה רוּחָם שֶׁל עַמּוּדֵי הָעוֹלָם, רַק מִשּׁוּם שֶׁהָעוֹלָם צָרִיךְ אוֹתָם. מָה הַטַּעַם? מִשּׁוּם שֶׁהָעוֹלָם נִבְרָא בְּדִין, וְהַכֹּל כָּךְ צָרִיךְ. מִשּׁוּם כָּךְ הַכֹּל תָּלוּי בְּמַעֲשֶׂה. וְעַל כֵּן הַכֹּהֵן בַּמַּעֲשֶׂה וּבַתִּקּוּן שֶׁהוּא עוֹשֶׂה לְמַטָּה, מִתְעוֹרְרִים עֶלְיוֹנִים וְתַחְתּוֹנִים לְתַקֵּן אוֹתָם, וְהֵם מִתְתַּקְּנִים עַל יָדוֹ."],[3,"","אָמַר רַבִּי יוֹסֵי, הֲרֵי שָׁנִינוּ, הָעֲרָבָה שֶׁדּוֹמֶה לַשְּׂפָתַיִם בַּיּוֹם הַזֶּה, וּמַה הִיא? אָמַר רַבִּי חִיָּיא, אַף עַל גַּב שֶׁלִּדְרָשׁ הוּא בָּא, כָּךְ זֶה וַדַּאי. שֶׁהֲרֵי בַּיּוֹם הַזֶּה זֶה תָלוּי בַּשְּׂפָתַיִם, בַּיּוֹם הַזֶּה מְצַוֶּה הַמֶּלֶךְ לָתֵת פְּתָקִים לַמְמֻנֶּה, וְהַדִּינִים מִסְתַּיְּמִים, וְנִסְתָּם לָשׁוֹן הָרָע מֵהָעוֹלָם. בַּיּוֹם הָרִאשׁוֹן שֶׁל הַחֹדֶשׁ הוּא רֵאשִׁית הַדִּין, וְהַסִּיּוּם הוּא בַּיּוֹם הַזֶּה, וַהֲרֵי נִתְבָּאֵר."],[4,"","בֹּא רְאֵה, בַּיּוֹם הַזֶּה הָעַמִּים עוֹבְדֵי עֲבוֹדָה זָרָה מַשְׁלִימִים וּמְסַיְּמִים אֶת הַבְּרָכוֹת שֶׁלָּהֶם וְשׁוֹרִים בְּדִין, וְיִשְׂרָאֵל בַּיּוֹם הַזֶּה מְסַיְּמִים אֶת הַדִּינִים שֶׁלָּהֶם וְשׁוֹרִים בִּבְרָכוֹת, שֶׁהֲרֵי לְיוֹם אַחֵר עֲתִידִים לְהִשְׁתַּעֲשֵׁעַ עִם הַמֶּלֶךְ, לִטֹּל מִמֶּנּוּ בְּרָכוֹת לְכָל הַשָּׁנָה, וּבְאוֹתָהּ שִׂמְחָה לֹא נִמְצָאִים עִם הַמֶּלֶךְ, רַק יִשְׂרָאֵל לְבַדָּם. וּמִי שֶׁיּוֹשֵׁב עִם הַמֶּלֶךְ וְנוֹטֵל אוֹתוֹ לְבַדּוֹ, כָּל מַה שֶּׁרוֹצֶה שׁוֹאֵל, וְנוֹתֵן לוֹ. וְעַל כֵּן יִשְׂרָאֵל מַתְחִילִים, וְעַמִּים עוֹבְדֵי עֲבוֹדָה זָרָה מְסַיְּמִים. וְעַל כֵּן כָּתוּב, (מלאכי א) אָהַבְתִּי אֶתְכֶם אָמַר ה' וְגוֹ'."],[5,"","אָמַר לוֹ, הֲרֵי אֲנִי רוֹאֶה אֶת עֵשָׂו בְּשַׁלְוָה, בְּמַלְכוּת, בִּכְרַכִּים עֶלְיוֹנִים, וְשׁוֹלֵט עַל הָעוֹלָם, וְאַתָּה אָמַרְתָּ וָאָשִׂים אֶת הָרָיו שְׁמָמָה?! אָמַר לוֹ, בְּכָל מָקוֹם זֶה כָּךְ, כֵּיוָן שֶׁהַמֶּלֶךְ הַקָּדוֹשׁ גָּזַר גְּזֵרָה וְשָׂם אוֹתָהּ גְּזֵרָה בַּפֶּתֶק שֶׁלּוֹ, הַכָּתוּב מֵעִיד כְּמוֹ שֶׁנַּעֲשָׂה. וְעַל כֵּן וָאָשִׂים אֶת הָרָיו שְׁמָמָה, שֶׁהֲרֵי שַׂמְתִּי אֶת זֶה בַּפֶּתֶק שֶׁלִּי, וְכֵן כָּל אוֹתָן טוֹבוֹת שֶׁגָּזַר עַל יִשְׂרָאֵל, שֶׁכָּתוּב (יחזקאל יז) אֲנִי ה' דִּבַּרְתִּי וְעָשִׂיתִי."],[6,"","וְזֹאת תּוֹרַת הָאָשָׁם וְזֹּאת תּוֹרַת הַמִּנְחָה וְזֹּאת תּוֹרַת זֶבַח הַשְּׁלָמִים זֹּאת תּוֹרַת הַחַטָּאת. רַבִּי יִצְחָק אָמַר, הֲרֵי פֵּרְשׁוּהָ, אִם לְמַטָּה - זוֹ בַּכֹּל, וְאִם לְמַעְלָה - זוֹ בַּכֹּל. וּמִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, נוֹטֵל אוֹתָהּ לְחֶלְקוֹ בַּכֹּל וְנֶאֱחָז בְּכָל הַצְּדָדִים, וְלֹא צָרִיךְ לְהַקְרִיב קָרְבָּן עַל נַפִשׁוֹ, וַהֲרֵי נִתְבָּאֵר."],[7,"","רַבִּי יִצְחָק פָּתַח, (ירמיה ב) הַכֹּהֲנִים לֹא אָמְרוּ אַיֵּה ה' וְתֹפְשֵׂי הַתּוֹרָה לֹא יְדָעוּנִי וְהָרֹעִים פָּשְׁעוּ בִי. הַכֹּהֲנִים - אֵלּוּ הַכֹּהֲנִים שֶׁמְּשַׁמְּשִׁים בִּכְהֻנָּה גְּדוֹלָה, וּמַקְרִיבִים דְּבָרִים קְדוֹשִׁים לִמְקוֹמָם, וּמְיַחֲדִים הַיִּחוּד כָּל אֶחָד וְאֶחָד כָּרָאוּי. וְתֹפְשֵׂי הַתּוֹרָה, מִי הֵם תֹּפְשֵׂי הַתּוֹרָה? וְכִי כֹהֲנִים אֵינָם תּוֹפְשֵׂי הַתּוֹרָה? אֶלָּא אֵלּוּ הֵם הַלְוִיִּם שֶׁתּוֹפְשִׂים אֶת הַכִּנּוֹרוֹת, שֶׁבָּאִים מִצַּד שֶׁל הַתּוֹרָה, וְהַתּוֹרָה נִתְּנָה מֵהַצַּד שֶׁלָּהֶם, וְהֵם מְמֻנִּים עַל הַשֶּׁבַח שֶׁל תִּשְׁבַּחְתּוֹ שֶׁל הַמֶּלֶךְ הַקָּדוֹשׁ לְיַחֵד אוֹתוֹ יִחוּד שָׁלֵם כָּרָאוּי. וְהָרֹעִים פָּשְׁעוּ בִי - אֵלֶּה הֵם גְּדוֹלֵי הָעַמִּים, שֶׁהֲרֵי רוֹעִים אֶת הָעָם כְּמוֹ רוֹעֶה שֶׁמַּנְהִיג אֶת צֹאנוֹ."],[8,"","וְאֵלֶּה הֵם שָׁלֹשׁ דְּרָגוֹת שֶׁצְּרִיכוֹת תָּמִיד לְהִמָּצֵא עַל הַקָּרְבָּן לִמְצֹא רָצוֹן לְמַעְלָה וּלְמַטָּה וְשֶׁיִּמָּצְאוּ בְרָכוֹת בְּכָל הָעוֹלָמוֹת. הַכֹּהֵן מַקְרִיב קָרְבָּן, וּמִתְכַּוֵּן לְיַחֵד אֶת הַשֵּׁם הַקָּדוֹשׁ כָּרָאוּי וּלְעוֹרֵר אֶת הַצַּד שֶׁלּוֹ, וְהַלְוִיִּם מִתְכַּוְּנִים בַּשִּׁיר לְעוֹרֵר אֶת הַצַּד שֶׁלָּהֶם וּלְהִכָּלֵל בְּצִדּוֹ שֶׁל הַכֹּהֵן, וְיִשְׂרָאֵל מְכַוֵּן לִבּוֹ וּרְצוֹנוֹ לִתְשׁוּבָה שְׁלֵמָה וְנִכְנָע לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, וְזֶה נוֹטֵל הַכֹּל וּמִתְכַּפֵּר חֶטְאוֹ, וְנִמְצֵאת שִׂמְחָה בָּעֶלְיוֹנִים וּבַתַּחְתּוֹנִים."]]],[["רִבִּי יְהוּדָה פָּתַח, (תהילים ק״ד:ג׳) הַמְקָּרֶה בַמַּיִם עֲלִיּוֹתָיו וְגוֹ'. קוּדְשָׁא בְּרִיךְ הוּא כַּד בָּרָא עָלְמָא, מִגּוֹ מַיָּא אַפִּיק לֵיהּ, וְסִדֵּר לֵיהּ עַל מַיָּא. מָה עֲבַד. פָּלַג מַיָּא לִתְרֵין. פַּלְגּוּתָא לְתַתָּא, וּפַלְגּוּתָא לְעֵילָּא. וְעָבִיד מִנַּיְיהוּ עוֹבָדִין, מִפַּלְגוּתָא תַּתָּאָה עָבֵד וְתִקֵּן עָלְמָא דָּא, וְסִדֵּר לֵיהּ עַל פַּלְגּוּתָא דָּא, וְאַתְקִין לֵיהּ לְעֵילָּא עָלַיְיהוּ. הֲדָא הוּא דִכְתִיב, (תהילים כ״ד:ב׳) כִּי הוּא עַל יַמִּים יְסָדָהּ. וּפַלְגּוּ אָחֳרָא סַלְקֵיהּ לְעֵילָּא, וְתָקַר בֵּיהּ תִּקְרָאִין עִלָּאִין, הֲדָא הוּא דִכְתִיב הַמְקָרֶה בַמַּיִם עֲלִיּוֹתָיו וְגוֹ'.","וַעֲבַד רָקִיעַ בֵּין תְּרֵין פַּלְגּוּתַיָּא אִלֵּין, הֲדָא הוּא דִכְתִיב (בראשית א׳:ו׳) יְהִי רָקִיעַ בְּתוֹךְ הַמָּיִם וְגוֹ', וְעָלַיְיהוּ אַתְקִין וְסִדֵּר עִלָּאִין קַדִּישִׁין מִגּוֹ טִיפֵּי טִיפֵּי בְּרוּחָא דְאִתְגַזְרָא בְּבְּסִיטָא (ס\"א בבוצינא) (ס\"א וסדר מלאכי עלאי קדישי, מגו רוחא דאתגזר מפומיה.) דִּכְתִּיב, (תהילים ל״ג:ו׳) וּבְרוּחַ פִּיו כָּל צְבָאָם.","וּבְאִלֵּין אַתְקִין וְסִדֵּר מְזַמְּרֵי תּוּשְׁבַּחְתֵּיהּ בְּיוֹמָא, וְאִתְעָרְבוּ בְּשַׁלְהוֹבֵי אֶשָּׁא. וְאִינּוּן גְדוּדֵי חַיָּילִין, אַמְרִין שִׁירָתָא בְּיוֹמָא, תּוּשְׁבְּחָן בְּצַפְרָא, וּזְמִירָן בְּרַמְשָׁא. כַּד מָטֵי לֵילְיָא, כֻּלְּהוּ פַּסְקֵי שִׁירָתָא. לְעֵילָּא מִנַּיְיהוּ, גְּדוּדִין דְּאֶשָּׁא, בְּשַׁלְהוֹבָא תַּקִּיף, קַיְימִין וּמְרִיחִין אֶשָּׁא דְּאָכְלָא, וְאָהַדְרֵי לְאַתְרַיְיהוּ.","וְאִית בְּסִטְרָא אָחֳרָא, דִּתְהוֹמִין סַלְּקִין אִלֵּין עַל אִלֵּין. וְאִית תְּהוֹמָא עִלָּאָה, וּתְהוֹמָא תַּתָּאָה, וּבְכֻלְּהוּ שָׁארָן מָארֵיהוֹן דְּדִינִין מִסִּטְרָא דְּדִינָא קַשְׁיָא. וְאִית בְּגוֹ סִטְרָא דִּתְהוֹמָא תַּתָּאָה, שַׁלְהוֹבָן דְּאוֹקְדִין זִיקִין נוּרִין, מְמָנָן עַל דִּינִין דְּעָלְמָא, לְאוֹקְדָא לְחַיָּיבַיָּא בְּנוּרָא, דְּנַגְדֵּי מֵהַהוּא נָהָר דִּינוּר. וְכֻלְּהוּ אֶשָּׁא, וְחֵיזוּ דִּלְהוֹן אֶשָּׁא דְּלָהִיט, וְקַיְימִין בֵּין עִלָּאֵי וְתַתָּאֵי.","וְכַד תְּנָנָא דְּמַדְבְּחָא סָלִיק, מִתְעַבְּרָן וְסַלְּקִין מֵהַהוּא דַּרְגָּא, דְּקַיְימִין לְשֵׁיצָאָה וּלְאוֹבָדָא, וְהַהוּא נְגִידוּ דְּאֶשָּׁא תַּקִּיפָא דְּנָהַר דִּינוּר, דְּאִיהוּ תַּקִּיף וְעִלָּאָה, אַהְדָּר לְאַתְרֵיהּ. וְכֻלְּהוּ, מִתְהַנְיָין מִתְּנָנָא דְּמַדְבְּחָא, בְּגִין דְּאִתְתָּקְנַת לָקֳבְלֵי (ס\"א מדבחא) מַלְכָּא עִלָּאָה, וּבְגִין כָּךְ מִתְהַנְיָין מִנֵּיהּ, וְאִינּוּן קְרֵבִין לְהָכָא. וּתְנָנָא אָחֳרָא סָלִיק, וְהָא אוֹקִימְנָא, לְכָל חַד וְחַד, רְעוּתָא דְּכֹלָּא דְּסַלְּקָא לְעֵילָּא, דְּאִיהוּ נַיְיחָא דְּרוּחָא, לְגַבֵּי מַלְכָּא קַדִּישָׁא.","הָא אִתְּמַר, דִּבְמַדְבְּחָא סַלְּקָא וְאִתְחַזֵּי אוּרִיאֵ\"ל, כְּחֵיזוּ דְּחַד אַרְיָא תַּקִּיפָא, רְבִיעַ עַל טַרְפֵיהּ. וַהֲווּ חָמָאן כַּהֲנֵי וְיִשְׂרָאֵל, וְחַדָּאן, דַּהֲווֹ יַדְעִין דְּאִתְקַבַּל בְּרַעֲוָא קָמֵי מַלְכָּא קַדִּישָׁא. וְאֶשָּׁא אָחֳרָא עִלָּאָה קַדִּישָׁא נָחִית, לְקַבְּלָא אֶשָּׁא תַּתָּאָה, כְּדֵין בַּר נָשׁ אָזִיל (נ\"א דחיל) וְאִזְדַּעְזָע קָמֵי מָארֵיהּ, וְתָב בְּתִיּוּבְתָּא שְׁלֵימָתָא.","לְמַלְכָּא דְּשַׁדְּרוּ לֵיהּ דּוֹרוֹנָא, וְאִתְיְישָׁר קָמֵיהּ, אָמַר לְעַבְדֵיהּ, זִיל וְטוֹל דּוֹרוֹן דָּא, דְּאַיְיתִיאוּ לִי. כַּךְ אָמַר קוּדְשָׁא בְּרִיךְ הוּא לְאוּרִיאֵ\"ל, זִיל וְקַבִּיל דּוֹרוֹנָא דִּבְנַי מַקְרִיבִין קָמַאי. כַּמָה חֶדְוָוה מִשְׁתַּכְּחֵי בְּכֹלָּא, כַּמָה בְּסִימוּתָא בְּכֹלָּא מִשְׁתְּכַח, כַּד כַּהֲנָא וְלֵיוָאָה, וְהַהוּא דְּמַקְרִיב קָרְבְּנָא, מְכַוְּונֵי לְקָרְבָא קָרְבְּנָא כְּדְקָא יֵאוֹת, בְּיִחוּדָא שְׁלִים.","תָּא חֲזֵי, כְּתִיב, (ויקרא ט׳:כ״ד) וַתֵּצֵא אֵשׁ מִלִּפְנֵי יְיָ' וַתֹּאכַל עַל הַמִּזְבֵּחַ אֶת הָעוֹלָה וְגוֹ'. דָּא אוּרִיאֵ\"ל, דְּנָחִית בְּחֵיזוּ דְּאֶשָּׁא בְּשַׁלְהוֹבָא, עַד דְּנָחִית לְמַדְבְּחָא, לְקַבְּלָא דּוֹרוֹנָא וְאִתְחַזֵּי כְּאַרְיֵה רַבְרְבָא, רְבִיעַ עַל קָרְבְּנָא.","וְכַד יִשְׂרָאֵל לָא אִשְׁתְּכָחוּ זַכָּאִין, אוֹ הַהוּא דְּמַקְרִיב קָרְבְּנָא לָא קָרִיב כַּדְקָא יָאוּת, וְלָא אִתְקַבָּל קָרְבָּנֵיהּ, הֲווֹ חָמָאן דְּלָא סָלִיק תְּנָנָא בְּאֹרַח מֵישָׁר, וַהֲוָה קָם חַד רוּחָא מִנוּקְבָּא דְּצָפוֹן, וְעָאל לְמַדְבְּחָא, וַהֲווּ חָמָאן דִּיּוּקְנָא דְּחַד כַּלְבָּא חֲצִיפָא, רְבִיעַ עַל קָרְבְּנָא. כְּדֵין הֲווֹ יַדְעֵי דְּלָא אִתְקַבָּל בְּרַעֲוָא הַהוּא קָרְבְּנָא.","לְמַלְכָּא דְּשַׁדְּרוּ לֵיהּ דּוֹרוֹן, חָמָא לֵיהּ מַלְכָּא דְּלָאו אִיהוּ כְּדַאי לְקָרְבָא קַמֵּיהּ, אָמַר מַלְכָּא, אֲסִיקוּ הַהוּא דּוֹרוֹנָא, וְהָבוּ לֵיהּ לְכַלְבָּא, דְּלָאו אִיהוּ כְּדַאי לְאַעֲלָא קָמַאי. כַּךְ בְּשַׁעֲתָא דְּקָרְבְּנָא אִתְקְרִיב, וְלָא אִתְקַבָּל בְּרַעֲוָא, דּוֹרוֹנָא לְכַלְבָּא אִתְמְסַר. וּבְגִין כָּךְ הֲווֹ חָמָאן, דִּיּוּקְנָא דְּכַלְבָּא עַל גַּבֵּי מַדְבְּחָא."],[[0,"ר׳ יהודה פתח וכו׳:","המקרה במים עליותיו וגו'. הקב״ה כשברא העולם, הוציאו מתוך מים, וערך אותו על מים. מה עשה. חילק את המים לב׳ חצאים, מחצה למטה, ומחצה למעלה, ועשה בהם פעולות. ממחצה שלמטה עשה ותקן את העולם הזה, וערך אותו על מחצה הזו, ותקן העולם למעלה ממנה. ז״ש, כי הוא על ימים יסדה. ומחצה האחרת העלה למעלה, וספן עמה תקרות העליונות. ז״ש המקרה במים עליותיו וגו׳."],[1,"ועבד רקיע בין וכו׳:","ועשה רקיע בין שתי המחצות האלו, ז״ש יהי רקיע בתוך המים וגו'. ועליהם תיקן וסידר מלאכים עליונים קדושים מתוך הרוח שנגזר מפיו, שכתוב. וברוח פיו כל צבאם."],[2,"ובאלין אתקין וסדר וכו׳:","ובאלו המלאכים תיקן וסידר מזמרי שבחיו ביום. והם מתערבים בלהבות אש. ואלו גדודי צבאות, אומרים שירה ביום, תשבחות בבקר, וזמירות בערב. כשמגיע הלילה כולם פוסקים מלומר שירה. אלא מלאכים אחרים אומרים שירה בלילה, כי אלו שביום אינם מזמרים בלילה (כנ״ל תרומה אות צ״ג) למעלה מהם, יש גדודי אש העומדים בשלהבת חזקה, ומריחים אש אוכלה, וחוזרים למקומם."],[3,"ואית בסטרא אחרא וכו׳:","ויש בצד האחר, דהיינו בקליפות, שהתהומות עולים אלו על אלו, ויש תהום עליון, שהוא בינה דקליפות, ויש תהום תחתון, שהוא מלכות דקליפות, ובכולם שוכנים בעלי הדין מצד הדין הקשה. ויש בתוך בחינת תהום התחתון, שלהבות השורפות ניצוצי אש, הממונים על דיני העולם, לשרוף הרשעים באש הנמשכת מנהר דינור. וכולם אש, ומראה שלהם אש לוהטת, ועומדים בין עליונים לתחתונים."],[4,"וכד תננא דמדבחא וכו׳:","וכשעשן המזבח עולה, נעברים ונאבדים, אלו מלאכי חבלה הנ״ל, ממדרגה ההיא, דהיינו מתהום התחתון, העומדים לכלות ולהאביד, ואותה הנזילה של אש חזק מנהר דינור, שהוא חזק ועליון, חוזרת למקומה. וכולם, דהיינו כל החיצונים, נהנים מעשן המזבח, משום שנתקן כנגד מזבח העליון, וע\"כ נהנים ממנו. והם קרבים לעשן הזה. והוא עשן אמורים ופדרים דמתאכלי בלילה, שמהם נזונים החיצונים. (כנ״ל תרומה רע״ז). ועשן אחר עולה. וכבר העמדנו (תרומה אות רע״ז) שהוא העשן העולה מן הקרבנות ביום, שהוא לקדושה. כי לכל אחד ואחד מזין העשן, הן לקדושה והן לסטרא אחרא, והוא רצון הכל העולה למעלה, מפני שהוא נחת רוח אל המלך הקדוש."],[5,"הא אתמר דבמדבחא וכו׳:","הנה למדנו, שבמזבח עולה ונראה אוריאל, כמראה אריה גבור הרובץ על טרפו, והיו כהנים וישראל רואים ושמחים, שהיו יודעים שקרבנם נתקבל ברצון לפני המלך הקדוש. ואש אחר עליונה וקדושה, ירדה מלמעלה, שהיא המלאך אוריאל, כנגד אש התחתונה שנתנו על המזבח, אז היה האדם הולך ומזדעזע לפני אדונו, ושב בתשובה שלמה."],[6,"למלכא דשדרו ליה וכו׳:","בדומה למלך שהעם שלחו לו מתנה, והיתה רצויה לפניו, אמר לעבדו, לך וקח מתנה זו שהביאו לי. כך אמר הקב״ה למלאך אוריאל. לך וקבל המתנה שבני הקריבו לפני כמה השמחה היתה נמצאת בכל, וכמה מתיקות היתה נמצאת בכל, בשעה שהכהן והלוי ואותו שהקריב הקרבן, היו מכוונים להקריב הקרבן כראוי, ביחוד השלם."],[7,"ת״ח כתיב ותצא וגו׳:","בוא וראה, כתוב, ותצא אש מלפני ה׳ ותאכל על המזבח את העולה וגו'. אש הזו, הוא אוריאל, שירד כמראה אש בשלהבת עד שירד למזבח לקבל המתנה, שהוא הקרבן, והיה נראה כאריה גדול רובץ על הקרבן."],[8,"וכד ישראל לא וכו׳:","וכשישראל לא נמצאו זכאים, או אותו שהקריב הקרבן לא הקריב כראוי, ולא נתקבל קרבנו, היו רואים שהעשן לא היה עולה בדרך ישר, והיה קם רוח אחד מן הנקב של הקליפות שבצפון, ובא אל המזבח, והיו רואים צורה של כלב אחד חצוף רובץ על הקרבן. אז היו יודעים שהקרבן לא נתקבל ברצון."],[9,"למלכא דשדרו ליה וכו׳:","בדומה למלך, ששלחו לו מתנה. ראה אותה המלך שאיננה כדאית להקריבה לפניו, אמר המלך, תסלקו מתנה ההיא, ותנו אותה אל הכלב, כי אינה כדאית להביאה לפני. כך בשעה שהקרבן נקרב, ולא נתקבל ברצון, נמסר הקרבן אל הכלב. ומשום זה היו רואים צורת כלב על המזבח."]],[[0,"","רַבִּי יְהוּדָה פָּתַח, (תהלים קד) הַמְקָרֶה בַמַּיִם עֲלִיּוֹתָיו וְגוֹ'. כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, הוֹצִיא אוֹתוֹ מִתּוֹךְ מַיִם, וְסִדֵּר אוֹתוֹ עַל הַמַּיִם. מֶה עָשָׂה? חִלֵּק אֶת הַמַּיִם לִשְׁנַיִם, מַחֲצִית לְמַטָּה וּמַחֲצִית לְמַעְלָה, וְעָשָׂה מֵהֶם מַעֲשִׂים. מֵהַמַּחֲצִית הַתַּחְתּוֹנָה עָשָׂה וְתִקֵּן אֶת הָעוֹלָם הַזֶּה וְסִדֵּר אוֹתוֹ עַל הַמַּחֲצִית הַזֹּאת, וְתִקֵּן אוֹתוֹ לְמַעְלָה עֲלֵיהֶם, זֶהוּ שֶׁכָּתוּב (שם כד) כִּי הוּא עַל יַמִּים יְסָדָהּ. וְאֶת הַמַּחֲצִית הָאַחֶרֶת הֶעֱלָה לְמַעְלָה וְסִדֵּר בּוֹ אֶת הַתִּקְרוֹת הָעֶלְיוֹנוֹת, זֶהוּ שֶׁכָּתוּב הַמְקָרֶה בַמַּיִם עֲלִיּוֹתָיו וְגוֹ'."],[1,"","וְעָשָׂה רָקִיעַ בֵּין שְׁנֵי הַחֲצָאִים הַלָּלוּ, זֶהוּ שֶׁכָּתוּב (בראשית א) יְהִי רָקִיעַ בְּתוֹךְ הַמָּיִם וְגוֹ'. וַעֲלֵיהֶם תִּקֵּן וְסִדֵּר עֶלְיוֹנִים קְדוֹשִׁים מִתּוֹךְ טִפּוֹת טִפּוֹת בְּרוּחַ שֶׁנִּגְזְרָה בְּתֹאַר (במאור) (וסדר מלאכים עליונים קדושים מתוך רוח שנגזרה מפיו), שֶׁכָּתוּב וּבְרוּחַ פִּיו כָּל צְבָאָם."],[2,"","וּבְאֵלּוּ תִּקֵּן וְסִדֵּר הַמְזַמְּרִים אֶת תִּשְׁבַּחְתּוֹ בַּיּוֹם, וְהִתְעָרְבוּ בְשַׁלְהֲבוֹת אֵשׁ. וְאוֹתָם גְּדוּדֵי הַצְּבָאוֹת אוֹמְרִים שִׁירָה בַּיּוֹם, תִּשְׁבָּחוֹת בַּבֹּקֶר וּזְמִירוֹת בָּעֶרֶב. כְּשֶׁמַּגִּיעַ הַלַּיְלָה, כֻּלָּם מַפְסִיקִים אֶת הַשִּׁירָה. מֵעֲלֵיהֶם גְּדוּדֵי אֵשׁ בְּשַׁלְהֶבֶת חֲזָקָה עוֹמְדִים וּמְרִיחִים אֵשׁ אוֹכֶלֶת, וְחוֹזְרִים לִמְקוֹמָם."],[3,"","וְיִשִׁ בַּצַּד הָאַחֵר שֶׁתְּהוֹמוֹת עוֹלִים אֵלּוּ עַל אֵלּוּ, וְיֵשׁ תְּהוֹם עֶלְיוֹן וּתְהוֹם תַּחְתּוֹן, וּבְכֻלָּם שׁוֹרִים בַּעֲלֵי הַדִּינִים מִצַּד שֶׁל הַדִּין הַקָּשֶׁה. וְיֵשׁ בְּתוֹךְ צַד הַתְּהוֹם הַתַּחְתּוֹן שַׁלְהָבוֹת שֶׁשּׂוֹרְפוֹת זִיקִים שֶׁל אֵשׁ הַמְמֻנִּים עַל דִּינֵי הָעוֹלָם, לִשְׂרֹף אֶת הָרְשָׁעִים בְּאֵשׁ שֶׁיּוֹצֵאת מֵאוֹתוֹ נְהַר דִּינוּר. וְכֻלָּם אֵשׁ, וּמַרְאֵיהֶם אֵשׁ לוֹהֶטֶת, וְעוֹמְדִים בֵּין עֶלְיוֹנִים וְתַחְתּוֹנִים."],[4,"","וּכְשֶׁעוֹלֶה עֲשַׁן הַמִּזְבֵּחַ, עוֹבְרִים וְעוֹלִים מֵאוֹתָהּ דַּרְגָּה, שֶׁעוֹמְדִים לְכַלּוֹת וּלְהַאֲבִיד, וְאוֹתוֹ זֶרֶם שֶׁל שֶׁל אֵשׁ חֲזָרָה שֶׁל נְהַר דִּינוּר, שֶׁהוּא תַקִּיף וְעֶלְיוֹן, חוֹזֵר לִמְקוֹמוֹ, וְכֻלָּם נֶהֱנִים מֵעֲשַׁן הַמִּזְבֵּחַ, מִשּׁוּם שֶׁנִּתְתַּקֵּן כְּנֶגֶד (המזבח) הַמֶּלֶךְ הָעֶלְיון, וּמִשּׁוּם כָּךְ הֵם נֶהֱנִים מִמֶּנּוּ, וְהֵם קְרֵבִים לְכָאן. וְעָשָׁן אַחֵר עוֹלֶה, וַהֲרֵי בֵּאַרְנוּ, לְכָל אֶחָד וְאֶחָד, הָרָצוֹן שֶׁל הַכֹּל שֶׁעוֹלֶה לְמַעְלָה, שֶׁהוּא נַחַת רוּחַ לַמֶּלֶךְ הַקָּדוֹשׁ."],[5,"","הֲרֵי נִתְבָּאֵר שֶׁבַּמִּזְבֵּחַ עוֹלֶה וְנִרְאֶה אוּרִיאֵ\"ל, כְּמוֹ מַרְאֶה שֶׁל אַרְיֵה חָזָק רוֹבֵץ עַל טַרְפּוֹ, וְהָיוּ הַכֹּהֲנִים וְיִשְׂרְאֵלִים רוֹאִים וּשְׂמֵחִים, שֶׁהָיוּ יוֹדְעִים שֶׁהִתְקַבֵּל בְּרָצוֹן לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, וְאֵשׁ אַחֶרֶת עֶלְיוֹנָה קְדוֹשָׁה יוֹרֶדֶת כְּנֶגֶד הָאֵשׁ הַתַּחְתּוֹנָה, וְאָז אָדָם הוֹלֵךְ (ירא) וּמִזְדַּעֲזֵעַ לִפְנֵי אֲדוֹנוֹ וִשָׁב בִּתְשׁוּבָה שְׁלֵמָה."],[6,"","לְמֶלֶךָֹ שֶׁשָּׁלְחוּ לוֹ דּוֹרוֹן, וְהָיָה מְקֻבָּל לְפָנָיו. אָמַר לְעַבְדּוֹ, לֵךְ וְטֹל אֶת הַדּוֹרוֹן הַזֶּה שֶׁהֵבִיאוּ לִי. כָּךְ אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְאוּרִיאֵל, לֵךְ וְקַבֵּל אֶת הַדּוֹרוֹן שֶׁבָּנַי מַקְרִיבִים לְפָנַי. כַּמָּה שִׂמְחָה נִמְצֵאת בַּכֹּל, כַּמָּה הִתְבַּשְּׂמוּת נִמְצֵאת בַּכֹּל, כְּשֶׁהַכֹּהֵן וְהַלֵּוִי וְאוֹתוֹ שֶׁמַּקְרִיב קָרְבָּן מְכַוְּנִים לְהַקְרִיב קָרְבָּן כָּרָאוּי בְּיִחוּד שָׁלֵם."],[7,"","בֹּא רְאֵה, כָּתוּב וַתֵּצֵא אֵשׁ מִלִּפְנֵי ה' וַתֹּאכַל עַל הַמִּזְבֵּחַ אֶת הָעֹלָה וְגוֹ'. זֶה אוּרִיאֵ\"ל, שֶׁיּוֹרֵד בְּמַרְאֶה שֶׁל אֵשׁ בְּשַׁלְהֶבֶת, עַד שֶׁיּוֹרֵד לַמִּזְבֵּחַ לְקַבֵּל אֶת הַדּוֹרוֹן, וְנִרְאֶה כְּמוֹ אַרְיֵה גָּדוֹל רוֹבֵץ עַל הַקָּרְבָּן."],[8,"","וּכְשֶׁיִּשְׂרָאֵל לֹא נִמְצְאוּ צַדִּיקִים, אוֹ שֶׁאוֹתוֹ מַקְרִיב הַקָּרְבָּן לֹא הִקְרִיב כָּרָאוּי וְלֹא הִתְקַבֵּל קָרְבָּנוֹ, הָיוּ רוֹאִים שֶׁהֶעָשָׁן לֹא עוֹלֶה בְדֶרֶךְ יְשָׁרָה, וְהָיְתָה עוֹמֶדֶת רוּחַ אַחַת מִנֶּקֶב הַצָּפוֹן וְנִכְנֶסֶת לַמִּזְבֵּחַ, וְהָיוּ רוֹאִים דְּיוֹקָן שֶׁל כֶּלֶב אֶחָד חָצוּף רוֹבֵץ עַל הַקָּרְבָּן, וְאָז הָיוּ יוֹדְעִים שֶׁלֹּא הִתְקַבֵּל בְּרָצוֹן אוֹתוֹ הַקָּרְבָּן."],[9,"","לְמֶלֶךְ שֶׁשָּׁלְחוּ לוֹ דּוֹרוֹן, רָאָה אוֹתוֹ הַמֶּלֶךְ שֶׁאֵינוֹ כְדַאי לְקָרְבוֹ לְפָנָיו. אָמַר הַמֶּלֶךְ, סַלְּקוּ אֶת אוֹתוֹ הַדּוֹרוֹן וּתְנוּ אוֹתוֹ לַכֶּלֶב, שֶׁאֵינוֹ כְדַאי לְהִכָּנֵס לְפָנַי. כָּךְ בְּשָׁעָה שֶׁנִּקְרַב הַקָּרְבָּן וְלֹא הִתְקַבֵּל בְּרָצוֹן, הַדּוֹרוֹן נִמְסַר לַכֶּלֶב, וּמִשּׁוּם כָּךְ הָיוּ רוֹאִים אֶת דְּיוֹקַן הַכֶּלֶב עַל גַּבֵּי הַמִּזְבֵּחַ."]]],[["תָּא חֲזֵי כְּתִיב (ויקרא ט׳:כ״ד) וַתֵּצֵא אֵשׁ מִלִּפְנֵי יְיָ' וַתֹּאכַל עַל הַמִּזְבֵּחַ אֶת הָעוֹלָה. אָמַר רִבִּי יְהוּדָה, דָּא אוּרִיאֵ\"ל, דְּאִתְחֲזֵי בְּשַׁלְהוֹבִיתָא דְּאֶשָּׁא עַל מַדְבְּחָא, כְּמָה דְּאִתְּמַר רְבִיעַ עַל קָרְבְּנָא. וּכְדֵין חֶדְוָותָא הֲוָה בְּכֹלָּא, דְּהָא אִתְקַבָּל בְּרַעֲוָוא, כְּמָה דִּכְתִּיב, וַיֵּרָא כְבוֹד יְיָ' אֶל כָּל הָעָם. וְאִי לָא הֲוָה עִרְבּוּבְיָא דִּבְנֵי אַהֲרֹן, מִן יוֹמָא דְּנָפְקוּ יִשְׂרָאֵל מִמִּצְרָיִם, לָא אִשְׁתְּכַח רַעֲוָא הָכִי לְעֵילָּא וְתַתָּא.","\u0003רעיא מהימנא\u0004 פִּקּוּדָא דָּא לִשְׂרוֹף קֳדָשִׁים בְּאֵשׁ. וַאֲבַתְרֵיהּ וְהַנּוֹתָר מִבְּשַׂר הַזָּבַח בַּיּוֹם הַשְּׁלִישִׁי בָּאֵשׁ יִשָּׂרֵף. תָּנָאִין וְאָמוֹרָאִין. בְּסִתְרֵי תּוֹרָה, אִית קֹדֶשׁ, וְאִית קֳדָשִׁים, וְאִית קֹדֶשׁ קֳדָשִׁים. מַה הֲנָאָה אִית לְּקוּדְשָׁא בְּרִיךְ הוּא בַּקֳדָשִׁים דְּאִתּוֹקָדוּ. אִי תֵּימָא בְּגִין יִצְּחָק, דִּבְשַׁעֲתָא דְּיִשְׂרָאֵל בְּעָקוּ, סָלִיק אֲפָרוֹ שֶׁל יִצְּחָק קַמֵּיהּ, דְּאִי חַיָּיבִין שְׂרֵיפָה אִשְׁתֵּזִיבוּ בְּגִינֵיהּ. הַאי לִדְּרָשָׁא אִיהוּ. וְאִי תֵּימְרוּן בְּגִין (צדיקייא) (נ\"א ואי בגין) בְּנֵי אַהֲרֹן דַּהֲווֹ שְׂרֵיפַת קֳדָשִׁים, דִּכְתִּיב בְּהוֹן וַתֵּצֵּא אֵשׁ מִלִּפְנֵי יְיָ' וַתֹּאכַל אוֹתָם וַיָמוּתוּ. וּמִיתַתְהוֹן כַּפָּרָה לְיִשְׂרָאֵל כְּמוֹ שְׂרֵיפַת קֳדָשִׁים, אוּף דָּא לִדְּרָשָׁא קָא אָתֵי.","אֶלָּא, תְּלַת אֶשִּׁין בִּשְׁרָגָא: אֶשָּׁא חִוָּורָא, וְאֶשָּׁא אוּכָמָא, וְאֶשָּׁא תְּכֶלְתָּא. לָקֳבֵל: תּוֹרָה, נְבִיאִים, וּכְתוּבִים. לָקֳבֵל: כֹּהֵן, לֵוִי, וְיִשְׂרָאֵל. וּתְכֵלֶת אִיהִי שְׁכִינְתָּא, קְרִיבָא לָן, וְאִיהִי אֲחִידָא בְּאִינּוּן פְּתִילוֹת, בְּכַנְפֵי מִצְּוָה, דְּאִתְּמַר בְּהוֹן וְעָשׂוּ לָהֶם צִּיצִּית. וְהַאי תְּכֵלֶת דְּאִיהִי שְׁכִינְתָּא, אִיהִי דִּינָא, דַּאֲכִילַת קָרְבָּנִין וְעִלָּוָון.","אִי אַשְׁכָּחַת בְּנֵי נָשָׁא, דְּאִינּוּן עֵצִּים יְבֵשִׁים, כְּגַוְונָא דְּאִינּוּן פְּתִילוֹת יְבֵשִׁין, בְּלָא מִשְׁחָא, דְּאִיהִי אוֹרַיְיתָא רַחֲמֵי, אִיהִי לוֹן (דלידונון) שְׂרֵיפָה, וְאוֹקִידַת לוֹן. וּבְגִין דְּעַמֵי הָאָרֶץ אִינּוּן בְּעִירָן, כְּמָה דְּאוּקְמוּהָ דְּאִינּוּן שֶׁקֶץ. תְּכֵלֶת, דְּאִיהִי אֲדֹנָי, אוֹקִידַת לוֹן, בְּגִין דְּקָרְבִין לְגַבָּהּ עִם שֶׁרֶץ, דְּאִיהוּ יֵצֶּר הָרָע, זָר, הֲדָא הוּא דִכְתִיב, (במדבר ג׳:י׳) וְהַזָּר הַקָּרֵב יוּמָת.","וְאִי בְּמִיתָתְהוֹן חַזְרִין בְּתִיּוּבְתָּא, (נ\"א כד שחיט לון מלאך המות מיכאל) מַלְאָךְ מִיכָאֵל דְּאִיהוּ כַּהֲנָא רַבָּא, אַרְיֵה דְּאָכִיל קָרְבְּנִין, נָחִית עָלַיְיהוּ, לְקָרְבָא לוֹן קָרְבְּנָא קֳדָם יְיָ'.","וְקֹדֶם דְּתִפּוּק נִשְׁמָתֵיהּ, מִתְוַודֶּה בְּכַמָּה וִדוּיִין, וְכַד נָפִיק נִשְׁמָתֵיהּ הוּא הֲוָה מִתְכַּוִון לִגְמוֹר אֶת הַשֵׁם, שְׁמַע יִשְׂרָאֵל וּבָרוּךְ שֵׁם, לְקָרְבָא נִשְׁמָתֵיהּ מָאנָא (נ\"א קרבנא) לְשֵׁם יְהוָֹ\"ה, וְצָּרִיךְ לְמִתְוַדֶּה לְקוּדְשָׁא בְּרִיךְ הוּא, לְקַבֵּלָא לְקָרְבָא ה' בִּשְׁמֵיהּ, דְּאָכִיל וְשֵׁצֵּי, וּלְאַחְזְרָה בְּתִיּוּבְתָּא לְגַבֵּי יה\"ו, אֶהְיֶ\"ה כְּחוּשְׁבָן מ\"ב. דַּאֲדֹנָי קָרֵינָא לֵיהּ דִּינָא דְּמַלְכוּתָא דִּינָא.","וִיכַוִּון בִּשְׁמָא מְפֹרָשׁ, דְּאִיהוּ יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א, בְּלֵּב אֶחָד. וּבֵיהּ יִפּוֹק רוּחֵיהּ. בְּנֶפֶשׁ דִּילֵיהּ מְקַבֵּל עָלֵיהּ מִיתָה וְיִסוּרִין. וּבְנִשְׁמְתָא מוֹדֶה בְּכַמָּה וִדוּיִין וּמִתְחָרֵט.","בְּנֶפֶשׁ מְקַבֵּל עָלֵיהּ מִיתָה שְׁחִיטָה שְׂרֵיפָה, וְאִי צָּרִיךְ ד' מִיתוֹת בֵּית דִּין, דְּאִינּוּן סְקִילָה שְׂרֵיפָה הֶרֶג וְחֶנֶק, מְקַבֵּל לֵיהּ מֵאֲדֹנָ\"י בְּנֶפֶשׁ דִּילֵיהּ. וּבְנִשְׁמָתֵיהּ מוֹדֶה בְּכַמָּה וִידוּיִין, וְחוֹזִר בְּתִיּוּבְתָּא לְגַבֵּי אֶהְיֶ\"ה, דְּאָחִיד בִּתְרֵין שְׁמָהָן, יְהוָֹ\"ה יְהוָֹ\"ה.","בְּמַחֲשַׁבְתֵיהּ יְכַוִין לְאַפָּקָא ודּוּי, וְקַבָּלַת מִיתָה עָלֵיהּ, בְּלֵּב א', דְּאִיהוּ שְׁמָא מְפֹרָשׁ, כְּגַוְונָא דָּא יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. (כבוד) בֵּיהּ כֹּהֲנִים כּוֹרְעִים וּמִשְׁתַּחֲוִים עַל פְּנֵיהֶם, וְאוֹמְרִים בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד. כָּבוֹד, אִיהוּ ל\"ב בְּחוּשְׁבָּן. וּבֵיהּ הָיָה מִתְכַּוִּין לִגְמוֹר אֶת הַשֵׁם. (וא\"ו איהו א' בלב).","וְתַנָאִין וְאָמוֹרָאִין, אִי תֵּימְרוּן וְכִי עַם הָאָרֶץ מְנָא יָדַע דָּא. אֶלָּא וַדַּאי עַם הָאָרֶץ אִיהוּ כְּשׁוֹר, אוֹ שֶׂה, אוֹ עֵז, אוֹ (פר) תּוֹר, אוֹ יוֹנָה. מַה בְּעִירָן לָא יַדְעֵי אוֹרַיְיתָא, דְּאִיהִי שֵׁם יְדוָֹ\"ד. הָכִי עַם הָאָרֶץ, לָא יָדַע. אֶלָּא מִיכָאֵל כַּהֲנָא רַבָּא, אִיהוּ עָבִיד לֵיהּ עוֹלָה וְקָרְבְּנָא קֳדָם יְיָ', וְאִיהוּ מְכַוְּון בִּשְׁמָא מְפֹרָשׁ, בִּסְלִיקוּ דְּרוּחֵיהּ, דְּתִפוּק בְּלֵּב אֶחָד, כְּגַוְונָא דְּכַד נָפִיק רוּחָא דְּבַּר נָשׁ בְּכָל לֵילְיָא.","וּבְגִין דָּא אוּקְמוּהָ רַבָּנָן, שׁוּב יוֹם א' לִפְנֵי מִיתָתָךְ, דִּבְכָל יוֹם וְיוֹם צָּרִיךְ בַּר נָשׁ לְאָהַדְרָא בְּתִיּוּבְתָא, וּלְמִמְסַר רוּחֵיהּ לְגַבֵּיהּ, דְּיִפוּק בְּאֶחָד, הֲדָא הוּא דִכְתִיב, (תהילים ל״א:ו׳) בְּיָדְךָ אַפְקִיד רוּחִי.","וְאִם הוּא תַּלְמִיד חָכָם, עָלֵיהּ אִתְּמַר (משלי י״ב:י׳) יוֹדֵעַ צַּדִּיק נֶפֶשׁ בְּהֶמְתּוֹ דְּלֵית חָכָם, כְּמוֹ כַּהֲנָא. כְּמָה דְּאוּקְמוּהָ הָרוֹצֶּה לְהַחְכִּים יַדְרִים. וְאִם תַּלְמִיד חָכָם הוּא, צָּרִיךְ שֶׁיְּהֵא בֵּיהּ חֶסֶד, וְעִם י' דְּאִיהוּ חָכְמָה, חָסִיד. וּמַאן דְּלֵית בֵּיהּ חָכְמָה, לָאו אִיהוּ חָסִיד. וּבְגִין דָּא אוּקְמוּהָ, וְלֹא עַם הָאָרֶץ חָסִיד. וְאִי אִית בֵּיהּ ה', חַמְשָׁה חוּמָשֵׁי תּוֹרָה, דְּאִתְיְיהִיבוּ מִשְּׂמָאלָא, אִתְקְרֵי גִּבּוֹר בַּתּוֹרָה, וִירֵא חֵטְא. וְאִי אִיהוּ בּוּר, אִתְּמַר בֵּיהּ, אֵין בּוּר יְרֵא חֵטְא."],[[0,"ת״ח כתיב ותצא וכו׳:","בוא וראה, כתוב, ותצא אש מלפני ה׳ ותאכל על המזבח את העולה. אמר ר׳ יהודה, זה הוא אוריאל, שנראה כשלהבת אש על המזבח. כמו שלמדנו, שהיה רובץ על הקרבן. ואז השמחה היתה בכל, כי נתקבל ברצון. כמ״ש, וירא כבוד ה׳ אל העם. ואם לא היה, ביום הזה, הבלבול של מיתת בני אהרן, הנה מיום שיצאו ממצרים לא היתה נמצאת נחת רוח כזו למעלה ולמטה."],[1,"פקודא דא לשרוף וכו׳:","מצוה זו היא לשרוף קדשים באש. ואח״כ והנותר מבשר הזבח ביום השלישי באש ישרף. תנאים ואמוראים: בסתרי תורה, יש קדש ויש קדשים ויש קדש הקדשים, שואל מה הנאה יש להקב\"ה מן הקדשים שנשרפו. אם תאמר, בשביל יצחק, שבשעה שישראל בצרה, עולה לפניו אפרו של יצחק, וע״כ צריכים לשרוף הקרבן עד אפר להזכיר זכותו, שאם חייבים שרפה יהיו נצולים בשבילו. זהו בא רק לדרש. ואם תאמר בשביל בני אהרן שהיו כמו שריפת קדשים, שכתוב בהם, ותצא אם מלפני ה׳ ותאכל אותם וימותו. ומיתתם היא כפרה לישראל כמו שריפת קדשים. גם זה הוא רק דרש."],[2,"אלא תלת אשין וכו׳:","ומשיב, אלא שלש אשות בגר, אש לבן אש שחור, אש תכלת, כנגד תורה נביאים כתובים, וכנגד כהן לוי ישראל, ותכלת היא השכינה שהיא קרובה לנו, שהיא שורה על התחתונים. והיא נאחזת באלה הפתילות, שהם כנפי מצוה, שנאמר בהם, ועשו להם ציצית, ותכלת זו שהיא השכינה היא דין, שאוכלת קרבנות ועולות."],[2,"","ביאור המאמר. נפש רוח נשמה של האדם, נקראים קדשים, הנפש נקראת קודש, והרוח קדשים, והנשמה קדש קדשים. וז״ש, \u0003פקודא דא לשרוף קדשים וכו׳, בסתרי תורה אית קדש ואית קדשים וכו׳\u0004 דהיינו שבסתרי תורה, מתבאר סוד שריפת קדשים, בשריפת נפש רוח נשמה של אדם, שה״ס קדש קדשים, וכו', לפני ה'. ושואל \u0003מה הנאה אית לקב״ה בקדשים דאתוקדו.\u0004 היינו מהי ההנאה שיש להקב״ה, משריפת הנשמות הנקראות קדשים. ומתרץ, \u0003אלא תלת אשין בשרגא\u0004 וכו', שג' אשות אלו הם, \u0003לקבל תורה ונביאים וכתובים\u0004 שאשא חוורא היא כנגד תורה, שהיא ת״ת. ואשא אוכמא היא כנגד נביאים, שהם נצח והוד. ואשא תכלתא היא כנגד כתובים, שהם מלכות. והם \u0003לקבל כהן לוי ישראל,\u0004 שפירושם ג׳ קוין, ימין שמאל ואמצע. ונמצא ש \u0003תורה\u0004 היא כנגד כהן שהוא קו ימין \u0003ונביאים\u0004 הם כנגד לוי, שהוא קו שמאל. \u0003וכתובים\u0004 הם כנגד ישראל, שהם קו האמצעי. ויש להבין הדברים, הרי תורה נביאים וכתובים הם ת״ת, נו״ה ומלכות, שהם זה תחת זה, ואיך תדמה אותם לכהן לוי ישראל, שהם ג׳ קוין, שהימין מול השמאל, והאמצעי, הוא ביניהם, וכולם במדרגה אחת."],[2,"","והענין הוא. שזה דומה, לאו״א וישסו״ת וזו\"ן, שהם ג״כ ג׳ מדרגות זה למטה מזה, ועכ״ז הם נעשים ג׳ קוין במדרגה אחת. כי או״א, בעת שהם מעלים הבינה ותו״מ שלהם, עולה עמהם גם מדרגה התחתונה, שהם ישסו״ת הדבוקים בבינה ותו״מ אלו (כנ״ל בהקסה״ז דף כ׳ ד״ה ואמא) ואלו ישסו״ת העולים לאו״א, נעשים אז קו שמאל לאו״א, ואח״כ בינה ותו״מ דישסו״ת שעלו לישסו״ת, כבר העלו עמהם גם הם את מדרגה התחתונה שלהם שהם זו״ן, למקום ישסו״ת שהוא עתה באו״א, ונמצאים כל ג׳ המדרגות שהיו מתחילה זו תחת זו, שהם עתה בחינת ג׳ קוין במדרגה אחת, שאו״א הם מקו ימין, וישסו״ת הם קו שמאל, וזו״ן הם קו אמצעי. ועל דרך זה ממש, נעשו תורה נביאים וכתובים לג׳ קוים. כי בעת שת\"ת שה\"ס תורה, העלו בינה ותו״מ שלהם, עלו עמהם גם המדרגה התחתונה שלו, שה״ס נו״ה, שה״ס נביאים, למקום הת״ת, ונעשו קו שמאל שלו. ואלו נו״ה בעת שהעלו בינה ותו״מ שלהם, עלתה עמהם גם המלכות לנצח והוד, שהם עתה בת״ת ונמצא עתה שהם שלשתם במקום ת״ת, ונעשו ג׳ קוין, שת\"ת הוא קו ימין, ונו״ה קו שמאל, והמלכות קו אמצעי. אמנם יש לדעת כאן, הכלל, שאין מלכות בלי יסוד, וע״כ אע״פ שכתובים הם מלכות כוללת המלכות גם יסוד, באפן, שיסוד ומלכות נעשו לקו אמצעי לת״ת ונו״ה, ע״ד הזו״ן שנעשו קו אמצעי לאו״א וישסו״ת. וכדי להעיר את זה, מדייק הרעיא מהימנא ואמר, \u0003שג׳ אשות\u0004 לבן שחור ותכלת אע״פ שהם זה תחת זה, כמו \u0003תורה נביאים וכתובים\u0004 מכל מקום הם ג׳ קוין כמו \u0003כהן לוי ישראל.\u0004"],[2,"","והנה אור הנר בכללו, הוא אור המלכות. כי המלכות נקראת נר. אלא כמו שאנו אומרים בז״א, שהוא כולל כל ג׳ קוין דבינה, מטעם, כיון דתלת מחד נפקי, חד בתלת קיימא (כנ״ל ב״א דף רפ״ז ד״ה תלת) אף המלכות אחר שנעשתה לקו אמצעי, בין תורה לנביאים, שה״ס ימין ושמאל, הרי גם המלכות כוללת אותם. אשר אש הלבן ה״ס קו ימין. ואש השחור ה״ס קו השמאל. ואש התכלת ה״ס קו האמצעי. אבל התכלת, שהיא עצם המלכות שנעשתה לקו אמצעי, כוללת בתוכה גם יסוד, כנ״ל, והיסוד הכלול בה הוא בחינת ימין שבתכלת, והמלכות עצמה ה״ס השמאל. ומבחינה זו, אע״פ שאנו אומרים שהתכלת הוא קו אמצעי, עכ״ז היא בחינת קו שמאל, מטעם היותה כלול מימין ושמאל, אשר הימין ה״ס היסוד, ועצם המלכות, שהיא התכלת, ה״ס שמאל, כמבואר."],[2,"","פירוש. כי הביא ב׳ פקודין בשריפת קדשים, שהם לשרוף הקדשים על המזבח, ולשרוף הנותר ממנו עד יום השלישי. ואלו ב׳ מיני שריפות נוהגים גם בנשמות. ושריפת הנותר יורה על בחינות הדינים שהם נקראים מנעולא ומפתחא שהם בחינות המסך דחירק, וכמו כן הם עולים מחמת חטאי התחתונים, ומתדבקים במלכות, שה״ס תכלת. אשר אז התכלת שורפתם ומבטלת אותם. וז״ס \u0003שריפת נותר.\u0004 ויש גם בחינת \u0003שריפת קדשים\u0004 על המזבח, דהיינו שריפת הנשמות, בסוד שהמלאך מיכאל עומד ומקריב אותם, על המזבח של מעלה. ואלו ב׳ מיני שריפות הולך ומבאר לפנינו."],[3,"אי אשכחת בני נשא וכו':","אם המלכות, שה״ס תכלת, מוצאת בני אדם. שהם עצים יבשים, כמו פתילות יבשים בלי שמן, שהיא התורה, ורחמים, המלכות, היא להם שרפה, ושורפת אותם. ומשום שעמי הארץ הם בהמות, כמו שהעמדנו שהם שקץ, התכלת, שהיא השם אדנ\"י, דהיינו מלכות, שורפת אותם, משום שקרבים אליה עם שרץ, שהוא יצר הרע, וזר. ז״ש והזר הקרב יומת."],[4,"ואי במיתתהון חזרין וכו':","ואם חוזרים בתשובה לפני מיתתם, כשמלאך מיכאל שוחט אותם, שהוא כהן גדול שהוא האריה האוכל קרבנות, יורד עליהם להקריב אותם קרבן לפני ה'."],[5,"וקדם דתפוק נשמתיה וכו':","ומטרם שיוצאת נשמתו, הוא מתודה בכמה וידוים, וכשיוצאת נשמתו, הוא היה מתכוין לגמור את השם, דהיינו להשלים יחוד המלכות שנקראת, שם, ביחוד, \u0003שמע ישראל,\u0004 שהוא יחוד ז״א, \u0003וברוך שם,\u0004 וכו', שהוא יחוד המלכות, לקרב נשמתו קרבן לשם הויה. וצריך להתודות להקב״ה, שיקבל ויקרב ה \u0003ה׳\u0004 השורפת ומכלה, שהיא המלכות, לשמו הויה, ולהחזיר בתשובה, ה \u0003ה׳\u0004 אל יה״ו אהיה, שהם כחשבון מ״ב, כלומר להשיב ה \u0003ה׳\u0004 ליה״ו, ויהיה היחוד העליון שבבינה הוי״ה אהיה, שהויה הוא חכמה ואהיה הוא בינה. כי מטרם שנשלם היחוד, קוראים להמלכות, אדני, שבהם אותיות דין, להורות על סוד דינא דמלכותא דינא. והיחוד הויה אהיה אינו שלם."],[6,"ויכוון בשמא מפרש וכו':","ויכוון בשם המפורש, שהוא יוד הא ואו הא, דהיינו הויה במילוי אלפין שהוא ז״א, שיתייחד בלב אחד, שהוא מלכות הנקראת לב. ובו יכוון כשמוציא את \u0003רוחו,\u0004 ובנפש שלו, מקבל עליו מיתה ויסורין. ובנשמה שלו, מתודה בכמה וידוים ומתחרט."],[7,"בנפש מקבל עליה וכו׳:","ומפרש דבריו. בנפש הוא מקבל עליו מיתה שחיטה שריפה. ואם צריך ארבע מיתות בית דין, שהם סקילה שריפה הרג וחנק, מקבלם על הנפש שלו, מאדני. ובנשמתו, הוא מתודה בכמה וידוים, וחוזר בתשובה אל השם אהיה שהוא בינה, הנאחז בב׳ שמות הויה הויה, כי החכמה נקראת הויה, כנ״ל בסוד היחוד הויה אהיה, וכן ז״א נקרא הויה. והבינה מקבלת מחכמה ומשפעת לז״א, ונמצאת נאחזת בין שניהם."],[8,"במחשבתיה יכוון לאפקא וכו׳:","ויכוון במחשבתו להוציא מפיו וידוי, וקבלת מיתה עליו בלב אחד, דהיינו שייחד המלכות הנקראת לב בסוד היחוד של הויה אחד, שהוא שם המפורש כעין זה, יוד הא ואו הא, דהיינו הויה במילוי אלפין שה״ס ז״א, שבו הכהנים כורעים ומשתחוים ונופלים על פניהם ואומרים ברוך שם כבוד מלכותו לעולם ועד. כבוד, הוא בחשבון ל״ב, שהיא המלכות הנקראת לב. ובו היה מתכוין לגמור את השם, דהיינו לגמור היחוד של מלכות עם הויה."],[9,"ותנאין ואמוראין וכו׳:","ותנאים ואמוראים, אם תאמרו, וכי עם הארץ מאין יודע זה. כל אלו הכונות. ומשיב, אלא ודאי עם הארץ הוא כשור, או שה, או עז, או תור, או יונה, המוקרבים על המזבח, מה הבהמות אינן יודעות תורה, שהיא שם הויה, כך עם הארץ אינו יודע, אלא מיכאל כהן גדול, הוא עושה אותו עולה וקרבן לפני ה', והוא מכוון בשם המפורש בעלית רוחו שיצא רוחו בלב אחד, ובכל אלו הכוונות הנ״ל, כמו שרוח האדם עולה בכל לילה. דהיינו שעולה למ\"ן אל המלכות."],[10,"ובגין דא אוקמוה וכו׳:","ומשום זה העמידו רבנן, שוב יום אחד לפני מיתתך, כי בכל יום ויום צריך האדם לחזור בתשובה ולמסור רוחו אליו, שיצא באחד, ז״ש, בידך אפקיד רוחי."],[10,"","ביאור המאמר. כי נתבאר לעיל (באות קל״ו בהסולם ד״ה פירוש) שהרע״מ מבאר לפנינו ב׳ מיני שריפות א) שריפת נותר, שה״ס נקודת המנעולא, דהיינו מלכות דמדת הדין שעולה ונגלה במלכות הממותקת מחמת חטאי התחתונים, בסוד לא זכה הא רע. (כנ״ל ויצא י״ג ד״ה סתרא) אשר התכלת, שהיא המלכות הנאחזת בה, שורפת אותם. וז״ש (באות קל״ז) \u0003אי אשכחת בני נשא דאינון וכו' פתילות יבשות בלא וכו׳ רחמי.\u0004 דהיינו עם הארץ החוטא כל ימיו עד שנגלה עליו בשורשו שבמלכות, הדינים דמלכות דמדת הדין, שהיא בלי רחמים, כלומר שאינה נמתקת בבינה שהיא מדת הרחמים. \u0003איהי לון שריפה, ואוקידת לון,\u0004 שהיא שורפת הנפש הזאת. \u0003ובגין דעמי הארץ אינון בעירן,\u0004 כלומר שיש להם נפש רוח נשמה מצד הבהמות הטהורות, שהם נמוכים מאד, ע״כ, \u0003תכלת דאיהי אדני אוקידת לון.\u0004 משום שדבוק בהם מדת הדין הקשה דמנעולא, שנקרא יצר הרע, דהיינו מלאך המות שה״ס יצה\"ר, וע״כ נאמר עליו \u0003והזר הקרב יומת.\u0004 אמנם רק הנפש של החוטא נפגמת ונשרפת. אבל רוח ונשמה שלו, אינם נפגמים כלל, אלא מסתלקים לשורשם. והטעם, כי הפגם דנקודת המנעולא, הנמשך מצמצום א', אינו פוגע רק במלכות לבדה, ולא כלום בט״ס ראשונות, וכיון ששורש רוח ונשמה, הם מבינה וז״א, ע״כ אין הפגם נוגע בהם אפילו משהו, אלא שמסתלקים מחמת הכלי הפגום, ועולים לשורשם, אלא הנפש הנמשכת ממלכות עצמה היא הנפגמת ונשרפת. ושריפה זו, ה״ס שריפת נותר (המובא לעיל באות קל״ו)."],[10,"","ועתה מבאר בחינת שריפה הב', שהיא שריפת קדשים, שהוא שריפת נשמות, המובא שם, דהיינו אותו החוטא, שגילה בשורש נשמתו בחינת מדת הדין דמנעולא, שה״ס מלאך המות, כי ממנה נמשכת המיתה (כנ״ל ויצא ט״ז ד\"ה וזהו) אם עושה תשובה בעת מיתתו, ומקבל עליו מיתה ושחיטה ושריפה כדי לעשות נחת רוח להקב\"ה, אז לאחר מיתתו, ממתיקים לו מדת הדין דמנעולא במדת הרחמים, שה״ס בינה, ונודע שיש בעליה זו קטנות וגדלות, שתחילה כשעולה המלכות לבינה מסתלקות הג״ר מבינה, ונשארת בו״ק בלי ראש, ואחריה מתמעטים כל המדרגות (כנ״ל ב״א דף ד׳ ד״ה ביאור) ונמצא שעל ידי זה שממתיקים לו מדת הדין במדת הרחמים דהיינו שהמלכות מבחינת שורשו עולה לבינה שבשורשו, נתמעטו הרוח והנשמה לבחינת ו\"ק בלי ראש. והם היו עד עתה שלמים, כי מדת הדין דמנעולא אינה פוגעת בט\"ס ראשונות שמשם רוח ונשמה, כנ\"ל. והסתלקות הראש מן הרוח והנשמה, נבחנת לשחיטה, כי השחיטה מבדלת הראש מן הגוף. ואדם הזה שעשה תשובה בשעת מיתתו זוכה להמתקת מדת הדין ברחמים, אבל מבחינת הקטנות בלבד, הנבחן כמו שחיטה."],[10,"","וז״ש \u0003ואי במיתתהון חזרין בתיובתא, כד שחיט לון מלאך מיכאל, דאיהי כהנא רבא, אריא דאכיל קרבנין,\u0004 כי המלאך מיכאל שהוא חסד, הנמשך מקו ימין, ומנקודת החולם, ששם נמצאת בחינת הדין הממותק בבינה, במדת הרחמים (כנ״ל ב״א ט״ו ד\"ה ההוא ע״ש) ודין הממותק הזה, ה״ס \u0003אריא דאכיל קרבנין.\u0004 וע״כ נבחר המלאך הזה, שימתיק מדת הדין שלו במדת הרחמים, שממעט הנשמה והרוח, שהיו שלמים, מבחינת ראש, שזה נבחן לשחיטה כנ״ל. וע״כ אומר \u0003כד שחיט לון מלאך מיכאל,\u0004 דהיינו שמעביר מהם בחי׳ הראש, שה״ס הג״ר שלהם. אמנם קטנות זו הנבחנת לשחיטה, מביאה אח״כ את הגדלות, דהיינו, שהמלכות יוצאת מן הבינה וחוזרת למקומה, ונגלים שוב הג״ר בכל המדרגות, (כנ״ל ב״א דף צ׳ ד\"ה בגין) שעי״ז שוב נעשה הזווג של קב״ה ושכינתיה משורש נשמתו. וז״ש, \u0003לקרבא לון קרבנא קדם ה׳,\u0004 כי שחיטה זו נבחנת, שמקריב אותם לקרבן לפני ה', שהם גורמים בזה זווג קב״ה ושכינתיה. שה״ס קרבן. וע״כ נבחן זה שמלאך מיכאל מקריב את הנשמות על המזבח, שה״ס המלכות ושורף אותם מבחינת אריה דאכיל קרבנין, דהיינו דין הממותק דבינה שבסוד נקודת החולם, שעי״ז נשחטים ונשרפים הג״ר של הנשמות על המזבח, ונעשים מ״ן לזו״ן. דהיינו שגורמים שהמלכות תחזור ותקבל הג״ר שלה, לעת הגדלות, ותתיחד עם ז״א, שה״ס קרבן."],[10,"","אמנם זה שעשה תשובה רק בשעת מיתתו, לא יוכל לקבל אחר מיתתו רק את הקטנות הנ״ל בלבד, ועם זה, זכותו גדולה מאוד, כי אם יתגלגל פעם ב׳, ויזכה לעסוק בתורה ועבודה, אז ימשיך הגדלות, ואז יעשה הזווג בין ז\"א ומלכות, כמ״ש לעיל (באות ק״מ) וז״ש, \u0003וכד נפיק נשמתיה הוא הוה מתכוון לגמור את השם, שמע ישראל וברוך שם,\u0004 כי יתכוון שע״י הקרבת נשמתו יזכה לגמור את היחוד של שמע ישראל, שהוא ז״א וברוך שם, שהוא מלכות, שזה יהיה אחד שיתגלגל פעם ב'."],[10,"","אבל ב׳ יחודים יש כאן, כי מצד נשמתו ששורשה הוא בבינה, נבחן היחוד השלם להוי״ה אהיה, שהויה ה״ס חכמה ואהיה ה״ס בינה. ועתה בעת הקטנות, נבחן שחסרה \u0003ה'\u0004 אחרונה להויה, ואין בה אלא \u0003יה״ו\u0004 שיורה שהוא ו\"ק וחסר ג\"ר וז\"ש (באות קל״ט) \u0003וצריך למתודה\u0004 וכו' \u0003לקרבא ה׳\u0004 וכו'. \u0003ולאחזרא בתיובתא לגבי יה״ו אהי״ה,\u0004 דהיינו שיכוון לזכות להגדלות ולגמור את השם, דהיינו שיקרב המלכות שהיא ה׳ אחרונה, אל שם \u0003יה״ו אהי״ה,\u0004 ויהיה יחוד השלם בבינה, \u0003הוי״ה אהי״ה.\u0004 ומצד רוחו, ששורשו הוא בז\"א, נבחן יחוד השלם דגדלות בסוד הויה במילוי אלפין, שהוא ז״א, עם המלכות השלמה שבסוד היחוד של ברוך שם כבוד מלכותו לעולם ועד. וז״ש (באות ק\"מ) \u0003ויכוון בשמא מפרש דאיהו יוד הא ואו הא, בלב אחד. וביה יפוק רוחיה,\u0004 דהיינו שביציאת רוחו, ששורשו בזעיר אנפין יכוון שיזכה לגדלות שאז יהיה היחוד, בהויה דמילוי אלפין, ובלב אחד, דהיינו המלכות שנקראת לב תהיה בסוד שמו אחד. וכמו שאומר (באות קמ״ב) \u0003דאיהו שמא מפרש וכו׳ ביה כהנים כורעים ומשתחוים וכו׳ ואומרים ברוך שם כבוד מלכותו לעולם ועד. ככוד, הוא ל״ב, וביה היה מתכוון לגמור את השם,\u0004 דהיינו שהיה מתכוון לזכות לגדלות ולגמור את השם, בסוד היחוד דהויה דאלפין שהוא ז׳יא והיחוד דברוך שם וכו׳ שהוא המלכות. והנפש שלו, מתדבקת במלכות עצמה, שהיא שורפת אותה ומבטלת הדינין שבה."],[10,"","וז״ש (באות קמ״א) \u0003בנפש, מקבל עליה מיתה, שחיטה, שריפה,\u0004 כי \u0003מיתה\u0004 היא לגוף, שחיטה היא לנשמה ורוח, שמיכאל מעביר מהם הראש ומשאירם ו\"ק בלי ראש הנחשב לשחיטה כנ״ל. \u0003שריפה,\u0004 היא לנפש, שהיא מתדבקת במלכות ונשרפת בסוד התכלת שבה, עד שראויה לתקון הזה דהמתקת המלכות בבינה, ע״י מיכאל. ולפעמים שעונותיו מרובים, הנפש צריכה לקבל על עצמה ארבע מיתות ב״ד מן המלכות, המרומזים בכתוב, \u0003והארץ,\u0004 שהיא המלכות, \u0003היתה תהו ובהו וחשך\u0004 וגו׳ \u0003ורוח\u0004 וגו׳, שתהו, הוא חנק. ובהו, הוא סקילה, וחשך, הוא שריפה, ורוח, הוא הרג (כמ״ש בהקדמת ספר הזהר אות קצ״ו וקצ״ז) וה״ס התהליך והתקון מצמצום א׳ שהוא מדת הדין, לצמצום ב׳ שהוא מדת הרחמים, אשר תהו ובהו, ה״ס צמצום א׳ והמסך שבו, וחשך ורוח, ה״ס צמצום ב׳ והמסך שלו. (כמ״ש לעיל בבראשית א׳ דף כ״ח ד\"ה היתה, ע״ש) ולפיכך כשהחוטא מקבל עליו ארבע מיתות ב״ד קודם מיתתו, מועיל לו, אשר מדת הדין דצמצום א׳ שגילה בחטאיו, תעבור ממנו ותתקן במדת הרחמים שבסוד צמצום ב׳, ע״י המלאך מיכאל כנ״ל. וז״ש, (באות קמ״א) \u0003ואי צריך ארבע מיתות בית דין וכו׳ מקבל ליה מאדני, בנפש דיליה,\u0004 ויועיל לו שמיכאל יקריב נשמתו לפני ה׳, כנ״ל."],[11,"ואם הוא ת״ח וכו׳:","ואם הוא תלמיד חכם, נאמר עליו, יודע צדיק נפש בהמתו, כי אין חכם כמו הכהן, שהוא חסד, כמו שהעמדנו, הרוצה להחכים ידרים. דהיינו שיתדבק בחסד שה״ס דרום. והוא מטעם, כי חסד דז״א בגדלות, נעשה לחכמה. ואם הוא תלמיד חכם, הוא צריך שיהיה בו חסד, ועם \u0003י׳\u0004 שהיא חכמה שבו, הוא \u0003חסיד.\u0004 ומי שאין בו חכמה אינו חסיד. ומשום זה העמידו, ולא עם הארץ חסיד (אבות פ״ב מ״ה) ואם יש בו \u0003ה׳\u0004 ראשונה, בינה, שה״ס חמשה חומשי תורה שניתנו משמאל, נקרא גבור בתורה וירא חטא, דהיינו שזוכה למדת הגבורה, ויש בו \u0003חסד\u0004 שה״ס חסיד, ויש בו \u0003גבורה,\u0004 שמשם ניתנה התורה, וה״ס \u0003י״ה\u0004 כי בגדלות נעשו חסד וגבורה דז״א לחכמה ובינה. ואם הוא בור, שאין בו תורה, נאמר בו אין בור ירא חטא (שם)."]],[[0,"","בֹּא רְאֵה, כָּתוּב וַתֵּצֵא אֵשׁ מִלִּפְנֵי ה' וַתֹּאכַל עַל הַמִּזְבֵּחַ אֶת הָעֹלָה. אָמַר רַבִּי יְהוּדָּה, זֶה אוּרִיאֵ\"ל, שֶׁנִּרְאָה בְּשַׁלְהֶבֶת אֵשׁ עַל הַמִּזְבֵּחַ, כְּמוֹ שֶׁנֶּאֱמַר רוֹבֵץ עַל הַקָּרְבָּן. וְאָז הָיְתָה שִׂמְחָה בַּכֹּל, שֶׁהֲרֵי הִתְקַבֵּל בְּרָצוֹן, כְּמוֹ שֶׁכָּתוּב וַיֵּרָא כְבוֹד ה' אֶל כָּל הָעָם. וְאִם לֹא הָיְתָה הָעִרְבּוּבְיָא שֶׁל בְּנֵי אַהֲרֹן מִיּוֹם שֶׁיָּצְאוּ יִשְׂרָאֵל מִמִּצְרַיִם, לֹא נִמְצָא רָצוֹן כָּךְ לְמַעְלָה וּלְמַטָּה."],[1,"","מִצְוָה זוֹ לִשְׂרֹף קָדָשִׁים בָּאֵשׁ, וְאַחֲרֶיהָ - וְהַנּוֹתָר מִבְּשַׂר הַזָּבַח בַּיּוֹם הַשְּׁלִישִׁי בָּאֵשׁ יִשָּׂרֵף. תַּנָּאִים וְאָמוֹרָאִים, בְּסִתְרֵי תוֹרָה יֵשׁ קֹדֶשׁ, וְיֵשׁ קָדָשִׁים, וְיֵשׁ קֹדֶשׁ קָדָשִׁים. מַה הֲנָאָה יֵשׁ לַקָּדוֹשׁ בָּרוּךְ הוּא בַּקְּדָשִׁים שֶׁנִּשְׂרְפוּ? אִם תֹּאמַר בִּשְׁבִיל יִצְחָק, שֶׁבְּשָׁעָה שֶׁיִּשְׂרָאֵל בְּצָרָה, עוֹלֶה אֶפְרוֹ שֶׁל יִצְחָק לְפָנָיו, שֶׁאִם חַיָּבִים שְׂרֵפָה יִנָּצְלוּ בִגְלָלוֹ - זֶהוּ לִדְרָשׁ. וְאִם תֹּאמְרוּ מִשּׁוּם (הצדיקים) (ואם משום) בְּנֵי אַהֲרֹן שֶׁהָיוּ שְׂרֵפַת קָדָשִׁים, שֶׁכָּתוּב בָּהֶם וַתֵּצֵא אֵשׁ מִלִּפְנֵי ה' וַתֹּאכַל אוֹתָם וַיָּמֻתוּ, וּמִיתָתָם כַּפָּרָה לְיִשְׂרָאֵל כְּמוֹ שְׂרֵפַת קָדָשִׁים - אַף זֶה לִדְרָשׁ בָּא."],[2,"","אֶלָּא שְׁלֹשָׁה אִשִּׁים בְּנֵר: אֵשׁ לְבָנָה, וְאֵשׁ שְׁחֹרָה, וְאֵשׁ תְּכֻלָּה, כְּנֶגֶד תּוֹרָה נְבִיאִים וּכְתוּבִים, כְּנֶגֶד כֹּהֵן לֵוִי וְיִשְׂרָאֵל. וּתְכֵלֶת הִיא שְׁכִינָה, קְרוֹבָה לָנוּ, וְהִיא אֲחוּזָה בְּאוֹתָן פְּתִילוֹת, בְּכַנְפֵי מִצְוָה, שֶׁנֶּאֱמַר בָּהֶם וְעָשׂוּ לָהֶם צִיצִית. וְהַתְּכֵלֶת הַזּוֹ שֶׁהִיא שְׁכִינָה, הִיא דִין שֶׁאוֹכֶלֶת קָרְבָּנוֹת וְעוֹלוֹת."],[3,"","אִם מוֹצֵאת בְּנֵי אָדָם שֶׁהֵם עֵצִים יְבֵשִׁים כְּמוֹ אוֹתָן פְּתִילוֹת יְבֵשׁוֹת, בְּלִי שֶׁמֶן, שֶׁהִיא תּוֹרָה וְרַחֲמִים, הִיא לָהֶם (שידונו) שְׂרֵפָה, וְשׂוֹרֶפֶת אוֹתָם. וּמִשּׁוּם שֶׁעַמֵּי הָאָרֶץ הֵם בְּהֵמוֹת, כְּמוֹ שֶׁבֵּאֲרוּהָ שֶׁהֵם שֶׁקֶץ. תְּכֵלֶת, שֶׁהִיא אֲדנָי, שׂוֹרֶפֶת אוֹתָם, מִשּׁוּם שֶׁקְּרֵבִים אֵלֶיהָ עִם שֶׁרֶץ, שֶׁהוּא יֵצֶר הָרָע זָר. זֶהוּ שֶׁכָּתוּב וְהַזָּר הַקָּרֵב יוּמָת."],[4,"","וְאִם בְּמִיתָתָם חוֹזְרִים בִּתְשׁוּבָה, (כששוחט אותם מלאך המות, מיכאל) הַמַּלְאָךְ מִיכָאֵל שֶׁהוּא כֹּהֵן גָּדוֹל, הָאַרְיֵה שֶׁאוֹכֵל קָרְבָּנוֹת יוֹרֵד עֲלֵיהֶם לְהַקְרִיבָם קָרְבָּן לִפְנֵי ה'."],[5,"","וְלִפְנֵי שֶׁתֵּצֵא נִשְׁמָתוֹ מִתְוַדֶּה בְּכַמָּה וִדּוּיִים, וּכְשֶׁיּוֹצֵאת נִשְׁמָתוֹ הוּא הָיָה מִתְכַּוֵּן לִגְמֹר אֶת הַשֵּׁם, שְׁמַע יִשְׂרָאֵל וּבָרוּךְ שֵׁם, לְהַקְרִיב אֶת נִשְׁמָתוֹ כְּלִי (קרבן) לְשֵׁם יְהֹוָ\"ה, וְצָרִיךְ לְהִתְוַדּוֹת אֶל הַקָּדוֹשׁ בָּרוּךְ הוּא לְקַבֵּל וּלְקָרֵב ה' שֶׁבִּשְׁמוֹ שֶׁאוֹכֶלֶת וּמְכַלָּה, וּלְהַחֲזִיר בִּתְשׁוּבָה לְיה\"ו אֶהְיֶ\"ה כְּחֶשְׁבּוֹן מ\"ב. שֶׁל אֲדנָ\"י קוֹרְאִים דִּין שֶׁל מַלְכוּת דִּין."],[6,"","וִיכַוֵּן בַּשֵּׁם הַמְפֹרָשׁ, שֶׁהוּא יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א, בְּלֵב אֶחָד, וּבוֹ תֵּצֵא רוּחוֹ. בַּנֶּפֶשׁ שֶׁלּוֹ מְקַבֵּל עָלָיו מִיתָה וְיִסּוּרִים, וּבַנְּשָׁמָה מוֹדֶה בְּכַמָּה וִדּוּיִים וּמִתְחָרֵט."],[7,"","בַּנֶּפֶשׁ מְקַבֵּל עָלָיו מִיתָה, שְׁחִיטָה, שְׂרֵפָה. וְאִם צָרִיךְ אַרְבַּע מִיתוֹת בֵּית דִּין, שֶׁהֵם סְקִילָה שְׂרֵפָה הֶרֶג וְחֶנֶק, מְקַבֵּל אוֹתָם מֵאֲדנָ\"י בַּנֶּפֶשׁ שֶׁלּוֹ. וּבְנִשְׁמָתוֹ מוֹדֶה בְּכַמָּה וִדּוּיִים, וְחוֹזֵר בִּתְשׁוּבָה אֶל אֶהְיֶ\"ה, שֶׁאָחוּז בִּשְׁנֵי שֵׁמוֹת - יְהֹוָ\"ה יְהֹוָ\"ה."],[8,"","בְּמַחֲשַׁבְתּוֹ יְכַוֵּן לְהוֹצִיא וִדּוּי וְקַבָּלַת מִיתָה עָלָיו בְּלֵב אֶחָד, שֶׁהוּא שֵׁם הַמְפֹרָשׁ, כְּמוֹ זֶה: יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א, (כבוד) שֶׁבּו הַכֹּהֲנִים כּורְעִים וּמִשְׁתַּחֲוִים עַל פְּנֵיהֶם וְאוֹמְרִים: בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד. כָּבוֹד הוּא ל\"ב בְּחֶשְׁבּוֹן, וּבוֹ הָיָה מִתְכַּוֵּן לִגְמֹר אֶת הַשֵּׁם. (וא\"ו הוא אחד בלב)."],[9,"","וְתַנָּאִים וְאָמוֹרָאִים, אִם תֹּאמְרוּ, וְכִי עַם הָאָרֶץ מִנַּיִן יוֹדֵעַ אֶת זֶה? אֶלָּא וַדַּאי עַם הָאָרֶץ הוּא כְּמוֹ שׁוֹר אוֹ שֶׂה אוֹ עֵז אוֹ (פר) תוֹר אוֹ יוֹנָה. מַה בְּהֵמוֹת אֵין יוֹדְעוֹת תּוֹרָה, שֶׁהִיא שֵׁם יְהֹוָ\"ה, כָּךְ עַם הָאָרֶץ לֹא יוֹדֵעַ. אֶלָּא מִיכָאֵל כֹּהֵן גָּדוֹל הוּא עוֹשֶׂה אוֹתוֹ עוֹלָה וְקָרְבָּן לִפְנֵי ה', וְהוּא מְכַוֵּן בַּשֵּׁם הַמְפֹרָשׁ בַּעֲלִיַּת רוּחוֹ שֶׁתֵּצֵא בְּלֵב אֶחָד, כְּמוֹ שֶׁכְּשֶׁיּוֹצֵאת רוּחַ הָאָדָם בְּכָל לַיְלָה."],[10,"","וּמִשּׁוּם זֶה פֵּרְשׁוּהָ הַחֲכָמִים, שׁוּב יוֹם אֶחָד לִפְנֵי מִיתָתְךְ. שֶׁבְּכָל יוֹם וָיוֹם צָרִיךְ אָדָם לַחֲזֹר בִּתְשׁוּבָה וְלִמְסֹר אֶת רוּחוֹ אֵלָיו שֶׁיֵּצֵא בְאֶחָד. זֶהוּ שֶׁכָּתוּב (תהלים לא) בְּיָדְךְ אַפְקִיד רוּחִי."],[11,"","וְאִם הוּא תַּלְמִיד חָכָם, עָלָיו נֶאֱמַר (משלי יב) יוֹדֵעַ צַדִּיק נֶפֶשׁ בְּהֶמְתּוֹ, שֶׁאֵין חָכָם כְּמוֹ הַכֹּהֵן, כְּמוֹ שֶׁבֵּאֲרוּהָ הָרוֹצֶה לְהַחְכִּים יַדְרִים. וְאִם תַּלְמִיד חָכָם הוּא, צָרִיךְ שֶׁיִּהְיֶה בּוֹ חֶסֶד, וְעִם י' שֶׁהִיא חָכְמָה - חָסִיד. וּמִי שֶׁאֵין בּוֹ חָכְמָה, אֵינוֹ חָסִיד. וּמִשּׁוּם כָּךְ פֵּרְשׁוּהָ, וְלֹא עַם הָאָרֶץ חָסִיד. וְאִם יֵשׁ בּוֹ ה', חֲמִשָּׁה חֻמְשֵׁי תוֹרָה שֶׁנִּתְּנוּ מִשְּׂמֹאל, נִקְרָא גִבּוֹר בַּתּוֹרָה וִירֵא חֵטְא. וְאִם הוּא בּוּר, נֶאֱמַר בּוֹ אֵין בּוּר יְרֵא חֵטְא."]]],[["וּמַאן דְּזָכֵי לְתִפְאֶרֶת, דְּאִיהוּ ו', וְאִיהוּ חָכָם מֵבִין בַּתּוֹרָה וִירֵא חֵטְא, יָרִית מַלְכוּתֵיהּ, דְּאִיהוּ הֵ\"א, מִצְּוַת הַמֶּלֶךְ, אִי עָבִיד פִּקּוּדֵי מַלְכָּא. כֵּיוָן דְּזָכֵי לְשֵׁם יְהוָֹ\"ה, זָכֵי לִשְׁמָא מְפֹרָשׁ דְּאִתְקְרֵי אָדָם, וְדָא יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. בְּהַהוּא זִמְנָא שַׁלִּיט עַל גּוּפֵיהּ, דְּאִיהוּ שׁוּתָּפוּ דְּנֶפֶשׁ הַבְּהֵמִית. וְרוּחַ הַבְּהֵמִית דִּבְנֶפֶשׁ הַבְּהֵמִית עֲשִׂיַּית הַבְלֵי עָלְמָא, רוּחַ מְמַלְּלָא בְּהַבְלֵי עָלְמָא (נשמה דבה כל הרהורין ומחשבות דהבלי עלמא). וְתַּלְמִיד חָכָם שַׁלִּיט עָלַיְיהוּ.","הֲדָא הוּא דִכְתִיב, (בראשית א׳:כ״ו) וְיִרְדּוּ בִדְגַת הַיָם וּבְעוֹף הַשָׁמַיִם וּבַבְּהֵמָה וּבְכָל הָאָרֶץ. מַאי וּבְכָל הָאָרֶץ. דָּא גּוּפָא, עוֹלָם קָטָן, וְדַחֲלִין מִנֵּיהּ, הֲדָא הוּא דִכְתִיב, (בראשית ט׳:ב׳) וּמוֹרַאֲכֶם וְחִתְּכֶם. מִסִּטְרָא דִּימִינָא, שַׁלִּיט עָלַיְיהוּ, בֵּיהּ וְיִרְדּוּ, כְּמָה דְאַתְּ אָמֵר, (תהילים ע״ב:ח׳) וְיִּרְדְּ מִיָּם עַד יָם. מִסִּטְרָא דִּשְׂמָאלָא, דַּחֲלִין מִנֵּיהּ, הֲדָא הוּא דִכְתִיב וּמוֹרַאֲכֶם וְחִתְּכֶם. וְעָלֵיהּ אִתְּמַר, יוֹדֵעַ צַּדִּיק נֶפֶשׁ בְּהֶמְתּוֹ.","בָּתַר דְּאִיהוּ צַּדִיק, לָא יָהִיב לֵיהּ שְׂכַר מִצְּוֹת, לֵית לֵיהּ אַגְרָא בְּעָלְמָא דָּא, וְלָא מְזוֹנָא לִבְעִירָן דְּעָנִי חָשׁוּב כַּמֵּת. אִיהוּ עִם שְׁכִינְתָּא בִּקְבִיעוּ דִּילָהּ עִמָּהּ עַל כֹּלָּא.","(דברים ד׳:כ״ד) כִּי יְיָ' אֱלֹהֶיךָ אֵשׁ אוֹכְלָה הוּא. הַאי אֵשׁ, צָּרִיךְ לֵיהּ תָּמִיד עִמָּהּ, דְּלֵית לֵיהּ כְּבִיָה, דְּאִיהוּ אָכִיל כָּל קָרְבָּנִין דִּצְּלוֹתִין, וּמִלִּין דְּאוֹרַיְיתָא. דְּאִיהִי שְׁכִינְתָּא אִיהוּ פַּרְנָסָה דִּילֵיהּ, וּבְמָּה. בִּצְּלוֹתִין, הֲדָא הוּא דִכְתִיב, (שיר השירים ה) פִּתְחִי לִי. פִּתְחִי לִי, בִּצְּלוֹתָא דְּאִתְּמַר בָּהּ (תהילים נ״א:י״ז) אֲדֹנָי שְׂפָתַי תִּפְתָּח, דְּאִיהִי אֲחוֹתִי רַעְיָתִי, וְלֵית רַעְיָתִי אֶלָּא פַּרְנָסָתִי, דְּבָהּ מְתַקְּנִין מַאֲכָלִין דְּקָרְבְּנִין דְּמַלְכָּא בְּנִין קַדִישִׁין, בְּכַמָּה מִינֵי מַאֲכָלִים, בְּנַהֲמָא דְּאוֹרַיְיתָא.","דְּאִתְּמַר בָּהּ (משלי ט׳:ה׳) לְכוּ לַחֲמוּ בְלַחְמִי, מִימִינָא. וּבְחַמְרָא, דְּאִיהוּ יֵינָא דְּאוֹרַיְיתָא, מִשְּׂמָאלָא. בְּנִסוּךְ הַמַּיִם, וְיַיִן דְּאוֹרַיְיתָא דְּבִכְתָב וּבְּעַל פֶּה, מֵעַמוּדָא דְּאֶמְצָּעִיתָא, דְּכָלִיל תַּרְוַויְיהוּ. בְּבִשְׂרָא, דְּאִיהִי בְּשַׂר הַקֹּדֶשׁ, בְּכַמָּה קָרְבָּנִין, דְּעָלָהּ אוּקְמוּהָ מָארֵי מַתְנִיתִין בְּבָשָׂר הַיוֹרֵד מִן הַשָּׁמַיִם עַסְקִינָן. מַאי מִן הַשָּׁמַיִם. עַמּוּדָא דְּאֶמְצָּעִיתָא. דְּעָלָהּ אִתְּמַר, וּבָשָׂר מִבְּשָׂרִי.","וְדָא בְּשַׂר הַקֹּדֶשׁ, דְּאַדְלִיקַת בְּכַמָּה שַׁלְהוֹבִין, מִסִּטְרָא דִּגְבוּרָה בִּרְחִימוּ דְּבַעְלָהּ, אִתּוֹקְדַת בִּרְחִימוּ דְּאַהֲבָה בְּקְרִיאַת שְׁמַע, בִּרְחִימוּ דְּיִחוּדָא, דְּלֵילְיָא וְיוֹמָם לָא תִכְבֶּה. וְחַבְרַיָּיא בְּחַיִּיכוֹן אַל תִּתְּנוּ דֳּמִי לוֹ לְּקוּדְשָׁא בְּרִיךְ הוּא, לְמֶהֱוִי אִיהוּ בְּשָׁלְהוֹבִין דִּרְחִימוּ דְּיִחוּדֵיהּ דִּקְרִיאַת שְׁמַע. לְקַיְּימָא בֵּיהּ, אֵשׁ תָּמִיד תּוּקַד עַל הַמִּזְבֵּחַ לֹא תִכְבֶּה. (ע\"כ רעיא מהימנא).","תָּא חֲזֵי, אַף עַל גַּב דִּבִנֵי אַהֲרֹן מִיתוּ בְּהַהִֹיא שַׁעֲתָא, יָאוּת הֲוָה בְּכַמָּה גַּוְונִין. חֲדָא, דְּלָא הֲוָה שַׁעֲתָא דִּקְטֹרֶת, דְּהָא קְטֹרֶת לָא סַלְּקָא, אֶלָּא בְּזִמְנִין יְדִיעָן, דִּכְתִיב (שמות ל׳:ז׳) וְהִקְטִיר עָלָיו אַהֲרֹן קְטֹרֶת סַמִּים בַּבֹּקֶר בַּבֹּקֶר. וְאֵימָתַי בְּהֵטִיבוֹ אֶת הַנֵּרוֹת וְגוֹ' לְאִשְׁתַּכְחָא שֶׁמֶן וּקְטֹרֶת כַּחֲדָא. וּכְתִיב וּבְהַעֲלוֹת אַהֲרֹן אֶת הַנֵּרוֹת בֵּין הָעַרְבַּיִם יַקְטִירֶנָּה וְגוֹ'.","וּבְזִמְנִין אִלֵּין אִתְקְרִיב, וְלָא בְּזִמְנָא אָחֳרָא, בַּר בְּזִמְנָא דְּמוֹתָנָא שַׁרְיָא בְּעָלְמָא, כְּמָה דְּאִעְרַע דִּכְתִיב (במדבר י״ז:י״א) וַיֹּאמֶר מֹשֶׁה אֶל אַהֲרֹן קַח אֶת הַמַּחְתָּה וְתֵן עָלֶיהָ אֵשׁ וְגוֹ'. וּבְנֵי אַהֲרֹן לָא קְרִיבוּ בְּשַׁעֲתָא דְּשֶמֶן וּקְטֹרֶת מִשְׁתַּכְחֵי כַּחֲדָא."],[[0,"ומאן דזכי לתפארת וכו׳:","ומי שזכה לת״ת שהוא \u0003ו׳,\u0004 כי מי שזכה לחסד וגבורה זוכה ג״כ בת״ת כי הת״ת הוא כללות מחסד וגבורה, והוא \u0003חכם מבין\u0004 בתורה וירא חטא, דהיינו שהחסד והגבורה שזכה בהם נעשו לחכמה ובינה, והוא חכם, מבין. הוא יורש \u0003המלכות\u0004 שלו, של הת״ת, שהוא \u0003ה׳\u0004 אחרונה של שם הויה, וזוכה בה, אם הוא עושה מצות המלך, כי המלכות נקראת מצות המלך. ונמצא שזכה לכל ד׳ אותיות י׳ ה׳ ו' ה׳, שהם חכמה, בינה, תפארת, ומלכות. כיון שזכה לשם \u0003הוי״ה,\u0004 הוא זוכה לשם המפורש שנקרא אדם, שזהו הויה במילוי אלפין, שהוא בגימטריא אדם, דהיינו מ״ה, כזה \u0003יוד הא ואו הא.\u0004 שיורה על ז\"א שהוא בגדלות. באותו זמן הוא שולט על הגוף שהוא השותף של נפש הבהמית ורוח הבהמי. כי עשית הבלי העולם היא בנפש הבהמית, והרוח הבהמי, מדבר בהבלי העולם. והנשמה הבהמית, שבה כל מיני הרהורים ומחשבות של הבלי העולם. והתלמיד חכם שולט עליהם. דהיינו על הגוף, ועל נר״נ הבהמיים."],[1,"הה\"ד וירדו בדגת וגו':","זהו שכתוב, וירדו בדגת הים ובעוף השמים ובבהמה ובכל הארץ. שדגת הים רומז לנשמה, ועוף השמים לרוח, ובבהמה לנפש. מהו בכל הארץ. הוא הגוף, שהוא עולם קטן. והם יראים מפני ההלמיד חכם השולט עליהם, שנאמר, ומוראכם וחתכם וגו'. מצד הימין, שהוא חסד, הוא שולט עליהם, בו, בחסד, נאמר \u0003וירדו,\u0004 שפירושו, כש״א \u0003וירד\u0004 מים עד ים, שהוא לשון שליטה. ומצד השמאל, שהוא גבורה, הם יראים ממנו, ז״ש ומוראכם ותתכם. ועליו נאמר, \u0003יודע צדיק נפש בהמתו.\u0004 דהיינו ששולט על הנפש הבהמית שלו."],[2,"בתר דאיהו צדיק וכו׳:","ומאחר שהוא צדיק, אין הקב״ה נותן לו שכר מצוות, ואין לו שכר בעולם הזה, ואין מזון לגוף ונר״ן הבהמיים שלו, ועני חשוב כמת. ועל הכל, הוא בקביעות עם השכינה."],[3,"כי ה׳ אלקיך אש אוכלה הוא:","אש זה שהיא השכינה, צריכה לו, להיות תמיד עמה, שאין לה כביה, שהיא אוכלת כל הקרבנות, שהם תפלות, ודברי תורה. כי היא השכינה, פרנסה שלו, של ז״א, ובמה, היא נבחנת לפרנסה שלו. הוא, בתפלות של ישראל שהיא מקבלת אותם. זהו שכתוב, \u0003פתחי לי,\u0004 דהיינו, פתחי לי בתפלה, שנאמר בה אדני שפתי תפתח, שהיא \u0003אחותי רעיתי,\u0004 ואין רעיתי אלא פרנסתי, דהיינו מלשון רעיה, כמו ה׳ רועי. כי בה בנים הקדושים דהיינו ישראל, מתקנים מאכלים של קרבנות המלך, שהוא ז״א, בכמה מיני מאכלים, בלחם התורה."],[4,"דאתמר בה, לכו וגו׳:","שנאמר בה, לכו לחמו בלחמי, מימין, מצד החסד. וביין, שהוא יין של תורה, משמאל, מצד הגבורה. בנסוך המים, שהוא ימין, ויינה של תורה שבכתב ושבעל פה, שהוא שמאל, מעמוד האמצעי, שהוא ת״ת, הכולל את שניהם, שכולל ימין ושמאל, שהם חסד וגבורה. בבשר, שהוא בשר הקדש, בכמה קרבנות, דהיינו מלכות, שעליה העמידו בעלי המשנה, בבשר היורד מן השמים עסקינן, (סנהדרין נ״ט:) מהו מן השמים. הוא עמוד האמצעי, שהוא ז״א הנקרא שמים. שעליה נאמר, שז״א שה״ס אדם, אמר עליה, ובשר מבשרי."],[5,"ודא בשר הקדש וכו׳:","ובשר הקדש הזה, שהוא מלכות, הבוערת בכמה להבות מצד הגבורה, באהבת בעלה, ז״א, נשרפת באהבה, של אהבת קריאת שמע, באהבת היחוד. אשר לילה ויומם לא תככה. וחברים: בחייכם, אל תתני דמי לו, להקב״ה, עד שהוא יהיה בשלהבת האהבה. של יחודו בקריאת שמע, לקיים בו, אש תמיד תוקד על המזבח לא תכבה."],[5,"","ביאור המאמר. הנה כל זמן שהאדם לא זכה, לתשובה שלמה, ולא השיג המוחין דג״ר, מחשבהו הרעיא מהימנא לעם הארץ, ולא נקרא תלמיד חכם אלא אחר שזכה למוחין דג״ר מהויה שבמילוי אלפין, שה״ס ג\"ר דז״א, אשר החסד שבו מתעלה לבחינת חכמה, והגבורה לבחינת בינה, כמ״ש לעיל (משפטים אות תק״כ) \u0003דרישא דמלכא בחסד וגבורה אתתקן.\u0004 וזה אמרו (באות קמ״ה) \u0003ואם תלמיד חכם הוא צריך שיהא ביה חסד,\u0004 דהיינו שיזכה מקודם לבחינת ו״ק, שמבחינת קו ימין, קומתו היא קומת חסד, \u0003ועם י׳ דאיהו חכמה, חסיד,\u0004 דהיינו שיזכה אח״כ גם לג\"ר אשר החסד מתעלה להיות חכמה, ונמצא שיש לו חסד וגם חכמה שה״ס ה \u0003י׳\u0004 שבתוך \u0003חסד,\u0004 ואז הוא \u0003חסיד. ומאן דלית ביה חכמה וכו׳\u0004 ולא עם הארץ חסיד, כי חסרה לו הי׳ שבתוך חסד, שהיא חכמה. והוא נחשב משום זה לעם הארץ. \u0003ואי אית אית ביה ה׳ וכו׳ אתקרי גבור בתורה וירא חטא,\u0004 וזה הוא מבחינת קו שמאל, שבהשגת מוחין דו״ק שקומתו הוא קומת גבורה, הוא נקרא \u0003גבור בתורה.\u0004 ואם זכה אח״כ אל הג״ר דקו שמאל, אשר מדת הגבורה שלו מתעלה להיות בינה, ה׳ ראשונה דהויה, שה״ס הארת החכמה הנמשכת משמאל דבינה, הוא נקרא \u0003ירא חטא.\u0004 והוא מטעם, כי אין הארת החכמה נמשכת מקו שמאל דבינה רק עם גילוי דינים הקשים על הרשעים שהמשיכו החכמה מלמעלה למטה (כנ״ל פקודי אות שע״ו, וצו אות קי״ד) והוא, כדי להטיל יראה ופחד, על אותם שרוצים להמשיך החכמה ממעלה למטה. נמצא שהאדם שזכה להארת חכמה דשמאל הוא \u0003ירא חטא,\u0004 שמתירא לחטוא ולהמשיך החכמה ממעלה למטה. שזה שורש האיסור של כל שס״ה לאוין."],[5,"","וצריכים לדעת כאן את ההפרש בין החכמה שבקו ימין, שהוא סוד החסד שנתעלה לחכמה, לבין הארת החכמה שבקו שמאל, שה״ס הגבורה שנתעלתה לבינה. כי החכמה דקו ימין היא בחינת או״א עלאין, שבעצמם הם חסדים מכוסים מחכמה, והם נקראים חכמה מב' טעמים, א', מפני שהם מלבישים על חכמה סתימאה דא״א. ב׳, שבעת שנגלה הארת החכמה בישסו״ת, הם מקבלים הארה זו מאו״א המלבישים לחכמה סתימאה, ונמצאים או״א עצם החכמה וישסו״ת מקבלים רק הארה. אבל גם אז, אע״פ שאו״א משפיעים הארת החכמה לישסו״ת היא רק בדרך העברה מחכמה סתימאה לישסו״ת. אבל באו״א עצמם אין החכמה מתלבשת בהם והם תמיד בחסדים מכוסים. וז״ס שאין ה \u0003י׳\u0004 יוצאת מאויר דאו״א לעולם (כנ״ל בראשית א׳ דף רנ״א ד״ה נחית) אלא ישסו״ת הם המקור לגילוי הארת החכמה, כי בהם יוצאת ה \u0003י׳ מאויר\u0004 שה\"ס חסדים ונעשים \u0003אור\u0004 שה״ס חכמה. אמנם חכמה זו שנגלית בישסו״ת הם מקבלים אותה מאו״א עלאין. וכל מקום שנזכרת חכמה בקו ימין, היא בחינת או״א עילאין. ובחינת החכמה שבקו שמאל היא בחינת ישסו\"ת, הנבחנים לבינה, אלא שחזרה להיות חכמה, ולא חכמה ממש מטעם הנ\"ל. וזכור כלל זה לכל המקומות, כי אי אפשר להזכיר את זה תמיד."],[5,"","וז״ש, \u0003ואי איהו בור, אתמר ביה, אין בור ירא חטא,\u0004 כי כל עוד שלא זכה לג\"ר דקו שמאל, שה״ס הארת החכמה שבקו שמאל, המתגלה ביחד עם דינים קשים על רשעים החוטאים, אין לו יראה מלחטוא. כי אין יראת חטא באה, אלא מהסתכלות בדינים המתגלים על החוטאים, בעת גלוי הארת החכמה כנ״ל."],[5,"","ואומר. (באות קמ״ו) \u0003בההוא זמנא שליט על גופיה דאיהו שותפו דנפש הבהמית\u0004 וכו'. כי בעת שזוכה להשיג הג״ר, ויש לו נפש רוח נשמה מבחינת הויה דאלפין, אז מתלבשים נר\"ן האלו בנר״ן הבהמיים של האדם, ובגוף הבהמי שלו. שעל ידי התלבשות הזאת נכנעים נר\"ן הבהמיים אל נר״ן הרוחניים, ונר״ן הרוחניים שולטים על הגוף ועל נר\"ן הבהמיים ומהפכים אותם לקדושה. וזה אמרו, \u0003ועליה אתמר, יודע צדיק נפש בהמתו\u0004, שפירושו ששולט על נפש הבהמית שלו."],[5,"","אמנם צריכים לדעת את ההפרש בין הגוף ונר״ן הבהמיים שלו לבין נר״ן הרוחניים הקדושים. הוא כי נר\"ן דקדושה נמשכים מהויה דאלפין, שה״ס קו אמצעי ז״א, המיחד ימין ושמאל זב״ז, באפן, שהימין נמשך ממעלה למטה, והארת חכמה שבשמאל תאיר ממטה למעלה בלבד (כנ\"ל בראשית א׳ דף ס׳ ד״ה מחלוקת). והגוף ונר״ן הבהמיים של האדם נמשכים מקליפת נוגה, המעורבת מטוב ורע. דהיינו שיש בהם מבחינת הטוב, הנמשך מיחוד דקו אמצעי כנ״ל בנר״ן הרוחניים, ויש בהם מבחינת הרע, שהוא הסטרא אחרא וכל הקליפות שאינם חפצים בתקון קו האמצעי, ודבוקים בקו שמאל בלבד, וכל חפצם הוא להמשיך הארת החכמה שבשמאל ממעלה למטה, ולקלקל היחוד דקו האמצעי. וכיון שהרע דקליפת נוגה מעורב בגוף ונר״ן הבהמים של האדם, אינם יכולים להתתקן בשתא אלפי שני ולפיכך מוכרח האדם למות. כי אינם נתתקנים רק ע״י המשכת החכמה ממעלה למטה שתהיה בגמר התקון, ואז נאמר בלע המות לנצח. ועד אז נבחן שאין להם מזונות, דהיינו הקיום הראוי להם."],[5,"","ובזמן שאדם משיג נר״ן הרוחניים מהויה דאלפין, אז נכנע הרע שבנוגה המעורב בגוף ונר\"ן הבהמיים של האדם, לבחינת הטוב שבנוגה שבהם, ואז מתלבשים נר״נ הרוחניים שבאדם בתוך נר\"נ הבהמיים והגוף הבהמי של האדם. שהם כבר נכנעים לטוב שבהם והם כולו טוב, אע״פ שאין מקבלים מזונותיהם הראוים להם, מפני שנכנעים ומתבטלים אל הטוב."],[5,"","וז״ש, \u0003הה״ד וירדו בדגת הים\u0004 וכו׳ שהם נר״נ הבהמיים של האדם. \u0003ובכל הארץ דא גופא עולם קטן,\u0004 כי הם נכנעים אל הטוב שבנגה, ואל נר״ן הרוחניים המלובשים בהם. וז״ש, \u0003בתר דאיהו צדיק,\u0004 דהיינו שדבוק בקו האמצעי, ואינו ממשיך הארת חכמה שבשמאל אלא ממטה למעלה \u0003לא יהיב ליה שכר וכו' ולא מזונא לבעירן\u0004 כי הגוף ונר״ן דבעירן, הם ניזונים רק ממעלה למטה, כמו הרע שבנוגה המעורב בהם, וכיון שהוא צדיק ודאי שאינו ממשיך להם כלום. \u0003דעני חשוב כמת, איהו עם שכינתא בקביעו\u0004 וכו׳ \u0003כי ה' אלקיך אש אוכלה הוא,\u0004 כי אחר שהצדיק קיבל על עצמו שלא לזון הגוף ונר״נ הבהמיים, והם בבחינת עני חשוב כמת, אז זוכה להשראת השכינה בקביעות, אשר השכינה שורפת את בחינות הרע שבנוגה שבהם, עד שיהיו ראוים לגמר התקון."],[5,"","ודע שהרעיא מהימנא מרמז לנו במאמר הזה, שאין הרשע מתתקן עד שיעברו עליו ג׳ גלגולים. שזסו״ה, הן כל אלה יפעל אל פעמים שלש עם גבר. \u0003גלגול ראשון\u0004. הוא בעם הארץ שזכה עכ״פ לעשות תשובה לפני מיתתו וכו׳ (כמבואר באות קל״ח ובהסולם באות קמ״ד ע״ש,) שאז זוכה למיתוק הכלים שיהיו ראוים לקבל האורות דנפש רוח ונשמה. \u0003גלגול שני\u0004, הוא אחר שכבר יש לו כלים הראוים לנפש רוח נשמה, מתגלגל ועושה תשובה בחיים, וזוכה לקבל האורות דו״ק שהם נפש רוח, שקומתם היא חסד וגבורה. (כמבואר באות קמ״ה.) \u0003גלגול שלישי\u0004 הוא שמתגלגל ועושה תשובה שלמה כראוי, ואז זוכה, שחסד וגבורה מתעלים לבחינת חכמה ובינה, ואז זוכה לבחינת נשמה. (כמבואר שם). ואלו ב׳ גלגולים האחרונים יכולים לבא בפעם א', כמו שמביא אותם הרעיא מהימנא ביחד, ולפעמים בזה אחר זה. וע״כ כתוב פעמים שלש עם גבר. אמנם אין הפירוש שהוא מוכרח לעשות תשובה בכל גלגול, אלא יכול להתגלגל אפילו מאה פעמים עד שיזכה לגלגול א', שהוא לעשות תשובה קודם מיתתו, וכל אלו נחשבים רק לגלגול א׳. וכן יכול להתגלגל כמה פעמים עד שיזכה לקבל נפש רוח, וכל אלו נחשבים לגלגול ב׳. וכן בגלגול ג'. (ע״כ רעיא מהימנא)."],[6,"תא חזי אע\"ג וכו׳:","בוא וראה, אע״פ שבני אהרן מתו באותה שעה, ולא הצילתם גדלות היום, צודק היה מכמה אפנים. א) שלא היתה שעת הקרבת הקטרת, כי קטרת אינה נקרבת רק בזמנים ידועים, דהיינו בבוקר ובערב, שכתוב, והקטיר עליו אהרן קטרת סמים בבקר בבקר. ומתי. בהטיבו את הנרות וגו'. כדי שימצא שמן וקטרת ביחד. וכתוב ובהעלות אהרן את הנרות וגו'."],[7,"ובזמנין אלין אתקריב וכו׳:","ובזמנים אלו בבקר ובערב, נקרבת הקטרת, ולא בזמן אחר. חוץ בזמן שמגפה שורה בעולם, שאז נקרבת גם שלא בזמנה. כמו שקרה, שכתוב ויאמר משה אל אהרן קח את המחתה ותן עליה אש וגו'. ובני אהרן לא הקריבו בשעה ששמן וקטרת נמצאים יחד, דהיינו בבקר או בערב, שרומז על יחוד חכמה ובינה, כי שמן הוא חכמה וקטרת היא בינה. וע״כ מתו."]],[[0,"","וּמִי שֶׁזּוֹכֶה לְתִפְאֶרֶת, שֶׁהוּא ו', וְהוּא חָכָם מֵבִין בַּתּוֹרָה וִירֵא חֵטְא, הוּא יוֹרֵשׁ אֶת מַלְכוּתוֹ, שֶׁהִיא הֵ\"א, מִצְוַת הַמֶּלֶךְ, אִם עוֹשֶׂה אֶת מִצְווֹת הַמֶּלֶךְ. כֵּיוָן שֶׁזּוֹכֶה לְשֵׁם יְהֹוָ\"ה, זוֹכֶה לַשֵּׁם הַמְפֹרָשׁ שֶׁנִּקְרָא אָדָם, וְזֶה יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. בְּאוֹתוֹ זְמַן שׁוֹלֵט עַל גּוּפוֹ, שֶׁהוּא שֻׁתָּפוּת שֶׁל נֶפֶשׁ הַבַּהֲמִית, וְרוּחַ הַבַּהֲמִית שֶׁבַּנֶּפֶשׁ הַבַּהֲמִית עֲשִׂיַּת הַבְלֵי הָעוֹלָם, רוּחַ שֶׁמְּדַבֶּרֶת בְּהַבְלֵי הָעוֹלָם, (נשמה שבה כל ההרהורים והמחשבות של הבלי העולם), וְתַלְמִיד חָכָם שׁוֹלֵט עֲלֵיהֶם."],[1,"","זְהִוּ שֶׁכָּתוּב, (בראשית א) וְיִרְדּוּ בִדְגַת הַיָּם וּבְעוֹף הַשָּׁמַיִם וּבַבְּהֵמָה וּבְכָל הָאָרֶץ. מַה זֶּה וּבְכָל הָאָרֶץ? זֶה הַגּוּף, עוֹלָם קָטָן, וּפוֹחֲדִים מִמֶּנּוּ. זֶהוּ שֶׁכָּתוּב (שם ט) וּמוֹרַאֲכֶם וְחִתְּכֶם. מִצַּד הַיָּמִין שׁוֹלֵט עֲלֵיהֶם, בּוֹ וְיִרְדּוּ, כְּמוֹ שֶׁנֶּאֱמַר (תהלים עב) וְיֵרְדְּ מִיָּם עַד יָם. מִצַּד הַשְּׂמֹאל פּוֹחֲדִים מִמֶּנּוּ, זֶהוּ שֶׁכָּתוּב וּמוֹרַאֲכֶם וְחִתְּכֶם, וְעָלָיו נֶאֱמַר יוֹדֵעַ צַדִּיק נֶפֶשׁ בְּהֶמְתּוֹ."],[2,"","אַחַר שֶׁהוּא צַדִּיק, לֹא נוֹתֵן לוֹ שְׂכַר מִצְווֹת, אֵין לוֹ שָׂכָר בָּעוֹלָם הַזֶּה וְלֹא מָזוֹן לַבְּהֵמוֹת, שֶׁעָנִי חָשׁוּב כְּמוֹ מֵת. הוּא עִם הַשְּׁכִינָה בִּקְבִיעוּת שֶׁלָּהּ עִמָּהּ עַל הַכֹּל."],[3,"","כִּי ה' אֱלֹהֶיךְ אֵשׁ אוֹכְלָה הוּא (דברים ד). הָאֵשׁ הַזּוֹ הוּא צָרִיךְ לִהְיוֹת תָּמִיד עִמָּהּ, שֶׁאֵין לָהּ כְּבִיָּה, שֶׁהוּא אוֹכֵל כָּל הַקָּרְבָּנוֹת שֶׁל הַתְּפִלּוֹת וְדִבְרֵי תוֹרָה. שֶׁהִיא הַשְּׁכִינָה הִיא פַּרְנָסָתוֹ, וּבַמֶּה? בִּתְפִלָּה, זֶהוּ שֶׁכָּתוּב (שיר ה) פִּתְחִי לִי. פִּתְחִי לִי, בִּתְפִלָּה, שֶׁנֶּאֱמַר בָּהּ (תהלים נא) אֲדנָי שְׂפָתַי תִּפְתָּח, שֶׁהִיא אֲחֹתִי רַעְיָתִי, וְאֵין רַעְיָתִי אֶלָּא פַּרְנָסָתִי, שֶׁבָּהּ מְתַקְּנִים מַאֲכָלִים שֶׁל קָרְבָּנוֹת שֶׁל הַמֶּלֶךְ הַבָּנִים הַקְּדוֹשִׁים, בְּכַמָּה מִינֵי מַאֲכָלִים, בַּלֶּחֶם שֶׁל הַתּוֹרָה."],[4,"","שֶׁנֶּאֱמַר בָּהּ (משלי ט) לְכוּ לַחֲמוּ בְלַחְמִי, מִיָּמִין. וּבְיַיִן, שֶׁהוּא יֵין הַתּוֹרָה, מִשְּׂמֹאל. בְּנִסּוּךְ הַמַּיִם, וְיֵין הַתּוֹרָה שֶׁבִּכְתָב וּבְעַל פֶּה, מֵהָעַמּוּד הָאֶמְצָעִי שֶׁכּוֹלֵל אֶת שְׁנֵיהֶם. בְּבָשָׂר, שֶׁהוּא בְּשַׂר הַקֹּדֶשׁ, בְּכַמָּה קָרְבָּנוֹת, שֶׁעָלֶיהָ פֵּרְשׁוּ בַּעֲלֵי הַמִּשְׁנָה שֶׁעוֹסְקִים בְּבָשָׂר הַיּוֹרֵד מִן הַשָּׁמַיִם. מַה זֶּה מִן הַשָּׁמַיִם? זֶה הָעַמּוּד הָאֶמְצָעִי, שֶׁעָלָיו נֶאֱמַר וּבָשָׂר מִבְּשָׂרִי."],[5,"","וְזְהִ בְּשַׂר הַקֹּדֶשׁ, שֶׁדּוֹלֶקֶת בְּכַמָּה שַׁלְהָבוֹת מִצַּד הַגְּבוּרָה בְּאַהֲבַת בַּעְלָהּ, נִשְׂרֶפֶת בְּאַהֲבָה שֶׁל אַהֲבָה בִּקְרִיאַת שְׁמַע, בְּאַהֲבַת הַיִּחוּד, שֶׁלַּיְלָה וָיוֹם לֹא תִכְבֶּה. וְהַחֲבֵרִים, בְּחַיֵּיכֶם, אַל תִּתְּנוּ דֳמִי לוֹ לַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהוּא יִהְיֶה בְּשַׁלְהָבוֹת שֶׁל אַהֲבָה שֶׁל יִחוּדוּ בַּקְּרִיאַת שְׁמַע, לְקַיֵּם בּוֹ אֵשׁ תָּמִיד תּוּקַד עַל הַמִּזְבֵּחַ לֹא תִכְבֶּה. (ע\"כ רעיא מהימנא)."],[6,"","בֹּא רְאֵה, אַף עַל גַּב שֶׁבְּנֵי אַהֲרֹן מֵתוּ בְּאוֹתָהּ שָׁעָה, זֶה הָיָה מַתְאִים בְּכַמָּה גְוָנִים. אֶחָד - שֶׁלֹּא הָיְתָה זוֹ שְׁעַת הַקְּטֹרֶת, שֶׁהֲרֵי קְטֹרֶת אֵינָהּ עוֹלָה אֶלָּא בִּזְמַנִּים יְדוּעִים, שֶׁכָּתוּב (שמות ל) וְהִקְטִיר עָלָיו אַהֲרֹן קְטֹרֶת סַמִּים בַּבֹּקֶר בַּבֹּקֶר. וּמָתַי? בְּהֵיטִיבוֹ אֶת הַנֵּרֹת וְגוֹ', לְהִמָּצֵא שֶׁמֶן וּקְטֹרֶת כְּאֶחָד. וְכָתוּב, וּבְהַעֲלֹת אַהֲרֹן אֶת הַנֵּרֹת בֵּין הָעַרְבַּיִם יַקְטִירֶנָּה וְגוֹ'."],[7,"","וּבַזְּמַנִּים הַלָּלוּ נִקְרֶבֶת, וְלֹא בִזְמַן אַחֵר, פְּרָט לִזְמַן שֶׁהַמָּוֶת שָׁרוּי בָּעוֹלָם, כְּמוֹ שֶׁקָּרָה, שֶׁכָּתוּב (במדבר יז) וַיֹּאמֶר מֹשֶׁה אֶל אַהֲרֹן קַח אֶת הַמַּחְתָּה וְתֶן עָלֶיהָ אֵשׁ וְגוֹ'. וּבְנֵי אַהֲרֹן לֹא הִקְרִיבוּ בְשָׁעָה שֶׁשֶּׁמֶן וּקְטֹרֶת נִמְצָאִים כְּאֶחָד."]]],[["וְעוֹד דְּדָחֲקוּ שַׁעֲתָא בְּחַיֵּי דַּאֲבוּהוֹן. וְעוֹד דְּלָא אַנְסִיבוּ, וַהֲווּ פְּגִימִין, דְּמַאן דְּלָא אַנְסִיב, פָּגִים הוּא, וְלָאו הוּא כְּדַאי לְאִשְׁתַּכְחָא בִּרְכָאן בְּעָלְמָא עַל יְדוֹי, עֲלוֹי לָא שַׁרְיָין, כָּל שֶׁכֵּן עַל יְדוֹי לַאֲחֵרִים. וְעוֹד, דְּהָא תְּנָן רְוָּוי חַמְרָא הֲווֹ, וּבְגִין כַּךְ, וַתֵּצֵא אֵשׁ מִלִּפְנֵי יְיָ' וַתֹּאכַל אוֹתָם וְגוֹ'. דְּהָא קְטֹרֶת חָבִיב הוּא מִכֹּלָּא, וְחֶדְוָותָא דְּעִלָּאִין וְתַתָּאִין, וּכְתִיב (משלי כ״ז:ט׳) שֶׁמֶן וּקְטֹרֶת יְשַׂמַּח לֵב.","\u0003רעיא מהימנא\u0004 (פקודי ר\"ס) לֵית מְצּוֹרָע אֶלָּא הַהוּא דְּאִתְעָבִיד בְּזָבוּתָא. דְּחָמֵשׁ דָּמִים אִינּוּן דְּדָם נִדָּה מִסְאֲבִין, דְּאִינּוּן כֻּלְּהוּ דָּם טָמֵא. וְה' דָּמִין דַּכְיָין. וּמַאן דְּאַעְבָּר עָלַיְיהוּ, כְּאִלּוּ אַעְבָּר עַל עֶשֶׂר דִּבְּרוֹת, דְּאִינּוּן כְּלַל תרי\"ג פִּקוּדִין.","וְשִׁפְחָה יִצֶּר הָרָע אִיהִי מַלְיָא מוּמִין. וּבְגִין דָּא, (ויקרא כ״א:י״ח) כָל אֲשֶׁר בּוֹ מוּם לֹא יִקְרָב. וּבְגִין דָּא, כַּהֲנָא לָא הֲוָה צָּרִיךְ לְקָרְבָא לְגַבֵי מַאן דְּאִית בֵּיהּ מוּמָא, מִכָּל מוּמִין דְּעָלְמָא. בְּגִין דְּמַטְרוֹנִיתָא אִתְּמַר בָּהּ, (שיר השירים ד׳:ז׳) כֻּלָּךְ יָפָה רַעְיָתִי וּמוּם אֵין בָּךְ. הָכִי לָא צָּרִיךְ לְקָרְבָא לְגַבָּהּ מַאן דְּאִית בֵּיהּ מוּם, וְאוּף הָכִי לָא צָּרִיךְ לְמִקְרַב לְגַבָּהּ זָר (במדבר ג׳:י׳) וְהַזָּר הַקָּרֵב יוּמָת וְהַיְינוּ מַמְזִ\"ר, מוּ\"ם זָר. מוּם נוּקְבָּא, זָר זָכָר. וּבְגִין דָּא מָנֵי. (ויקרא י״ח:י״ט) וְאֶל אִשָּׁה בְּנִדַּת טוּמְאָתָהּ לֹא תִקְרַב וְעַל אִינּוּן דִּקְרִיבִין לָהּ, כְּתִיב בְּהוֹן וַיַקְרִיבוּ לִפְנֵי יְיָ' אֵשׁ זָרָה אֲשֶׁר לֹא צִּוָּה אוֹתָם וַתֵּצֵּא אֵשׁ מִלִּפְנֵי יְיָ'. וַתֹּאכַל אוֹתָם וַיָמוּתוּ.","וְקָרְבָּן דְּאַתְוָון אִינּוּן, י' בָּאִישׁ, ה' בָּאִשָּׁה, ו' בַּבֵּן חָתָן, ה' בַּכַּלָּה. זַכָּאָה אִיהוּ מַאן דְּאַקְרִיב אַתְוָון דִּיְדוָֹ\"ד, בֵּיהּ וּבְאִתְּתֵיהּ וּבִבְרֵיהּ וּבִבְרַתֵּיהּ, בִּקְדוּשָּׁה וּבִבְרָכָה בִּנְקִיוּ בַּעֲנָוָה וּבְבֹשֶׁת פָּנִים בְּכָל מִדוֹת טָבִין דִּכְתִיבִין עַל מָארֵי מַתְנִיתִין.","וּמִתְחַמְּמִין בְּאֶשִׁין קַדִישִׁין, דְּאִישׁ וְאִשָּׁה דְּאִינּוּן אֵשׁ, עוֹלֶה וְיּוֹרֵד, אֵשׁ קֹדֶשׁ דַּעֲצֵּי הַמַעֲרָכָה, דְּאִינּוּן עֲצֵּי הַקֹּדֶשׁ אֵבָרִין קַדִישִׁין, וְאֵשׁ שֶׁל גָּבוֹהַּ נָחִית, דְּאִיהוּ קֹדֶשׁ הַקָּדָשִׁים, וּבְגִין תְּרֵין אֶשִּׁין אִלֵּין אָמַר נָבִיא, (ישעיהו כ״ד:ט״ו) בָּאוּרִים כַּבְּדוּ יְיָ'. דְּאִינּוּן אֶשִּׁין דִּשְׁכִינְתָא, דְּבָהּ כְּתִיב (דברים ד׳:כ״ד) כִּי יְיָ' אֱלֹהֶיךָ אֵשׁ אוֹכְלָה הוּא.","וְאִינּוּן אֵשׁ עִלָּאָה כִּסֵּא רַחֲמִים. אֵשׁ תַּתָּאָה כִּסֵּא דִּין. וְאִינּוּן בִּינָה וּמַלְכוּת מַלְכוּת אֵשׁ עוֹלֶה. בִּינָה אֵשׁ יוֹרֵד. יְהוָֹ\"ה, עַמּוּדָא דְּאֶמְצָּעִיתָא, אָחִיד בְּתַרְוַויְיהוּ. בִּינָה יה\"ו ה' מַלְכוּת.","תִּפְאֶרֶת כַּד אָחִיד לוֹן, שַׁרְיָא עָלֵיהּ חָכְמָה, דְּבֵיהּ כֹּ\"חַ מַ\"ה. מָ\"ה: אִיהוּ יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. כֹּחַ דִּילֵיהּ, יוֹ\"ד וָא\"ו דָּלֶ\"ת. הֵ\"א אָלֶ\"ף. וָא\"ו אָלֶ\"ף וָא\"ו. הֵ\"א אָלֶ\"ף. וְכֻלְּהוּ מ\"ב אַתְוָון, מִשְׁתַּכְחִין בְּבַּר נָשׁ וּבְאִתְתֵיהּ וּבִבְנוֹי, וּבְגִין דָּא לֵית בַּר נָשׁ שְׁלִים, אֶלָּא בְּבֵן וּבַת.","וּמַאן דְּלֵית לֵיהּ בֵּן דְּאִיהוּ ו', אִסְתַּלָּק י' מִינֵיהּ. וּמַאן דְּלֵית לֵיהּ בַּת, דְּאִיהִי ה', אִסְתָּלַק ה' עִלָּאָה, דְּאִיהִי אֵם, מִן בַּת זוּגֵיהּ. דְּאַתְוָון לָא שַׁרְיָין דָּא בְּלָא דָּא. וּבְגִין דָּא, בְּאִישׁ וְאִשָּׁה בֵּן וּבַת, דְּאִתְעָבֵידוּ כְּדְקָא יִאוֹת, שַׁרְיָא עָלַיְיהוּ יְהוָֹ\"ה, וְאִתְקְרִיאוּ (שם י\"ד) (ס\"א בנים לקודשא בריך הוא. הדא הוא דכתיב) (דברים י״ד:א׳) בָּנִים אַתֶם לַיְדוָֹ\"ד אֱלֹהֵיכֶם. (ע\"כ רעיא מהימנא).","(ויקרא ז׳:ל״ה) זֹאת מִשְׁחַת אַהֲרֹן וּמִשְׁחַת בָּנָיו. רִבִּי יוֹסֵי אָמַר, זֹאת וַדַאי מְשִׁיחוּתָא דְּאַהֲרֹן. דְּהָא אַהֲרֹן אִתְמְשַׁח, וְאַיְיתֵי מִמְשַׁח רְבוּת עִלָּאָה מֵעֵילָּא, וְנָגִיד לֵיהּ לְתַתָּא. וְעַל יְדָא דְּאַהֲרֹן אִתְמְשַׁח, מִמְשִׁיחָתָא קַדִישָׁא לְאִתְבָּרְכָא, וְעַל דָּא זֹאת מִשְׁחַת אַהֲרֹן וּמִשְׁחַת בָּנָיו וַדַּאי.","רִבִּי יְהוּדָה פָּתַח, (מלכים ב ד׳:ב׳) וַיֹאמֶר אֵלֶיהָ אֱלִישָׁע מָה אֶעֱשֶׂה לָךְ הַגִידִי לִי מַה יֶּשׁ לָךְ בַּבָּיִת. מֵהָכָא אוֹלִיפְנָא, דְּלֵית בִּרְכָתָא שַׁרְיָא בְּפָתוֹרָא רֵיקַנְיָא, וְעַל מִלָּה רֵיקָנִית. וַתֹּאמֶר אֵין לְשִׁפְחָתְךָ כֹּל בַּבַּיִת כִּי אִם אָסוּךְ שָׁמֶן. אָמַר לָהּ, ודַּאי סִיּוּעָא דְּנִיסָּא הוּא, דְּהָא וַדַּאי בְּאַתְרֵיהּ הוּא, וּמִתַּמָּן בִּרְכָאן נָפְקִין וְשַׁרְיָין. מַה כְּתִיב הֵם מַגִּישִׁים אֵלֶיהָ וְהִיא מוֹצָקֶת. וְהִיא מוֹצָקֶת סְתָם.","רִבִּי יוֹסֵי אָמַר, וַיַּעֲמוֹד הַשָּׁמֶן, כְּמָה דְּאוּקְמוּהָ, דִּכְתִּיב, (ישעיהו ה׳:א׳) בְּקֶרֶן בֶּן שָׁמֶן. וּכְתִיב (שיר השירים א׳:ג׳) שֶׁמֶן תּוּרַק שְׁמֶךָ, לְאַחֲזָאָה דְּהָא מֵהַאי שֶׁמֶן, נְגִּידִין בִּרְכָאן עַל יְדָא דְּכַהֲנָא, וְכַהֲנָא נָגִיד לְהוּ לְתַתָּא, וְאַמְשַׁח (ס\"א ואתמשך) לְהַאי זֹאת, הֲדָא הוּא דִכְתִיב זֹאת מִשְׁחַת אַהֲרֹן וּמִשְׁחַת בָּנָיו, וּכְתִיב (תהילים קל״ג:ב׳) כַּשֶּׁמֶן הַטּוֹב עַל הָרֹאשׁ, וְהָא אִתְּמַר.","(ויקרא ח׳:ב׳) קַח אֶת אַהֲרֹן וְאֶת בָּנָיו אִתּוֹ וְאֶת הַבְּגָדִים. רִבִּי חִיָּיא פָּתַח (תהילים ל״ו:י׳) כִּי עִמְּךָ מְקוֹר חַיִּים בְּאוֹרְךָ נִרְאֶה אוֹר. כִּי עִמְּךָ מְקוֹר חַיִּים, דָּא שֶׁמֶן עִלָּאָה, דְּנָגִיד וְלָא פָּסִיק לְעָלְמִין, דְּשַׁרְיָא בְּגוֹ חָכְמָה עִלָּאָה דְּכֹלָּא, הֲדָא הוּא דִכְתִיב כִּי עִמְּךָ, עִמְּךָ שַׁרְיָא, וְלָא מִתְפָּרְשָׁא מִנָךְ לְעָלְמִין, בַּחֲבִיבוּתָא דְּכֹלָּא. מְקוֹר חַיִים, בְּגִין דְּהִיא מְקוֹרָא וּמַבּוּעָא דְּחַיִּים, לְאַפָּקָא חַיִּים לְאִילָנָא עִלָּאָה, וּלַאֲדְלָקָא בּוּצִינִין. וְעַל דָּא הַהוּא אִילָנָא אִקְרֵי עֵץ חַיִּים, אִילָנָא דְּנָטִיעַ וְאִשְׁתָּרְשָׁא בְּגִין הַהוּא מְקוֹרָא דְּחַיִּים.","וְעַל דָּא בְּאוֹרְךָ נִרְאֶה אוֹר. בְּאוֹרְךָ: דָּא אוֹר דְּגָנִיז לְצַדִּיקַיָּיא לְזִמְנָא דְּאָתֵי, דִּכְתִּיב, (בראשית א׳:ד׳) וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב. וּמֵהַהוּא נְהִירוּ זְמִינִין יִשְׂרָאֵל לְאַנְהָרָא לְעָלְמָא דְּאָתֵי."],[[0,"ועוד דדחקו שעתא וכו׳:","ועוד, שהיו דוחקים את השעה להקריב קטרת בחיי אביהם, שלא הותר להקריב קטרת לשום אדם בחייו, כמ״ש להלן (פ׳ אחרי אות ס״ח) ועוד שלא היו נשואים, והיו פגומים, כי מי שלא נשא אשה הוא פגום, ואינו ראוי שתמצאנה ברכות בעולם על ידו, כי הברכות אינן שורות עליו, וכל שכן שאינן נמשכות על ידו לאחרים. ועוד הרי למדנו, שתויי יין היו. ומשום זה, ותצא אש מלפני ה׳ ותאכל אותם וגו'. כי קטרת חביבה היא מכל הקרבנות, והיא שמחת עליונים ותחתונים. וכתוב, שמן וקטרת ישמח לב."],[1,"לית מצורע אלא וכו׳:","אין מצורע אלא אותו שנעשה בזבות, דהיינו שאמו נתעברה עמו בימי נדתה. כי חמש דמים הם בדם נדה המטמאים, שהם כולם דם טמא. וה׳ דמים יש שהם טהורים. ומי שעובר עליהם, כאלו עבר על עשרת הדברות, שהם כלל כל תרי״ג מצות."],[2,"ושפחה יצר הרע וכו׳:","והקליפה שנקראת שפחה, שהיא יצר הרע, היא מלאה מומים. ומשום זה, כל איש אשר בו מום לא יקרב. ומשום זה, אין הכהן צריך לקרב למי שיש בו מום מכל מומים שבעולם, משום שהמטרוניתא, שהיא המלכות, נאמר בה, כלך יפה רעיתי ומום אין בך, וכך אין צריך לקרב אליה מי שיש בו מום. ואף כך, לא צריך לקרב אליה זר, והזר הקרב יומת. והיינו סוד \u0003ממזר,\u0004 שהוא אותיות \u0003מום זר,\u0004 שהם דכר ונוקבא וקליפות, \u0003מום,\u0004 היא הנקבה, \u0003זר\u0004 הוא הזכר. ומשום זה צוה ואל אשה בנדת טומאתה לא תקרב. ועל אותם שקרבו אליה, דהיינו נדב ואביהוא, כתוב בהם, ויקריבו לפני ה׳ אש \u0003זרה\u0004 אשר לא צוה אותם ותצא אש מלפני ה׳ ותאכל אותם וימותו."],[3,"וקרבן דאתוון אינון וכו׳:","וקרבן האותיות, והיינו יחוד אותיות השם, היא, \u0003י׳\u0004 באיש, \u0003ה׳\u0004 באשה, שהם סוד או״א, \u0003ו׳\u0004 בבן, חתן, שה״ס ז״א, \u0003ה׳\u0004 בכלה, שה״ס המלכות. אשרי הוא מי שמיחד ומקרב האותיות דהוי״ה, בו ובאשתו, כנגד \u0003י״ה,\u0004 ובבנו ובבתו, כנגד \u0003ו״ה,\u0004 בקדושה ובברכה בטהרה בענוה ובבושת פנים ובכל מדות טובות הכתובים על ידי בעלי המשנה."],[4,"ומתחממין באשין קדישין וכו׳:","ומתחממים באשות קדושות דאיש ואשה, שה״ס י״ה כנ״ל, שהם אש עולה ויורדת, כי אש הנקבה היא עולה ממטה למעלה, ואש הזכר יורדת ממעלה למטה. אש \u0003קודש\u0004 של עצי המערכה, שהם עצי הקדש, האברים הקדושים, ואש של גבוה יורדת, שהיא \u0003קדש קדשים,\u0004 ובשביל שתי אשות אלו, אמר הנביא, באורים כבדו ה׳, שהם אשות של השכינה, שבה כתוב, כי ה׳ אלקיך אש אוכלה הוא."],[5,"ואינון אש עלאה וכו׳:","והרע״מ מפרש דבריו, ואומר שאלו ב׳ אשות הנ״ל, הם, אש עליון שהוא כסא הרחמים, ואש תחתון שהוא כסא דין, שהם, בינה שה״ס הרחמים, ומלכות שה״ס דין. מלכות היא אש עולה ממטה למעלה, בינה היא אש יורדת ממעלה למטה. הוי״ה שהוא עמוד האמצעי. ת״ת, אחוז בשתיהן, וע״כ אש עליון ה\"ס יה״ו, שי״ה ה״ס בינה, וה \u0003ו׳\u0004 הוא ת״ת האחוז בה. ואש תחתון ה״ס \u0003ה׳\u0004 אחרונה מלכות."],[6,"תפארת כד אחיד וכו׳:","תפארת כשנאחז בהן, בב׳ אשות הנ״ל בינה ומלכות, שורה עליו \u0003חכמה.\u0004 שבו אותיות \u0003כ״ח מ״ה.\u0004 מ״ה, היא יוד הא ואו הא, שבגימטריא מ\"ה. כ״ח שלו, ה״ס מילוי המילוי של הויה דאלפין, כזה: יו״ד, וא\"ו דל״ת. ה״א, אלף. ואו, אלף, ואו. הא, אלף. ועם ד׳ אותיות הוי״ה פשוטים בלי מילוי, הם ביחד מ״ב. דהיינו ד׳ אותיות הויה בלי מילוי, ועשר אותיות של הויה במילוי, וכ״ח אותיות של הויה במילוי המילוי. וכל מ״ב אותיות אלו נמצאות באדם, ובאשתו, ובבניו, שה״ס ד׳ אותיות הויה, (כנ״ל אות קנ״ז) אשר עם סוד המילוי, ועם מילוי המילוי הם מ\"ב אותיות. ומשום זה אין האדם שלם, אלא בבן ובת."],[7,"ומאן דלית ליה וכו׳:","ומי שאין לו בן, שהוא \u0003ו׳\u0004 דהויה, מסתלקת ממנו \u0003י'\u0004 דהויה. ומי שאין לו בת, שהיא \u0003ה'\u0004 אחרונה דהויה, מסתלקת ממנו \u0003ה׳\u0004 עליונה, שהיא האם של בת זוגו, בי האותיות אינן שורות זו בלי זו. ומשום זה, באיש ואשה בן ובת, שנעשו כראוי, שורה עליהם \u0003הויה,\u0004 ונקראים, בנים אתם לה׳ אלקיכם. (ע״כ רעיא מהימנא)."],[8,"זאת משחת אהרן ומשחת בניו:","ר׳ יוסי אמר, \u0003זאת\u0004 שהיא המלכות, היא ודאי המשחה של אהרן. כי אהרן נמשח מחכמה, והביא משמן המשחה העליון מלמעלה שהוא חכמה, והמשיכו למטה אל המלכות. וע״י אהרן נמשחה המלכות, ממשחת קדש להתברך. וע״כ נאמר, \u0003זאת\u0004 משחת אהרן ומשחת בניו. ודאי."],[9,"רבי יהודה פתח וכו׳:","רי״פ, ויאמר אליה אלישע מה אעשה לך הגידי לי מה יש לך בבית. מכאן למדנו, שאין הברכה שורה בשולחן ריק, ועל דבר ריק. ותאמר אין לשפחתך כל בבית כי אם אסוך שמן. אמר לה, אלישע, ודאי הוא עזרת הנס מה שיש לך שמן, שהוא רומז על חכמה, כי ודאי במקומו הוא, במקום החכמה, שמשם יוצאות הברכות ושורות למטה. מה כתוב, הם מגישים אליה והיא מוצקת. שנאמר והיא מוצקת סתם, שלא נזכר מי מוצקת, כי סובב על החכמה."],[10,"ר׳ יוסי אמר וכו׳:","רי״א, ויעמוד השמן, היינו כמו שהעמידו, שכתוב בקרן בן שמן. שקרן פירושו מלכות, ושמן הוא חכמה. וכתוב, שמן תורק שמך, שפירושו שהשמן שהוא חכמה משפיע לשמך שהוא מלכות. להראות שמשמן הזה, שהוא חכמה, נמשכות ברכות על ידי הכהן, והכהן ממשיך אותו למטה, ומושח ל \u0003זאת\u0004 הזו שהיא המלכות. ז״ש, זאת משחת אהרן ומשחת בניו. שפירושו ש \u0003זאת\u0004 שהיא מלכות היא נמשחה על ידי אהרן, שהוא המשיך השמן מחכמה. וכתוב, כשמן הטוב על הראש וגו' הרי שהשמן. נמשך על ראש אהרן. והיא ממשיכה למלכות. והרי למדנו."],[11,"קח את אהרן וגו׳:","קח את אהרן ואת בניו אתו ואת הבגדים. ר׳ חייא פתח, כי עמך מקור חיים באורך נראה אור. \u0003כי עמך מקור חיים,\u0004 זה הוא שמן העליון הנמשך ואינו נפסק לעולם, שהוא שורה בתוך חכמה העליונה על הכל. ז\"ש \u0003כי עמך,\u0004 ששורה \u0003עמך\u0004 באהבה שעל הכל, ואינו נפרד ממך לעולם, \u0003מקור חיים.\u0004 שהיא בינה, כי חכמה ובינה הם דבוקים יחד בזווג שאינו נפסק לעולם. ונקראת הבינה מקור חיים, משום שהיא המקור והמבוע של החיים, שהוא השפעת החכמה שנקרא חיים, להוציא החיים מן החכמה, בשביל האילן העליון, שהוא ז״א, ולהדליק הנרות של המלכות. וע״כ האילן ההוא, ז״א, נקרא עץ החיים. שהוא אילן הנטוע ונשרש במקור החיים ההוא, שהוא בינה."],[12,"ועל דא באורך וכו׳:","ועל כן, \u0003באורך נראה אור.\u0004 באורך, זה הוא האור הגנוז לצדיקים לעתיד לבא. שכתוב וירא אלקים את האור כי טוב. ומאותו האור עתידים מתלבשים נר״ן האלו בנר״ן הבהמיים של האדם ישראל להאיר לעולם הבא."]],[[0,"","וְעוֹד, שֶׁדָּחֲקוּ אֶת הַשָּׁעָה בְּחַיֵּי אֲבִיהֶם, וְעוֹד שֶׁלֹּא הָיוּ נְשׂוּאִים, וְהָיוּ פְגוּמִים. שֶׁמִּי שֶׁלֹּא נִשָּׂא הוּא פָּגוּם, וְאֵינוֹ כְדַאי שֶׁיִּמָּצְאוּ בְרָכוֹת עַל יָדוֹ בָּעוֹלָם. עָלָיו הֵן לֹא שׁוֹרוֹת, כָּל שֶׁכֵּן עַל יְדֵי אֲחֵרִים. וְעוֹד, שֶׁהֲרֵי שָׁנִינוּ שֶׁהָיוּ שְׁתוּיֵי יַיִן, וּמִשּׁוּם כָּךְ וַתֵּצֵא אֵשׁ מִלִּפְנֵי ה' וַתֹּאכַל אֹתָם וְגוֹ'. שֶׁהֲרֵי הַקְּטֹרֶת הִיא חֲבִיבָה מִן הַכֹּל, וְהִיא שִׂמְחַת הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים. וְכָתוּב שֶׁמֶן וּקְטֹרֶת יְשַׂמַּח לֵב."],[1,"","רעיָּא מְהֵיּמְנָא אֵין מְצֹרָע אֶלָּא אוֹתוֹ שֶׁנַּעֲשֶׂה בְזִיבָה. שֶׁחֲמִשָּׁה דָמִים הֵם שֶׁל דַּם נִדָּה שֶׁמְּטַמְּאִים, שֶׁכֻּלָּם הֵם דָּם טָמֵא, וַחֲמִשָּׁה דָמִים טְהוֹרִים. וּמִי שֶׁעוֹבֵר עֲלֵיהֶם כְּאִלּוּ עָבַר עַל עֲשֶׂרֶת הַדִּבְּרוֹת, שֶׁהֵם כְּלָל שֶׁל תַּרְיַ\"ג מִצְווֹת."],[2,"","וְשִׁפְחָה, יֵצֶר הָרָע, הִיא מְלֵאָה בְּמוּמִים, וּמִשּׁוּם כָּךְ (ויקרא כא) כָּל אֲשֶׁר בּוֹ מוּם לֹא יִקְרָב. וּמִשּׁוּם זֶה הַכֹּהֵן לֹא הָיָה צָרִיךְ לִקְרַב אֶל מִי שֶׁיֵּשׁ בּוֹ מוּם מִכָּל הַמּוּמִים שֶׁבָּעוֹלָם, מִשּׁוּם שֶׁנֶּאֱמַר בַּגְּבִירָה, (שיר ד) כֻּלָּךְ יָפָה רַעְיָתִי וּמוּם אֵין בָּךְ, כָּךְ לֹא צָרִיךְ לִקְרַב אֵלֶיהָ מִי שֶׁיֵּשׁ בּוֹ מוּם, וְאַף כָּךְ לֹא צָרִיךְ לִקְרַב אֵלֶיהָ זָר, (במדבר ג) וְהַזָּר הַקָּרֵב יוּמָת, וְהַיְנוּ מַמְזֵ\"ר, מוּ\"ם זָר. מוּם נְקֵבָה, זָר זָכָר. וּמִשּׁוּם כָּךְ צִוָּה, (ויקרא יח) וְאֶל אִשָּׁה בְּנִדַּת טֻמְאָתָהּ לֹא תִקְרַב. וְעַל אוֹתָם שֶׁקְּרֵבִים אֵלֶיהָ כָּתוּב בָּהֶם, וַיַּקְרִיבוּ לִפְנֵי ה' אֵשׁ זָרָה אֲשֶׁר לֹא צִוָּה אֹתָם וַתֵּצֵא אֵשׁ מִלִּפְנֵי ה' וַתֹּאכַל אוֹתָם וַיָּמֻתוּ."],[3,"","וְקָרְבָּן שֶׁל אוֹתִיּוֹת הֵם, י' בָּאִישׁ, ה' בָּאִשָּׁה, ו' בַּבֵּן חָתָן, ה' בַּכַּלָּה. אַשְׁרֵי מִי שֶׁמַּקְרִיב אוֹתִיּוֹת יְהֹוָ\"ה בּוֹ וּבְאִשְׁתּוֹ וּבִבְנוֹ וּבְבִתּוֹ בִּקְדֻשָּׁה וּבִבְרָכָה, בִּנְקִיּוּת, בַּעֲנָוָה וּבְבֹשֶׁת פָּנִים, בְּכָל מִדּוֹת טוֹבוֹת שֶׁכְּתוּבוֹת עַל בַּעֲלֵי הַמִּשְׁנָה."],[4,"","וּמִתְחַמְּמִים בְּאִשִּׁים קְדוֹשִׁים, שֶׁאִישׁ וְאִשָּׁה שֶׁהֵם אֵשׁ, עוֹלֶה וְיוֹרֵד, אֵשׁ קֹדֶשׁ שֶׁל עֲצֵי הַמַּעֲרָכָה, שֶׁהֵם עֲצֵי הַקֹּדֶשׁ אֵיבָרִים קְדוֹשִׁים, וְאֵשׁ שֶׁל גָּבוֹהַּ יוֹרֵד, שֶׁהִיא קֹדֶשׁ הַקְּדָשִׁים, וּבִשְׁבִיל שְׁנֵי הָאִשִּׁים הַלָּלוּ אָמַר הַנָּבִיא (ישעיה כד) בָּאוּרִים כַּבְּדוּ ה', שֶׁהֵם הָאִשִּׁים שֶׁל הַשְּׁכִינָה, שֶׁבָּהּ כָּתוּב (דברים ד) כִּי ה' אֱלֹהֶיךְ אֵשׁ אֹכְלָה הוּא."],[5,"","וְהֵם אֵשׁ עֶלְיוֹן, כִּסֵּא רַחֲמִים. אֵשׁ תַּחְתּוֹנָה, כִּסֵּא דִין. וְהֵם בִּינָה וּמַלְכוּת. מַלְכוּת - אֵשׁ עוֹלֶה. בִּינָה - אֵשׁ יוֹרֵד. יְהֹוָה, עַמּוּד הָאֶמְצָעִי, אוֹחֵז בִּשְׁנֵיהֶם. בִּינָה יה\"ו, ה' מַלְכוּת."],[6,"","כַּאֲשֶׁר הַתִּפְאֶרֶת אוֹחֶזֶת אוֹתָם, שׁוֹרָה עָלָיו חָכְמָה, שֶׁבָּהּ כֹּ\"חַ מָ\"ה. מָ\"ה - הוּא יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. הַכֹּחַ שֶׁלּוֹ - יוֹ\"ד וָא\"ו דָּלֶ\"ת. הֵ\"א אָלֶ\"ף. וָא\"ו אָלֶ\"ף וָא\"ו. הֵ\"א אָלֶ\"ף. וְכֻלָּן אַרְבָּעִים וּשְׁתַּיִם אוֹתִיּוֹת נִמְצָאוֹת בָּאָדָם וּבְאִשְׁתּוֹ וּבְבָנָיו, וּמִשּׁוּם כָּךְ אֵין אָדָם שָׁלֵם אֶלָּא בְּבֵן וּבַת."],[7,"","וּמִי שֶׁאֵין לוֹ בֵּן, שֶׁהוּא ו', מִסְתַּלֶּקֶת מִמֶּנּוּ י'. וּמִי שֶׁאֵין לוֹ בַּת, שֶׁהִיא ה', מִסְתַּלֶּקֶת ה' הָעֶלְיוֹנָה, שֶׁהִיא אֵם, מִבַּת זוּגוֹ. שֶׁהָאוֹתִיּוֹת לֹא שׁוֹרוֹת זוֹ בְּלִי זוֹ, וּמִשּׁוּם כָּךְ בְּאִישׁ וְאִשָּׁה, בֵּן וּבַת שֶׁנַּעֲשׂוּ כָרָאוּי, שׁוֹרֶה עֲלֵיהֶם יְהֹוָ\"ה, וְנִקְרָאִים (בנים לקדוש ברוך הוא. זהו שכתוב) (שם יד) בָּנִים אַתֶּם לַה' אֱלֹהֵיכֶם. (ע\"כ רעיא מהימנא)."],[8,"","זֹאת מִשְׁחַת אַהֲרֹן וּמִשְׁחַת בָּנָיו. רַבִּי יוֹסֵי אָמַר, זֹּאת וַדַּאי מְשִׁיחַת אַהֲרֹן, שֶׁהֲרֵי אַהֲרֹן נִמְשַׁח, וּבָא מִשֶּׁמֶן מִשְׁחָה עָלָיו מִלְמַעְלָה, וּמַשְׁפִּיעַ אוֹתוֹ לְמַטָּה. וְעַל יְדֵי שֶׁאַהֲרֹן נִמְשַׁח מִמְּשִׁיחָה קְדוֹשָׁה לְהִתְבָּרֵךְ, וְעַל זֶה זֹּאת מִשְׁחַת אַהֲרֹן וּמִשְׁחַת בָּנָיו וַדַּאי."],[9,"","רַבִּי יְהוּדָה פָּתַח, (מלכים בד) וַיֹּאמֶר אֵלֶיהָ אֱלִישָׁע מָה אֶעֱשֶׂה לָּךְ הַגִּידִי לִי מַה יֶּשׁ לָךְ בַּבָּיִת. מִכָּאן לָמַדְנוּ, שֶׁאֵין הַבְּרָכָה שׁוֹרָה בְשֻׁלְחָן רֵיק וְעַל דָּבָר רֵיקָנִי. וַתֹּאמֶר אֵין לְשִׁפְחָתְךְ כֹל בַּבַּיִת כִּי אִם אָסוּךְ שָׁמֶן. אָמַר לָהּ, וַדַּאי זֶהוּ סִיּוּעַ שֶׁל נֵס, שֶׁהֲרֵי וַדַּאי אַחֲרָיו הוּא, וּמִשָּׁם בְּרָכוֹת יוֹצְאוֹת וְשׁוֹרוֹת. מַה כָּתוּב? הֵם מַגִּישִׁים אֵלֶיהָ וְהִיא מוֹצָקֶת. וְהִיא מוֹצָקֶת סְתָם."],[10,"","רַבִּי יוֹסֵי אָמַר, וַיַּעֲמֹד הַשָּׁמֶן, כְּמוֹ שֶׁבֵּאֲרוּהָ, שֶׁכָּתוּב (ישעיה ה) בְּקֶרֶן בֶּן שָׁמֶן. וְכָתוּב (שיר א) שֶׁמֶן תּוּרַק שְׁמֶךְ, לְהַרְאוֹת שֶׁהֲרֵי מֵהַשֶּׁמֶן הַזֶּה שׁוֹפְעוֹת בְּרָכוֹת עַל יַד הַכֹּהֵן, וְהַכֹּהֵן מַשְׁפִּיעַ אוֹתָן לְמַטָּה וּמוֹשֵׁחַ (ונמשך) לַזֹּאת הַזּוֹ. זֶהוּ שֶׁכָּתוּב זֹּאת מִשְׁחַת אַהֲרֹן וּמִשְׁחַת בָּנָיו, וְכָתוּב (תהלים קלג) כַּשֶּׁמֶן הַטּוֹב עַל הָרֹאשׁ, וַהֲרֵי נִתְבָּאֵר."],[11,"","קַח אֶת אַהֲרֹן וְאֶת בָּנָיו אִתּוֹ וְאֶת הַבְּגָדִים. רַבִּי חִיָּיא פָּתַח, כִּי עִמְּךְ מְקוֹר חַיִּים בְּאוֹרְךְ נִרְאֶה אוֹר. כִּי עִמְּךְ מְקוֹר חַיִּים - זֶה הַשֶּׁמֶן הָעֶלְיוֹן שֶׁשּׁוֹפֵעַ וְאֵינוֹ פוֹסֵק לְעוֹלָמִים, שֶׁשָּׁרוּי בְּתוֹךְ הַחָכְמָה הָעֶלְיוֹנָה שֶׁל הַכֹּל. זֶהוּ שֶׁכָּתוּב כִּי עִמְּךְ, עִמְּךְ שָׁרוּי, וְלֹא נִפְרָד מִמְּךְ לְעוֹלָמִים, בַּחֲבִיבוּת שֶׁל הַכֹּל. מְקוֹר חַיִּים, מִשּׁוּם שֶׁהִיא מְקוֹר וּמַעְיַן הַחַיִּים, לְהוֹצִיא חַיִּים לָעֵץ הָעֶלְיוֹן וּלְהַדְלִיק אֶת הַנֵּרוֹת. וְעַל זֶה אוֹתוֹ הָעֵץ נִקְרָא עֵץ חַיִּים, הָאִילָן שֶׁנָּטוּעַ וְנִשְׁרָשׁ מִשּׁוּם אוֹתוֹ מְקוֹר הַחַיִּים."],[12,"","וְעַל זֶה בְּאוֹרְךְ נִרְאֶה אוֹר. בְּאוֹרְךְ - זֶה הָאוֹר שֶׁגָּנוּז לַצַּדִּיקִים לֶעָתִיד לָבֹא, שֶׁכָּתוּב (בראשית א) וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב. וּמֵאוֹתוֹ אוֹר עֲתִידִים יִשְׂרָאֵל לְהָאִיר בָּעוֹלָם הַבָּא."]]],[["דָּבָר אַחֵר כִּי עִמְּךָ מְקוֹר חַיִּים וְגוֹ', דָּא קוּדְשָׁא בְּרִיךְ הוּא, דְּאִיהוּ אִילָנָא עִלָּאָה בִּמְצִיעוּת גִּנְתָּא, דְּאָחִיד לְכָל סִטְרִין. מַאי טַעְמָא. בְּגִין דְּאָחִיד בֵּיהּ הַהוּא (נ\"א בההוא) מְקוֹר חַיִּים, וְאַעְטַּר לֵיהּ בְּעִטְרִין עִלָּאִין סַחֲרָנֵיהּ דְּגִּנְתָּא. כְּאִימָּא דִּמְעַטְּרָא לִבְרָהּ עַל כֹּלָּא, הֲדָא הוּא דִּכְתִּיב, (שיר השירים ג׳:י״א) צְאֶינָה וּרְאֶינָה בְּנוֹת צִיּוֹן וְגוֹ'. וּבְגִין כָּךְ כִּי עִמְּךָ מְקוֹר חַיִּים, וְעַל דָּא בְּאוֹרְךָ נִרְאֶה אוֹר.","רִבִּי יִצְחָק אָמַר, כִּי עִמְּךָ מְקוֹר חַיִּים, דָּא כֹּהֵן גָּדוֹל לְעֵילָּא, לָקֳבְלֵיהּ כֹּהֵן גָּדוֹל לְתַתָּא. בְּגִין כַּךְ, אַנְגִּיד כַּהֲנָא מְשַׁח רְבוּת עִלָּאָה קַדִּישָׁא לְתַתָּא, וְאַדְלִיק בּוּצִינִין לְעֵילָּא. דְּכֹהֵן גָּדוֹל שְׁלִים בִּשְׁלִימוּ דְּז' יוֹמִין עִלָּאִין, וּלְאִתְעַטְּרָא עַל כֹּלָּא.","לָקֳבֵל דָּא ז' יְמֵי מִלּוּאִים, לְכַהֲנָא דִּלְתַתָּא, לְאִשְׁתַּכְּחָא כֹּלָּא כְּגַוְונָא דִּלְעֵילָּא. וְעַל דָּא יְמֵי מִלּוּאִים אִקְרוּן: יוֹמֵי אַשְׁלְמוּתָא. בְּגִין דְּיִשְׁתְּלִים כַּהֲנָא בִּשְׁאָר יוֹמִין אָחֳרָנִין, לְאַשְׁלְמָא ז' כַּחֲדָא. וְאִלֵּין יְמֵי מִלּוּאִים אִקְרוּן, בְּגִין דְּאִתְאַחֲדָן שְׁאָר אָחֳרָנִין בֵּיהּ. מַאי קָא מַיְירֵי. דְּכַד כַּהֲנָא אִתְּעַר, כָּל שְׁאָר אָחֳרָנִין מִתְעָרִין עִמֵּיהּ.","וּבְגִין כָּךְ כְּתִיב וּמִפֶּתַח אֹהֶל מוֹעֵד וְגוֹ', עַד יוֹם מְלֹאת וְגוֹ'. ז' יוֹמִין וַדַּאי, כְּדֵין אִתְעֲטָּר כַּהֲנָא לְתַתָּא בְּכֹלָּא, כְּגַוְונָא דִּלְעֵילָּא. בְּגִין דִּבְשַׁעֲתָא דְּכַהֲנָא דִּלְתַתָּא אִתְּעַר, כֹּלָּא יִתְּעֲרוּן עַל יְדֵיהּ לְעֵילָּא, וְיִשְׁתַּכְחוּן בִּרְכָאן לְעֵילָּא וְתַתָּא.","רִבִּי אַבָּא אָמַר, מַאי שְׁנָא דְּמַשַׁח מֹשֶׁה לְאַהֲרֹן. אֶלָּא, בְּגִין דְּאִיהוּ בְּרָא דְּהַהוּא (ס\"א אחיד בההוא) אֲתַר מְקוֹרָא דְּחַיֵּי. וּכְתִיב (ישעיהו ס״ג:י״ב) מוֹלִיךְ לִימִין מֹשֶׁה זְרוֹעַ תִּפְאַרְתּוֹ. וּמֹשֶׁה שִׁמֵּשׁ כָּל אִינּוּן ז' יְמֵי מִלּוּאִין, לְאַשְׁרָאָה כֹּלָּא עִמֵּיהּ דְּאַהֲרֹן.","רִבִּי חִזְקִיָּה הֲוָה יָתִיב קָמֵי דְּרִבִּי אֶלְעָזָר, אָמַר לֵיהּ, כַּמָה נְהוֹרִין אִתְבְּרִיאוּ עַד לָא אִבְרֵי עָלְמָא. אָמַר לֵיהּ ז'. וְאִלֵּין אִינּוּן: אוֹר תּוֹרָה. אוֹר גֵּיהִנָּם. אוֹר גַּן עֵדֶן. אוֹר כִּסֵּא הַכָּבוֹד. אוֹר בֵּית הַמִּקְדָּשׁ. אוֹר תְּשׁוּבָה. אוֹרוֹ שֶׁל מָשִׁיחַ. וְאִלֵּין אִתְבְּרִיאוּ עַד לָא אִתְבְּרֵי עָלְמָא. ז' נְהוֹרִין בּוּצִינִין אִתְאֲחָדוּ בֵּיהּ בְּאַהֲרֹן, וְהוּא אַדְלִיק בּוּצִינִין מֵעֵילָּא לְתַתָּא.","רִבִּי אֶלְעָזָר פָּתַח (קהלת ג׳:כ׳) הַכֹּל הָיָה מִן הֶעָפָר וְהַכֹּל שָׁב אֶל הֶעָפָר. הָא תָּנֵינָן, הַכֹּל הָיָה מִן הֶעָפָר, אֲפִילּוּ גַּלְגַּל חַמָּה. מַאן הֶעָפָר. הַהוּא דְּשַׁרְיָא תְּחוֹת כּוּרְסֵי יְקָרָא קַדִּישָׁא.","בְּסִפְרָא דְּבֵי רַב יֵיסָא סָבָא, הַכֹּל הָיָה מִן הֶעָפָר, אֲתַר דְּכָנִישׁ לְכֹלָּא, מְלַמֵּד, דְּנַפְקוּ שְׁבִילִין לְהַאי סִטְרָא וּלְהַאי סִטְרָא, וְאִתְכְּנָשׁוּ לְאַנְהָרָא, כְּעַפְרָא דָּא דְּזַרְקִין לָהּ לְכָל עִבָר. וְעַל דָּא הַכֹּל הָיָה מִן הֶעָפָר, וְהַכֹּל שָׁב אֶל הֶעָפָר וַדַּאי.","אֶלָּא מִן הֶעָפָר, דְּבֵי מַקְדְּשָׁא קַדִּישָׁא. וְהַאי עָפָר מֵעַפְרָא עִלָּאָה, כְּמָה דְאַתְּ אָמֵר (איוב כ״ח:ו׳) וְעַפְרוֹת זָהָב לוֹ. כְּמָה דְּאִשְׁתְּכַח עוֹבָדָא לְתַתָּא, הָכִי נָמֵי הוּא לְעֵילָּא כְּגַוְונָא דָּא. וְאוֹקִימְנָא עָפָר, עָפָר דְּבֵי מַקְדְּשָׁא. דְּעָלְמָא דָּא בְּה' אִתְבְּרֵי. וְעַל דָּא, אֲפִילּוּ גַּלְגַּל חַמָּה. כְּמָה דְּאַתְּ אָמֵר, אֵלֶה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם, בְּה' בְּרָאָם. וּבְגִּינֵי כַּךְ, הַכֹּל הָיָה מִן הֶעָפָר. מַאן עָפָר. הַהוּא דְּשָׁרִי תְּחוֹת כּוּרְסֵי יְקָרָא קַדִּישָׁא.","כְּתִיב (שיר השירים ד׳:ז׳) כֻּלָּךְ יָפָה רַעְיָתִי וּמוּם אֵין בָּךְ. כֻּלָּךְ יָפָה רַעְיָתִי, דָּא כְּנֶסֶת יִשְׂרָאֵל. וּמוּם אֵין בָּךְ, אֵלּוּ סַנְהֶדְרִין דְּאִינּוּן לָקֳבֵיל שִׁבְעִין וּתְרֵין שְׁמָהָן. ע' נֶפֶשׁ דְּנַחְתּוּ עִם יַעֲקֹב, וְקוּדְשָׁא בְּרִיךְ הוּא עַל כֹּלָּא. וְעַל דָּא אֵין בּוֹדְקִין מִן הַסַנְהֶדְרִין וּלְמַעְלָה תְּנָן.","כְּתִיב (שמות י״ט:ו׳) וְאַתֶם תִּהְיוּ לִי מַמְלֶכֶת כֹּהֲנִים וְגוֹי קָדוֹשׁ. מַאן מַמְלֶכֶת כֹּהֲנִים. כְּמָה דְאַתְּ אָמֵר, זֹאת מִשְׁחַת אַהֲרֹן וּמִשְׁחַת בָּנָיו, דְּכַד אִתְבָּרְכָא כְּנֶסֶת יִשְׂרָאֵל עַל יְדָא דְּכַהֲנֵי, כְּדֵין אִתְקְרֵי עַל שְׁמֵיהוֹן, הֲדָא הוּא דִכְתִיב מַמְלֶכֶת כֹּהֲנִים.","רַבִּי שִׁמְעוֹן אָמַר, תָּא חֲזֵי, מַלְכוּת כֹּהֲנִים לָא אִקְרֵי, אֶלָּא מַמְלֶכֶת, דְּאַמְלְכוּ לָהּ כַּהֲנֵי, וְעַבְדוּ לָהּ (גבירתא) גְּבוּרְתָּא עַל כֹּלָּא. אֲבָל מַלְכוּת כֹּהֲנִים לָא אִקְרֵי, דְּהָא מִן הַשָּׁמַיִם אִקְרֵי מַלְכוּת, מַלְכוּת שָׁמַיִם וַדַּאי. וְהָכָא מַמְלֶכֶת, כְּמָה דְאַתְּ אָמֵר דְּכַהֲנֵי אַמְלְכוּ לָהּ, וּמְחַבְּרָאן לָהּ בְּמַלְכָּא, וּכְדֵין הִיא מַמְלֶכֶת, עַל כָּל גִּנְזֵי מַלְכָּא. מַמְלֶכֶת עַל כָּל זַיְנֵי מַלְכָּא. מַמְלֶכֶת בְּעִלָּאֵי וְתַתָּאֵי. מַמְלֶכֶת עַל כָּל עָלְמָא."],[[0,"ד״א, כי עמך וגו׳:","פירוש אחר. כי עמך מקור חיים וגו'. זהו הקב״ה, שהוא אילן העליון, ז״א, באמצע הגן, שהוא מלכות, הכולל כל הצדדים, הכולל ימין ושמאל. מהו הטעם. הוא, משום שאחוז בו מקור חיים ההוא, שהוא בינה, ומעטרהו בעטרות עליונות מסביב הגן, כי הגן, שהוא המלכות, מלבשת את ז\"א ומסבבת אותו, ואז ז״א מקבל המוחין דג״ר שה״ס עטרות, מבינה. שהיא כמו אם המעטרת את בנה על הכל. ז״ש צאנה וראנה בנות ציון במלך שלמה בעטרה שעטרה לו אמו. ועל זה נאמר כי עמך מקור חיים. ועל זה, באורך נראה אור."],[1,"ר׳ יצחק אמר וכו׳:","רי״א, כי עמך מקור חיים, זהו הכהן הגדול למעלה, שהוא חסד דז״א, וכנגדו הוא הכהן הגדול למטה, בעולם הזה, וע״כ ממשיך הכהן שהוא חסד שמן המשחה העליון הקדוש, שהוא חכמה, למטה, אל המלכות, ומדליק הנרות שלמעלה, שהם ז׳ הספירות חג״ת נהי״ם, כי כהן הגדול, שהוא חסד, שלם בשלמות ז׳ ימים העליונים, שהם חג״ת נהי\"מ, להתעטר על כל הספירות. כי החסד כולל בתוכו כל ז׳ הספירות."],[2,"לקבל דא ז׳ וכו׳:","כנגד זה, שלמעלה, יש ז׳ ימי מילואים להכהן שלמטה בעולם הזה, כדי שימצא הכל כעין שלמעלה. וע״כ נקראים ימי מילואים, שפירושו ימי ההשלמה, כדי שיושלם הכהן, שהוא כנגד חסד, בשאר ימים אחרים, של ז׳ הספירות, כדי להשלים שבע ספירות ביחד. וע״כ נקראים אלו ימי מילואים, משום ששאר ספירות האחרות נתאחדו בו. שואל, מה זאת אומרת. ומשיב, שהפירוש הוא, שאם הכהן נתעורר להשפיע מתעוררת עמו גם שאר ספירות האחרות להשפיע, מתוך שהן התאחדו עמו יחד."],[3,"ובג״כ כתיב ומפתח וגו׳:","ומשום זה כתוב, ומפתח אהל מועד וגו' עד יום מלאת וגו', ז׳ ימים ודאי, כדי להשלים ז׳ ספירות, אז מתעטר הכהן למטה לגמרי כעין שלמעלה, כדי שבשעה שהכהן שלמטה יתעורר, יתעורר על ידו הכל למעלה, כל ז״ס, ותמצאנה הברכות למעלה ולמטה."],[4,"ר׳ אבא אמר וכו׳:","רא״א, מה השינוי שמשה שהוא ת״ת, משח את אהרן שהוא חסד, הגבוה מת״ת. ומשיב. אלא משום שהוא בן לאותו מקום שהוא מקור החיים, שהוא בינה, וכתוב מוליך לימין משה זרוע תפארתו. ומשה שמש כל אלו ז׳ ימי מילואים להשרות הכל עם אהרן."],[4,"","פירוש. משה הוא בן הבינה, שה״ס דעת, דהיינו ת״ת שעלה והכריע בין ב׳ קוין של הבינה ונעשה שם סוד הדעת, ויחד אותם זה בזה, והאירם, שמשום זה, כיון דתלת מחד נפקי, שיצאו ג׳ קוין בבינה, חב״ד, חד בתלת קיימא, יצאו ג׳ קוין ונתפשטו גם בת״ת, שהם חג״ת, (כנ״ל ב״א דף רפ״ז ד״ה תלת) ונמצא שמשה שה״ס בן הבינה, דהיינו דעת, הוא גבוה מן החסד, שהחסד הוא התפשטות שלו, שהוא נקרא ימין משה, דהיינו הקו ימין שלו. כמ״ש מוליך לימין משה וגו'. וע״כ שמש משה בז׳ ימי מילואים, כדי להשרות הז׳ ספירות, מן הדעת, על אהרן."],[5,"ר׳ חזקיה הוה יתיב וכו':","ר״ח היה יושב לפני ר׳ אלעזר. אמר לו, כמה אורות נבראו מטרם שנברא העולם. אמר לו, שבעה, ואלו הם, אור תורה, אור גיהנם, אור גן עדן, אור כסא הכבוד, אור בית המקדש, אור תשובה, ואור המשיח. שה״ס ז׳ ספירות דבריאה חג״ת נהי\"מ. ואלו נבראו מטרם שנברא העולם. שבעה אורות ונרות, דהיינו ז״ס, נתאחדו בו, באהרן, והוא הדליק את הנרות, והמשיך מז׳ נרות שלמעלה לז׳ נרות שלמטה."],[6,"ר׳ אלעזר פתח וכו׳:","רא״פ, הכל היה מן העפר והכל שב אל העפר. הנה למדנו, הכל היה מן העפר ואפילו גלגל חמה. מה הוא העפר. הוא אותו העפר השורה תחת כסא הכבוד הקדוש. שהוא בינה."],[6,"","פירוש. שהוקשה לו לר׳ אלעזר, מה שלמדנו, הכל היה מן העפר, שהוא מלכות, ואפילו גלגל החמה, הרומז על הת״ת, הלא להיפך הוא, שהמלכות נאצלת מת\"ת. ועל זה משיב, שהכונה היא על המלכות שבבינה, שהיא למעלה מת״ת, וממנה היה הכל, ואפילו גלגל החמה, שהוא ת״ת."],[7,"בספרא דבי רב ייסא סבא וכו׳:","בספרו של ר״י סבא, יש. הכל היה מן העפר. היינו המקום המקבץ הכל, שהוא המלכות, מלמד שיצאו שבילים לצד זה ולצד זה, דהיינו לימין ולשמאל, ונתקבצו להאיר בכל הצדדים, כעפר הזה שזורקים אותו לכל צד. וע״כ הכל היה מן העפר והכל שב אל העפר. ודאי. ולפי״ז, שעפר פירושו מלכות, קשה על מה שאמר ר״א, אשר העפר, פירושו עפר שתחת כסא הכבוד הקדוש, שהוא מלכות שבבינה."],[8,"אלא מן העפר וכו׳:","ומשיב, אלא, מן העפר, פירושו, מו העפר שבביהמ״ק הקדוש, דהיינו מלכות, כמו שאמר ר׳ ייסא סבא, ועפר הזה, הוא מעפרא עלאה, מבינה, כש״א, ועפרות זהב לו, שפירושו בינה, שנקראת זהב, כי כמו שנמצאת הפעולה למטה במלכות, כעין זה, היא נמצאת גם כן למעלה בבינה. והעמדנו, שעפר פירושו, עפר בית המקדש, כי עולם זה שהוא מלכות נברא ב \u0003ה׳\u0004 שהיא בינה, ועל כן אפילו גלגל החמה היה מן העפר, כש״א אלה תולדות \u0003השמים\u0004 והארץ בהבראם, שפירושו ב \u0003ה׳\u0004 בראם, הרי שגם השמים שהם גלגל החמה נבראו ב \u0003ה',\u0004 ומשום זה, הכל היה מן העפר. מי הוא עפר. הוא, אותו ששורה תחת כסא הכבוד הקדוש. שהוא בינה."],[8,"","פירוש. שר׳ אלעזר מתרץ דבריו, שאינם סותרים דברי ר׳ ייסא סבא, כי מה שאמר ר׳ ייסא, שעפר הוא מלכות, היינו מלכות הממותקת בבינה, המכונה עפר בית המקדש. ונודע, שבעת שעלתה המלכות להתמתק בבינה, וקבלה המלכות צורת בינה, נכללו שתיהן זו מזו, וכמו שהמלכות קבלה צורת הבינה כך קבלה הבינה את צורת המלכות. וז\"ש, \u0003והאי עפר. מעפרא עלאה הוא\u0004 שעפר הזה קבל צורתו מעפרא עלאה, דהיינו מבינה, \u0003כמה דאשתכח עובדא לתתא,\u0004 כמו שנמצאת פעולת שיתוף של המלכות בבינה למטה, במלכות, דהיינו שקיבלה צורת בינה, \u0003הכי נמי הוא לעילא כגוונא דא,\u0004 כן ישנה פעולת השתוף למעלה בבינה כעין זה, שגם הבינה קבלה צורת המלכות. ופעולת השתוף, הן במלכות והן בבינה נקראת עפר. ועל כן, \u0003ואוקימנא, עפר,\u0004 פירושו, \u0003עפר דבי מקדשא,\u0004 שפירושו, פעולת השיתוף של מלכות ובינה זו בזו. שזה סוד, \u0003דעלמא דא בה׳ אתברי\u0004 שהכונה היא על פעולת השיתוף של המלכות בבינה, הנקראת \u0003ה׳\u0004 שמשם נברא העולם, כי אם לא היתה פעולה זו לא היה יכול העולם להתקיים (כמ״ש לעיל ב״א דף ז׳ ד״ה וכבר) שז״ס ב \u0003ה׳\u0004 בראם, \u0003ועל דא אפילו גלגל חמה,\u0004 כי גם התפארת המרומז בגלגל החמה, יצא מפעולת השיתוף הזאת. הרי, \u0003מאן עפר, ההוא דשארי תחות כורסי יקרא קדישא,\u0004 שהיא בינה הנקראת כסא אל החכמה. באפן, שגם ר׳ ייסא סבר שהיא בינה, אלא מה שאמר שהיא מלכות, כונתו צורת המלכות שקבלה הבינה. כי כונתו היא בעיקר על פעולת השיתוף שבמלכות מבינה. שהוא ה׳ דהבראם, ששורש זה הוא בינה."],[9,"כתיב כלך יפה וגו׳:","כתוב, כלך יפה רעיתי ומום אין בך. \u0003כלך יפה רעיתי,\u0004 זו כנסת ישראל. שהיא המלכות, \u0003ומום אין בך,\u0004 אלו הם הסנהדרין, שהם כנגד ע״ב שמות שבמלכות (כמ״ש לעיל וירא דף ע״ח ד״ה אלין) ועיקרם הוא ע', בסוד ע׳ סנהדרין ושני עדים. וכנגד שבעים נפש שירדו עם יעקב, והקב״ה על כולם. שהם ע״ב. וע״כ אין בודקין אחר מומין מסנהדרין ולמעלה."],[10,"תנן כתיב ואתם וכו׳:","למדנו. כתוב ואתם תהיו לי ממלכת כהנים וגוי קדוש. מהו ממלכת כהנים. הוא, כש״א זאת משחת אהרן ומשחת בניו. שפירושו, ש \u0003זא״ת\u0004 שהיא המלכות נמשחה מאהרן (כנ״ל אות קס״ב) כי כשנתברכה כנסת ישראל שהיא המלכות על ידי הכהנים, אז היא נקראת על שמם, ז\"ש, ממלכת נהנים."],[11,"רבי שמעון אמר וכו׳:","רש״א, בוא וראה, אינה נקראת מלכות כהנים אלא ממלכת, משום שהכהנים שהם חסד, המליכו אותה, עי״ז שממישיכים לה חסדים, והחכמה שבה מתלבשת בחסדים ואז היא מאירה ושולטת, ועשו אותה גבורה על הכל. אבל \u0003מלכות\u0004 כהנים אינה נקראת, כי מבחינת מה שנמשכת מן השמים, שהם ז״א, היא נקראת מלכות, דהיינו מלכות שמים ודאי, וכאן נקראת \u0003ממלכת,\u0004 שהוא כמו שאתה אומר, שהכהנים המליכו אותה וחיברו אותה במלך, בז\"א. ואז כשנתחברה עם ז״א. היא ממלכת על כל אוצרות המלך, ממלכת על כל נשק המלך, ממלכת בעליונים ובתחתונים, ממלכת על כל העולם."]],[[0,"","דָּבָר אַחֵר כִּי עִמְּךְ מְקוֹר חַיִּים וְגוֹ' - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהוּא עֵץ עֶלְיוֹן בְּאֶמְצַע הַגָּן שֶׁאוֹחֵז אֶת כָּל הַצְּדָדִים. מָה הַטַּעַם? מִשּׁוּם שֶׁאָחוּז בּוֹ אוֹתוֹ (באותו) מְקוֹר חַיִּים, וּמְעַטֵּר אוֹתוֹ בַּעֲטָרוֹת עֶלְיוֹנוֹת סְבִיב הַגָּן כְּמוֹ אֵם שֶׁמְּעַטֶּרֶת אֶת בְּנָהּ עַל הַכֹּל. זֶהוּ שֶׁכָּתוּב (שיר ג) צְאֶינָה וּרְאֶינָה בְּנוֹת צִיּוֹן וְגוֹ'. וּמִשּׁוּם כָּךְ כִּי עִמְּךְ מְקוֹר חַיִּים, וְעַל זֶה בְּאוֹרְךְ נִרְאֶה אוֹר."],[1,"","רַבִּי יִצְחָק אָמַר, כִּי עִמְּךְ מְקוֹר חַיִּים - זֶה הַכֹּהֵן הַגָּדוֹל לְמַעְלָה, כְּנֶגְדּוֹ כֹּהֵן גָּדוֹל לְמַטָּה. מִשּׁוּם כָּךְ מַשְׁפִּיעַ הַכֹּהֵן שֶׁמֶן מִשְׁחַת קֹדֶשׁ עֶלְיוֹן לְמַטָּה וּמַדְלִיק מְנוֹרוֹת לְמַעְלָה. שֶׁהַכֹּהֵן הַגָּדוֹל שָׁלֵם בִּשְׁלֵמוּת שֶׁל שִׁבְעַת הַיָּמִים הָעֶלְיוֹנִים, וּלְהִתְעַטֵּר עַל הַכֹּל."],[2,"","כְּנֶגֶד זֶה שִׁבְעָה יְמֵי מִלּוּאִים לַכֹּהֵן שֶׁלְּמַטָּה, שֶׁיִּמָּצֵא הַכֹּל כְּמוֹ שֶׁלְּמַעְלָה. וְעַל זֶה יְמֵי הַמִּלּוּאִים נִקְרְאוּ יְמֵי הַהַשְׁלָמָה, כְּדֵי שֶׁיִּשְׁתַּלֵּם הַכֹּהֵן בִּשְׁאָר הַיָּמִים הָאֲחֵרִים לְהַשְׁלִים שִׁבְעָה כְאֶחָד. וְאֵלֶּה נִקְרָאִים יְמֵי מִלּוּאִים, מִשּׁוּם שֶׁאוֹחֲזִים בּוֹ שְׁאָר הָאֲחֵרִים. מַה זֶּה אוֹמֵר? שֶׁכְּשֶׁהַכֹּהֵן מִתְעוֹרֵר, כָּל שְׁאָר הָאֲחֵרִים מִתְעוֹרְרִים עִמּוֹ."],[3,"","וּמִשּׁוּם כָּךְ כָּתוּב, וּמִפֶּתַח אֹהֶל מוֹעֵד וְגוֹ', עַד יוֹם מְלֹאת וְגוֹ'. שִׁבְעָה יָמִים וַדַּאי, וְאָז מִתְעַטֵּר הַכֹּהֵן לְמַטָּה בַּכֹּל כְּמוֹ שֶׁלְּמַעְלָה. מִשּׁוּם שֶׁבְּשָׁעָה שֶׁמִּתְעוֹרֵר הַכֹּהֵן שֶׁלְּמַטָּה, הַכֹּל יִתְעוֹרְרוּ עַל יָדוֹ לְמַעְלָה, וְיִמָּצְאוּ בְרָכוֹת לְמַעְלָה וּלְמַטָּה."],[4,"","רַבִּי אַבָּא אָמַר, מַה שּׁוֹנֶה שֶׁמָּשַׁח מֹשֶׁה אֶת אַהֲרֹן? אֶלָּא מִשּׁוּם שֶׁהוּא הַבֵּן שֶׁל אוֹתוֹ (אחוז באותו) מָקוֹם מְקוֹר הַחַיִּים, וְכָתוּב (ישעיה סג) מוֹלִיךְ לִימִין מֹשֶׁה זְרוֹעַ תִּפְאַרְתּוֹ. וּמֹשֶׁה שִׁמֵּשׁ כָּל אוֹתָם יְמֵי מִלּוּאִים, לְהַשְׁרוֹת הַכֹּל עִם אַהֲרֹן."],[5,"","רַבִּי חִזְקִיָּה הָיָה יוֹשֵׁב לִפְנֵי רַבִּי אֶלְעָזָר. אָמַר לוֹ, כַּמָּה אוֹרוֹת נִבְרְאוּ טֶרֶם שֶׁנִּבְרָא הָעוֹלָם? אָמַר לוֹ, שִׁבְעָה. וְאֵלּוּ הֵם: אוֹר תּוֹרָה, אוֹר גֵּיהִנֹּם, אוֹר גַּן עֵדֶן, אוֹר כִּסֵּא הַכָּבוֹד, אוֹר בֵּית הַמִּקְדָּשׁ, אוֹר תְּשׁוּבָה, אוֹרוֹ שֶׁל מָשִׁיחַ. וְאֵלֶּה נִבְרְאוּ בְּטֶרֶם שֶׁנִּבְרָא הָעוֹלָם. שִׁבְעָה אוֹרוֹת וּמְאוֹרוֹת שֶׁנֶּאֶחְזוּ בְאַהֲרֹן, וְהוּא מַדְלִיק מְנוֹרוֹת מִמַּעְלָה לְמַטָּה."],[6,"","רַבִּי אֶלְעָזָר פָּתַח, (קהלת ג) הַכֹּל הָיָה מִן הֶעָפָר וְהַכֹּל שָׁב אֶל הֶעָפָר. הֲרֵי שָׁנִינוּ, הַכֹּל הָיָה מִן הֶעָפָר - אֲפִלּוּ גַלְגַּל חַמָּה. מִי הֶעָפָר? אוֹתוֹ שֶׁשָּׁרוּי תַּחַת כִּסֵּא הַכָּבוֹד הַקָּדוֹשׁ."],[7,"","בְּסִפְרוֹ שֶׁל רַב יֵיסָא סָבָא, הַכֹּל הָיָה מִן הֶעָפָר - מָקוֹם שֶׁכּוֹנֵס אֶת הַכֹּל. מְלַמֵּד שֶׁיָּצְאוּ שְׁבִילִים לַצַּד הַזֶּה וְלַצַּד הַזֶּה, וְהִתְכַּנְּסוּ לְהָאִיר כְּמוֹ הֶעָפָר הַזֶּה שֶׁזּוֹרְקִים אוֹתוֹ לְכָל עֵבֶר. וְעַל זֶה, הַכֹּל הָיָה מִן הֶעָפָר, וְהַכֹּל שָׁב אֶל הֶעָפָר וַדַּאי."],[8,"","אֶלָּא מִן הֶעָפָר - שֶׁל בֵּית הַמִּקְדָּשׁ הַקָּדוֹשׁ. וְהֶעָפָר הַזֶּה מֵהֶעָפָר הָעֶלְיוֹן, כְּמוֹ שֶׁנֶּאֱמַר (איוב כח) וְעַפְרוֹת זָהָב לוֹ. כְּמוֹ שֶׁנִּמְצָא מַעֲשֶׂה לְמַטָּה, כָּךְ הוּא לְמַעְלָה כְּמוֹ זֶה. וּבֵאַרְנוּ עָפָר, עָפָר שֶׁל בֵּית הַמִּקְדָּשׁ, שֶׁהָעוֹלָם הַזֶּה נִבְרָא בְהֵ\"א. וְעַל זֶה - אֲפִלּוּ גַּלְגַּל חַמָּה, כְּמוֹ שֶׁנֶּאֱמַר אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם - בְּה' בְּרָאָם. וּמִשּׁוּם כָּךְ, הַכֹּל הָיָה מִן הֶעָפָר. אֵיזֶה עָפָר? אוֹתוֹ שֶׁשָּׁרוּי תַּחַת כִּסֵּא הַכָּבוֹד הַקָּדוֹשׁ."],[9,"","כָּתוּב (שיר ד) כֻּלָּךְ יָפָה רַעְיָתִי וּמוּם אֵין בָּךְ. כֻּלָּךְ יָפָה רַעְיָתִי - זוֹ כְּנֶסֶת יִשְׂרָאֵל. וּמוּם אֵין בָּךְ - אֵלּוּ סַנְהֶדְרִין, שֶׁהֵם כְּנֶגֶד שִׁבְעִים וּשְׁנַיִם שֵׁמוֹת. שִׁבְעִים נֶפֶשׁ שֶׁיָּרְדוּ עִם יַעֲקֹב, וְהַקָּדוֹשׁ בָּרוּךְ הוּא עַל כֻּלָּם. וְעַל זֶה אֵין בּוֹדְקִין מִן הַסַּנְהֶדְרִין וּלְמַעְלָה."],[10,"","שָׁנִינוּ, כָּתוּב (שמות יט) וְאַתֶּם תִּהְיוּ לִי מַמְלֶכֶת כֹּהֲנִים וְגוֹי קָדוֹשׁ. מִי זוֹ מַמְלֶכֶת כֹּהֲנִים? כְּמוֹ שֶׁנֶּאֱמַר, זֹּאת מִשְׁחַת אַהֲרֹן וּמִשְׁחַת בָּנָיו. שֶׁכְּשֶׁמִּתְבָּרֶכֶת כְּנֶסֶת יִשְׂרָאֵל עַל יַד הַכֹּהֲנִים, אָז נִקְרֵאת עַל שְׁמָם, זֶהוּ שֶׁכָּתוּב מַמְלֶכֶת כֹּהֲנִים."],[11,"","רַבִּי שִׁמְעוֹן אָמַר, בּא רְאֵה, מַלְכוּת כֹּהֲנִים לֹא נִקְרֵאת, אֶלָּא מַמְלֶכֶת, שֶׁהִמְלִיכוּ אוֹתָהּ הַכֹּהֲנִים וְעָשׂוּ אוֹתָהּ גְּבִירָה עַל הַכֹּל. אֲבָל מַלְכוּת כֹּהֲנִים לֹא נִקְרֵאת, שֶׁהֲרֵי מִן הַשָּׁמַיִם נִקְרֵאת מַלְכוּת, מַלְכוּת שָׁמַיִם וַדַּאי. וְכָאן מַמְלֶכֶת, כְּמוֹ שֶׁנֶּאֱמַר שֶׁכֹּהֲנִים הִמְלִיכוּ אוֹתָהּ, וּמְחַבְּרִים אוֹתָהּ עִם הַמֶּלֶךְ, וְאָז הִיא מַמְלֶכֶת עַל כָּל גִּנְזֵי הַמֶּלֶךְ. מַמְלֶכֶת עַל כָּל כְּלֵי זֵינוֹ שֶׁל הַמֶּלֶךְ. מַמְלֶכֶת בָּעֶלְיוֹנִים וּבַתַּחְתּוֹנִים. מַמְלֶכֶת עַל כָּל הָעוֹלָם."]]],[["רִבִּי יוֹסֵי אָמַר, כְּתִיב (עמוס ט׳:ו׳) וַאֲגֻדָּתוֹ עַל אֶרֶץ יְסָדָהּ. וַאֲגֻדָּתוֹ: כַּד אִזְדְּוַוג מַלְכָּא לָקֳבְלָהּ, בְּכָל אִינּוּן עִטְרִין קַדִישִׁין, בִּכְנוּפְיָא חַד, כְּדֵין וַאֲגֻדָּתוֹ כְּתִיב.","רִבִּי יִצְחָק אָמַר, וַאֲגֻדָּתוֹ: כְּמָה דְאַתְּ אָמֵר, (שמות י״ב:כ״ב) וּלְקַחְתֶּם אֲגֻדַּת אֵזוֹב. מַאי קָא מַיְירֵי. דְּכַד מִתְחַבְּרָאן כַּחֲדָא, וְאִתְבָּרְכָא מִנַּיְיהוּ, כְּדֵין שַׁלְטָא עַל כֹּלָּא, וְנַהֲרָא לְעֵילָּא וְתַתָּא. וְכֹלָּא בְּשַׁעֲתָא דְּכַהֲנָא פָּלַח פּוּלְחָנָא, וְאַקְרִיב קָרְבְּנָא, וְאַקְטַר קְטֹרֶת, וּמְכַוִּון מִלִּין לְקָרְבָא כֹּלָּא כַּחֲדָא. כְּדֵין כְּתִיב, וַאֲגֻדָּתוֹ עַל אֶרֶץ יְסָדָהּ.","רִבִּי יוֹסֵי אָמַר, כַּד נָטַל אַהֲרֹן כֹּלָּא נַטְלִין עִמֵּיהּ, עַד דְּאִתְבָּרְכָא כְּנֶסֶת יִשְׂרָאֵל, וְאִתְבָּרְכָאן עִלָּאֵי וְתַתָּאֵי. כְּדֵין כְּתִיב, (תהילים קל״ה:כ״א) בָּרוּךְ יְיָ' מִצִיּוֹן שׁוֹכֵן יְרוּשָׁלַם הַלְלוּיָהּ. (תהילים ע״ב:י״ט) וּבָרוּךְ שֵׁם כְּבוֹדוֹ לְעוֹלָם וְיִמָּלֵא כְבוֹדוֹ אֶת כָּל הָאָרֶץ אָמֵן וְאָמֵן.","רִבִּי אֶלְעָזָר הֲוָה אָזִיל מִקַּפּוֹטְקַיָּא לְלוּד, וַהֲווּ עִמֵּיהּ רִבִּי יֵיסָא וְרִבִּי חִזְקִיָּה. פָּתַח רִבִּי אֶלְעָזָר וְאָמַר, (ישעיהו נ״א:ט״ז) וָאָשִׂים דְּבָרַי בְּפִיךָ וּבְצֵל יָדִי כִּסִּיתִיךָ וְגוֹ'. תָּנֵינָן, כָּל בַּר נָשׁ דְּאִשְׁתָּדַּל בְּמִלֵּי דְּאוֹרַיְיתָא, וְשִׂפְוָותֵיהּ מְרַחְשָׁן אוֹרַיְיתָא, קוּדְשָׁא בְּרִיךְ הוּא חַפְּיָא עָלֵיהּ, וּשְׁכִינְתָּא פַּרְשָׂא עָלֵיהּ גַּדְפָהָא, הֲדָא הוּא דִכְתִיב וָאָשִׂים דְּבָרַי בְּפִיךָ וּבְצֵל יָדִי כִּסִּיתִיךָ. וְלֹא עוֹד, אֶלָּא דְּהוּא מְקַיֵּים עָלְמָא, וְקוּדְשָׁא בְּרִיךְ הוּא חַדֵּי עִמֵּיהּ, כְּאִלּוּ הַהוּא יוֹמָא נָטַע שְׁמַיָא וְאַרְעָא. הֲדָא הוּא דִכְתִיב, (ישעיהו נ״א:ט״ז) לִנְטוֹעַ שָׁמַיִם וְלִיסוֹד אָרֶץ וְלֵאמֹר לְצִיּוֹן עַמִּי אָתָּה.","מִכָּאן אוֹלִיפְנָא, דְּיִשְׂרָאֵל אִקְרוּן בִּשְׁמָא דְּצִיּוֹן, דִּכְתִּיב וְלֵאמֹר לְצִיּוֹן עַמִּי אַתָּה, וַחֲמֵינָא דִּכְנֶסֶת יִשְׂרָאֵל אִקְרֵי בִּשְׁמָא דְּצִיּוֹן, דִּכְתִּיב, (ישעיהו א׳:כ״ז) צִיּוֹן בְּמִשְׁפָּט תִּפָּדֶה וְשָׁבֶיהָ בִּצְדָקָה.","תּוּ פָּתַח וְאָמַר, (ישעיהו ח׳:ט״ז) צוֹר תְּעוּדָה חֲתוֹם תּוֹרָה בְּלִמּוּדָי. צוֹר תְּעוּדָה. דָּא סַהֲדוּתָא דְּדָוִד, דִּכְתִּיב, (תהילים קל״ב:י״ב) וְעֵדוֹתִי זוֹ אֲלַמְּדֵם. צוֹר: הִיא קִשּׁוּרָא, כְּמַאן דְּקָטַר קְטוּרָא בַּאֲתַר חַד. חֲתוֹם תּוֹרָה בְּלִמּוּדָי. חֲתוֹם תּוֹרָה: חַתִימָה דְּאוֹרַיְיתָא, וְכָל נְגִידוּ וּרְבוּ דְּנָגִיד מִלְּעֵילָּא, בְּאָן (נ\"א בין) חֲתִימָה דִּילֵיהּ. בְּלִמּוּדָי. בְּגִין דְּתַמָּן אִתְכְּנַשׁ רְבוּ וּמִשְׁחָא, בֵּין תְּרֵין קַיָימִין, דְּתַמָּן שַׁרְיָין, אֲתַר כְּנִישׁוּ דְּכָל רְבוּת וּמְשַׁח דְּנָגִיד מִלְּעֵילָּא, לְאַשְׁדָּאָה לֵיהּ בְּפוּמָא דְּאַמָּה, וּלְאַרְקָא לֵיהּ בְּהַאי תְּעוּדָה. וּכְדֵין אִתְקְשַׁר כֹּלָּא קִשְׁרָא חַד מְהֵימָנָא.","תָּא חֲזֵי, מַה בֵּין אִינּוּן דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא, לִנְבִיאֵי מְהֵימְנֵי. אִינּוּן דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא, עֲדִיפֵי מִנְּבִיאֵי בְּכָל זִמְנָא. מַאי טַעֲמָא. דְּאִינּוּן קַיְימֵי בְּדַרְגָּא עִלָּאָה, יַתִּיר מִנְּבִיאֵי, אִינּוּן דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא קַיְימֵי לְעֵילָּא, בְּאַתְרָא דְּאִקְרֵי תּוֹרָה, (נ\"א תפארת) דְּהוּא קִיוּמָא דְּכָל מְהֵימְנוּתָא. וּנְבִיאֵי קַיְימֵי לְתַתָּא, בַּאֲתַר דְּאִקְרוּן נֶצַח וְהוֹד. וְעַל דָּא (אקרון), אִינּוּן דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא, עֲדִיפֵי מִנְּבִיאֵי, וְעִלָּאִין מִנְּהוֹן יַתִּיר. דְּאִלֵּין קַיְימִין לְעֵילָּא, וְאִלֵּין קַיְימִין לְתַתָּא. אִינּוּן דְּאַמְרֵי מִלִּין בְּרוּחַ הַקֹּדֶשׁ, קַיְימֵי לְתַתָּא מְכֻּלְּהוּ. (ועל דא)","זַכָּאִין אִינּוּן דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא, דְּאִינּוּן בְּדַרְגָּא עִלָּאָה יַתִּיר עַל כֹּלָּא. (ועל דא) מַאן דְּלָעֵי בְּאוֹרַיְיתָא, לָא אִצְטְרִיךְ לָא לְקָרְבְּנִין, וְלָא לְעִלָּוָון. דְּהָא אוֹרַיְיתָא עָדִיף מִכֹּלָּא, וְקִשּׁוּרָא דִּמְהֵימְנוּתָא דְּכֹלָּא. וְעַל דָּא כְּתִיב, (משלי ג׳:י״ז) דְּרָכֶיהָּ דַּרְכֵי נֹעַם וְכָל נְתִיבוֹתֶיהָ שָׁלוֹם. וּכְתִיב, (תהילים קי״ט:קס״ה) שָׁלוֹם רָב לְאוֹהֲבֵי תוֹרָתֶךָ וְאֵין לָמוֹ מִכְשׁוֹל.","עַד דַּהֲווֹ אָזְלֵי, אַשְׁכָּחוּ חַד גַּבְרָא דְּהֲוָה אָתֵי, וְג' עַנְפֵּי הֲדַס בִּידֵיהּ, קְרִיבוּ גַּבֵּיהּ, אָמְרוּ לֵיהּ לָמָּה לָךְ הַאי. אָמַר לְרַוְוחָא אוֹבְדָא. אָמַר רִבִּי אֶלְעָזָר שַׁפִּיר קָאָמְרָת. אֲבָל ג' אִלֵּין לָמָּה. אָמַר לֵיהּ, חַד לְאַבְרָהָם. חַד לְיִצְחָק, וְחַד לְיַעֲקֹב. וְקַשִׁירְנָא לְהוּ כַּחֲדָא, וְאָרַחְנָא בְּהוּ. בְּגִין דִּכְתִּיב, (שיר השירים א׳:ג׳) לְרֵיחַ שְׁמָנֶיךָ טוֹבִים שֶׁמֶן תּוּרַק שְׁמֶךָ. בְּגִין דִּבְהַאי רֵיחָא, אִתְקְיַּים חוּלְשָׁא דְּנַפְשָׁא, וּבְהֵימְנוּתָא דָּא אִתְקַיְּימָא, וְאִתְנְגִידוּ בִּרְכָאן מֵעֵילָּא וְתַתָּא. אָמַר רִבִּי אֶלְעָזָר זַכָּאָה חוּלָקֵיהוֹן דְּיִשְׂרָאֵל בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי."],[[0,"ר׳ יוסי אמר וכו׳:","רי״א, כתוב ואגדתו על ארץ יסדה. \u0003ואגדתו,\u0004 היינו כשמזדווג המלך, שהוא ז״א, כנגדה, כנגד המלכות שנקראת ארץ, בכל אלו עטרות הקדושות בקיבוץ אחד, דהיינו שג׳ מוחין חב״ד שלו הנקראים עטרות מתאגדים יחד בסוד ג׳ קוין, אז כתוב, \u0003ואגדתו.\u0004 ושיעור הכתוב, שאגדתו, שהם ג׳ מוחין שלו, על ארץ יסדה, הוא משפיע אל המלכות שנקראת ארץ."],[1,"ר׳ יצחק אמר וכו׳:","רי״א, ואגדתו, הוא כמו שאתה אומר, ולקחתם לכם אגדת אזוב. שואל מה זאת אומרת. ומשיב, כי כשמתחברים ז״א ומלכות יחד, והמלכות מתברכת מן ג׳ קוין של ז״א, אז היא שולטת על כולם, כלומר, שג׳ קוין דז״א מתלבשים בה, ושולטת עליהם, והיא מאירה למעלה ולמטה, וכל זה הוא בשעה שהכהן עובד עבודה ומקריב קרבן ומקטיר קטרת, ומכוון בדברים לקרב הכל ביחוד אחד. אז כתוב, ואגדתו על ארץ יסדה."],[1,"","פירוש. שר׳ יצחק חולק על ר׳ יוסי שפירש, שאגדתו סובב על המוחין דז״א, שהם משפיעים למלכות הנקראת ארץ. אלא שאומר שאגדתו משמע על אגדה שנתיסדה במלכות עצמה. כמו שנאמר ולקחתם אגדת אזוב, שהאגדה נלקחת בידו, כן ואגדתו על ארץ יסדה, פירושו שז״א לוקח אגודת ג׳ קוין שלו, ומיסדם במלכות."],[2,"ר׳ יוסי אמר וכו׳:","רי״א, כשאהרן שה״ס קו ימין, חסד דז״א, נוסע להשפיע למלכות, כולם נוסעים עמו, דהיינו כל ג׳ הקוין, עד שמתברכת כנסת ישראל מג' הקוין, ומתברכים העליונים שהם ספירות דז״א, והתחתונים שהם ספירות המלכות, אז כתוב, ברוך הויה מציון שוכן ירושלים הללויה. שז״א שנקרא \u0003הויה\u0004 מתברך מ \u0003ציון,\u0004 שהוא יסוד המלכות. וברוך שם כבודו לעולם וימלא כבודו את כל הארץ אמן ואמן. ששם כבודו, שהוא המלכות. מחברך מז״א."],[2,"","פירוש. ר׳ יוסי מחזק דבריו, שאמר לעיל (באות קע״ט,) שאגדתו סובב על מוחין דז״א המאירים בהמלכות. ומוסיף. שהכתוב משמיענו, ש \u0003אגדתו\u0004 של ז״א, שהם ג׳ קוין שלו, אינם מתברכים בשלמות, דהיינו שיאירו גם בהארת חכמה רק בשעה \u0003שעל ארץ יסדה,\u0004 שמשפיע אותם ליסוד המלכות שנקרא ציון. כמ\"ש ברוך ה׳ מציון וגו'. כי בעת שג׳ קוין דז״א אינם מאירים בהמלכות, אין לו אלא חסדים מכוסים מחכמה. וזהו שמשמיענו הכתוב, ו \u0003אגדתו,\u0004 שתאיר בשלמות, \u0003על ארץ יסדה.\u0004"],[3,"ר' אלעזר הוה וכו׳:","ר״א היה הולך מקפוטקיא ללוד. והיו עמו ר׳ יוסי ור׳ חזקיה. פתח ר׳ אלעזר ואמר, ואשים דברי בפיך ובצל ידי כסיתיך וגו'. למדנו, כל אדם העוסק בתורה ושפתותיו דובבות תורה, הקב״ה מכסה עליו, והשכינה פורשת עליו כנפיה. ז״ש, ואשים דברי בפיך ובצל ידי כסיתיך. ולא עוד, אלא שהוא מקיים את העולם, והקב״ה שמח עמו, כאלו ביום ההוא היה נוטע שמים וארץ. וזהו שהכתוב מסיים, לנטוע שמים וליסוד ארץ ולאמר לציון עמי אתה."],[4,"מכאן אוליפנא דישראל וכו׳:","מכאן למדנו, שישראל נקראים בשם ציון, שכתוב, ולאמוד לציון עמי אתה. וראינו, שכנסת ישראל נקראת בשם ציון, שכתוב, ציון במשפט תפדה ושביה בצדקה."],[5,"תו פתח ואמר וכו׳:","עוד פתח ואמר. צור תעודה חתום תורה בלמודי. \u0003צור תעודה,\u0004 זו היא עדותו של דוד. דהיינו מלכות. שכתוב, ועדותי זו אלמדם. \u0003צור\u0004 פירושו קשר, כמי שקושר קשר במקום אחד וצור תעודה, פירושו, המלכות קשורה. חתום תורה בלמודי. \u0003חתום תורה,\u0004 פירושו חתימת התורה, שהיא ז״א, שכל השפע והגדלות הנמשכים מלמעלה, איפה היא החתימה שלו, דהיינו הגמר, היא \u0003בלמודי,\u0004 שהם נצח והוד, הנקראים למודי ה', כי שם מתקבצים הגדלות והשמן בין שני עמודים, נו״ה, לשרות שם, שהם מקום כל הגדלות והשמן הנוזל מלמעלה, מת״ת שנקרא תורה, לשפוך אותו אל פי היסוד, ולהריק אותו ב \u0003תעודה\u0004 הזו, שהיא המלכות, ואז מתקשר הכל קשר נאמן אחד. ויהיה שיעור הכתוב, \u0003צור תעודה,\u0004 קשר המלכות הוא, על ידי זה, ש \u0003חתום תורה בלמודי,\u0004 אשר שפע התורה נחתמת, דהיינו שנגמרת בנצח והוד, ומהם ליסוד. ואז נקשרת המלכות ביסוד, לקבל השפע ונעשה הכל קשר אחד."],[6,"תא חזי מה וכו':","בוא וראה, מה בין אלו העוסקים בתורה לנביאים הנאמנים, הוא, כי אלו העוסקים בתורה חשובים בכל זמן מנביאים. מהו הטעם. משום שהם עומדים במדרגה עליונה יתירה מנביאים, כי אלו העוסקים בתורה עומדים למעלה במקום הנקרא תורה, שהוא ז״א, שהוא קיום כל האמונה. שהיא המלכות, שאין לה משהו אלא מה שז״א נותן לה. והנביאים עומדים למטה, דהיינו למטה מחזה דז״א, במקום שנקרא נצח והוד. וע״כ אלו שעוסקים בתורה, חשובים מנביאים, והם עליונים יותר מהם. כי אלו עומדים למעלה, ואלו עומדים למטה. ואלו שאומרים דברים ברוח הקודש, עומדים למטה מכולם. כי רוח הקדש נמשך מן המלכות שהיא למטה מכולם."],[7,"זכאין אינון דמשתדלי וכו׳:","אשרי הם העוסקים בתורה, שהם במדרגה עליונה יתירה על כולם. מי שעוסק בתורה, אינו צריך לא לקרבנות ולא לעולות. כי התורה יותר טובה מכל, והיא קשר של אמונת כל. דהיינו קשר המלכות. וע״כ כתוב, דרכיה דרכי נועם וכל נתיבותיה שלום. וכתוב, שלום רב לאוהבי תורתיך ואין למו מכשול."],[8,"עד דהוו אזלי וכו׳:","בעוד שהיו הולכים, פגשו איש אחד שהיה בא, וג׳ ענפי הדס בידו. קרבו אליו. אמרו לו, למה לך זה. אמר, כדי לתת הרוחה אל האובדת, דהיינו הנשמה יתרה הנאבדת מנפש האדם במוצאי שבת. אמר ר׳ אלעזר, יפה אמרת, אבל שלשה למה לך, היה די בהדס אחד. אמר לו, אחד לאברהם אחד ליצחק ואחד ליעקב. שהם ג׳ קוין, חסד גבורה ת״ת. וקשרתי אותם יחד, והרחתי בהם משום שכתוב, לריח שמניך טובים שמן תורק שמך. כי בריח הזה מתקיימת חולשת הנפש, ומתקיימת באמונה זו, שהיא המלכות. ונמשכות ברכות מלמעלה ומלמטה. פירוש. כי ריח, רומז על הארת החכמה המתגלה במלכות. שהיא נמשכת מג׳ קוין דז״א, שה״ס ג׳ הדסים, וע״כ כשמריחים את ההדסים צריכים לכוון להמשיך הארת החכמה מהם אל המלכות. אמר ר׳ אלעזר, אשרי חלקם של ישראל בעולם הזה ובעולם הבא."]],[[0,"","רַבִּי יוֹסֵי אָמַר, כָּתוּב (עמוס ט) וַאֲגֻדָּתוֹ עַל אֶרֶץ יְסָדָהּ. וַאֲגֻדָּתוֹ - כְּשֶׁמִּזְדַּוֵּג הַמֶּלֶךְ כְּנֶגְדָּהּ בְּכָל אוֹתָן הָעֲטָרוֹת הַקְּדוֹשׁוֹת בְּכִנּוּס אֶחָד, אֲזַי וַאֲגֻדָּתוֹ כָּתוּב."],[1,"","רַבִּי יִצְחָק אָמַר, וַאֲגֻדָּתוֹ - כְּמוֹ שֶׁנֶּאֱמַר וּלְקַחְתֶּם אֲגֻדַּת אֵזוֹב. מַה זֶּה אוֹמֵר? שֶׁכְּשֶׁמִּתְחַבְּרִים כְּאֶחָד וּמִתְבָּרֶכֶת מֵהֶם, אֲזַי שׁוֹלֶטֶת עַל הַכֹּל וּמְאִירָה לְמַעְלָה וּלְמַטָּה, וְהַכֹּל בְּשָׁעָה שֶׁהַכֹּהֵן עוֹבֵד אֶת הָעֲבוֹדָה וּמַקְרִיב קָרְבָּן וּמַקְטִיר קְטֹרֶת וּמְכַוֵּן דְּבָרִים לְקָרֵב הַכֹּל כְּאֶחָד. אֲזַי כָּתוּב, וַאֲגֻדָּתוֹ עַל אֶרֶץ יְסָדָהּ."],[2,"","רַבִּי יוֹסֵי אָמַר, כְּשֶׁנּוֹסֵעַ אַהֲרֹן, הַכֹּל נוֹסְעִים עִמּוֹ, עַד שֶׁמִּתְבָּרֶכֶת כְּנֶסֶת יִשְׂרָאֵל וּמִתְבָּרְכִים עֶלְיוֹנִים וְתַחְתּוֹנִים, אֲזַי כָּתוּב (תהלים קלה) בָּרוּךְ ה' מִצִּיּוֹן שֹׁכֵן יְרוּשָׁלם הַלְלוּיָהּ. (שם עב) וּבָרוּךְ שֵׁם כְּבוֹדוֹ וְיִמָּלֵא כְבוֹדוֹ אֶת כָּל הָאָרֶץ אָמֵן וְאָמֵן."],[3,"","רַבִּי אֶלְעָזָר הָיָה הוֹלֵךְ מִקַּפּוֹטְקִיָּא לְלוֹד, וְהָיוּ עִמּוֹ רַבִּי יֵיסָא וְרַבִּי חִזְקִיָּה. פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, (ישעיה נא) וָאָשִׂם דְּבָרַי בְּפִיךְ וּבְצֵל יָדִי כִּסִּיתִיךְ וְגוֹ'. שָׁנִינוּ, כָּל אָדָם שֶׁמִּשְׁתַּדֵּל בְּדִבְרֵי תוֹרָה וְשִׂפְתוֹתָיו מְרַחֲשׁוֹת תּוֹרָה, הַקָּדוֹשׁ בָּרוּךְ הוּא מְכַסֶּה עָלָיו, וּשְׁכִינָה פּוֹרֶשֶׂת כְּנָפֶיהָ עָלָיו. זֶהוּ שֶׁכָּתוּב וָאָשִׂם דְּבָרַי בְּפִיךְ וּבְצֵל יָדִי כִּסִּיתִיךְ. וְלֹא עוֹד, אֶלָּא שֶׁהוּא מְקַיֵּם אֶת הָעוֹלָם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא שָׂמֵחַ עִמּוֹ כְּאִלּוּ אוֹתוֹ יוֹם נָטַע שָׁמַיִם וָאָרֶץ. זֶהוּ שֶׁכָּתוּב (שם) לִנְטֹעַ שָׁמַיִם וְלִיסֹד אָרֶץ וְלֵאמֹר לְצִיּוֹן עַמִּי אָתָּה."],[4,"","מִכָּאן לָמַדְנוּ שֶׁיִּשְׂרָאֵל נִקְרְאוּ בַשֵּׁם שֶׁל צִיּוֹן, שֶׁכָּתוּב וְלֵאמֹר לְצִיּוֹן עַמִּי אָתָּה. וְרָאִיתִי שֶׁכְּנֶסֶת יִשְׂרָאֵל נִקְרֵאת בַּשֵּׁם שֶׁל צִיּוֹן, שֶׁכָּתוּב (שם א) צִיּוֹן בְּמִשְׁפָּט תִּפָּדֶה וְשָׁבֶיהָ בִּצְדָקָה."],[5,"","עוֹד פָּתַח וְאָמַר, (שם ח) צוֹר תְּעוּדָה חֲתוֹם תּוֹרָה בְּלִמֻּדָי. צוֹר תְּעוּדָה - זוֹ עֵדוּת שֶׁל דָּוִד, שֶׁכָּתוּב (תהלים קלב) וְעֵדוֹתִי זוֹ אֲלַמְּדֵם. צוֹר - הִיא קִשּׁוּר, כְּמוֹ שֶׁקּוֹשֵׁר קֶשֶׁר בְּמָקוֹם אֶחָד. חֲתוֹם תּוֹרָה בְּלִמֻּדָי. חֲתוֹם תוֹרָה - חֲתִימָה שֶׁל הַתּוֹרָה, וְכָל שֶׁפַע וּמִשְׁחַת שֶׁמֶן שֶׁשּׁוֹפְעִים מִלְמַעְלָה, בְּאֵיזוֹ (בין) חֲתִימָה שֶׁלּוֹ? בְּלִמֻּדָי. מִשּׁוּם שֶׁשָּׁם מִתְכַּנֵּס שֶׁמֶן מִשְׁחָה בֵּין שְׁנֵי עַמּוּדִים שֶׁשָּׁם שׁוֹרִים, מְקוֹם הַכִּנּוּס שֶׁל כָּל שֶׁמֶן מִשְׁחָה שֶׁשּׁוֹפֵעַ מִמַּעַל, לִשְׁפֹּךְ אוֹתוֹ לְפִי הָאַמָּה וּלְהָרִיק אוֹתוֹ בַּתְּעוּדָה הַזֹּאת, וְאָז נִקְשָׁר הַכֹּל קֶשֶׁר אֶחָד נֶאֱמָן."],[6,"","בֹּא וּרְאֵה מַה בֵּין אוֹתָם שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה לִנְבִיאִים נֶאֱמָנִים. אוֹתָם שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה עֲדִיפִים מִנְּבִיאִים בְּכָל פַּעַם. מָה הַטַּעַם? שֶׁהֵם עוֹמְדִים בְּדַרְגָּה עֶלְיוֹנָה יוֹתֵר מִבַּנְּבִיאִים, אֵלּוּ שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה עוֹמְדִים לְמַעְלָה, בְּמָקוֹם שֶׁנִּקְרָא תוֹרָה, (תפארת) שֶׁהוּא קִיּוּמָהּ שֶׁל כָּל הָאֱמוּנָה, וּנְבִיאִים עוֹמְדִים לְמַטָּה בְּמָקוֹם שֶׁנִּקְרְאוּ נֵצַח וְהוֹד. וְעַל כֵּן (נקראו) אוֹתָם שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה עֲדִיפִים מִנְּבִיאִים, וְעֶלְיוֹנִים יוֹתֵר מֵהֶם. שֶׁאֵלּוּ עוֹמְדִים לְמַעְלָה, וְאֵלּוּ עוֹמְדִים לְמַטָּה. וְאוֹתָם שֶׁאוֹמְרִים דְּבָרִים בְּרוּחַ הַקֹּדֶשׁ, עוֹמְדִים לְמַטָּה מִכֻּלָּם."],[7,"","אַשְׁרֵי אוֹתָם שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה, שֶׁהֵם בְּדַרְגָּה יוֹתֵר עֶלְיוֹנָה עַל הַכֹּל. מִי שֶׁעוֹסֵק בַּתּוֹרָה, לֹא צָרִיךְ לֹא לְקָרְבָּנוֹת וְלֹא לְעוֹלוֹת, שֶׁהֲרֵי הַתּוֹרָה עֲדִיפָה מֵהַכֹּל, וְקֶשֶׁר שֶׁל הָאֱמוּנָה שֶׁל הַכֹּל. וְעַל זֶה כָּתוּב, דְּרָכֶיהָ דַּרְכֵי נֹעַם וְכָל נְתִיבֹתֶיהָ שָׁלוֹם. וְכָתוּב, (תהלים קיט) שָׁלוֹם רָב לְאֹהֲבֵי תוֹרָתֶךְ וְאֵין לָמוֹ מִכְשׁוֹל."],[8,"","עַד שֶׁהָיוּ הוֹלְכִים, מָצְאוּ אִישׁ אֶחָד שֶׁהָיָה בָּא וּשְׁלֹשָׁה עַנְפֵי הֲדַס בְּיָדוֹ. קָרְבוּ אֵלָיו, אָמְרוּ לוֹ, לָמָּה לְךְ אֶת אֵלֶּה? אָמַר, לְהַרְוִיחַ אֲבֵדָה. אָמַר רַבִּי אֶלְעָזָר, יָפֶה אָמַרְתָּ, אֲבָל שְׁלֹשָׁה אֵלֶּה לְשֵׁם מָה? אָמַר לוֹ, אֶחָד לְאַבְרָהָם, אֶחָד לְיִצְחָק, וְאֶחָד לְיַעֲקֹב, וְקָשַׁרְתִּי אוֹתָם יַחַד וְהֵרַחְתִּי בָהֶם, מִשּׁוּם שֶׁכָּתוּב (שיר א) לְרֵיחַ שְׁמָנֶיךְ טוֹבִים שֶׁמֶן תּוּרַק שְׁמֶךְ. מִשּׁוּם שֶׁבָּרֵיחַ הַזֶּה עוֹמֶדֶת חֻלְשַׁת הַנֶּפֶשׁ, וּבָאֱמוּנָה הַזּוֹ מִתְקַיֶּמֶת, וְשׁוֹפְעוֹת בְּרָכוֹת מִמַּעְלָה וּמַטָּה. אָמַר רַבִּי אֶלְעָזָר, אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא."]]],[["תָּא חֲזֵי, לֵית עָלְמָא (נ\"א נפשא) מִתְקַיְּימָא, אֶלָּא עַל רֵיחָא, וּמֵרֵיחָא דָּא אִשְׁתְּמוֹדְעָא רֵיחָא אָחֳרָא. דְּהָא בְּשַׁעֲתָא דְּנָפִיק שַׁבְּתָא, (נתפרדה החבילה) וְסַלְּקָא נַפְשָׁא יְתֵירָא, וְאִשְׁתָּאֲרוּן נַפְשָׁא וְרוּחָא מִתְפָּרְשָׁן עֲצִיבִין, אָתָא רֵיחָא דָּא, וּמִתְקָרְבָן דָּא בְּדָא וְחַדָּאן.","וְעַל דָּא, בָּעֵי רוּחָא בָּתַר רוּחָא, לְקַבְּלָא רֵיחָא, כֵּיוָן דְּאִתְקָבַּל רֵיחָא מִתְקָרְבָן כַּחֲדָא וְחַדָּאן. כֵּי הַאי גַּוְונָא רֵיחָא דְּקוּרְבְּנָא, בְּרֵיחָא (דא) מִתְקָרְבִין כֹּלָּא כַּחֲדָא, וּמִתְלַהֲטָן בּוּצִינֵי וְחַדָּאן.","תָּא חֲזֵי, תְּרֵי בּוּצִינֵי, חַד לְעֵילָּא וְחַד לְתַתָּא, אִי לָהִיט בַּר נָשׁ הַאי בּוּצִינָא דִּלְתַתָּא, וְכַבֵי לָהּ (ס\"א לההוא דלעילא), הַהוּא תְּנָנָא דְּסָלִיק (נ\"א מבוצינא תתאה), לָהִיט הַהוּא בּוּצִינָא עִלָּאָה. כַּךְ תְּנָנָא דְּקָרְבְּנִין, הַאי תְּנָנָא דְּסָלִיק, לָהִיט בּוּצִינֵי עִלָּאֵי, וּמִתְלַהֲטָן בְּחַד, וּמִתְקָרְבִין כֻּלְּהוּ כַּחֲדָא, בְּרֵיחָא דָּא. וּבְגִין כָּךְ, רֵיחַ נִיחֹחַ לַיְיָ', (אשה) וְהָא אוּקְמוּהָ.","וְעַל דָּא, רֵיחָא דְּקָרְבְּנָא, קִיּוּמָא דְּכֹלָּא, וְקִיּוּמָא דְּעָלְמָא. וְקָרְבְּנָא עַל יְדָא דְּכַהֲנָא, דְּמִקְרַב כֹּלָּא. וּבְגִין כָּךְ, שִׁבְעָה יוֹמֵי אַשְׁלְמוּתָא, אִשְׁתְּלִימוּ בֵּיהּ, בְּגִין דְּיִתְבָּרְכוּן כֻּלְּהוּ בְּפוּלְחָנֵיהּ, וְיִשְׁתְּכָחוּ חֶדְוָואן וּבִרְכָּאן לְעֵילָּא וְתַתָּא.","כְּתִיב (ישעיהו כ״ה:א׳) יְיָ' אֱלֹהַי אַתָּה אֲרוֹמִמְךָ וְגוֹ', הַאי קְרָא אוּקְמוּהָ, יְיָ' אֱלֹהַי אַתָּה. דְּבָעֵי בַּר נָשׁ לְאוֹדָאָה לִשְׁמָא קַדִּישָׁא, וּלְשַׁבְּחָא לֵיהּ עַל כֹּלָּא. וּמַאן אֲתַר שְׁבָחָא דִּילֵיהּ, כְּמָה דְּאוּקְמוּהָ. וְהָכָא מֵעֲמִיקָא דְּכֹלָּא, דִּכְתִּיב כִּי עָשִׂיתָ פֶּלֶא. פֶּלֶא: כְּמָה דִּכְתִּיב, (ישעיהו ט׳:ה׳) וַיִּקְרָא שְׁמוֹ פֶּלֶא, וְהָא אִתְּמַר. עֵצוֹת מֵרָחוֹק, עֵצוֹת: כְּמָה דְאַתְּ אָמֵר, יוֹעֵץ. מֵרָחוֹק: דִּכְתִּיב, (ירמיהו ל״א:ג׳) מֵרָחוֹק יְיָ' נִרְאָה לִי. וּכְתִיב, (משלי ל״א:י״ד) מִמֶּרְחָק תָּבִיא לַחְמָהּ.","אֱמוּנָה אֹמֶן, כְּמָה דְאַתְּ אָמֵר, (דברים ל״ב:ד׳) אֵל אֱמוּנָה וְאֵין עָוְל. וְאוּקְמוּהָ אֱמוּנָה בַּלַּיְלָה, כְּמָה דְאַתְּ אָמֵר (תהילים צ״ב:ג׳) וְאֱמוּנָתֶךָ בַּלֵּילוֹת. וּכְתִיב (איכה ג׳:כ״ג) חֲדָשִׁים לַבְּקָרִים רַבָּה אֱמוּנָתֶךָ, וְזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְדַכְּאָה לוֹן לְיִשְׂרָאֵל מֵחוֹבֵיהוֹן, כְּמָה דִּכְתִּיב, (יחזקאל ל״ו:כ״ה) וְזָרַקְתִּי עֲלֵיכֶם מַיִם טְהוֹרִים וּטְהַרְתֶּם מִכָּל טֻמְאוֹתֵיכֶם וּמִכָּל גִּלּוּלֵיכֶם אֲטַהֵר אֶתְכֶם. בָּרוּךְ יְיָ לְעוֹלָם אָמֵן וְאָמֵן"],[[0,"ת״ח לית עלמא וכו׳:","בוא וראה. אין העולם מתקיים אלא על הריח, ומריח הזה שמריחים למטה, נודע ריח אחר למעלה, שה״ס הארת חכמה. כי בשעה שיוצא השבת, והנפש יתירה שאדם קונה בשבת מסתלקת, ונשארים נפש ורוח של האדם מפורדים ועצובים, בא הריח הזה, שממשיכים אותו ע\"י ריח ההדסים, והנפש והרוח מתקרבים על ידו זה אל זה, ושמחים."],[1,"ועל דא בעי וכו׳:","וע״כ, צריך הרוח של האדם אחר הרוח שלמעלה, שהוא ז״א, לקבל את הריח, שה״ס הארת החכמה, כיון שמתקבל הריח מתקרבים רוח ונפש שלמעלה, שהן זו״ן, וכן רוח ונפש של האדם, זה אל זה, ושמחים. כעין זה הוא, ריח של הקרבן, שבריח הזה מתקרבים הכל יחד, דהיינו כל הספירות של ז״א, ומתלהטים מהם הנרות, שהם הספירות של המלכות, ושמחים."],[2,"ת״ח תרי בוציני וכו׳:","בוא וראה, שני נרות, אחד למעלה ואחד למטה, אם אדם מדליק אותו הנר שלמטה, ומכבה אותו הנר שלמעלה, עשן ההוא העולה מן הנר שלמטה מדליק אותו הנר שלמעלה. (כמ\"ש זה לעיל נח אות רמ״א), כך העשן של הקרבן, עשן הזה העולה מן הקרבן, גורם להמשכת הארת החכמה למעלה, ומדליק נרות העליונים, שהם ז״א ומלכות, ונדלקים יחד, ומתקרבות כל הספירות יחד בריח הזה, ומשום זה ריח ניחח לה׳. וכבר העמידוהו."],[3,"וע״ד ריחא דקרבנא וכו׳:","וע״כ, ריח הקרבן הוא קיום הכל וקיום העולם, והקרבן הוא על ידי הכהן המקריב הכל, ומשום זה, שבעת ימי מילואים נשלמים בו, שהם כנגד ז״ס חג״ת נהי״מ, כדי שכולם יתברכו בעבודתו, ושמחות וברכות תמצאנה למעלה ולמטה."],[4,"כתיב ה׳ אלקי וכו׳:","כתוב, ה׳ אלקי אתה ארוממך אודה שמך כי עשית פלא עצות מרחוק אמונה אמן. מקרא זה העמידוהו. \u0003ה׳ אלקי אתה,\u0004 היינו, שצריך האדם להודות להשם הקדוש, ולשבחו על הכל. ומאיזה מקום השבח שלו. הוא כמו שהעמידוהו. וכאן הוא, מהעמוק מכל, שהוא כתר, שכתוב \u0003כי עשית פלא,\u0004 פלא, פירושו כמו שכתוב, ויקרא שמו פלא, שהוא כתר. וכבר למדנו את זה. עצות מרחוק, \u0003עצות\u0004 הוא כמו שאתה אומר פלא \u0003יועץ\u0004 דהיינו בינה שנקראת עצה. \u0003מרחוק,\u0004 כמ״ש, מרחוק ה׳ נראה לי, וכתוב ממרחק תביא לחמה, שפירושו חכמה, אשר עצות, שהיא בינה, מקבלת ממנה."],[5,"אמונה אמן:","היינו כש״א, אל אמונה ואין עול. והעמידוהו, אמונה היא בלילה, דהיינו מלכות שנקראת לילה נקראת ג״כ אמונה, כמ״ש ואמונתך בלילות, וכתוב, חדשים לבקרים רבה אמונתך, שהוא מלכות. ועתיד הקב״ה לטהר את ישראל מעונותיהם, כמ״ש וזרקתי עליכם מים טהורים וטהרתם מכל טומאותיכם ומכל גלוליכם אטהר אתכם. ברוך ה׳ לעולם אמן ואמן."]],[[0,"","בֹּא רְאֵה, אֵין הָעוֹלָם (הנפש) מִתְקַיֵּם אֶלָּא עַל רֵיחַ, וּמֵהָרֵיחַ הַזֶּה נוֹדָע רֵיחַ אַחֵר. שֶׁהֲרֵי בְּשָׁעָה שֶׁיּוֹצֵאת שַׁבָּת (נתפרדה החבילה) וְעוֹלָה הַנֶּפֶשׁ הַיְתֵרָה, וְנִשְׁאֲרוּ הַנֶּפֶשׁ וְהָרוּחַ נִפְרָדוֹת עֲצוּבוֹת, בָּא הָרֵיחַ הַזֶּה, וּמִתְקָרְבִים זֶה לָזֶה וּשְׂמֵחִים."],[1,"","וְעַל זֶה צָרִיךְ רוּחַ אַחַר רוּחַ, לְקַבֵּל רֵיחַ. כֵּיוָן שֶׁמִּתְקַבֵּל רֵיחַ, מִתְקָרְבִים כְּאֶחָד וּשְׂמֵחִים. כְּגוֹן זֶה רֵיחַ שֶׁל הַקָּרְבָּנוֹת, בְּרֵיחַ זֶה מִתְקָרְבִים כֻּלָּם כְּאֶחָד, וְנִדְלָקִים הַנֵּרוֹת וּשְׂמֵחִים."],[2,"","בֹּא רְאֵה, שְׁנֵי מְאוֹרוֹת, אֶחָד לְמַעְלָה וְאֶחָד לְמַטָּה, אִם מַלְהִיט אָדָם הַמָּאוֹר שֶׁלְּמַטָּה הַזֶּה וּמְכַבֶּה אוֹתוֹ (את אותו שלמעלה), אוֹתוֹ עָשָׁן שֶׁעוֹלֶה (מהמאור התחתון), מַלְהִיט אוֹתוֹ הַמָּאוֹר הָעֶלְיוֹן. כָּךְ עֲשַׁן הַקָּרְבָּנוֹת, הֶעָשָׁן הַזֶּה שֶׁעוֹלֶה, מַלְהִיט הַמְּאוֹרוֹת הָעֶלְיוֹנִים וּמִתְלַהֲטִים בְּאֶחָד, וְכֻלָּם מִתְקָרְבִים כְּאֶחָד בָּרֵיחַ הַזֶּה. וּמִשּׁוּם כָּךְ, רֵיחַ נִיחֹחַ לַה', (אשה) וַהֲרֵי פֵּרְשׁוּהָ."],[3,"","וְעַל כֵּן רֵיחַ הַקָּרְבָּן הוּא קִיּוּם שֶׁל הַכֹּל וְקִיּוּם הָעוֹלָם. וְהַקָּרְבָּן עַל יַד הַכֹּהֵן שֶׁמַּקְרִיב הַכֹּל, וּמִשּׁוּם כָּךְ שִׁבְעָה יְמֵי הַשְׁלָמָה נִשְׁתַּלְּמוּ בוֹ, כְּדֵי שֶׁכֻּלָּם יִתְבָּרְכוּ בַעֲבוֹדָתוֹ, וְיִמָּצְאוּ שְׂמָחוֹת וּבְרָכוֹת לְמַעְלָה וּלְמַטָּה."],[4,"","כָּתוּב, (ישעיה כה) ה' אֱלֹהַי אַתָּה אֲרוֹמִמְךְ וְגוֹ'. הַפָּסוּק הַזֶּה פֵּרְשׁוּהוּ, ה' אֱלֹהַי אַתָּה, שֶׁצָּרִיךְ אָדָם לְהוֹדוֹת לַשֵּׁם הַקָּדוֹשׁ וּלְשַׁבֵּחַ אוֹתוֹ עַל הַכֹּל. וּמֵאֵיזֶה מָקוֹם הַשֶּׁבַח שֶׁלּוֹ? כְּמוֹ שֶׁבֵּאֲרוּהָ. וְכָאן מֵהָעֹמֶק שֶׁל הַכֹּל, שֶׁכָּתוּב כִּי עָשִׂיתָ פֶּלֶא. פֶּלֶא - כְּמוֹ שֶׁכָּתוּב (שם ט) וַיִּקְרָא שְׁמוֹ פֶּלֶא, וַהֲרֵי נֶאֱמַר. עֵצוֹת מֵרָחֹק, עֵצוֹת - כְּמוֹ שֶׁנֶּאֱמַר יוֹעֵץ. מֵרָחֹק - שֶׁכָּתוּב (ירמיהלא) מֵרָחוֹק ה' נִרְאָה לִי. וְכָתוּב (משלי לא) מִמֶּרְחָק תָּבִיא לַחְמָהּ."],[5,"","אֱמוּנָה אֹמֶן - כְּמוֹ שֶׁנֶּאֱמַר (דברים לב) אֵל אֱמוּנָה וְאֵין עָוֶל. וּפֵרְשׁוּהָ אֱמוּנָה בַּלַּיְלָה, כְּמוֹ שֶׁנֶּאֱמַר (תהלים צב) וֶאֱמוּנָתְךְ בַּלֵּילוֹת. וְכָתוּב (איכה ג) חֲדָשִׁים לַבְּקָרִים רַבָּה אֱמוּנָתֶךְ. וְעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְטַהֵר אֶת יִשְׂרָאֵל מֵחֲטָאֵיהֶם, כְּמוֹ שֶׁכָּתוּב (יחזקאל לו) וְזָרַקְתִּי עֲלֵיכֶם מַיִם טְהוֹרִים וּטְהַרְתֶּם מִכֹּל טֻמְאוֹתֵיכֶם וּמִכָּל גִּלּוּלֵיכֶם אֲטַהֵר אִתכִם, בָּרוּךָ ה' לְעוֹלָם אָמֵן וְאָמֵן"]]]]};
